window.HOLUS_DATA=window.HOLUS_DATA||{};window.HOLUS_DATA["ap"]={"id":"ap","num":6,"name":"Anatomy & Physiology","area":"Body systems","lessons":[{"n":1,"title":"The Human Body","kicker":"Lesson 1 of your course, built from Chapter 1 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–85 minutes","steps":[{"id":"ap1-1","chapter":"Anatomy, physiology and pathology","title":"Anatomy, physiology and pathology","teach":["Anatomy is the study of the body’s structure: what the parts are and how they’re organized. Physiology is the study of what those parts do and how they do it. Pathology is the study of the body’s diseases.","Anatomy and physiology are hard to separate. Your mouth is a good example: teeth break food down mechanically (structure doing a job), the tongue tastes and moves food, and saliva contains enzymes that start breaking complex carbohydrates into simple sugars.","People have studied the body for a long time. Leonardo da Vinci was the first to draw the whole skeleton correctly, Andreas Vesalius wrote a book on the human body, and William Harvey worked out how blood circulates."],"keyPoints":["Anatomy = structure","Physiology = function","Pathology = disease"],"mnemonic":{"cue":"Anatomy is what it IS, physiology is what it DOES","explanation":"Ask \"what is it made of and where is it?\" for anatomy, and \"what does it do?\" for physiology."},"act":{"type":"sort","prompt":"Sort each statement into the right field of study.","categories":["Anatomy","Physiology","Pathology"],"items":[{"label":"The heart has four chambers","category":0,"feedback":"That describes structure, so it’s anatomy."},{"label":"The heart pumps blood to the lungs and body","category":1,"feedback":"That describes what the heart does, so it’s physiology."},{"label":"How a heart attack damages heart muscle","category":2,"feedback":"That’s about disease, so it’s pathology."},{"label":"The femur is the longest bone in the body","category":0,"feedback":"Size and shape are structure: anatomy."},{"label":"Saliva enzymes break starch into sugars","category":1,"feedback":"That’s a process, so it’s physiology."},{"label":"What happens to bones in osteoporosis","category":2,"feedback":"That’s a disease, so it’s pathology."}]}},{"id":"ap1-2","chapter":"Anatomic position","title":"Anatomic position","teach":["To keep everyone using the same language, scientists use four reference systems: directions, planes, cavities and structural units.","All of them assume the body is in anatomic position: standing upright and facing forward, arms at the sides, palms and feet facing forward. Even if a patient is lying down, you describe locations as if they were standing this way."],"goodToKnow":"\"Left\" and \"right\" always mean the patient’s left and right, not yours.","act":{"type":"choice","prompt":"Which describes anatomic position?","options":[{"label":"Standing upright, facing forward, arms at the sides, palms facing forward","correct":true,"feedback":"Right. Palms forward is the detail people often miss."},{"label":"Standing upright, arms at the sides, palms facing the thighs","correct":false,"feedback":"Close, but in anatomic position the palms face forward."},{"label":"Lying on the back, arms by the sides","correct":false,"feedback":"That’s lying down. Anatomic position is standing and facing forward."}]}},{"id":"ap1-3","chapter":"Directional terms, part 1","title":"Directional terms, part 1","teach":["Superior means above (the head is superior to the neck). Inferior means below (the foot is inferior to the ankle).","Anterior means toward the front; ventral, the belly side, means the same thing. Posterior means toward the back; dorsal, the back side, means the same thing. The esophagus is posterior to the trachea.","Cephalad or cranial means toward the head, so it’s another word for superior. Caudal means toward the tail, and is sometimes used for inferior. Humans only have a tail as embryos."],"visual":{"kind":"hub","title":"Pairs of opposites","items":[{"label":"Superior / inferior","detail":"Above / below"},{"label":"Anterior / posterior","detail":"Front / back (ventral / dorsal)"},{"label":"Cephalad / caudal","detail":"Toward the head / toward the tail"},{"label":"Medial / lateral","detail":"Toward the midline / toward the side"},{"label":"Proximal / distal","detail":"Near / far from the point of attachment"}]},"act":{"type":"choice","prompt":"The vertebral column is ______ to the digestive tract.","options":[{"label":"Posterior (dorsal)","correct":true,"feedback":"Right. The spine sits behind the gut."},{"label":"Anterior (ventral)","correct":false,"feedback":"Anterior means in front. The spine is behind the gut."},{"label":"Superior","correct":false,"feedback":"Superior means above. Here the spine is behind, not above."}]}},{"id":"ap1-4","chapter":"Directional terms, part 2","title":"Directional terms, part 2","teach":["Medial means closer to the midline of the body: the nose is medial on the face, and the ulna is on the medial side of the forearm. Lateral means toward the side: the ears are lateral, and the radius is lateral to the ulna.","Proximal means near the point of attachment or origin. Distal means away from it. These are used mostly for limbs: the elbow is proximal to the wrist, and the wrist is distal to the elbow."],"mnemonic":{"cue":"Proximal = proximity, distal = distance","explanation":"Proximal parts are close to where the limb joins the trunk; distal parts are a long distance from it."},"act":{"type":"sort","prompt":"Pick the right term for each statement.","categories":["Proximal","Distal","Medial","Lateral"],"items":[{"label":"The knee, compared with the ankle","category":0,"feedback":"The knee is closer to the hip, where the leg attaches."},{"label":"The fingers, compared with the wrist","category":1,"feedback":"Fingers are farther from the shoulder attachment."},{"label":"The nose on the face","category":2,"feedback":"The nose sits on the midline."},{"label":"The radius, compared with the ulna","category":3,"feedback":"The radius is on the thumb side, away from the midline."},{"label":"The ears on the face","category":3,"feedback":"The ears are toward the sides."},{"label":"The wrist, compared with the elbow","category":1,"feedback":"The wrist is farther from the attachment, so it’s distal."}]}},{"id":"ap1-5","chapter":"Body planes","title":"Body planes","teach":["Planes are imaginary flat surfaces passing through the body. They’re most useful when describing dissections or scans.","A midsagittal (median) plane divides the body down the middle into equal left and right halves. Any sagittal plane runs parallel to it and divides the body into unequal left and right parts.","A horizontal or transverse plane divides the body into superior and inferior portions. A frontal or coronal plane divides it into anterior and posterior portions, at right angles to the sagittal plane.","When an organ is cut, a cut along its long axis is a longitudinal section, and a cut across it is a transverse or cross section."],"visual":{"kind":"flow","title":"Three planes","items":[{"label":"Sagittal (midsagittal)","detail":"Left and right parts. Midsagittal gives equal halves."},{"label":"Frontal (coronal)","detail":"Front (anterior) and back (posterior) parts."},{"label":"Transverse (horizontal)","detail":"Upper (superior) and lower (inferior) parts."}]},"act":{"type":"choice","prompt":"A CT scan slice that separates the chest from the abdomen is cut along which plane?","options":[{"label":"Transverse (horizontal)","correct":true,"feedback":"Right. It splits the body into upper and lower parts."},{"label":"Frontal (coronal)","correct":false,"feedback":"A frontal plane splits front from back."},{"label":"Midsagittal","correct":false,"feedback":"A midsagittal plane splits left from right."}]}},{"id":"ap1-6","chapter":"The dorsal cavity","title":"The dorsal cavity","teach":["The body has two major cavities, the dorsal cavity and the ventral cavity. The organs inside any cavity are called the viscera.","The dorsal cavity holds the nervous system organs that coordinate the body. It has two parts: the cranial cavity, which holds the brain, and the spinal cavity, which holds the spinal cord."],"act":{"type":"choice","prompt":"The spinal cord sits in the:","options":[{"label":"Spinal cavity, part of the dorsal cavity","correct":true,"feedback":"Right. The dorsal cavity is the cranial cavity plus the spinal cavity."},{"label":"Thoracic cavity, part of the ventral cavity","correct":false,"feedback":"The thoracic cavity holds the heart and lungs."},{"label":"Abdominopelvic cavity","correct":false,"feedback":"That holds digestive, urinary and reproductive organs."}]}},{"id":"ap1-7","chapter":"The ventral cavity","title":"The ventral cavity","teach":["The ventral cavity holds organs that keep the internal environment steady (homeostasis). Its first part is the thoracic cavity, surrounded by the rib cage.","Inside the thoracic cavity, the heart sits in the pericardial sac (the pericardial cavity) and each lung is covered by a pleural membrane (the pleural cavities). Between the two pleural cavities is the mediastinum, which holds the heart, thymus, lymph and blood vessels, trachea, esophagus and nerves.","The diaphragm separates the thoracic cavity from the abdominopelvic cavity. That second part holds the kidneys, stomach, liver and gallbladder, small and large intestines, spleen, pancreas, and in women the ovaries and uterus.","Parietal refers to the wall of a cavity (the parietal peritoneum lines the abdominal wall). Visceral refers to the covering of an organ (the visceral peritoneum covers the abdominal organs)."],"visual":{"kind":"flow","title":"Cavities of the body","items":[{"label":"Dorsal cavity","detail":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"label":"Thoracic cavity","detail":"Pericardial cavity (heart), pleural cavities (lungs), mediastinum."},{"label":"Diaphragm","detail":"The muscle that separates the chest from the abdomen."},{"label":"Abdominopelvic cavity","detail":"Stomach, liver, intestines, kidneys, spleen, pancreas, and in women the ovaries and uterus."}]},"mnemonic":{"cue":"Parietal = partition wall, visceral = viscera","explanation":"The parietal layer lines the wall; the visceral layer hugs the organ (the viscera)."},"act":{"type":"sort","prompt":"Put each organ in its cavity.","categories":["Cranial","Thoracic","Abdominopelvic"],"items":[{"label":"Brain","category":0,"feedback":"The brain is in the cranial cavity."},{"label":"Heart","category":1,"feedback":"The heart is in the pericardial cavity, inside the thoracic cavity."},{"label":"Lungs","category":1,"feedback":"Each lung is in a pleural cavity in the thorax."},{"label":"Esophagus (in the chest)","category":1,"feedback":"It runs through the mediastinum."},{"label":"Liver","category":2,"feedback":"The liver is below the diaphragm."},{"label":"Kidneys","category":2,"feedback":"The textbook lists the kidneys in the abdominopelvic cavity."},{"label":"Uterus","category":2,"feedback":"The uterus is in the pelvic part."}]}},{"id":"ap1-8","chapter":"Levels of organization","title":"Levels of organization","teach":["All living material is made of cells, the smallest units of life. Cells form tissues, tissues form organs, organs form systems, and all the systems together make the organism.","Below the cell are atoms (like carbon, hydrogen and oxygen) and molecules (like water, sugars and amino acids), but these aren’t alive. The cell is the smallest living unit and the basic unit of biologic organization.","The fluid part of a cell is protoplasm. It’s surrounded by the cell (plasma) membrane, which controls what enters and leaves, and it contains organelles such as mitochondria, ribosomes and lysosomes."],"act":{"type":"order","prompt":"Put the levels of organization in order, smallest first.","items":[{"label":"Atoms","detail":"Smallest units of elements"},{"label":"Molecules","detail":"Atoms joined by chemical bonds"},{"label":"Cells","detail":"Smallest living units"},{"label":"Tissues","detail":"Similar cells doing similar jobs"},{"label":"Organs","detail":"Different tissues working together"},{"label":"Systems","detail":"Groups of organs"},{"label":"Organism","detail":"All systems together"}]}},{"id":"ap1-9","chapter":"The four tissue types","title":"The four tissue types","teach":["Every tissue in the body fits one of four groups.","Epithelial tissue covers and protects surfaces (outside, like skin, and inside, like the intestine lining), forms glands and lines cavities. Its cells sit close together with almost no material between them.","Connective tissue binds and supports other tissues. Its cells make fibers (collagen and elastin) set in a nonliving matrix. Blood, bone and lymphatic tissue are specialized connective tissues.","Muscle tissue has long cells (muscle fibers) that generate movement by contracting forcefully. There are three types: skeletal (voluntary, pulls on bones), smooth (involuntary, in the intestines and blood vessels) and cardiac (involuntary, only in the heart).","Nervous tissue is made of nerve cells that link the sensory and motor structures of the body into one coordinating system."],"keyPoints":["4 tissue types: epithelial, connective, muscle, nervous","3 muscle types: skeletal, smooth, cardiac"],"act":{"type":"sort","prompt":"Match each description to its tissue.","categories":["Epithelial","Connective","Muscle","Nervous"],"items":[{"label":"Lines the intestine and forms glands","category":0,"feedback":"Covering, lining and glands are epithelial jobs."},{"label":"Bone and blood","category":1,"feedback":"Both are specialized connective tissues."},{"label":"Contracts forcefully to create movement","category":2,"feedback":"That’s muscle."},{"label":"Pushes food along the digestive tract","category":2,"feedback":"Smooth muscle does this."},{"label":"Carries signals between sensory and motor structures","category":3,"feedback":"That’s nervous tissue."},{"label":"Cells make collagen and elastin fibers in a matrix","category":1,"feedback":"Fibers in a matrix is the mark of connective tissue."}]}},{"id":"ap1-10","chapter":"Body systems: covering, support and movement","title":"Body systems: covering, support and movement","teach":["The integumentary system is the skin (epidermis and dermis) plus hair, nails, sebaceous glands and sweat glands. It insulates and protects the body, helps control temperature and water, and has receptors for temperature and pressure.","The skeletal system is bones, cartilage and the membranes around bones. It protects and supports, acts as levers for movement, makes blood cells in red marrow, stores fat in yellow marrow, and stores minerals like calcium and phosphorus.","The muscular system is muscles, fasciae, tendon sheaths and bursae. Skeletal muscle moves bones, smooth muscle moves food and blood, and cardiac muscle makes the heart contract."],"act":{"type":"choice","prompt":"Red bone marrow making blood cells is a job of which system?","options":[{"label":"Skeletal","correct":true,"feedback":"Right. Bones make blood cells and store fat and minerals."},{"label":"Cardiovascular","correct":false,"feedback":"The cardiovascular system moves blood, but bones make the cells."},{"label":"Lymphatic","correct":false,"feedback":"Not in this textbook’s list. Blood cells come from red bone marrow."}]}},{"id":"ap1-11","chapter":"Body systems: control and transport","title":"Body systems: control and transport","teach":["The nervous system (brain, spinal cord, cranial and peripheral nerves) controls and coordinates the other systems, interprets stimuli and handles the special senses.","The endocrine system is the ductless glands. The pituitary, the \"master gland\", controls the thyroid, adrenals, ovaries and testes. Hormones regulate the body chemically, and the hypothalamus links this system with the nervous system.","The cardiovascular system (heart, arteries, veins, capillaries) pumps blood carrying oxygen, nutrients and wastes.","The lymphatic (immune) system (lymph nodes, thymus, spleen, lymph vessels) drains extra fluid from tissues, carries absorbed fats from the intestine to the blood, and protects against disease."],"act":{"type":"sort","prompt":"Which system does each job?","categories":["Nervous","Endocrine","Cardiovascular","Lymphatic"],"items":[{"label":"Interprets sight, hearing, taste and smell","category":0,"feedback":"The special senses are nervous system work."},{"label":"Regulates the body with hormones","category":1,"feedback":"Hormones come from endocrine glands."},{"label":"Pumps blood through arteries, veins and capillaries","category":2,"feedback":"That’s the cardiovascular system."},{"label":"Carries absorbed fats from the intestine","category":3,"feedback":"Lymph vessels pick up fats."},{"label":"Drains extra fluid from tissue spaces","category":3,"feedback":"That’s a lymphatic job."},{"label":"Pituitary controls other glands","category":1,"feedback":"The pituitary is the endocrine master gland."}]}},{"id":"ap1-12","chapter":"Body systems: exchange, processing and reproduction","title":"Body systems: exchange, processing and reproduction","teach":["The respiratory system (nasal cavities, pharynx, larynx, trachea, bronchi, lungs) brings oxygen into the blood and removes carbon dioxide.","The digestive system is the alimentary canal (mouth to anus) plus the salivary glands, liver and pancreas. It breaks food into simpler substances that cells can absorb and gets rid of what can’t be digested.","The urinary system (two kidneys, two ureters, bladder, urethra) chemically regulates the blood, makes and removes urine, and helps maintain homeostasis.","The reproductive system is the ovaries, uterine tubes, uterus and vagina in women, and the testes, vas deferens, seminal vesicles, prostate, penis and urethra in men. It maintains sexual characteristics and continues the species."],"act":{"type":"sort","prompt":"Which system does each organ belong to?","categories":["Respiratory","Digestive","Urinary","Reproductive"],"items":[{"label":"Larynx","category":0,"feedback":"The larynx is part of the airway."},{"label":"Pancreas","category":1,"feedback":"It’s an associated gland of the digestive system."},{"label":"Ureters","category":2,"feedback":"They carry urine from the kidneys to the bladder."},{"label":"Prostate gland","category":3,"feedback":"It’s part of the male reproductive system."},{"label":"Bronchi","category":0,"feedback":"They lead into the lungs."},{"label":"Liver","category":1,"feedback":"The textbook lists it as a digestive gland."}]}},{"id":"ap1-13","chapter":"Homeostasis","title":"Homeostasis","teach":["Homeostasis is keeping the body’s internal environment within narrow limits. Claude Bernard was one of the first scientists to explain why it matters. Blood sugar, body temperature, heart rate and the fluid around cells are all kept in range.","Blood sugar: after a carbohydrate meal, blood glucose rises. The pancreas releases insulin, which moves extra glucose into the liver to be stored as glycogen. Between meals, when glucose drops, the pancreas releases glucagon, which breaks glycogen back down into glucose.","Temperature: when you overheat, the hypothalamus makes you sweat and widens blood vessels near the skin to lose heat. When you’re cold, it makes you shiver and narrows those vessels to hold heat in.","If homeostasis isn’t maintained, the body becomes diseased and eventually dies."],"visual":{"kind":"cycle","title":"Blood sugar balance","items":[{"label":"Meal raises glucose","detail":"Carbohydrates are broken down into glucose."},{"label":"Insulin released","detail":"The pancreas sends extra glucose to the liver."},{"label":"Stored as glycogen","detail":"The liver stores it for later."},{"label":"Glucose drops between meals","detail":"Cells keep using glucose."},{"label":"Glucagon released","detail":"Glycogen is broken back into glucose."}]},"act":{"type":"choice","prompt":"Between meals, blood glucose falls. What does the pancreas release?","options":[{"label":"Glucagon, which turns stored glycogen back into glucose","correct":true,"feedback":"Right. Glucagon raises blood glucose."},{"label":"Insulin, which moves glucose into the liver","correct":false,"feedback":"Insulin lowers blood glucose. That’s the response after a meal."},{"label":"Sweat, to cool the body","correct":false,"feedback":"Sweating is for temperature, not blood sugar."}]}},{"id":"ap1-14","chapter":"Negative and positive feedback","title":"Negative and positive feedback","teach":["The body keeps checking itself and correcting changes using negative feedback: a change triggers a response that reverses it. A home thermostat works the same way: when it gets cold, the furnace turns on; when it’s warm enough, it turns off. Body temperature control is negative feedback.","Positive feedback is the opposite: a stimulus leads to more of the same response. In labour, after the first contraction, the uterus keeps contracting harder and more often."],"mnemonic":{"cue":"Negative = \"no more\", positive = \"more, more\"","explanation":"Negative feedback shuts the change down. Positive feedback builds it up until an end point (like birth)."},"act":{"type":"sort","prompt":"Negative or positive feedback?","categories":["Negative feedback","Positive feedback"],"items":[{"label":"Sweating when body temperature rises","category":0,"feedback":"It brings temperature back down."},{"label":"Contractions growing stronger during labour","category":1,"feedback":"Each contraction leads to a stronger one."},{"label":"Insulin release after a meal","category":0,"feedback":"It brings blood glucose back down."},{"label":"Shivering in the cold","category":0,"feedback":"It brings temperature back up to normal."},{"label":"A furnace switching off when the room is warm","category":0,"feedback":"That’s the thermostat example of negative feedback."}]}}],"flashcards":[{"front":"Anatomy","back":"The study of the body’s structure and how its parts are organized."},{"front":"Physiology","back":"The study of what body parts do and how they do it."},{"front":"Pathology","back":"The study of the diseases of the body."},{"front":"Anatomic position","back":"Standing upright, facing forward, arms at the sides, palms and feet facing forward."},{"front":"Superior / inferior","back":"Above / below."},{"front":"Anterior (ventral) / posterior (dorsal)","back":"Toward the front / toward the back."},{"front":"Cephalad (cranial) / caudal","back":"Toward the head / toward the tail."},{"front":"Medial / lateral","back":"Toward the midline / toward the side."},{"front":"Proximal / distal","back":"Near / away from the point of attachment or origin."},{"front":"Midsagittal plane","back":"Divides the body into equal left and right halves (also called the median plane)."},{"front":"Transverse (horizontal) plane","back":"Divides the body into superior and inferior portions."},{"front":"Frontal (coronal) plane","back":"Divides the body into anterior and posterior portions."},{"front":"Viscera","back":"The organs inside any body cavity."},{"front":"Dorsal cavity","back":"Cranial cavity (brain) and spinal cavity (spinal cord)."},{"front":"Thoracic cavity","back":"Holds the heart in the pericardial cavity and the lungs in the pleural cavities, with the mediastinum between them."},{"front":"Mediastinum","back":"Space between the pleural cavities holding the heart, thymus, trachea, esophagus, vessels and nerves."},{"front":"Parietal / visceral","back":"Lining the wall of a cavity / covering an organ."},{"front":"Protoplasm","back":"The fluid part of a cell."},{"front":"Four tissue types","back":"Epithelial, connective, muscle and nervous."},{"front":"Three muscle types","back":"Skeletal (voluntary), smooth (involuntary, gut and vessels), cardiac (heart only)."},{"front":"Homeostasis","back":"Keeping the internal environment within narrow limits."},{"front":"Negative feedback","back":"A response that reverses a change, like temperature control."},{"front":"Positive feedback","back":"A response that increases the change, like labour contractions."}],"quiz":[{"q":"The organs of any cavity are referred to as the viscera.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the organs of any cavity are called the viscera. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"A __________________ is any plane that divides the body into superior and inferior portions.","o":["frontal","mid-sagittal","coronal","transverse"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says a horizontal or transverse plane divides the body into superior and inferior portions. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The heart is located within the _______________ cavity.","o":["pleural","pericardial","abdominal","cranial"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 says the heart sits in the pericardial sac, called the pericardial cavity, inside the thoracic cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The wrist is _____________________ to the elbow.","o":["proximal","superior","distal","superficial"],"a":2,"e":"Checked answer, not from an official key. Distal means away from the point of attachment. The textbook’s own example is \"the wrist is distal to the elbow\". Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What are the smallest living units of biologic organization?","o":["Atoms","Cells","Organelles","Systems"],"a":1,"e":"Checked answer, not from an official key. Table 1-1 says cells are the smallest living units of biologic organization. Atoms and molecules are smaller but not alive. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Skin, hair, and nails belong to the ________________________ system.","o":["integumentary","muscular","digestive","endocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says the integumentary system includes the skin, hair, nails, sebaceous glands and sweat glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What term is used for the maintenance (within varying narrow limits) of the internal environment of the body?","o":["physiology","homeostasis","pathology","epithelium"],"a":1,"e":"Checked answer, not from an official key. Chapter 1 defines homeostasis as the maintenance, within varying narrow limits, of the internal environment of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of muscle is found along the digestive tract?","o":["smooth","cardiac","skeletal","vascular"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says smooth (involuntary) muscle is found in the intestines, where it pushes food along the digestive tract. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Body temperature control is an example of, _______________________ a process by which the body responds to a stimulus by correcting the change and bringing the body back to the original setting.","o":["positive feedback","endocrinology","negative feedback","pathology"],"a":2,"e":"Checked answer, not from an official key. Chapter 1 uses body temperature control as its example of negative feedback, which corrects a change and brings the body back to normal. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The first contraction during labor results in stronger and stronger contractions of the uterus. This process is an example of _____________________________.","o":["negative feedback","endocrinology","pathology","positive feedback"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 gives labour as the example: after the first contraction, the uterus keeps contracting with more strength and frequency. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The study of the diseases of the body is called ___________________.","o":["anatomy","physiology","endocrinology","pathology"],"a":3,"e":"Checked answer, not from an official key. Chapter 1 says pathology is the study of the diseases of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"What type of tissue generates movement by contracting in a forcible manner?","o":["muscle","nervous","connective","epithelial"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 says muscle tissue generates movement by shortening or contracting in a forcible manner. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"Anatomy is the study of diseases in the body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Anatomy is the study of structure. The study of disease is pathology. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"There are four types of muscle in the human body.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. There are three types of muscle tissue: skeletal, smooth and cardiac. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."},{"q":"The prostate gland, penis, and urethra belong to the male reproductive system.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 1 lists the prostate gland, penis and urethra as part of the male reproductive system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 1."}],"caseStudy":{"title":"From a warm room to a whole-body response","scenario":"During a classroom demonstration, a learner becomes warm and begins sweating. They say the skin alone is “fixing” temperature.","prompts":["Which structures detect and coordinate the change?","Which tissue and organ-system responses help release heat?","Why is this an example of negative feedback rather than a single-organ action?"],"takeaway":"Thermoregulation illustrates the course’s central idea: structure, signalling, circulation and effectors cooperate to keep a variable within a workable range."},"perStepChapter":true},{"n":2,"title":"The Chemistry of Life","kicker":"Lesson 2 of your course, built from Chapter 2 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"80–95 minutes","steps":[{"id":"ap2-1","chapter":"Why chemistry matters","title":"Why chemistry matters","teach":["Every cell, tissue and organ is made of chemicals, and the body works through chemical reactions. Digestion, for example, breaks complex food into simple sugars, which cells then turn into ATP, the fuel they run on.","All matter is made of elements: basic substances that can’t be broken down into anything simpler. 92 elements occur naturally."],"act":{"type":"choice","prompt":"What is an element?","options":[{"label":"A basic substance that can’t be broken down into anything simpler","correct":true,"feedback":"Right. Carbon, oxygen and hydrogen are examples."},{"label":"Any substance made of two or more kinds of atoms","correct":false,"feedback":"That’s a compound."},{"label":"The smallest living unit","correct":false,"feedback":"That’s the cell, from Lesson 1."}]}},{"id":"ap2-2","chapter":"Inside an atom","title":"Inside an atom","teach":["Atoms are the smallest particles of an element that still have all its properties. They take part in chemical reactions through their electrons.","Each atom has a heavy, compact nucleus made of protons (positive charge) and neutrons (no charge). Hydrogen is the exception: its nucleus is a single proton. Much lighter electrons (negative charge) orbit the nucleus.","Protons and neutrons each weigh about 1,800 times more than an electron, so an atom’s weight comes almost entirely from its nucleus. Like charges repel and unlike charges attract."],"visual":{"kind":"hub","title":"Parts of an atom","items":[{"label":"Proton","detail":"In the nucleus. Positive charge, 1 unit of weight."},{"label":"Neutron","detail":"In the nucleus. No charge, 1 unit of weight."},{"label":"Electron","detail":"Orbits the nucleus in energy levels. Negative charge, almost weightless."}]},"act":{"type":"sort","prompt":"Where is each particle, and what charge does it carry?","categories":["In the nucleus","Orbits the nucleus"],"items":[{"label":"Proton (+)","category":0,"feedback":"Protons are in the nucleus."},{"label":"Neutron (no charge)","category":0,"feedback":"Neutrons are in the nucleus too."},{"label":"Electron (−)","category":1,"feedback":"Electrons orbit in energy levels."}]}},{"id":"ap2-3","chapter":"Elements, isotopes and the periodic table","title":"Elements, isotopes and the periodic table","teach":["An element is a substance whose atoms all have the same number of protons and the same number of electrons. Because protons and electrons match, atoms are electrically neutral. The atomic number is that number of protons (or electrons).","Isotopes are atoms of the same element with different numbers of neutrons. Carbon has three: C12, C13 and C14, all with six protons and six electrons but six, seven or eight neutrons. C14 is mildly radioactive and is used to date fossil remains. Radioactive iodine is used to treat thyroid disorders.","Carbon is the element found in all living matter. The study of carbon compounds is organic chemistry.","Dmitri Mendeleev noticed that elements could be grouped by similar properties, which gave us the periodic table, arranged by increasing atomic number. John Dalton proposed the atomic theory in 1808."],"mnemonic":{"cue":"Isotopes: same Protons, different Neutrons","explanation":"Change the protons and you have a different element. Change only the neutrons and you have an isotope."},"act":{"type":"choice","prompt":"C12 and C14 are both carbon because they have the same number of:","options":[{"label":"Protons","correct":true,"feedback":"Right. Six protons makes it carbon. They differ only in neutrons."},{"label":"Neutrons","correct":false,"feedback":"Neutrons are what differ between isotopes."},{"label":"Energy levels filled with electrons","correct":false,"feedback":"The defining feature is the number of protons."}]}},{"id":"ap2-4","chapter":"Energy levels","title":"Energy levels","teach":["You can’t know exactly where an electron is, but you can describe the area where it’s likely to be: its orbital. Orbitals group into energy levels drawn as rings around the nucleus.","Hydrogen has one electron in its first level. Carbon has two in the first level and four in the second. Oxygen has two in the first and six in the second. The outer level is what takes part in bonding, and eight electrons fill it."],"act":{"type":"number","prompt":"How many electrons does oxygen have in its second (outer) level?","answer":6,"tolerance":0,"unit":"electrons","explanation":"Oxygen has 2 electrons in its first level and 6 in its second, so it needs 2 more to fill its outer level. That’s why it bonds with two hydrogens in water."}},{"id":"ap2-5","chapter":"Ionic bonds","title":"Ionic bonds","teach":["Atoms bond by transferring or sharing their outermost electrons. When atoms of two or more different elements combine this way, they form a compound. A molecule is the smallest particle that keeps all the properties of the compound (H₂O is both).","In an ionic bond, one atom gains electrons and the other loses them. Atoms that gain electrons become negative; atoms that lose electrons become positive. These charged atoms are ions, and the attraction between opposite charges holds them together.","Table salt is the classic example: sodium has one outer electron, chlorine has seven. Sodium gives its electron to chlorine, making Na⁺ and Cl⁻. Ionic compounds dissociate (split into ions) in water. Many mineral salts the body needs, like sodium, chloride, potassium, calcium and phosphate, exist as ions."],"act":{"type":"choice","prompt":"When sodium gives an electron to chlorine, sodium becomes:","options":[{"label":"A positive ion (Na⁺)","correct":true,"feedback":"Right. Losing a negative electron leaves a positive charge."},{"label":"A negative ion (Na⁻)","correct":false,"feedback":"Gaining electrons makes an ion negative. Sodium loses one."},{"label":"An isotope of sodium","correct":false,"feedback":"Isotopes differ in neutrons, not electrons."}]}},{"id":"ap2-6","chapter":"Covalent and hydrogen bonds","title":"Covalent and hydrogen bonds","teach":["In a covalent bond, atoms share electrons to fill their outer levels. Covalent molecules don’t dissociate in water. Carbon, oxygen, hydrogen and nitrogen form covalent bonds, and together they make up about 95% of the material in cells.","Hydrogen bonds are very weak. They hold water molecules together by forming a bridge between the negative oxygen of one molecule and the positive hydrogens of another. They also help fold molecules like proteins into their 3D shape.","Atoms that give up electrons in a reaction are electron donors (like sodium); those that take them are electron acceptors (like chlorine). Electron carriers accept electrons briefly and use their energy to make ATP."],"act":{"type":"sort","prompt":"Which type of bond is described?","categories":["Ionic","Covalent","Hydrogen"],"items":[{"label":"Electrons are transferred from one atom to another","category":0,"feedback":"Transfer = ionic."},{"label":"Electrons are shared","category":1,"feedback":"Sharing = covalent."},{"label":"Splits into ions in water","category":0,"feedback":"Ionic compounds dissociate in water."},{"label":"Holds one water molecule to the next","category":2,"feedback":"That’s the hydrogen bond bridge."},{"label":"Joins the C, H, O and N in large cell molecules","category":1,"feedback":"These elements bond covalently."},{"label":"Helps fold a protein into its shape","category":2,"feedback":"Hydrogen bonds shape proteins."}]}},{"id":"ap2-7","chapter":"Water","title":"Water","teach":["Water is the most abundant substance in cells, about 60% to 80%. Blood plasma is 91% water.","Water is two hydrogens covalently bonded to one oxygen. Oxygen pulls electrons harder, so water is polar: slightly negative at the oxygen and slightly positive at the hydrogens. That’s why salt dissociates in it: Cl⁻ is drawn to the hydrogens and Na⁺ to the oxygen.","Water’s jobs: it takes part in reactions (digestion uses water to break molecules apart, called hydrolysis); it’s the \"universal solvent\" where reactions happen; it carries hormones and enzymes in plasma; it absorbs and releases heat, steadying body temperature; it cushions the fetus (amniotic fluid) and the brain and spinal cord (cerebrospinal fluid); and it’s the base of body lubricants like mucus and synovial fluid."],"keyPoints":["Most abundant substance in cells (60–80%)","Polar molecule","Solvent, transport, temperature control, protection, lubrication"],"act":{"type":"choice","prompt":"Why does table salt dissolve (dissociate) in water?","options":[{"label":"Water is polar, so its charged ends pull the Na⁺ and Cl⁻ ions apart","correct":true,"feedback":"Right. The unequal sharing of electrons in water is the key."},{"label":"Salt is held together by covalent bonds","correct":false,"feedback":"Salt is ionic. Covalent compounds don’t dissociate in water."},{"label":"Water is a base","correct":false,"feedback":"Pure water is neutral, pH 7."}]}},{"id":"ap2-8","chapter":"Carbon dioxide, oxygen and ammonia","title":"Carbon dioxide, oxygen and ammonia","teach":["Carbon dioxide (CO₂) is a waste product of cellular respiration. If it builds up, it reacts with water to form carbonic acid, which is toxic, so we breathe it out quickly. Plants use it in photosynthesis, and it’s the source of the carbon in all organic compounds.","Molecular oxygen (O₂) is needed by everything that breathes air. Cells use it to turn the energy in glucose into ATP. Plants keep the atmosphere at about 21% oxygen.","Ammonia (NH₃) comes from breaking down proteins and amino acids. Even a little is harmful, so the liver uses enzymes to convert it to urea, which the kidneys remove in urine."],"visual":{"kind":"flow","title":"Getting rid of ammonia","items":[{"label":"Protein breakdown","detail":"Amino acids are used for energy."},{"label":"Ammonia (NH₃)","detail":"Toxic nitrogen waste."},{"label":"Liver","detail":"Enzymes convert ammonia to urea."},{"label":"Kidneys","detail":"Urea is filtered out in urine."}]},"act":{"type":"choice","prompt":"Which organ turns toxic ammonia into urea?","options":[{"label":"Liver","correct":true,"feedback":"Right. The kidneys then excrete the urea."},{"label":"Kidneys","correct":false,"feedback":"The kidneys remove urea, but the liver makes it."},{"label":"Lungs","correct":false,"feedback":"The lungs get rid of carbon dioxide."}]}},{"id":"ap2-9","chapter":"Mineral salts (electrolytes)","title":"Mineral salts (electrolytes)","teach":["Mineral salts, or electrolytes, are small ions that cells need to survive. They’re parts of enzymes or of the environment enzymes need to work.","Calcium is needed for muscle contraction, nerve transmission and strong bones; it’s the fifth most abundant element in the body. Phosphate is needed to make ATP. Chloride is needed for nerve transmission. Sodium and potassium are needed for muscle contraction and nerve transmission."],"act":{"type":"sort","prompt":"Match each mineral to a job the textbook gives it.","categories":["Calcium","Phosphate","Sodium and potassium"],"items":[{"label":"Building strong bones","category":0,"feedback":"Calcium."},{"label":"Making ATP","category":1,"feedback":"Phosphate is part of ATP."},{"label":"Muscle contraction and nerve signals","category":2,"feedback":"Sodium and potassium (calcium helps too)."}]}},{"id":"ap2-10","chapter":"Carbohydrates","title":"Carbohydrates","teach":["Carbohydrates are made of carbon, hydrogen and oxygen in a 1:2:1 ratio, like glucose (C₆H₁₂O₆). The smallest are simple sugars, usually chains of five or six carbons.","Important five-carbon sugars are ribose and deoxyribose, part of RNA and DNA. Important six-carbon sugars are glucose and fructose. Glucose and fructose together make sucrose (table sugar), a disaccharide.","Many glucose molecules bonded together make starch, glycogen (animal starch), cellulose (plant fiber) and chitin. Carbohydrates have two main jobs: storing energy (the more common job) and strengthening cells (cellulose, chitin)."],"act":{"type":"sort","prompt":"Five-carbon or six-carbon sugar?","categories":["Five-carbon","Six-carbon"],"items":[{"label":"Ribose","category":0,"feedback":"Ribose is in RNA."},{"label":"Deoxyribose","category":0,"feedback":"Deoxyribose is in DNA."},{"label":"Glucose","category":1,"feedback":"C₆H₁₂O₆."},{"label":"Fructose","category":1,"feedback":"Fructose is a six-carbon sugar."}]}},{"id":"ap2-11","chapter":"Lipids","title":"Lipids","teach":["Lipids don’t dissolve in water. They include fats, phospholipids, steroids and prostaglandins. About 95% of the fat in the body is triglycerides, now called triacylglycerols: one glycerol (a three-carbon molecule) plus fatty acids.","A fatty acid is saturated if its carbons are joined only by single bonds. Saturated fats (whole milk, butter, eggs, beef, pork, coconut and palm oils) tend to be solid at room temperature, and too much contributes to cardiovascular disease.","An unsaturated fatty acid has one or more double bonds. These fats (sunflower, corn and fish oils) tend to be liquid at room temperature.","Fats store energy, insulate the body under the skin, and cushion organs like the kidneys."],"act":{"type":"sort","prompt":"Saturated or unsaturated?","categories":["Saturated","Unsaturated"],"items":[{"label":"Only single bonds between carbons","category":0,"feedback":"Single bonds only = saturated."},{"label":"One or more double bonds","category":1,"feedback":"Double bonds = unsaturated."},{"label":"Butter","category":0,"feedback":"Solid at room temperature."},{"label":"Fish oil","category":1,"feedback":"Liquid at room temperature."},{"label":"Coconut oil","category":0,"feedback":"The textbook lists coconut and palm oils as saturated."},{"label":"Corn oil","category":1,"feedback":"Unsaturated."}]}},{"id":"ap2-12","chapter":"Proteins","title":"Proteins","teach":["Proteins are made of carbon, hydrogen, oxygen and nitrogen, and most also contain sulfur. Their building blocks are 20 amino acids. Each amino acid has a carboxyl group, an amine group, a hydrogen and a variable R group.","The covalent bonds that join amino acids into a protein are called peptide bonds.","Proteins do a lot: they build membranes and muscle (actin and myosin); enzymes are protein catalysts that speed up reactions without being changed; antibodies are proteins that fight foreign antigens; and proteins can be broken down for energy.","Structure: primary is the amino acid sequence; secondary is coiling into helices or pleated sheets from hydrogen bonds; tertiary is further folding, partly from bonds between sulfur atoms; quaternary is how separate units fit together. Heat or a pH change can break hydrogen bonds and stop a protein from working."],"act":{"type":"order","prompt":"Put the levels of protein structure in order.","items":[{"label":"Primary","detail":"The sequence of amino acids"},{"label":"Secondary","detail":"Coiling into helices or pleated sheets (hydrogen bonds)"},{"label":"Tertiary","detail":"Further folding (including sulfur bonds)"},{"label":"Quaternary","detail":"How separate units fit together"}]}},{"id":"ap2-13","chapter":"Nucleic acids and ATP","title":"Nucleic acids and ATP","teach":["DNA is the genetic material in the nucleus and controls everything the cell does. RNA is related to it; messenger RNA and transfer RNA are needed to make proteins.","Both are chains of nucleotides. A nucleotide is a sugar (deoxyribose in DNA, ribose in RNA), a nitrogen base and a phosphate group. DNA is a double helix; RNA is single-stranded.","Purines have a double ring: adenine and guanine. Pyrimidines have a single ring: thymine, cytosine and uracil. DNA uses A, T, G and C. RNA swaps uracil in for thymine. In DNA, A pairs with T and C pairs with G.","ATP (adenosine triphosphate) is the cell’s fuel: ribose + adenine + three phosphates, with energy stored in the second and third phosphate bonds. ADP + phosphate + energy makes ATP; breaking ATP back to ADP releases energy for repair, reproduction, assimilation and transport."],"mnemonic":{"cue":"Pure As Gold; CUT the Py","explanation":"Purines are Adenine and Guanine. Pyrimidines are Cytosine, Uracil and Thymine."},"act":{"type":"sort","prompt":"Sort the bases.","categories":["Purines (double ring)","Pyrimidines (single ring)"],"items":[{"label":"Adenine","category":0,"feedback":"Purine."},{"label":"Guanine","category":0,"feedback":"Purine."},{"label":"Thymine","category":1,"feedback":"Pyrimidine, DNA only."},{"label":"Cytosine","category":1,"feedback":"Pyrimidine."},{"label":"Uracil","category":1,"feedback":"Pyrimidine, RNA only."}]}},{"id":"ap2-14","chapter":"Diffusion","title":"Diffusion","teach":["Diffusion is the movement of molecules from an area of high concentration to an area of low concentration. Open a perfume bottle and the molecules randomly collide with air molecules until they spread through the room. These random collisions are called Brownian movement.","Temperature affects diffusion: the higher the temperature, the faster molecules move.","In the lungs, oxygen diffuses from the air (high) into the blood (low), and carbon dioxide diffuses from the blood (high) into the lungs (low) to be breathed out."],"act":{"type":"choice","prompt":"What happens to the rate of diffusion as temperature rises?","options":[{"label":"It speeds up","correct":true,"feedback":"Right. Heat makes molecules move faster."},{"label":"It slows down","correct":false,"feedback":"The textbook says higher temperature means faster movement."},{"label":"It doesn’t change","correct":false,"feedback":"Temperature does affect diffusion."}]}},{"id":"ap2-15","chapter":"Osmosis and tonicity","title":"Osmosis and tonicity","teach":["The plasma membrane is selectively permeable: it lets only some materials through. Materials cross it in three ways: diffusion, osmosis and active transport.","Osmosis is a special kind of diffusion: the movement of water only, across a selectively permeable membrane, from where water is more concentrated (fewer solutes) to where it’s less concentrated (more solutes).","Red blood cells show it clearly. In an isotonic solution (normal saline), salt inside and outside is equal, so the cell keeps its shape. In a hypotonic solution (pure water), water rushes in and the cell swells and bursts. In a hypertonic solution (5% salt), water leaves and the cell shrivels (crenates).","Proteins in blood can’t leave the capillaries, so they create osmotic pressure that pulls most escaped fluid back in."],"visual":{"kind":"flow","title":"A red blood cell in three solutions","items":[{"label":"Isotonic","detail":"Equal concentration. No change in shape."},{"label":"Hypotonic","detail":"Less solute outside. Water moves in; the cell swells and can burst."},{"label":"Hypertonic","detail":"More solute outside. Water moves out; the cell shrivels."}]},"mnemonic":{"cue":"HypO: the cell swells like an O","explanation":"In a hypotonic solution the cell takes on water and swells. In a hypertonic one it shrinks."},"act":{"type":"sort","prompt":"What happens to a red blood cell in each solution?","categories":["Isotonic","Hypotonic","Hypertonic"],"items":[{"label":"Normal saline","category":0,"feedback":"Same salt concentration as the cell."},{"label":"Distilled water","category":1,"feedback":"Water moves in and the cell can burst."},{"label":"5% salt solution","category":2,"feedback":"Water moves out and the cell shrivels."},{"label":"The cell shrivels","category":2,"feedback":"That’s a hypertonic solution."},{"label":"The cell swells","category":1,"feedback":"That’s a hypotonic solution."}]}},{"id":"ap2-16","chapter":"Active transport","title":"Active transport","teach":["Diffusion and osmosis can’t bring in everything a cell needs. Sugars, amino acids, larger proteins and fats often have to be moved against a concentration gradient, from low concentration to high.","This is active transport, and it needs energy in the form of ATP. It’s the main way most cells get the materials they need."],"act":{"type":"sort","prompt":"Does the process need energy (ATP)?","categories":["Needs ATP","No ATP needed"],"items":[{"label":"Active transport","category":0,"feedback":"It moves materials against the gradient."},{"label":"Diffusion","category":1,"feedback":"Molecules move down the gradient on their own."},{"label":"Osmosis","category":1,"feedback":"Water moves down its gradient on its own."}]}},{"id":"ap2-17","chapter":"pH, acids, bases and buffers","title":"pH, acids, bases and buffers","teach":["pH measures hydrogen ion (H⁺) concentration. Pure water splits into equal H⁺ and OH⁻, so its pH is 7: neutral.","An acid releases extra H⁺ in water and has a pH below 7. A base (alkali) combines with H⁺ and has a pH above 7. The scale is logarithmic, so each step is a tenfold change: lemon juice (pH 2) is 100 times more acidic than tomato juice (pH 4).","In the body: stomach acid is near pH 1, urine about 6, saliva just under 7, and blood 7.4 (slightly basic).","Enzymes are very sensitive to pH, so the body uses buffers: substances that release H⁺ when levels fall and take it up when levels rise. The key blood buffer is carbonic acid and bicarbonate."],"visual":{"kind":"flow","title":"Body fluids on the pH scale","items":[{"label":"Stomach, pH ~1","detail":"Very acidic."},{"label":"Urine, pH ~6","detail":"Slightly acidic."},{"label":"Pure water, pH 7","detail":"Neutral."},{"label":"Blood, pH 7.4","detail":"Slightly basic."}]},"act":{"type":"number","prompt":"Lemon juice is pH 2 and tomato juice is pH 4. How many times more acidic is lemon juice?","answer":100,"tolerance":0,"unit":"times","explanation":"Each pH step is a tenfold change. Two steps is 10 × 10 = 100 times."}}],"flashcards":[{"front":"Atom","back":"Smallest particle of an element that keeps its properties and reacts through its electrons."},{"front":"Proton / neutron / electron","back":"Positive, in nucleus / no charge, in nucleus / negative, orbits nucleus."},{"front":"Element","back":"A substance whose atoms all have the same number of protons and electrons."},{"front":"Isotope","back":"Same element (same protons), different number of neutrons."},{"front":"Atomic number","back":"The number of protons (or electrons) in an atom."},{"front":"Compound","back":"Atoms of two or more different elements bonded together."},{"front":"Ionic bond","back":"One atom gains electrons and another loses them; opposite ions attract. Dissociates in water."},{"front":"Covalent bond","back":"Atoms share electrons. Doesn’t dissociate in water."},{"front":"Hydrogen bond","back":"Weak bond that holds water molecules together and shapes proteins."},{"front":"Ion","back":"A charged atom. Gaining electrons makes it negative; losing them makes it positive."},{"front":"Water in cells","back":"60–80% of a cell; polar; the universal solvent."},{"front":"Ammonia","back":"Toxic waste from protein breakdown; the liver turns it into urea."},{"front":"Carbohydrate ratio","back":"C:H:O in a 1:2:1 ratio."},{"front":"Triacylglycerol","back":"Glycerol + fatty acids; 95% of body fat."},{"front":"Saturated vs unsaturated fat","back":"Single bonds only, solid / one or more double bonds, liquid."},{"front":"Peptide bond","back":"Covalent bond joining amino acids into a protein."},{"front":"Enzyme","back":"A protein catalyst that speeds up a reaction without being changed."},{"front":"Purines","back":"Adenine and guanine (double ring)."},{"front":"Pyrimidines","back":"Thymine, cytosine and uracil (single ring)."},{"front":"RNA vs DNA bases","back":"RNA uses uracil instead of thymine."},{"front":"ATP","back":"Ribose + adenine + 3 phosphates; the cell’s fuel."},{"front":"Diffusion","back":"Molecules move from high to low concentration."},{"front":"Osmosis","back":"Water moves across a selectively permeable membrane toward the side with more solute."},{"front":"Isotonic / hypotonic / hypertonic","back":"No change / cell swells / cell shrivels."},{"front":"Active transport","back":"Moving materials against a concentration gradient, using ATP."},{"front":"pH 7","back":"Neutral. Below 7 is acidic; above 7 is basic."},{"front":"Buffer","back":"Releases or takes up H⁺ to keep pH steady. Blood: carbonic acid/bicarbonate."}],"quiz":[{"q":"What is formed when two or more different elements combine by sharing electrons?","o":["proton","chemical","ion","compound"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says that when atoms of two or more different elements combine by transferring or sharing electrons, a compound is created. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What kind of bond is formed when one atom gains an electron and another atom loses an electron?","o":["ionic","covalent","hydrogen","molecular"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says an ionic bond forms when one atom gains electrons while the other loses electrons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Which nucleotide is found in RNA but not in DNA?","o":["guanine","adenine","thymine","uracil"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says RNA substitutes uracil for thymine. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The covalent bonds that are formed between different amino acids to form a protein are known as _______________________________.","o":["peptide bonds","ionic bonds","hydrogen bonds","electrolyte bonds"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says the covalent bonds that form between amino acids to make proteins are called peptide bonds. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The type of transport that requires energy input is called ________________________.","o":["passive transport","diffusion","osmosis","active transport"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says active transport needs energy in the form of ATP to move materials against a concentration gradient. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"A solution with a pH of 3 is called a(n) _______________________.","o":["acid","base","ion","solute"],"a":0,"e":"Checked answer, not from an official key. Acids have pH values below 7, so a solution with a pH of 3 is an acid. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The basic building blocks of proteins are ______________________.","o":["triglycerides","monosaccharides","amino acids","nucleotides"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says the basic building blocks of proteins are 20 amino acids. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What are the smallest particles of an element?","o":["atoms","molecules","compounds","cells"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says atoms are the smallest particles of an element that keep all its characteristics. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The compact central nucleus of an atom contains _______________ and ________________.","o":["electrons; protons","electrons; neutrons","protons; neutrons","electrons; isotopes"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says each atom has a compact central nucleus made of protons and neutrons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"What element is found in all living matter?","o":["nitrogen","carbon","lithium","oxygen"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says carbon is the element found in all living matter. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"In an atom, __________________ orbit the nucleus?","o":["protons","electrons","neutrons","isotopes"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says the lighter electrons orbit the nucleus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"When the solute concentration outside a red blood cell equals the solute concentration inside the cell, the solution is called _____________________.","o":["hypotonic","osmotic","hypertonic","isotonic"],"a":3,"e":"Checked answer, not from an official key. Chapter 2 says that in an isotonic solution (normal saline) the salt concentration outside the red blood cell equals the concentration inside. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Distilled water has a pH of 7 and is therefore _______________________.","o":["acidic","basic","neutral","ionic"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 says distilled water has a pH of 7, which indicates neutrality. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Which type of chemical bond holds water molecules together by forming a bridge between the negative oxygen atom of one water molecule and the positive hydrogen atoms of another water molecule?","o":["isotopic","hydrogen","ionic","covalent"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 describes hydrogen bonds as a bridge between the negative oxygen of one water molecule and the positive hydrogens of another. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"DNA and RNA are examples of _____________________.","o":["proteins","lipids","nucleic acids","carbohydrates"],"a":2,"e":"Checked answer, not from an official key. Chapter 2 names DNA and RNA as the two important nucleic acids in cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Isotopes are atoms of the same element that have different numbers of neutrons but the same number or protons.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says isotopes are atoms of the same element with different numbers of neutrons. Same element means the same number of protons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Atoms that gain electrons become negatively charged.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says atoms that gain electrons become negatively charged. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"An element is a substance whose atoms all contain the same number of neutrons.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 defines an element by the same number of protons and electrons, not neutrons. Atoms with different numbers of neutrons are isotopes of the same element. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"Temperature has no effect on diffusion rate.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 2 says the higher the temperature, the faster the movement of diffusing molecules. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."},{"q":"The two purine nitrogen bases are adenine and guanine.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 2 says the two purine nitrogen bases are adenine and guanine. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 2."}],"caseStudy":{"title":"A cell placed in a new solution","scenario":"A teaching model shows identical cells placed into three unlabeled solutions. One swells, one retains its volume and one shrinks.","prompts":["Classify each surrounding solution as hypotonic, isotonic or hypertonic.","Explain the direction of net water movement without saying that solute itself must cross.","Identify one reason a real cell may respond differently from a simplified model."],"takeaway":"Predicting transport requires the gradient, membrane permeability and the identity of the moving substance—not a memorized arrow alone."},"perStepChapter":true},{"n":3,"title":"Cell Structure","kicker":"Lesson 3 of your course, built from Chapter 3 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"75–95 minutes","steps":[{"id":"ap3-1","chapter":"The cell and its parts","title":"The cell and its parts","teach":["The cell is the basic unit of biologic organization; your body is made of trillions of them. Every cell is protoplasm (a watery mix of carbohydrates, proteins, lipids, nucleic acids and salts) surrounded by a cell membrane. Structures inside it are organelles.","Protoplasm inside the nucleus is nucleoplasm; protoplasm outside it is cytoplasm.","Human cells are eukaryotic (\"true\" nucleus): they have membrane-bound organelles. Prokaryotic cells, like bacteria, don’t.","Most cells are 10 to 100 micrometers across (a micrometer is a thousandth of a millimeter). Light microscopes magnify 10× to 1000×; seeing fine detail takes an electron microscope."],"act":{"type":"choice","prompt":"What makes a cell eukaryotic?","options":[{"label":"It has membrane-bound organelles, including a true nucleus","correct":true,"feedback":"Right. Human cells are eukaryotic; bacteria are prokaryotic."},{"label":"It has a cell wall","correct":false,"feedback":"Plant cells have walls, but that isn’t what makes a cell eukaryotic."},{"label":"It has no nucleus","correct":false,"feedback":"That describes a prokaryotic cell."}]}},{"id":"ap3-2","chapter":"Discovering cells and the cell theory","title":"Discovering cells and the cell theory","teach":["Robert Hooke first described cells in 1665, looking at dead cork. The empty walls looked like little rooms, so he called them cellulae. Antonie van Leeuwenhoek soon saw living \"animalcules\" in pond water.","In 1838 Matthias Schleiden (a botanist) said all plants are made of cells, and in 1839 Theodor Schwann (a zoologist) said the same of animals. That laid the foundation of the cell theory.","The modern cell theory: cells are the basic units of organization of all organisms; all organisms are made of one or more cells; cells arise only from preexisting cells by cell division; and all cells today descend from the first cells on earth."],"act":{"type":"sort","prompt":"Match each person to what they did.","categories":["Hooke","Leeuwenhoek","Schleiden","Schwann"],"items":[{"label":"Named cells after looking at cork (1665)","category":0,"feedback":"Robert Hooke."},{"label":"Saw living \"animalcules\" in pond water","category":1,"feedback":"Antonie van Leeuwenhoek."},{"label":"All plants are made of cells (1838)","category":2,"feedback":"Matthias Schleiden, a botanist."},{"label":"All animals are made of cells (1839)","category":3,"feedback":"Theodor Schwann, a zoologist."}]}},{"id":"ap3-3","chapter":"The cell membrane","title":"The cell membrane","teach":["The cell (plasma) membrane is a double layer of phospholipids with proteins embedded in it. Each phospholipid has a water-attracting (hydrophilic) head and water-repelling (hydrophobic) tails. Water passes through easily by osmosis.","The proteins do many jobs: channels for small ions, pumps for active transport (using ATP), receptor sites for hormones, identity markers, \"cement\" that holds cells together, and anchors for the cytoskeleton. The sodium-potassium pump in muscle and nerve cells is made of protein.","This arrangement is called the fluid mosaic model: the pieces are like mosaic tiles set in a fluid rather than solid cement. Every membrane-bound organelle has the same basic structure."],"visual":{"kind":"hub","title":"Jobs of membrane proteins","items":[{"label":"Channels","detail":"Let small dissolved ions through."},{"label":"Pumps","detail":"Active transport against a gradient, using ATP."},{"label":"Receptors","detail":"Binding sites for hormones."},{"label":"Identity markers","detail":"Tell the body which cells are \"self\"."},{"label":"Adhesion and support","detail":"Hold cells together and anchor the cytoskeleton."}]},"act":{"type":"choice","prompt":"The cell membrane’s structure is described as:","options":[{"label":"A fluid mosaic: a double phospholipid layer with proteins embedded in it","correct":true,"feedback":"Right."},{"label":"A rigid wall of cellulose","correct":false,"feedback":"That’s a plant cell wall."},{"label":"A single layer of protein","correct":false,"feedback":"It’s a double layer of phospholipids with proteins in it."}]}},{"id":"ap3-4","chapter":"Cytoplasm: solutions and colloids","title":"Cytoplasm: solutions and colloids","teach":["Cytoplasm is mostly water, with RNA, enzymes, hormones and other chemicals in it. Some are in solution and some are in colloidal suspension.","In a solution, individual atoms or ions are spread through the water. In a colloid, clumps of atoms are spread through it.","Which one a substance forms depends on polarity. Water is polar. Polar compounds, like ionically bonded salts, dissolve readily. Nonpolar compounds (covalent molecules that share electrons evenly) don’t dissolve readily. So mineral salts (sodium, potassium, calcium, chlorine, phosphorus) are in solution, while proteins, carbohydrates, fats and nucleic acids are in colloidal suspension.","Cytoplasm also holds storage granules, fat droplets and vacuoles (membrane-bound spaces holding water, food or waste)."],"act":{"type":"sort","prompt":"In the cytoplasm, is each substance in solution or in a colloid?","categories":["Solution (individual ions)","Colloid (clumps of atoms)"],"items":[{"label":"Sodium","category":0,"feedback":"Mineral salts dissolve."},{"label":"Potassium","category":0,"feedback":"Mineral salts dissolve."},{"label":"Proteins","category":1,"feedback":"Large nonpolar organic molecules are colloidal."},{"label":"Fats","category":1,"feedback":"Nonpolar, so colloidal."},{"label":"Nucleic acids","category":1,"feedback":"Colloidal."},{"label":"Calcium","category":0,"feedback":"Mineral salt, in solution."}]}},{"id":"ap3-5","chapter":"The nucleus","title":"The nucleus","teach":["The nucleus is the control center of the cell. Remove it and the cell loses its functions; transplant a nucleus and the cell takes on the donor’s characteristics.","The nuclear membrane (envelope) is a double membrane. The outer membrane connects to the endoplasmic reticulum. It has pores that let materials such as messenger RNA leave for the cytoplasm.","Stained, the nucleus shows dark threads of chromatin, the genetic material. During cell division the DNA duplicates, shortens and thickens into visible chromosomes. Chromosomes are made of DNA and proteins.","Human body cells have 46 chromosomes (22 pairs of autosomes plus one pair of sex chromosomes). Egg and sperm cells have 23.","The nucleolus is a round body with no membrane, made mostly of DNA, RNA and protein. It makes ribosomes."],"keyPoints":["46 chromosomes in body cells; 23 in egg and sperm","Chromatin when not dividing; chromosomes when dividing","Nucleolus makes ribosomes"],"act":{"type":"choice","prompt":"What does the nucleolus do?","options":[{"label":"Makes ribosomes","correct":true,"feedback":"Right. That’s how it supports protein synthesis."},{"label":"Makes ATP","correct":false,"feedback":"That’s the mitochondria."},{"label":"Packages secretions","correct":false,"feedback":"That’s the Golgi apparatus."}]}},{"id":"ap3-6","chapter":"Mitochondria","title":"Mitochondria","teach":["Mitochondria are small oblong organelles with two membranes. The inner membrane folds into cristae, which give lots of surface for energy reactions.","Cellular respiration (its aerobic phase) happens on the cristae, turning the chemical energy in food into ATP: glucose + oxygen → ATP + carbon dioxide + water. That’s why mitochondria are called the powerhouses of the cell.","High-energy cells like muscle have mitochondria with many cristae; low-energy cells like cheek lining have fewer. Mitochondria have their own DNA and are inherited from the mother through the egg."],"act":{"type":"choice","prompt":"Why do muscle cells have mitochondria with many cristae?","options":[{"label":"More folds mean more surface for making ATP, and muscle needs a lot of energy","correct":true,"feedback":"Right."},{"label":"Cristae store calcium for contraction","correct":false,"feedback":"Cristae are where ATP is made."},{"label":"Muscle cells have no nucleus","correct":false,"feedback":"That isn’t the reason."}]}},{"id":"ap3-7","chapter":"Lysosomes","title":"Lysosomes","teach":["Lysosomes are small, usually round bodies filled with powerful digestive enzymes. They have three jobs.","They fuse with food vacuoles to break stored food into usable pieces (starch to sugars, protein to amino acids, fat to fatty acids and glycerol). They break down worn-out parts so the material can be recycled. And they act as \"suicide agents\" in old or weak cells, releasing their enzymes to destroy the cell. This is autolysis."],"act":{"type":"choice","prompt":"Autolysis is when:","options":[{"label":"A lysosome releases its enzymes and destroys an old or weak cell","correct":true,"feedback":"Right."},{"label":"A cell divides into two","correct":false,"feedback":"That’s cell division."},{"label":"A ribosome builds a protein","correct":false,"feedback":"That’s protein synthesis."}]}},{"id":"ap3-8","chapter":"Endoplasmic reticulum and Golgi apparatus","title":"Endoplasmic reticulum and Golgi apparatus","teach":["The endoplasmic reticulum (ER) is a network of membrane-bound channels called cisternae, used to store and transport what the cell makes. It connects to the outer nuclear membrane and to the cell membrane.","Rough (granular) ER has ribosomes attached, so it’s a site of protein synthesis, especially proteins the cell will secrete. All cells have it.","Smooth (agranular) ER has no ribosomes and is found only in some cells: in the gonads, where it makes sex hormones, and in the intestinal lacteals, where it helps transport fats.","The Golgi apparatus is a stack of flat sacs, like pancakes. It’s where compounds the cell will secrete are collected and concentrated, a bit like a warehouse. It makes carbohydrates to combine with proteins, and lysosomes can form there. It also makes the cellulose of plant cell walls."],"act":{"type":"sort","prompt":"Rough ER, smooth ER or Golgi?","categories":["Rough ER","Smooth ER","Golgi apparatus"],"items":[{"label":"Has ribosomes attached","category":0,"feedback":"That’s what makes it rough."},{"label":"Makes sex hormones in the gonads","category":1,"feedback":"Smooth ER."},{"label":"Collects and concentrates secretions","category":2,"feedback":"The Golgi is the cell’s warehouse."},{"label":"Helps transport fats in intestinal lacteals","category":1,"feedback":"Smooth ER."},{"label":"Looks like a stack of pancakes","category":2,"feedback":"Flat sac-like cisternae."},{"label":"Found in all cells","category":0,"feedback":"All cells have rough ER; only some have smooth ER."}]}},{"id":"ap3-9","chapter":"Ribosomes and protein synthesis","title":"Ribosomes and protein synthesis","teach":["Ribosomes are tiny granules made of ribosomal RNA and protein, with no membrane. They float in the cytoplasm or sit on rough ER, and they’re where proteins are made.","The code for a protein is a gene on DNA in the nucleus. In transcription, messenger RNA (mRNA) copies the code with the help of the enzyme RNA polymerase, then leaves through a nuclear pore to a ribosome.","In translation, transfer RNA (tRNA) brings amino acids from the cytoplasm. Each tRNA has three bases called an anticodon, which matches three bases on the mRNA called a codon. The ribosome links the amino acids into a polypeptide chain."],"visual":{"kind":"flow","title":"From gene to protein","items":[{"label":"Gene on DNA","detail":"The code, in the nucleus."},{"label":"Transcription","detail":"mRNA copies the code (RNA polymerase helps)."},{"label":"mRNA leaves","detail":"Through a nuclear pore to a ribosome."},{"label":"Translation","detail":"tRNA anticodons match mRNA codons, bringing amino acids."},{"label":"Protein","detail":"The ribosome links amino acids into a chain."}]},"mnemonic":{"cue":"Transcription = copy (in the nucleus); Translation = build (in the cytoplasm)","explanation":"You transcribe notes word for word; you translate them into a new language: amino acids."},"act":{"type":"order","prompt":"Put the steps of protein synthesis in order.","items":[{"label":"mRNA copies a gene in the nucleus","detail":"Transcription"},{"label":"mRNA leaves through a nuclear pore","detail":"Goes to a ribosome"},{"label":"tRNA brings amino acids","detail":"Anticodon matches codon"},{"label":"The ribosome links the amino acids","detail":"Forms a polypeptide chain"}]}},{"id":"ap3-10","chapter":"Centrioles, cilia and flagella","title":"Centrioles, cilia and flagella","teach":["Centrioles are a pair of cylinders at right angles near the nucleus (together, the centrosome). Each is nine sets of triplet fibers. During cell division they move to opposite poles and form spindle fibers (microtubules of tubulin) that guide the duplicated chromosomes into the new cells.","Cilia and flagella are hair-like projections that beat. Cilia are short and come in rows; in the airway they sweep mucus and trapped dust up to the throat. A flagellum is long and there are only one to a few; the sperm cell uses one to swim.","Inside, both have nine double fibrils in a ring around two central ones (the \"9 + 2\" pattern), growing from a basal body built like a centriole."],"act":{"type":"sort","prompt":"Centrioles, cilia or flagellum?","categories":["Centrioles","Cilia","Flagellum"],"items":[{"label":"Form spindle fibers in cell division","category":0,"feedback":"Centrioles."},{"label":"Sweep mucus up the airway","category":1,"feedback":"Rows of short cilia."},{"label":"Propels the sperm cell","category":2,"feedback":"A single long flagellum."},{"label":"Nine sets of triplet fibers","category":0,"feedback":"Centriole structure."}]}},{"id":"ap3-11","chapter":"Plant cells: plastids and the cell wall","title":"Plant cells: plastids and the cell wall","teach":["Your course also compares plant and animal cells. Plant cells have a cell wall and plastids; animal cells don’t.","Chloroplasts are large plastids containing green chlorophyll. They are the site of photosynthesis, which turns light energy into chemical energy (glucose). Inside are stacks of membranes; each stack is a granum, made of thylakoids, and the grana are linked by lamellae.","Chromoplasts hold other pigments: xanthophyll (yellow) and carotene (red-orange). Leucoplasts have no pigment and store food, like sugar in onions and starch in potatoes.","The cell wall is made of cellulose, made by the Golgi. We can’t digest it; in our diet it’s fiber."],"act":{"type":"sort","prompt":"Which plastid?","categories":["Chloroplast","Chromoplast","Leucoplast"],"items":[{"label":"Site of photosynthesis","category":0,"feedback":"Chloroplasts contain chlorophyll."},{"label":"Yellow xanthophyll in a banana peel","category":1,"feedback":"Chromoplasts hold carotenoid pigments."},{"label":"Stores starch in a potato","category":2,"feedback":"Leucoplasts are storage plastids."},{"label":"Contains stacks called grana","category":0,"feedback":"Grana are inside chloroplasts."},{"label":"Red-orange carotene in carrots","category":1,"feedback":"Chromoplast."}]}},{"id":"ap3-12","chapter":"Apoptosis and aging","title":"Apoptosis and aging","teach":["Apoptosis is a natural, gene-controlled process by which cells die. It removes damaged cells, cells past their lifespan, infected cells and some cancer cells.","With age, repairing cells and replacing them by division gets harder. Some biologists think \"death genes\" switch on later in life."],"act":{"type":"choice","prompt":"Apoptosis is:","options":[{"label":"A natural, gene-controlled process of cell death","correct":true,"feedback":"Right."},{"label":"A type of cell division","correct":false,"feedback":"It’s cell death, not division."},{"label":"Always caused by infection","correct":false,"feedback":"It’s a normal process that also removes old and damaged cells."}]}}],"flashcards":[{"front":"Protoplasm","back":"Watery colloidal solution inside the cell membrane."},{"front":"Nucleoplasm / cytoplasm","back":"Protoplasm inside / outside the nucleus."},{"front":"Eukaryotic vs prokaryotic","back":"Has membrane-bound organelles / doesn’t (e.g., bacteria)."},{"front":"Modern cell theory","back":"Cells are the basic units of life; all organisms are cells; cells come only from preexisting cells; all cells descend from the first cells."},{"front":"Schleiden and Schwann","back":"Founded the cell theory (plants 1838, animals 1839)."},{"front":"Fluid mosaic model","back":"Double phospholipid layer with embedded proteins."},{"front":"Solution vs colloid","back":"Individual atoms or ions spread out / clumps of atoms spread out."},{"front":"Polar vs nonpolar","back":"Dissolves readily in water / doesn’t dissolve readily."},{"front":"Nucleus","back":"Control center; double membrane with pores."},{"front":"Chromatin vs chromosomes","back":"Long thin DNA threads / shortened, thickened DNA during division."},{"front":"Human chromosome number","back":"46 in body cells; 23 in egg and sperm."},{"front":"Nucleolus","back":"Membrane-free body in the nucleus that makes ribosomes."},{"front":"Mitochondria","back":"Powerhouses; aerobic respiration on the cristae makes ATP."},{"front":"Lysosomes","back":"Digestive enzymes: digest food, recycle parts, destroy old cells (autolysis)."},{"front":"Rough ER","back":"Has ribosomes; makes proteins for secretion."},{"front":"Smooth ER","back":"No ribosomes; sex hormones and fat transport."},{"front":"Golgi apparatus","back":"Stacked sacs that collect and concentrate secretions."},{"front":"Ribosomes","back":"rRNA + protein granules; sites of protein synthesis."},{"front":"Transcription","back":"mRNA copies a gene’s code in the nucleus."},{"front":"Translation","back":"tRNA brings amino acids to the mRNA at the ribosome."},{"front":"Codon / anticodon","back":"Three bases on mRNA / matching three bases on tRNA."},{"front":"Gene","back":"A region of DNA with the code for a particular protein."},{"front":"Centrioles","back":"Form spindle fibers that move chromosomes during division."},{"front":"Cilia vs flagella","back":"Short, many, move material / long, few, move the cell."},{"front":"Chloroplast","back":"Plastid with chlorophyll; site of photosynthesis; contains grana."},{"front":"Leucoplast","back":"Colorless plastid that stores food."},{"front":"Apoptosis","back":"Natural, gene-controlled cell death."}],"quiz":[{"q":"Clumps of atoms that are distributed throughout a water medium are referred to as a _________________.","o":["solution","compound","colloid","solute"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says in a colloid, clumps of atoms rather than individual atoms are distributed throughout the water. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Chromosomes are made of ________ molecules and proteins.","o":["DNA","RNA","lipids","ATP"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says chromosomes are made of DNA molecules and proteins. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Large organelles found mainly in plant cells that are the site of photosynthesis are known as __________________________.","o":["nuclei","mitochondria","chloroplasts","thylakoids"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says chloroplasts are large organelles found mainly in plant cells and are the site of photosynthesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which structures form the spindle fibres during cell division and guide the duplicated chromosomes to their daughter cells?","o":["nucleoli","mitochondria","centrioles","lysosomes"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says the centrioles form the spindle fibers during cell division and guide the duplicated chromosomes to their daughter cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"What are the basic units of organization of all organisms?","o":["Organelles","Organs","Molecules","Cells"],"a":3,"e":"Checked answer, not from an official key. The modern cell theory in Chapter 3 says cells are the basic units of organization of all organisms. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Chemical energy from food is converted to another form of chemical energy called ______________ in the mitochondria.","o":["ATP","glycogen","glucose","RNA"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says cellular respiration on the cristae converts food (chemical energy) into ATP. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Sodium, potassium, calcium, chlorine, and phosphorus are all examples of ___________________.","o":["proteins","carbohydrates","lipids","mineral salts","None of the above"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 lists sodium, potassium, calcium, chlorine and phosphorus as the mineral salts that are in solution in the cytoplasm. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The process of translation occurs in the _________________.","o":["nucleus","nucleolus","cytoplasm","smooth ER","None of the above"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says tRNA collects amino acids in the cytoplasm and brings them to the mRNA at the ribosomes, which are in the cytoplasm. That process is translation. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of compound does not dissolve readily in water?","o":["Polar","Sonic","Electrolytic","Nonpolar"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says nonpolar compounds do not dissolve readily in water. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of RNA has three nitrogen bases at one end that are known collectively as an anticodon?","o":["Ribosomal","Messenger","Lysosomal","Transfer"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says each tRNA is coded for an amino acid by three nitrogen bases at one end, known as the anticodon. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which type of plastids store food?","o":["Chloroplasts","Chromoplasts","Leucoplasts","Granum"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says leucoplasts have no pigment and are storage plastids. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The aerobic phase of cellular respiration occurs in which organelle?","o":["Ribosome","Lysosome","Nucleus","Mitochondrion"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says the aerobic phase of cellular respiration occurs in the mitochondrion. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Which term refers to the conversion of light energy into chemical energy?","o":["Dehydration Synthesis","Cellular Respiration","Hydrolysis","Photosynthesis"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 defines photosynthesis as the conversion of light energy into chemical energy. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The cells of the human body contain _____ chromosomes.","o":["40","46","36","42","22"],"a":1,"e":"Checked answer, not from an official key. Chapter 3 says the cells of the human body contain 46 chromosomes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"What type of RNA is used during the process of transcription?","o":["Ribosomal","Messenger","Transverse","Transfer"],"a":1,"e":"Checked answer, not from an official key. Chapter 3 says messenger RNA copies the code from DNA in a process called transcription. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The assembly of flat saclike cisternae where compounds to be secreted by the cell are collected and concentrated is called the _________________________________.","o":["mitochondrion","smooth ER","Golgi apparatus","lysosome"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 describes the Golgi apparatus as flat sac-like cisternae where compounds to be secreted are collected and concentrated. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The cell wall of plant cells is composed of ______________________.","o":["cellulose","lipid","protein","nucleic acid","chloroplasts"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says the plant cell wall is made of a complex carbohydrate called cellulose. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"The many stacks of membranes found inside chloroplasts are known as _________________________.","o":["granum","cristae","chlorophyll","xanthophyll","None of the above"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says a chloroplast contains many stacks of membranes, each called a granum. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"A region of DNA that contains instructions for the amino acid sequence of a particular protein is called a(n) __________________.","o":["codon","sugar","gene","anticodon"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says the code to make a particular protein is a gene on a DNA molecule. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Transcription occurs in what organelle?","o":["Ribosome","Lysosome","Mitochondrion","Nucleus"],"a":3,"e":"Checked answer, not from an official key. Chapter 3 says mRNA copies the code from the DNA molecule in the nucleus, which is transcription. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"DNA molecules that shorten and thicken during cell division are known as .","o":["chromatids","chromatin units","chromosomes","ribosomes"],"a":2,"e":"Checked answer, not from an official key. Chapter 3 says that when DNA duplicates during cell division it shortens and thickens and becomes visible as chromosomes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"In a colloid, individual atoms or ions are distributed throughout the medium.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. That describes a solution. In a colloid, clumps of atoms, not individual atoms or ions, are distributed through the medium. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Cells arise only from pre-existing cells through the process of cell division.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. This is one of the principles of the modern cell theory in Chapter 3. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Apoptosis is a natural process by which cells in the body die.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 3 says apoptosis is a natural process by which cells in the body die, controlled by specific genes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."},{"q":"Eukaryotic cells do not have membrane-bound organelles.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Eukaryotic cells do have membrane-bound organelles. Cells without them (like bacteria) are prokaryotic. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 3."}],"caseStudy":{"title":"Follow a secreted enzyme","scenario":"A glandular cell has been stimulated to release a protein enzyme. The gene is active, the cell has abundant rough ER and Golgi cisternae, and secretory vesicles are moving toward its plasma membrane.","prompts":["Trace the enzyme from DNA information to a finished product outside the cell.","Explain why this cell contains abundant rough ER, Golgi apparatus, and mitochondria.","Predict what would happen to delivery if vesicles could no longer move along cytoskeletal tracks.","Identify the membrane event that releases vesicle contents while preserving the cell boundary."],"takeaway":"A cellular product is the result of coordinated information flow, organelle processing, energy transfer, cytoskeletal transport, and membrane trafficking—not the action of one isolated structure."},"perStepChapter":true},{"n":4,"title":"Cellular Metabolism and Reproduction","kicker":"Lesson 4 of your course, built from Chapter 4 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"95–120 minutes","steps":[{"id":"ap4-1","chapter":"Metabolism: building up and breaking down","title":"Metabolism: building up and breaking down","teach":["Metabolism is all the chemical changes inside a cell. Anabolism uses energy to build large molecules from small ones. Catabolism breaks large molecules into small ones and releases energy.","Cells break down (catabolize) carbohydrates, fats and proteins step by step, and use the released energy (measured in calories) to make ATP from ADP and phosphate. ATP is the energy every cell process runs on.","All of this food energy starts with photosynthesis in plants, which turns light energy into glucose."],"mnemonic":{"cue":"Anabolism Adds, Catabolism Cuts","explanation":"Anabolic reactions build up and cost energy; catabolic reactions break down and release it."},"act":{"type":"sort","prompt":"Anabolism or catabolism?","categories":["Anabolism (builds, uses energy)","Catabolism (breaks down, releases energy)"],"items":[{"label":"Joining amino acids into a protein","category":0,"feedback":"Building a larger molecule."},{"label":"Breaking glucose down to make ATP","category":1,"feedback":"Breaking down releases energy."},{"label":"Storing glucose as glycogen","category":0,"feedback":"Linking glucose units builds a larger molecule."},{"label":"Digesting fat into fatty acids and glycerol","category":1,"feedback":"Breaking down."}]}},{"id":"ap4-2","chapter":"Cellular respiration: the big picture","title":"Cellular respiration: the big picture","teach":["Cellular (biochemical) respiration is the oxygen-requiring, or aerobic, way cells make ATP. It isn’t the same as breathing. Overall: glucose + 6 O₂ → 6 CO₂ + 6 H₂O + ATP.","Glucose is the most common substance broken down aerobically to make ATP. The process is continuous, but it’s taught in three steps: glycolysis in the cytoplasm, then the Krebs citric acid cycle and the electron transport system in the mitochondria."],"visual":{"kind":"flow","title":"Three steps of cellular respiration","items":[{"label":"Glycolysis","detail":"Cytoplasm. Doesn’t need oxygen. Glucose → 2 pyruvic acid."},{"label":"Krebs citric acid cycle","detail":"Mitochondria. Needs oxygen. Releases CO₂, loads NAD and FAD."},{"label":"Electron transport system","detail":"Mitochondrial cristae. Needs oxygen. Makes most of the ATP."}]},"act":{"type":"sort","prompt":"Where does each step happen?","categories":["Cytoplasm","Mitochondria"],"items":[{"label":"Glycolysis","category":0,"feedback":"Glycolysis is in the cytoplasm."},{"label":"Krebs citric acid cycle","category":1,"feedback":"In the mitochondria."},{"label":"Electron transport","category":1,"feedback":"On the cristae of the mitochondria."}]}},{"id":"ap4-3","chapter":"Glycolysis","title":"Glycolysis","teach":["Glycolysis is the first step for both aerobic and anaerobic breakdown of glucose. Because it doesn’t need oxygen, it’s sometimes called anaerobic respiration.","It costs 2 ATP to start (adding phosphates to glucose, called phosphorylation). The six-carbon sugar splits into two three-carbon PGAL molecules, which become PGA and then two pyruvic acid molecules, making 4 ATP. Net gain: 2 ATP.","Two NADH₂ are also made. If oxygen is present, they send their electrons through electron transport for 6 more ATP, so aerobic glycolysis gives 8 ATP in total. Anaerobic glycolysis gives only 2."],"act":{"type":"number","prompt":"Glycolysis uses 2 ATP to start and produces 4 ATP. What is the net gain?","answer":2,"tolerance":0,"unit":"ATP","explanation":"4 made minus the 2 paid back = 2 ATP. With oxygen, the 2 NADH₂ add 6 more, for 8."}},{"id":"ap4-4","chapter":"The Krebs citric acid cycle","title":"The Krebs citric acid cycle","teach":["With oxygen present, each pyruvic acid enters the mitochondria. In a transition step it loses a carbon as CO₂ and becomes acetyl-CoA. Hans Krebs described the cycle in 1937.","Acetyl-CoA joins oxaloacetic acid to make citric acid (the cycle’s name). Citric acid is broken down step by step (alpha-ketoglutaric acid, succinic acid, malic acid) back to oxaloacetic acid, releasing CO₂ and passing hydrogens to the carriers NAD and FAD.","Per pyruvic acid: 3 CO₂, 4 NADH₂, 1 FADH₂ and 1 ATP (as GTP). Each glucose makes two pyruvic acids, so double everything."],"act":{"type":"choice","prompt":"Where does the Krebs citric acid cycle take place?","options":[{"label":"In the mitochondria","correct":true,"feedback":"Right, on the cristae and in the matrix."},{"label":"In the cytoplasm","correct":false,"feedback":"That’s glycolysis."},{"label":"In the nucleus","correct":false,"feedback":"The nucleus holds DNA. Respiration happens in the mitochondria."}]}},{"id":"ap4-5","chapter":"Electron transport and the ATP total","title":"Electron transport and the ATP total","teach":["Most ATP is made in the electron transport system on the mitochondrial cristae. NAD and FAD hand on the electrons they collected. As electrons pass from carrier to carrier (NAD, FAD, quinone, cytochromes), they give up energy that’s used to make ATP.","Oxygen is the final electron acceptor. It takes the electrons and hydrogens and forms water. That’s why breaking down glucose needs oxygen.","Each NADH₂ yields 3 ATP and each FADH₂ yields 2. The textbook totals 38 ATP per glucose (or 36 ATP plus 2 GTP), capturing about 60% of glucose’s energy."],"goodToKnow":"Newer textbooks often give a lower total, about 30 to 32 ATP. For your course test, use the textbook’s 38.","act":{"type":"choice","prompt":"What is the final electron acceptor in electron transport?","options":[{"label":"Oxygen","correct":true,"feedback":"Right. Oxygen takes the electrons and forms water."},{"label":"NAD","correct":false,"feedback":"NAD is a carrier that passes electrons on."},{"label":"Carbon dioxide","correct":false,"feedback":"CO₂ is a waste product of the Krebs cycle."}]}},{"id":"ap4-6","chapter":"Without oxygen: fermentation and lactic acid","title":"Without oxygen: fermentation and lactic acid","teach":["Glucose can be broken down without oxygen in two situations. Both start with glycolysis and make only 2 ATP per glucose.","Fermentation happens in yeast. Pyruvic acid becomes CO₂ and acetaldehyde, which becomes ethyl alcohol. The CO₂ makes bread rise; the alcohol is used in beer and wine.","In human muscle, when exercise outpaces the oxygen supply, NADH₂ passes its hydrogens to pyruvic acid, forming lactic acid. Lactic acid builds up and causes short-term muscle fatigue. When oxygen returns, it’s converted back to pyruvic acid. The textbook calls this anaerobic respiration."],"act":{"type":"sort","prompt":"Fermentation (yeast) or anaerobic respiration in muscle?","categories":["Fermentation","Muscle (anaerobic)"],"items":[{"label":"Produces ethyl alcohol","category":0,"feedback":"Yeast fermentation makes alcohol."},{"label":"Produces lactic acid","category":1,"feedback":"Muscle makes lactic acid."},{"label":"Makes bread rise","category":0,"feedback":"The CO₂ from yeast does this."},{"label":"Causes temporary muscle fatigue","category":1,"feedback":"Lactic acid build-up."}]}},{"id":"ap4-7","chapter":"Other foods in the \"cellular furnace\"","title":"Other foods in the \"cellular furnace\"","teach":["We don’t only eat glucose. Other foods join respiration at the step that matches their structure.","Glucose is a simple carbohydrate. Starch, glycogen and other sugars enter where glucose does. Digestion breaks fat into fatty acids and glycerol: glycerol enters glycolysis at the PGA stage, and fatty acids enter the Krebs cycle. Proteins become amino acids, which enter at pyruvic acid or at different points in the Krebs cycle."],"act":{"type":"sort","prompt":"Where does each food piece enter?","categories":["Glycolysis","Krebs citric acid cycle"],"items":[{"label":"Glucose","category":0,"feedback":"Glucose starts glycolysis."},{"label":"Glycerol","category":0,"feedback":"Enters at the PGA stage."},{"label":"Fatty acids","category":1,"feedback":"Enter the Krebs cycle."},{"label":"Glutamic acid (amino acid)","category":1,"feedback":"Resembles alpha-ketoglutaric acid in the cycle."}]}},{"id":"ap4-8","chapter":"Discovering DNA","title":"Discovering DNA","teach":["Friedrich Miescher found DNA in 1869 and called it nuclein. In the 1920s P. A. Levine showed it contained phosphate, a five-carbon sugar and nitrogen bases.","In 1953 Rosalind Franklin’s X-ray photograph showed DNA was a helix. James Watson and Francis Crick used it to work out the full 3D structure and won the Nobel Prize in 1962 (with Maurice Wilkins). Franklin had died of cancer before then. Today all three are credited."],"act":{"type":"choice","prompt":"Whose X-ray work showed that DNA is a helix?","options":[{"label":"Rosalind Franklin","correct":true,"feedback":"Right."},{"label":"Friedrich Miescher","correct":false,"feedback":"Miescher first found DNA in 1869."},{"label":"Hans Krebs","correct":false,"feedback":"Krebs described the citric acid cycle."}]}},{"id":"ap4-9","chapter":"DNA structure and replication","title":"DNA structure and replication","teach":["DNA is the hereditary material of the cell. It controls which proteins are made, and so controls the cell’s chemistry.","It’s a double helix of nucleotides, like a spiral staircase: the handrails are sugar and phosphate, and the steps are base pairs. Adenine pairs with thymine (two hydrogen bonds); guanine pairs with cytosine (three). A purine always pairs with a pyrimidine.","A gene is a sequence of base pairs that codes for a protein. The Human Genome Project found about 3 billion base pairs coding over 30,000 genes (the textbook’s figures).","Before a cell divides, DNA replicates: helicase enzymes unzip the hydrogen bonds, and DNA polymerase adds new nucleotides to each strand."],"act":{"type":"sort","prompt":"Which base pairs with each one in DNA?","categories":["Pairs with thymine","Pairs with cytosine"],"items":[{"label":"Adenine","category":0,"feedback":"A–T, two hydrogen bonds."},{"label":"Guanine","category":1,"feedback":"G–C, three hydrogen bonds."}]}},{"id":"ap4-10","chapter":"The cell cycle and interphase","title":"The cell cycle and interphase","teach":["Cellular reproduction is how a single cell duplicates itself. The cell cycle has three main stages: interphase, mitosis and cytokinesis.","Interphase is the longest stage. It isn’t division, but the cell is very busy. The DNA is unwound and visible only as threads of chromatin. G1 is the main growth phase. In the S (synthesis) phase, DNA duplicates, so each chromosome becomes two sister chromatids joined at the centromere. In G2 the cell gets ready: centrioles start to separate, mitochondria replicate and tubulin is made.","Speed varies: embryo cells cycle in under 20 minutes, a typical mammal cell in about 24 hours. Liver cells divide only if damaged; nerve and muscle cells rarely divide."],"act":{"type":"order","prompt":"Put the phases of interphase in order.","items":[{"label":"G1","detail":"Main growth phase"},{"label":"S","detail":"DNA duplicates into sister chromatids"},{"label":"G2","detail":"Final preparation for division"}]}},{"id":"ap4-11","chapter":"Mitosis","title":"Mitosis","teach":["Mitosis divides the nucleus into two identical nuclei. The daughter cells are exact copies (clones) of the parent cell.","Prophase: chromosomes shorten and thicken and become visible as two sister chromatids joined at the centromere. Centrioles move to opposite poles and spindle fibers form. The nuclear membrane breaks down.","Metaphase: chromosomes line up on the equatorial (metaphase) plate. Anaphase, the shortest stage: centromeres divide and sister chromatids are pulled to opposite poles in a V shape. Telophase: chromosomes uncoil, the spindle breaks down and a nuclear membrane forms around each set."],"mnemonic":{"cue":"PMAT: Prophase, Metaphase, Anaphase, Telophase","explanation":"Metaphase = Middle, Anaphase = Apart, Telophase = Two nuclei."},"act":{"type":"order","prompt":"Put the stages of mitosis in order.","items":[{"label":"Prophase","detail":"Chromosomes appear; spindle forms; nuclear membrane breaks down"},{"label":"Metaphase","detail":"Chromosomes line up at the middle"},{"label":"Anaphase","detail":"Sister chromatids pulled apart"},{"label":"Telophase","detail":"Two new nuclei form"}]}},{"id":"ap4-12","chapter":"Cytokinesis","title":"Cytokinesis","teach":["Cytokinesis divides the cytoplasm to finish making two cells. It can start in anaphase.","In animal cells, a ring of actin filaments pinches the membrane inward, forming a cleavage furrow until the cell splits. Plant cells build a cell plate across the middle instead, which becomes a new cell wall."],"act":{"type":"choice","prompt":"In animal cells, the pinching-in of the membrane during cytokinesis is called a:","options":[{"label":"Cleavage furrow","correct":true,"feedback":"Right."},{"label":"Cell plate","correct":false,"feedback":"That’s how plant cells divide."},{"label":"Metaphase plate","correct":false,"feedback":"That’s where chromosomes line up in metaphase."}]}},{"id":"ap4-13","chapter":"Meiosis","title":"Meiosis","teach":["Sexual reproduction joins two gametes (sperm and egg) into a fertilized egg, or zygote, giving offspring more genetic variety. Gametes are made by meiosis, which happens only in the gonads (ovaries and testes).","Meiosis is a reduction division: body cells are diploid (2n, 46 chromosomes), and gametes are haploid (n, 23). Fertilization restores 46.","DNA duplicates once, but there are two divisions. In prophase I, matching (homologous) chromosomes pair up in synapsis, forming tetrads, and may swap segments: crossing-over, seen as an X-shaped chiasma. Meiosis I separates the pairs (46 to 23); meiosis II separates the sister chromatids. The result is four haploid cells."],"act":{"type":"sort","prompt":"Mitosis or meiosis?","categories":["Mitosis","Meiosis"],"items":[{"label":"Two identical daughter cells","category":0,"feedback":"Mitosis makes clones."},{"label":"Four cells, each with half the chromosomes","category":1,"feedback":"Meiosis is a reduction division."},{"label":"Crossing-over can happen","category":1,"feedback":"Only in prophase I of meiosis."},{"label":"Repairs a cut finger","category":0,"feedback":"Tissue repair is by mitosis."},{"label":"Happens only in the gonads","category":1,"feedback":"Meiosis makes gametes."},{"label":"One division","category":0,"feedback":"Meiosis has two."}]}},{"id":"ap4-14","chapter":"Making sperm and eggs","title":"Making sperm and eggs","teach":["The four cells from meiosis still have to mature. This is gametogenesis.","Spermatogenesis happens in the seminiferous tubules of the testes. All four cells become sperm: the nucleus becomes the head, mitochondria gather in the middle piece to power the tail, and the cytoplasm becomes the flagellum. It begins at puberty and continues into old age.","Oogenesis, the formation of the egg, happens in the ovary. The cytoplasm divides unequally, so only one functional egg forms. The smaller cells are polar bodies, which die. Meiosis begins in the female embryo, and egg production stops after menopause."],"act":{"type":"choice","prompt":"The first meiotic division of oogenesis makes one large cell and one small cell. The small cell is a:","options":[{"label":"Polar body","correct":true,"feedback":"Right. Polar bodies give their cytoplasm to the egg and then die."},{"label":"Sperm","correct":false,"feedback":"Sperm come from spermatogenesis in the testes."},{"label":"Zygote","correct":false,"feedback":"A zygote is a fertilized egg."}]}},{"id":"ap4-15","chapter":"When cell division goes wrong","title":"When cell division goes wrong","teach":["A mutation is a mistake in copying DNA, which can be caused by chemicals (smoke, asbestos), radiation, X-rays or some viruses. If it affects the genes that control division, cells keep dividing and form a tumor. Cells that spread and form tumors elsewhere are metastases.","Carcinomas come from epithelial tissue; sarcomas from connective tissue such as bone. Cancer-causing agents are carcinogens.","Chromosome and gene disorders in the chapter: Down syndrome is usually caused by an extra chromosome 21. Klinefelter’s syndrome affects males with extra X chromosomes, most often XXY. Tay-Sachs disease is an inherited recessive disorder of lipid metabolism. Progeria causes premature aging."],"act":{"type":"sort","prompt":"Match each term to its meaning.","categories":["Carcinogen","Carcinoma","Sarcoma","Metastasis"],"items":[{"label":"A cancer-causing agent","category":0,"feedback":"Like tobacco smoke or asbestos."},{"label":"A tumor from epithelial tissue","category":1,"feedback":"Carcinoma."},{"label":"A tumor from connective tissue, like bone","category":2,"feedback":"Sarcoma."},{"label":"A tumor that has spread to a new site","category":3,"feedback":"Metastasis."}]}},{"id":"ap4-16","chapter":"Aging and metabolism","title":"Aging and metabolism","teach":["With age, metabolism slows because less energy is needed for growth and maintenance, so calorie needs drop. Eating less and exercising daily help prevent the weight gain common from the early 40s.","Women stop producing eggs after menopause, but men keep producing sperm into their 80s."],"act":{"type":"choice","prompt":"Why do calorie needs fall with age, according to the textbook?","options":[{"label":"Metabolism slows because less energy is needed for growth and maintenance","correct":true,"feedback":"Right."},{"label":"Cells stop making ATP","correct":false,"feedback":"Cells always need ATP; they just need less overall."},{"label":"Mitochondria disappear","correct":false,"feedback":"That isn’t what the textbook says."}]}}],"flashcards":[{"front":"Metabolism","back":"All the chemical changes inside a cell."},{"front":"Anabolism / catabolism","back":"Builds large molecules, uses energy / breaks them down, releases energy."},{"front":"Cellular respiration equation","back":"Glucose + 6 O₂ → 6 CO₂ + 6 H₂O + ATP."},{"front":"Glycolysis","back":"In the cytoplasm; glucose → 2 pyruvic acid; net 2 ATP (8 with oxygen)."},{"front":"Krebs citric acid cycle","back":"In the mitochondria; breaks down acetyl-CoA, releasing CO₂ and loading NAD and FAD."},{"front":"Electron transport system","back":"On the cristae; makes most of the ATP; oxygen is the final electron acceptor."},{"front":"ATP per glucose (textbook)","back":"38 ATP (or 36 ATP + 2 GTP)."},{"front":"Fermentation","back":"Anaerobic breakdown of glucose by yeast; makes CO₂ and ethyl alcohol; 2 ATP."},{"front":"Lactic acid","back":"Made in muscle when oxygen runs short; causes temporary fatigue."},{"front":"Fat digestion products","back":"Fatty acids and glycerol."},{"front":"Watson, Crick and Franklin","back":"Credited with discovering DNA’s double helix (1953)."},{"front":"DNA base pairing","back":"A–T and G–C."},{"front":"Gene","back":"A sequence of base pairs that codes for a protein."},{"front":"Cell cycle stages","back":"Interphase, mitosis, cytokinesis."},{"front":"Interphase phases","back":"G1 (growth), S (DNA synthesis), G2 (preparation)."},{"front":"Centromere","back":"Where sister chromatids are joined."},{"front":"Mitosis stages","back":"Prophase, metaphase, anaphase, telophase."},{"front":"Cleavage furrow","back":"The pinching-in of the membrane in animal cytokinesis."},{"front":"Meiosis","back":"Reduction division in the gonads; four haploid cells."},{"front":"Haploid / diploid","back":"23 chromosomes (n) / 46 chromosomes (2n)."},{"front":"Crossing-over","back":"Exchange of DNA between homologous chromosomes in prophase I."},{"front":"Zygote","back":"A fertilized egg."},{"front":"Oogenesis / spermatogenesis","back":"Egg formation in the ovary / sperm formation in the testes."},{"front":"Polar body","back":"Small cell from unequal division in oogenesis; dies."},{"front":"Carcinogen","back":"A cancer-causing agent."},{"front":"Down syndrome","back":"Usually an extra chromosome 21."},{"front":"Klinefelter’s syndrome","back":"Males with extra X chromosomes, most often XXY."}],"quiz":[{"q":"The most common substance decomposed aerobically in cells to produce ATP is _________________________.","o":["glucose","protein","oxygen","water"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says the most common substance decomposed aerobically in cells to produce ATP is glucose. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the net gain of ATP molecules produced by glycolysis, the citric acid cycle, and the electron transport system for each glucose molecule?","o":["38","30","34","28"],"a":0,"e":"Checked answer, not from an official key. The textbook totals 38 ATP per glucose (or 36 ATP and 2 GTP) from glycolysis, the citric acid cycle and electron transport. Newer sources often say about 30 to 32, but this test follows the textbook. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The first step in the anaerobic breakdown of glucose into carbon dioxide gas and water is known as __________________________.","o":["hydrolysis","respiration","glycolysis","anabolism"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says the first step in breaking glucose down to carbon dioxide and water is glycolysis, which doesn’t need oxygen. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Which term refers to the breakdown of glucose in human muscle cells when oxygen is insufficient due to muscle fatigue?","o":["anaerobic respiration","aerobic respiration","fermentation","metabolism"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 calls the breakdown of glucose in muscle cells without enough oxygen anaerobic respiration. Fermentation is the yeast version. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Glucose is a simple ___________________________ .","o":["protein","nucleic acid","carbohydrate","lipid"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says glucose is a simple carbohydrate. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Males who have an extra X chromosome (47,XXY) have __________________________________ .","o":["Tay-Sachs disease","Down syndrome","carcinoma","Klinefelter’s syndrome"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says Klinefelter’s syndrome is caused by extra X chromosomes in males, most commonly XXY. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Biochemical respiration is the oxygen-requiring or process of ATP production.","o":["metabolism","anaerobic","aerobic","glycolysis"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says biochemical respiration is strictly the oxygen-requiring, or aerobic, process of ATP production. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Sister chromatids are attached to one another at the __________________________.","o":["spindle fiber","microtubule","aster","centromere"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says sister chromatids are attached to each other at the centromere. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"When we cut a finger, cells are repaired and replaced by __________________________.","o":["mitosis","meiosis","spermatogenesis","oogenesis"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says that when we cut a finger, the cells are repaired and replaced by mitosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Cancer-causing agents are called __________________________ .","o":["carcinomas","sarcomas","carcinogens","metastases"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says cancer-causing agents are called carcinogens. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The first meiotic division of oogenesis yields one large cell and one smaller cell called a(n) __________________________ .","o":["sperm","oocyte","polar body","daughter cell"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says unequal division in oogenesis makes smaller cells called polar bodies. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The Krebs citric acid cycle takes place in the __________________________ .","o":["nucleus","mitochondrion","ribosome","Golgi apparatus"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the Krebs citric acid cycle takes place in the mitochondria. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Most of the ATP produced during biochemical respiration is produced in the ______________________ system.","o":["glycolysis","carrier transport","electron transport","respiratory"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says most of the ATP made during biochemical respiration is produced in the electron transport system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the ultimate electron acceptor for the electrons captured by the cofactors during glucose decomposition?","o":["Nitrogen","Hydrogen","Oxygen","Carbon"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says oxygen is the ultimate electron acceptor for the electrons captured by the cofactors. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Digestion decomposes fat molecules into fatty acids and __________________________ .","o":["nucleic acid","glutamic acid","glucose","glycerol"],"a":3,"e":"Checked answer, not from an official key. Chapter 4 says digestion decomposes fat into fatty acids and glycerol. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Development of eggs in females is called __________________________.","o":["mitosis","oogenesis","spermatogenesis","cytogenesis"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the formation of the female egg is called oogenesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Unwound strands of chromosomes visible as threads in the nucleoplasm are called _______________________.","o":["nucleotides","chromatin","chromatids","centromere"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the unwound strands of chromosomes are visible only as dark threads called chromatin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The indentation of the cell membrane during cytokinesis is called a __________________________.","o":["cleavage furrow","prophase","cell plate","metaphase plate"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says animal cells separate by a pinching-in of the membrane called a cleavage furrow. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The process by which a single cell duplicates itself is known as __________________________ .","o":["cellular respiration","cellular reproduction","anaerobic respiration","aerobic respiration"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says cellular reproduction is the process by which a single cell duplicates itself. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"What is the hereditary material of the cell?","o":["RNA","protein","DNA","lipid"],"a":2,"e":"Checked answer, not from an official key. Chapter 4 says DNA is the hereditary material of the cell. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Which term refers to a fertilized egg?","o":["Gamete","Zygote","Sperm","Ovum"],"a":1,"e":"Checked answer, not from an official key. Chapter 4 says the sperm and egg unite to form a fertilized egg, or zygote. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The special kind of cellular reproduction that occurs only in gametes is known as mitosis.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The special division that makes gametes is meiosis, not mitosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"The formation of the female egg is called oogenesis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says the formation of the female egg is called oogenesis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Down syndrome is a congenital defect commonly caused by an extra copy of chromosome 21.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 4 says Down syndrome is a congenital defect commonly caused by an extra chromosome 21. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."},{"q":"Fermentation in yeast cells is a type of aerobic respiration.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Fermentation in yeast is anaerobic: it happens without oxygen. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 4."}],"caseStudy":{"title":"From breakfast glucose to tissue renewal","scenario":"A tissue cell receives glucose and oxygen, uses ATP for active transport, duplicates its DNA, and later divides to replace a worn cell. During a brief period of high demand, glycolysis outpaces mitochondrial oxidation and lactate formation increases.","prompts":["Trace the major carbon and electron path from glucose through aerobic respiration.","Explain why lactate formation can support continued glycolysis but cannot match aerobic ATP output.","Place DNA replication, mitosis, and cytokinesis in the correct cell-cycle order.","Explain why this somatic-cell division is mitosis rather than meiosis."],"takeaway":"Cellular energy pathways and cell reproduction are linked by ATP demand, molecular regulation, and accurate information transfer; neither process is a single isolated reaction."},"perStepChapter":true},{"n":5,"title":"Tissues","kicker":"Lesson 5 of your course, built from Chapter 5 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"85–105 minutes","steps":[{"id":"ap5-1","chapter":"What a tissue is","title":"What a tissue is","teach":["A tissue is a group of cells with a similar structure and function. Tissues are classified by how their cells are arranged and by how much material lies between the cells.","The study of tissues is histology. (Cytology is the study of cells.) The four basic types are epithelial, connective, muscle and nervous. Tissues combine to form organs."],"mnemonic":{"cue":"Histo = tissue, cyto = cell","explanation":"Histology studies tissues; cytology studies cells."},"act":{"type":"choice","prompt":"The study of tissues is called:","options":[{"label":"Histology","correct":true,"feedback":"Right."},{"label":"Cytology","correct":false,"feedback":"Cytology is the study of cells."},{"label":"Pathology","correct":false,"feedback":"Pathology is the study of disease."}]}},{"id":"ap5-2","chapter":"Epithelial tissue: what it does","title":"Epithelial tissue: what it does","teach":["Epithelial tissue has four main jobs. It protects (skin, the lining of the gut). It absorbs (nutrients through the small intestine lining). It secretes (all glands are epithelial tissue). And it excretes (sweat glands get rid of wastes like urea).","Its cells are packed tightly with little or no material between them, which makes it hard to penetrate. Cells are anchored to each other and to the tissue below by the basement membrane, like adhesive under floor tiles.","The free surface may be plain or have cilia, a flagellum, microvilli or secretory vesicles."],"act":{"type":"choice","prompt":"What anchors epithelial cells to each other and to the tissue underneath?","options":[{"label":"The basement membrane","correct":true,"feedback":"Right."},{"label":"The matrix","correct":false,"feedback":"Matrix is the material between cells in connective tissue."},{"label":"Intercalated disks","correct":false,"feedback":"Those connect cardiac muscle cells."}]}},{"id":"ap5-3","chapter":"Epithelial cell shapes","title":"Epithelial cell shapes","teach":["Squamous cells are flat. They line the mouth, blood and lymph vessels, parts of the kidney tubules, throat, esophagus and anus, and form the skin. They mainly protect.","Cuboidal cells look like small cubes. They’re found in glands and gland ducts (sweat and salivary), covering the ovaries, and in the retina. They secrete and protect, and absorb in parts of the kidney tubules.","Columnar cells are tall rectangles. They line the stomach, the intestinal villi, the uterine tubes, the upper airway, the bile duct and mammary ducts. Many have cilia."],"act":{"type":"sort","prompt":"Which cell shape is it?","categories":["Squamous","Cuboidal","Columnar"],"items":[{"label":"Flat cells lining blood vessels","category":0,"feedback":"Squamous."},{"label":"Cube-shaped cells in salivary gland ducts","category":1,"feedback":"Cuboidal."},{"label":"Tall cells lining the small intestine villi","category":2,"feedback":"Columnar."},{"label":"Outer surface of the skin","category":0,"feedback":"Stratified squamous."},{"label":"Lining of the uterine tubes","category":2,"feedback":"Columnar, often ciliated."}]}},{"id":"ap5-4","chapter":"Epithelial arrangements","title":"Epithelial arrangements","teach":["Epithelium is named by shape plus arrangement. Simple is one layer thick (capillaries, lung alveoli). Stratified is several layers thick (stratified squamous lines the mouth and throat and forms the skin surface).","Pseudostratified looks layered because the nuclei sit at different heights, but every cell touches the basement membrane. Pseudostratified ciliated columnar epithelium lines the throat, trachea and bronchi.","Transitional epithelium is several layers of stretchy cells. It looks flat when stretched (full bladder) and saw-toothed when relaxed (empty bladder). It lines the renal pelvis, ureters, bladder and upper urethra."],"act":{"type":"sort","prompt":"Match the arrangement to where it’s found.","categories":["Simple","Stratified","Pseudostratified","Transitional"],"items":[{"label":"Capillary walls and lung alveoli","category":0,"feedback":"One thin layer for easy exchange."},{"label":"Lining of the mouth","category":1,"feedback":"Several layers for protection."},{"label":"Trachea, with cilia","category":2,"feedback":"Pseudostratified ciliated columnar."},{"label":"Urinary bladder","category":3,"feedback":"Stretches as the bladder fills."}]}},{"id":"ap5-5","chapter":"Epithelium named by function","title":"Epithelium named by function","teach":["Mucous membrane lines every body cavity that opens to the outside: the digestive, respiratory, urinary and reproductive tracts. It protects, absorbs and secretes mucus, enzymes and bile salts.","Endothelium is the special name for the single layer of squamous cells lining the circulatory system (blood and lymph vessels). In the heart it’s called endocardium. Capillaries are just one layer of endothelium.","Mesothelium, or serous tissue, lines the large body cavities that don’t open to the outside. The pleura lines the thoracic cavity, the pericardium covers the heart, and the peritoneum lines the abdominal cavity. It reduces friction and secretes fluid."],"act":{"type":"sort","prompt":"Which membrane or lining is it?","categories":["Mucous membrane","Endothelium","Serous (mesothelium)"],"items":[{"label":"Lines the digestive tract","category":0,"feedback":"It opens to the outside."},{"label":"Lines blood vessels","category":1,"feedback":"Endothelium lines the circulatory system."},{"label":"Pleura lining the thoracic cavity","category":2,"feedback":"Serous membrane."},{"label":"Peritoneum lining the abdomen","category":2,"feedback":"Serous membrane."},{"label":"Lines the airway","category":0,"feedback":"Mucous membrane."}]}},{"id":"ap5-6","chapter":"Glands","title":"Glands","teach":["All glands are made of epithelial tissue.","Exocrine glands have ducts that carry their secretions to a surface. Simple exocrine glands have one unbranched duct (sweat glands, sebaceous glands, most digestive glands). Compound exocrine glands have branching ducts (mammary glands, large salivary glands).","Endocrine glands are ductless and secrete hormones straight into the blood (thyroid, pituitary). Goblet cells are single-celled glands that secrete mucus."],"mnemonic":{"cue":"EXOcrine EXits through a duct; ENDOcrine goes in(to the blood)","explanation":"Endocrine glands have no ducts."},"act":{"type":"sort","prompt":"Exocrine or endocrine?","categories":["Exocrine (ducts)","Endocrine (ductless)"],"items":[{"label":"Sweat gland","category":0,"feedback":"Simple exocrine."},{"label":"Thyroid gland","category":1,"feedback":"Secretes hormones into the blood."},{"label":"Mammary gland","category":0,"feedback":"Compound exocrine."},{"label":"Pituitary gland","category":1,"feedback":"Endocrine."},{"label":"Salivary gland","category":0,"feedback":"Compound exocrine."}]}},{"id":"ap5-7","chapter":"Connective tissue: the basics","title":"Connective tissue: the basics","teach":["Connective tissue supports other tissues and allows movement. Unlike epithelium, it has lots of intercellular material called matrix, with collagen and elastin fibers in it. The type and amount of matrix is a main difference between connective tissues.","There are three subgroups: loose, dense and specialized connective tissue."],"visual":{"kind":"hub","title":"Jobs of connective tissue","items":[{"label":"Support","detail":"Bones and cartilage."},{"label":"Nourish and transport","detail":"Blood carries nutrients, gases and hormones."},{"label":"Connect","detail":"Tendons (muscle to bone), ligaments (bone to bone)."},{"label":"Protect","detail":"Bones guard organs; white blood cells fight microbes."},{"label":"Insulate and store","detail":"Fat insulates and stores energy; bone stores calcium."}]},"act":{"type":"choice","prompt":"Which tissue has an abundance of intercellular material called matrix?","options":[{"label":"Connective","correct":true,"feedback":"Right."},{"label":"Epithelial","correct":false,"feedback":"Epithelial cells are tightly packed with almost no matrix."},{"label":"Nervous","correct":false,"feedback":"Matrix is the mark of connective tissue."}]}},{"id":"ap5-8","chapter":"Loose connective tissue","title":"Loose connective tissue","teach":["Loose connective tissue has loosely woven fibers and fills spaces between and within organs. There are three types: areolar, adipose and reticular.","Areolar is the most widespread. It surrounds organs, muscles, vessels and nerves and attaches skin to the tissue below. Its cells: fibroblasts make fibers and repair injuries; histiocytes are fixed macrophages that eat debris and microbes; mast cells make heparin (an anticoagulant) and histamine (an inflammatory substance released in allergies).","Adipose tissue is packed with fat cells that look like soap bubbles. It cushions organs (like the kidneys) and insulates the body.","Reticular tissue is a fine network of fibers that forms the framework of the liver, bone marrow, spleen and lymph nodes."],"act":{"type":"sort","prompt":"Which loose connective tissue?","categories":["Areolar","Adipose","Reticular"],"items":[{"label":"Attaches skin to the tissue below","category":0,"feedback":"Areolar."},{"label":"Loaded with fat cells","category":1,"feedback":"Adipose."},{"label":"Framework of the spleen and lymph nodes","category":2,"feedback":"Reticular."},{"label":"Contains mast cells that make histamine","category":0,"feedback":"Areolar."},{"label":"Cushions the kidneys","category":1,"feedback":"Adipose."}]}},{"id":"ap5-9","chapter":"Dense connective tissue","title":"Dense connective tissue","teach":["Dense connective tissue is tightly packed protein fibers.","Dense regular tissue has fibers in a regular arrangement: tendons attach muscle to bone, ligaments attach bone to bone, and aponeuroses are wide, flat tendons. Tendons are mostly collagen; ligaments mix collagen and elastin.","Dense irregular tissue has fibers going in many directions: the dermis of the skin, muscle sheaths, joint capsules, the outer coat of arteries, and fascia (which covers a whole muscle)."],"mnemonic":{"cue":"Tendons Tie muscle to bone; Ligaments Link bone to bone","explanation":"Both are dense regular connective tissue."},"act":{"type":"sort","prompt":"Regular or irregular dense connective tissue?","categories":["Dense regular","Dense irregular"],"items":[{"label":"Tendon","category":0,"feedback":"Attaches muscle to bone."},{"label":"Ligament","category":0,"feedback":"Attaches bone to bone."},{"label":"Dermis of the skin","category":1,"feedback":"Fibers run in many directions."},{"label":"Fascia around a muscle","category":1,"feedback":"Dense irregular."},{"label":"Aponeurosis","category":0,"feedback":"A wide flat tendon."}]}},{"id":"ap5-10","chapter":"Cartilage","title":"Cartilage","teach":["Cartilage cells are chondrocytes, sitting in cavities called lacunae within a firm matrix of protein and polysaccharides.","Hyaline cartilage has no visible fibers (\"hyaline\" means clear). The fetal skeleton starts as hyaline cartilage and is mostly replaced by bone (ossification). It remains on joint surfaces, in the costal cartilages joining ribs to the sternum, in the rings of the trachea and bronchi, and in the nasal septum.","Fibrocartilage is mostly tough collagen, so it’s dense and very resistant to stretching. It forms the intervertebral disks and the pubic symphysis.","Elastic cartilage is mostly elastin, so it stretches and springs back. It forms the external ear, the auditory tubes and the epiglottis."],"act":{"type":"sort","prompt":"Which type of cartilage?","categories":["Hyaline","Fibrocartilage","Elastic"],"items":[{"label":"Rings of the trachea","category":0,"feedback":"Hyaline."},{"label":"Intervertebral disks","category":1,"feedback":"Strong shock absorbers."},{"label":"External ear","category":2,"feedback":"Flexible and springs back."},{"label":"Dense and very resistant to stretching","category":1,"feedback":"Lots of collagen."},{"label":"Epiglottis","category":2,"feedback":"Elastic."},{"label":"Covers bone ends at joints","category":0,"feedback":"Hyaline."}]}},{"id":"ap5-11","chapter":"Bone, dentin and blood","title":"Bone, dentin and blood","teach":["Bone is very firm connective tissue. Its two types are compact bone (the dense outer layer) and cancellous bone (the spongy inner layer). Bone cells (osteocytes) sit in lacunae, and the matrix is hardened with calcium and phosphorus salts. Chapter 7 covers bone in detail.","Dentin forms the teeth. It’s like bone but harder and denser, and it’s covered by white enamel on the crown.","Blood is a unique connective tissue: a fluid portion (plasma) plus formed elements (red and white blood cells). It transports gases, nutrients, hormones and wastes, protects the body and helps regulate temperature. Blood cells are made in hematopoietic tissue (red bone marrow and lymphoid organs)."],"act":{"type":"choice","prompt":"Which connective tissue is made of plasma plus formed elements?","options":[{"label":"Blood","correct":true,"feedback":"Right."},{"label":"Bone","correct":false,"feedback":"Bone has a hard mineral matrix."},{"label":"Cartilage","correct":false,"feedback":"Cartilage has a firm matrix with chondrocytes."}]}},{"id":"ap5-12","chapter":"Lymphoid tissue, the RE system and synovial membranes","title":"Lymphoid tissue, the RE system and synovial membranes","teach":["Lymphoid tissue is in the lymph nodes, thymus, spleen, tonsils and adenoids. Its main role is making antibodies to protect against disease.","The reticuloendothelial (RE) system is the connective tissue cells that do phagocytosis: Kupffer’s cells lining the liver (and cells lining the spleen and marrow), macrophages, and microglia in the central nervous system.","Synovial membranes line the cavities of freely moving joints and the bursae (small fluid-filled sacs that prevent friction). They are classed as specialized connective tissue."],"act":{"type":"choice","prompt":"Which membrane lines the cavities of freely moving joints?","options":[{"label":"Synovial","correct":true,"feedback":"Right. It also lines bursae."},{"label":"Serous","correct":false,"feedback":"Serous membranes line closed body cavities like the thorax."},{"label":"Mucous","correct":false,"feedback":"Mucous membranes line cavities that open to the outside."}]}},{"id":"ap5-13","chapter":"Muscle tissue","title":"Muscle tissue","teach":["Muscle tissue contracts (shortens and thickens) because of two proteins, actin and myosin. Muscle cells are long, so they’re called muscle fibers. There are three types.","Smooth muscle: spindle-shaped cells with one nucleus, no striations, involuntary (autonomic control). It’s in the walls of hollow organs like the gut, arteries and veins. Its outer longitudinal and inner circular layers push contents along: in the gut this is peristalsis.","Skeletal (striated) muscle: long cells with many nuclei and light and dark bands (actin and myosin). Voluntary, controlled by the central nervous system. It moves bones and makes up about 40% of body weight.","Cardiac muscle: only in the heart. Striated like skeletal, one nucleus and involuntary like smooth. Its branching cells connect at intercalated disks, which coordinate the heartbeat."],"act":{"type":"sort","prompt":"Smooth, skeletal or cardiac?","categories":["Smooth","Skeletal","Cardiac"],"items":[{"label":"Spindle-shaped with one nucleus, no stripes","category":0,"feedback":"Smooth."},{"label":"Many nuclei and voluntary","category":1,"feedback":"Skeletal."},{"label":"Intercalated disks","category":2,"feedback":"Cardiac."},{"label":"Lines the digestive tract (peristalsis)","category":0,"feedback":"Smooth."},{"label":"Pulls on bones","category":1,"feedback":"Skeletal."},{"label":"Striated but involuntary","category":2,"feedback":"Cardiac."}]}},{"id":"ap5-14","chapter":"Nervous tissue","title":"Nervous tissue","teach":["The neuron (nerve cell) is the conducting cell of nervous tissue; neuroglia are supporting cells. Neurons are very long, so they’re also called nerve fibers.","A neuron has a cell body with the nucleus, dendrites that receive stimuli and carry them to the cell body, and an axon that carries the impulse away to the axon endings.","Nervous tissue makes up the brain, spinal cord and nerves. It’s the most highly organized tissue: it controls and coordinates the body, handles the senses, emotions and reasoning, and makes memory possible."],"visual":{"kind":"flow","title":"Direction of a nerve impulse","items":[{"label":"Dendrites","detail":"Receive the stimulus."},{"label":"Cell body","detail":"Contains the nucleus."},{"label":"Axon","detail":"Carries the impulse away."},{"label":"Axon endings","detail":"Pass the signal on."}]},"act":{"type":"choice","prompt":"Which part of a neuron receives stimuli and carries them to the cell body?","options":[{"label":"Dendrites","correct":true,"feedback":"Right."},{"label":"Axon","correct":false,"feedback":"The axon carries impulses away from the cell body."},{"label":"Neuroglia","correct":false,"feedback":"Neuroglia are supporting cells."}]}},{"id":"ap5-15","chapter":"Tissues and aging","title":"Tissues and aging","teach":["Cells divide more slowly in older adults, so injuries, especially to bone, heal more slowly and sometimes incompletely. Muscle cells and working neurons decrease with age.","Collagen fibers become irregular, making tendons and ligaments more fragile and less flexible, and elastic fibers lose their stretch. This is why skin wrinkles over time."],"act":{"type":"choice","prompt":"Why does skin wrinkle with age, according to the textbook?","options":[{"label":"Collagen becomes irregular and elastic fibers lose their stretch","correct":true,"feedback":"Right."},{"label":"Epithelial cells stop dividing completely","correct":false,"feedback":"They slow down, but the textbook links wrinkles to fiber changes."},{"label":"Adipose tissue increases","correct":false,"feedback":"The textbook points to connective tissue fibers."}]}}],"flashcards":[{"front":"Histology","back":"The study of tissues."},{"front":"Four basic tissues","back":"Epithelial, connective, muscle, nervous."},{"front":"Epithelial functions","back":"Protect, absorb, secrete, excrete."},{"front":"Basement membrane","back":"Anchors epithelial cells to each other and to the tissue below."},{"front":"Squamous / cuboidal / columnar","back":"Flat / cube-shaped / tall rectangles."},{"front":"Simple vs stratified","back":"One layer / several layers."},{"front":"Pseudostratified","back":"Looks layered, but every cell touches the basement membrane (trachea)."},{"front":"Transitional epithelium","back":"Stretchy layers lining the bladder, ureters and renal pelvis."},{"front":"Endothelium","back":"Epithelium lining the circulatory system."},{"front":"Pleura / pericardium / peritoneum","back":"Serous membranes of the thoracic cavity / heart / abdominal cavity."},{"front":"Exocrine vs endocrine","back":"Glands with ducts / ductless glands secreting hormones into the blood."},{"front":"Goblet cell","back":"Single-celled gland that secretes mucus."},{"front":"Matrix","back":"Abundant intercellular material of connective tissue."},{"front":"Loose connective tissue types","back":"Areolar, adipose, reticular."},{"front":"Mast cells","back":"Make heparin and histamine."},{"front":"Tendon / ligament","back":"Muscle to bone / bone to bone."},{"front":"Chondrocytes","back":"Cartilage cells, in lacunae."},{"front":"Hyaline cartilage","back":"No visible fibers; joint surfaces, trachea, nasal septum, costal cartilage."},{"front":"Fibrocartilage","back":"Dense, resists stretching; intervertebral disks, pubic symphysis."},{"front":"Elastic cartilage","back":"Flexible; external ear, auditory tube, epiglottis."},{"front":"Compact vs cancellous bone","back":"Dense outer layer / spongy inner layer."},{"front":"Blood","back":"Connective tissue of plasma plus formed elements."},{"front":"Synovial membrane","back":"Lines freely moving joint cavities and bursae."},{"front":"Smooth muscle","back":"Spindle-shaped, one nucleus, involuntary, hollow organ walls."},{"front":"Skeletal muscle","back":"Striated, many nuclei, voluntary."},{"front":"Cardiac muscle","back":"Striated, one nucleus, involuntary, intercalated disks."},{"front":"Dendrite / axon","back":"Carries impulses toward / away from the cell body."}],"quiz":[{"q":"The two types of ________________ tissue are compact (dense) and cancellous (spongy).","o":["adipose","blood","areolar","bone"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says bone is made of two types of tissue: compact bone and cancellous (spongy) bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which glands are ductless and secrete hormones directly into the bloodstream?","o":["Goblet","Endocrine","Exocrine","Holocrine"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says endocrine glands are ductless and secrete hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What is the dense regular connective tissue that attaches muscle to bone?","o":["Ligament","Areolar","Fascia","Tendon"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says tendons are dense regular connective tissue that attach muscle to bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Epithelial cells are anchored to each other and to underlying tissues by the __________________ membrane.","o":["basement","apical","corner","endocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says epithelial cells are anchored to each other and to underlying tissues by the basement membrane. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Mast cells produce which inflammatory substance in response to allergies?","o":["Fibroblasts","Histamine","Collagen","Cartilage"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says mast cells produce histamine, an inflammatory substance produced in response to allergies. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Chondrocytes are found in cavities called _____________________.","o":["lacunae","lamellae","canaliculi","canals"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says chondrocytes are found in cavities called lacunae. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of cartilage is dense and very resistant to stretching?","o":["Hyaline cartilage","Costal cartilage","Elastic cartilage","Fibrocartilage"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says fibrocartilage’s collagen fibers make it dense and very resistant to stretching. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"All glands are made of __________________________ tissue.","o":["connective","nervous","epithelial","muscle"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says all glands are made of epithelial tissue. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which unique connective tissue is composed of a fluid portion (plasma) and formed elements?","o":["Blood","Bone","Connective tissue proper","Cartilage"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says blood is a unique connective tissue made of a fluid portion (plasma) and formed elements. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The type of muscle that lines the digestive tract is called _________________________ muscle.","o":["smooth","cardiac","skeletal","striated"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says smooth muscle is found in the walls of the digestive tract, where it pushes food along. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"A epithelium has several layers of epithelial cells thick.","o":["simple","stratified","pseudostratified","columnar"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says the stratified arrangement is several layers of cells thick. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of tissue makes up the brain and spinal cord?.","o":["Smooth","Nervous","Skeletal","Muscle"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says nervous tissue makes up the brain, spinal cord and nerves. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What type of tissue is loaded with fat cells?.","o":["Areolar","Epithelial","Adipose","Dense regular connective"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says adipose tissue is loaded with fat cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The three types of _______________________ tissue are smooth, skeletal, and cardiac.","o":["connective","nervous","muscle","epithelial"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 names the three types of muscle tissue as smooth, striated (skeletal) and cardiac. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Areolar, adipose, and reticular tissues are all types of _______________________________ tissue.","o":["loose connective","dense connective","epithelial","nervous"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says the three types of loose connective tissue are areolar, adipose and reticular. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The ________________________ is the serous tissue that lines the thoracic cavity.","o":["pericardium","peritoneum","pleura","endothelium"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says the pleura is the serous membrane that lines the thoracic cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of membrane lines the cavities of freely moving joints?","o":["Peritoneum","Pericardial","Synovial","Endothelial"],"a":2,"e":"Checked answer, not from an official key. Chapter 5 says synovial membranes line the cavities of freely moving joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which type of tissue has a regular arrangement of embedded fibres and makes up tendons and ligaments?","o":["Loose connective tissue","Dense connective tissue","Areolar connective tissue","Cartilage"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says tendons and ligaments are dense connective tissue with a regular arrangement of fibers. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"What is the special name given to the epithelium that lines the circulatory system?","o":["Endomysium","Pericardium","Peritoneum","Endothelium"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says endothelium is the special name for the epithelium that lines the circulatory system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Which tissue is characterized by an abundance of intercellular material called the matrix?","o":["Epithelial","Nervous","Muscle","Connective"],"a":3,"e":"Checked answer, not from an official key. Chapter 5 says connective tissue has an abundance of intercellular material called matrix. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Cells of which type of muscle are spindle-shaped with a single nucleus?","o":["Cardiac","Smooth","Nervous","Skeletal"],"a":1,"e":"Checked answer, not from an official key. Chapter 5 says smooth muscle cells are spindle-shaped with a single nucleus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The study of tissue is called cytology.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The study of tissue is histology. Cytology is the study of cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Simple epithelium is several layers thick","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Simple epithelium is one cell layer thick. Several layers is stratified. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"The three types of loose connective tissue are areolar, adipose and reticular.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 5 says the three types of loose connective tissue are areolar, adipose and reticular. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."},{"q":"Endocrine glands have ducts.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Endocrine glands are ductless. Exocrine glands have ducts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 5."}],"caseStudy":{"title":"Map the wall of the small intestine","scenario":"A cross-section of small intestine shows a tall absorptive lining with goblet cells, loose connective tissue containing capillaries, bands of smooth muscle, and nerve fibers coordinating movement and secretion.","prompts":["Classify the epithelial lining and explain why its structure suits absorption.","Identify the tissue beneath the epithelium and explain how it supports nutrient transfer.","Explain the distinct roles of goblet cells, smooth muscle, and nervous tissue.","Trace an absorbed water-soluble nutrient from the epithelial surface toward a blood vessel without treating tissues as isolated layers."],"takeaway":"An organ works because multiple tissue classes form an integrated route: boundary and absorption, support and transport, movement, and regulation."},"perStepChapter":true},{"n":6,"title":"The Integumentary System","kicker":"Lesson 6 of your course, built from Chapter 6 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"90–110 minutes","steps":[{"id":"ap6-1","chapter":"The integumentary system","title":"The integumentary system","teach":["The integumentary system is the skin and its appendages: hair, nails, and sebaceous, ceruminous and sweat glands. \"Integument\" means covering.","An adult’s skin covers over 3,000 square inches and weighs about 6 pounds, nearly twice the weight of the brain or liver. It receives about one-third of all the blood circulating through the body.","It’s flexible but tough, repairs itself, is almost waterproof, blocks UV rays and most harmful chemicals, and helps control body temperature through sweating."],"act":{"type":"choice","prompt":"About how much of the body’s circulating blood does the skin receive?","options":[{"label":"One-third","correct":true,"feedback":"Right, according to the textbook."},{"label":"One-half","correct":false,"feedback":"The textbook says about one-third."},{"label":"One-fifth","correct":false,"feedback":"It’s more: about one-third."}]}},{"id":"ap6-2","chapter":"Layers of the skin","title":"Layers of the skin","teach":["The skin has two main layers. The epidermis on top is epithelial tissue. The dermis beneath it is dense connective tissue. Under the dermis is the subcutaneous layer, also called the hypodermis.","The epidermis is stratified squamous keratinized epithelium, held together by interlocking links called desmosomes. It has no blood vessels and sits on a basement membrane. It’s thickest on the palms and soles.","Cells at the bottom divide by mitosis and push older cells up. As they rise they lose water, fill with the protein keratin and die. This is keratinization. The dead surface cells are constantly shed."],"visual":{"kind":"flow","title":"From the surface down","items":[{"label":"Epidermis","detail":"Epithelial tissue; no blood vessels."},{"label":"Dermis","detail":"Dense connective tissue: the \"true skin\"."},{"label":"Hypodermis (subcutaneous)","detail":"Areolar and adipose tissue; fat."}]},"act":{"type":"order","prompt":"Put the layers in order from the surface down.","items":[{"label":"Epidermis","detail":"Outer layer"},{"label":"Dermis","detail":"Second layer"},{"label":"Hypodermis","detail":"Subcutaneous layer with fat"}]}},{"id":"ap6-3","chapter":"The five layers of the epidermis","title":"The five layers of the epidermis","teach":["From the surface down: stratum corneum, stratum lucidum, stratum granulosum, stratum spinosum and stratum germinativum.","Stratum corneum (horny layer): up to 25 layers of dead, keratinized, scale-like cells surrounded by lipids. They’re about 20% water (versus 70% in the deepest layer) and constantly shed (dandruff on the scalp). It’s a barrier to light and heat waves, microorganisms and most chemicals. Friction thickens it into a callus.","Stratum lucidum (clear layer): one or two layers of flat, transparent cells, hard to see in thin skin.","Stratum granulosum (granular layer): two or three layers of flattened cells, very active in keratinization. Cells lose their nuclei here.","Stratum spinosum (spiny or prickly layer): several layers of polyhedral cells whose outlines look spiny. Desmosomes are still common.","Stratum germinativum (regenerative layer, with the stratum basale at its base): the deepest and most important layer, the only epidermal cells that divide by mitosis. The epidermis regenerates only while this layer is intact."],"mnemonic":{"cue":"Come, Let’s Get Sun Burned","explanation":"Corneum, Lucidum, Granulosum, Spinosum, Basale (germinativum), from the top down."},"act":{"type":"order","prompt":"Put the layers of the epidermis in order, outermost first.","items":[{"label":"Stratum corneum","detail":"Horny layer"},{"label":"Stratum lucidum","detail":"Clear layer"},{"label":"Stratum granulosum","detail":"Granular layer"},{"label":"Stratum spinosum","detail":"Spiny layer"},{"label":"Stratum germinativum","detail":"Regenerative layer"}]}},{"id":"ap6-4","chapter":"Match the layer to its feature","title":"Match the layer to its feature","teach":["Each layer has something that marks it out. Use these to answer \"which layer...\" questions."],"act":{"type":"sort","prompt":"Which layer of the epidermis?","categories":["Corneum","Lucidum","Granulosum","Spinosum","Germinativum"],"items":[{"label":"Outermost layer; barrier to light and heat","category":0,"feedback":"Stratum corneum."},{"label":"The clear layer","category":1,"feedback":"Stratum lucidum."},{"label":"Cells lose their nuclei; very active in keratinization","category":2,"feedback":"Stratum granulosum."},{"label":"Spiny-looking polyhedral cells","category":3,"feedback":"Stratum spinosum."},{"label":"Only layer that divides by mitosis; has melanocytes","category":4,"feedback":"Stratum germinativum."},{"label":"Thickens into a callus with friction","category":0,"feedback":"Stratum corneum."}]}},{"id":"ap6-5","chapter":"Skin color","title":"Skin color","teach":["Melanocytes in the stratum germinativum make the pigment melanin, which produces skin color. Everyone has about the same number of melanocytes; genes control how much melanin they make. Sunlight stimulates them, which is a suntan.","Melanin protects against UV rays. Concentrations of melanin form freckles, moles and the areola. Albinism is a recessive condition in which no melanin is made.","Other color changes: the pink tint of light skin comes from blood vessels in the dermis, and blushing is those vessels dilating. Cyanosis is a bluish color caused by lack of oxygen in the blood; in darker skin it looks greyish or ashy."],"act":{"type":"choice","prompt":"Which cells produce skin color?","options":[{"label":"Melanocytes, which make melanin","correct":true,"feedback":"Right."},{"label":"Keratinocytes, which make keratin","correct":false,"feedback":"Keratin is a tough protein, not the pigment."},{"label":"Fibroblasts","correct":false,"feedback":"Fibroblasts make connective tissue fibers."}]}},{"id":"ap6-6","chapter":"The dermis and hypodermis","title":"The dermis and hypodermis","teach":["The dermis (corium, or \"true skin\") is dense connective tissue with collagen and elastin fibers. It holds blood vessels, nerves, lymph vessels, smooth muscle, sweat glands, hair follicles and sebaceous glands.","It has two parts: the papillary portion next to the epidermis and the deeper reticular portion.","Below it, the subcutaneous tissue (superficial fascia or hypodermis) is areolar tissue with lots of fat. It attaches the skin to muscle or bone, and it’s where hypodermic injections go."],"act":{"type":"choice","prompt":"The subcutaneous layer full of fat is the:","options":[{"label":"Hypodermis","correct":true,"feedback":"Right."},{"label":"Dermis","correct":false,"feedback":"The dermis is dense connective tissue above it."},{"label":"Epidermis","correct":false,"feedback":"The epidermis is the outer epithelial layer."}]}},{"id":"ap6-7","chapter":"Hair","title":"Hair","teach":["Each hair has three layers: the cuticle (overlapping scale-like cells on the outside), the cortex (the main part, with pigment in dark hair) and the medulla (the center, often with air spaces).","The shaft is the visible part. The root sits in the hair follicle, a tube of epidermis. Growth starts in the hair bulb, nourished by blood vessels. Scalp hair grows for about 3 years, then rests for 1 or 2.","The arrector pili is a bundle of smooth muscle attached to the follicle. When it contracts (fear or cold), the hair stands up and you get goose flesh.","Grey hair lacks pigment in the cortex; white hair also has air bubbles in the shaft. Hair texture depends on the shape of its keratin."],"act":{"type":"sort","prompt":"Match each hair part to its description.","categories":["Shaft","Root","Cuticle","Medulla","Arrector pili"],"items":[{"label":"The visible part of the hair","category":0,"feedback":"Shaft."},{"label":"Sits inside the follicle","category":1,"feedback":"Root."},{"label":"Outer layer of overlapping scales","category":2,"feedback":"Cuticle."},{"label":"Central part, often with air spaces","category":3,"feedback":"Medulla."},{"label":"Smooth muscle that causes goose flesh","category":4,"feedback":"Arrector pili."}]}},{"id":"ap6-8","chapter":"Nails","title":"Nails","teach":["Nails are modified horny epidermal cells made of very hard keratin.","The nail body is the visible part. The nail root is the part attached to the nail bed, and nails grow from the root area about 1 mm a week. The lunula is the white crescent at the base. The cuticle (eponychium) is stratum corneum extending over the base of the nail.","Fingernails grow faster than toenails: a lost fingernail regrows in about 3½ to 5½ months, a toenail in 6 to 8 months."],"act":{"type":"sort","prompt":"Which part of the nail?","categories":["Nail body","Nail root","Lunula","Cuticle (eponychium)"],"items":[{"label":"The visible part","category":0,"feedback":"Nail body."},{"label":"Where the nail grows from","category":1,"feedback":"Nail root."},{"label":"White crescent at the base","category":2,"feedback":"Lunula."},{"label":"Skin extending over the base","category":3,"feedback":"Cuticle."}]}},{"id":"ap6-9","chapter":"Sebaceous glands","title":"Sebaceous glands","teach":["Sebaceous glands grow along the walls of hair follicles and make sebum, an oily substance that lubricates the skin and hair and gives them a gloss. Sebum also fights bacteria and fungi.","Sebum production is controlled by hormones: it rises at puberty (acne), late in pregnancy, and falls in later life (dry skin).","Ceruminous glands in the ear canal are modified sebaceous glands that make earwax (cerumen).","In acne, a clogged gland’s sebum oxidizes into a blackhead; trapped sebum can feed bacteria and form a pimple, or a boil if deeper."],"act":{"type":"choice","prompt":"What is the oily substance that lubricates the skin?","options":[{"label":"Sebum","correct":true,"feedback":"Right, from sebaceous glands."},{"label":"Sweat","correct":false,"feedback":"Sweat is watery and cools the body."},{"label":"Cerumen","correct":false,"feedback":"Cerumen is earwax."}]}},{"id":"ap6-10","chapter":"Sweat glands","title":"Sweat glands","teach":["Sweat glands are simple coiled tubes with a duct opening on the skin. They’re most numerous on the palms and soles (about 3,000 per square inch on the palms).","Eccrine glands are the most common and numerous type and are the ones that cool the body. Apocrine glands are found only in the armpits, scrotum, labia majora and around the anus. They open into hair follicles, become active at puberty and don’t regulate temperature.","Sweat contains the same inorganic materials as blood but much more dilute. Its chief salt is sodium chloride. It also carries urea, uric acid, ammonia and lactic acid. Fresh sweat is nearly odorless; bacteria feeding on it cause the smell."],"act":{"type":"sort","prompt":"Eccrine or apocrine?","categories":["Eccrine","Apocrine"],"items":[{"label":"Most common and numerous","category":0,"feedback":"Eccrine."},{"label":"Cools the body","category":0,"feedback":"Eccrine."},{"label":"Found in the armpits and groin, opening into hair follicles","category":1,"feedback":"Apocrine."},{"label":"Becomes active at puberty and adds to body odor","category":1,"feedback":"Apocrine."}]}},{"id":"ap6-11","chapter":"Functions of the skin","title":"Functions of the skin","teach":["Sensation: receptors for temperature and pressure send signals to the brain and spinal cord.","Protection: the skin blocks most chemicals (though fat-soluble chemicals like DDT and poison ivy’s chemicals get through), melanin blocks UV, and the skin’s \"acid mantle\" kills most bacteria.","Thermoregulation: normal temperature is about 98.6°F (37°C). In heat, dermal vessels dilate and sweat evaporates to remove heat. In cold, vessels constrict to keep heat in the core; holding that too long can cause frostbite.","Secretion: sebum and sweat. Vitamin D: UV light helps the skin make a precursor that the liver and kidneys turn into vitamin D, which helps absorb calcium and phosphorus."],"visual":{"kind":"hub","title":"What the skin does","items":[{"label":"Sensation","detail":"Temperature and pressure receptors."},{"label":"Protection","detail":"Barrier, melanin, acid mantle."},{"label":"Thermoregulation","detail":"Blood vessels and sweat."},{"label":"Secretion","detail":"Sebum and sweat."},{"label":"Vitamin D","detail":"Made with help from sunlight."}]},"act":{"type":"choice","prompt":"On a hot day, how does the skin help cool you?","options":[{"label":"Dermal blood vessels dilate and sweat evaporates, carrying heat away","correct":true,"feedback":"Right."},{"label":"Dermal blood vessels constrict","correct":false,"feedback":"That keeps heat in. It happens in the cold."},{"label":"The arrector pili contracts","correct":false,"feedback":"That causes goose flesh."}]}},{"id":"ap6-12","chapter":"Burns","title":"Burns","teach":["First-degree burns involve only the epidermis: redness, pain, maybe slight swelling. Sunburn is an example. They heal in about a week with no scarring.","Second-degree burns involve the epidermis and dermis: redness, pain, swelling and blisters. First- and second-degree burns are partial-thickness burns because the deepest layer survives.","Third-degree (full-thickness) burns completely destroy the epidermis and dermis. They’re often painless because the nerve receptors are destroyed, heal only from the edges, and usually need skin grafts."],"act":{"type":"sort","prompt":"Which degree of burn?","categories":["First-degree","Second-degree","Third-degree"],"items":[{"label":"Epidermis only; redness and pain","category":0,"feedback":"First-degree."},{"label":"Blisters; epidermis and dermis involved","category":1,"feedback":"Second-degree."},{"label":"Epidermis and dermis completely destroyed","category":2,"feedback":"Third-degree."},{"label":"Often painless; needs grafts","category":2,"feedback":"Nerve endings are destroyed."},{"label":"Mild sunburn","category":0,"feedback":"First-degree."}]}},{"id":"ap6-13","chapter":"Skin disorders","title":"Skin disorders","teach":["Skin cancer: basal cell carcinoma is most common and rarely spreads; squamous cell carcinoma can spread; malignant melanoma, from a mole, is the most dangerous.","Infections: warts are caused by human papillomavirus; cold sores by herpes simplex type I; impetigo by Staphylococcus aureus bacteria (honey-colored crust); shingles by the chickenpox virus reactivating; ringworm (tinea) by fungi.","Other conditions: psoriasis is a chronic disorder with red patches covered by thick, dry, silvery scales. Vitiligo causes irregular patches with no pigment. Alopecia is hair loss."],"act":{"type":"sort","prompt":"What causes or describes each condition?","categories":["Virus","Bacterium","Fungus","Not an infection"],"items":[{"label":"Warts","category":0,"feedback":"Human papillomavirus."},{"label":"Impetigo","category":1,"feedback":"Staphylococcus aureus."},{"label":"Ringworm (athlete’s foot)","category":2,"feedback":"Fungi."},{"label":"Shingles","category":0,"feedback":"The chickenpox virus."},{"label":"Vitiligo","category":3,"feedback":"Loss of pigment; cause unknown."},{"label":"Psoriasis","category":3,"feedback":"Chronic disorder, possibly genetic."}]}},{"id":"ap6-14","chapter":"Skin lesions","title":"Skin lesions","teach":["A macule is a flat, small discoloration even with the skin surface (a small rash). A papule is a solid elevation under 1 cm. A wheal is a pale or red swelling, like a mosquito bite.","A vesicle or bulla is a thin blister with clear fluid; a pustule is a similar small elevation filled with pus. A crust is a scab. A furuncle (boil) is a staph infection of a follicle or gland. A cyst is an epithelium-lined sac.","A callus is a thickened area from friction; on bony parts of the foot, these form corns."],"act":{"type":"sort","prompt":"Name the lesion.","categories":["Macule","Papule","Wheal","Pustule"],"items":[{"label":"Flat discoloration even with the skin","category":0,"feedback":"Macule."},{"label":"Solid raised bump under 1 cm","category":1,"feedback":"Papule."},{"label":"Swelling like a mosquito bite","category":2,"feedback":"Wheal."},{"label":"Small raised bump filled with pus","category":3,"feedback":"Pustule."}]}},{"id":"ap6-15","chapter":"Skin and aging","title":"Skin and aging","teach":["With age, sebum drops (drier skin), collagen and elastin are lost (sagging and wrinkles), blood flow decreases and the skin thins. Fewer melanocytes in some areas leaves age spots, and less melanin means grey or white hair.","Hair thins, nails become brittle or thick and prone to fungus, and older adults feel the cold more because of reduced circulation and less fat under the skin."],"act":{"type":"choice","prompt":"Why does skin get drier with age?","options":[{"label":"Sebaceous glands secrete less sebum","correct":true,"feedback":"Right."},{"label":"Sweat glands make more sweat","correct":false,"feedback":"Dry skin comes from less sebum."},{"label":"The stratum corneum disappears","correct":false,"feedback":"It doesn’t disappear."}]}}],"flashcards":[{"front":"Integumentary system","back":"Skin plus hair, nails, and sebaceous, ceruminous and sweat glands."},{"front":"Skin blood supply","back":"About one-third of circulating blood."},{"front":"Epidermis / dermis / hypodermis","back":"Epithelial outer layer / dense connective tissue / fatty subcutaneous layer."},{"front":"Keratinization","back":"Cells move up, lose water, fill with keratin and die."},{"front":"Epidermal layers (out to in)","back":"Corneum, lucidum, granulosum, spinosum, germinativum (basale)."},{"front":"Stratum corneum","back":"Outermost; dead keratinized cells; barrier to light, heat, microbes and chemicals."},{"front":"Stratum lucidum","back":"The clear layer."},{"front":"Stratum spinosum","back":"Spiny-looking polyhedral cells."},{"front":"Stratum germinativum","back":"Deepest; only dividing layer; contains melanocytes."},{"front":"Melanocytes","back":"Make melanin, the pigment of skin color."},{"front":"Cyanosis","back":"Bluish skin from lack of oxygen in the blood."},{"front":"Callus","back":"Thickened skin from friction."},{"front":"Hair layers","back":"Cuticle, cortex, medulla."},{"front":"Hair shaft / root","back":"Visible part / part in the follicle."},{"front":"Arrector pili","back":"Smooth muscle on the follicle; causes goose flesh."},{"front":"Lunula","back":"White crescent at the base of the nail."},{"front":"Sebum","back":"Oil from sebaceous glands that lubricates skin and hair."},{"front":"Cerumen","back":"Earwax from ceruminous glands."},{"front":"Eccrine vs apocrine","back":"Most numerous, cooling / armpit and groin, odor, no cooling."},{"front":"Main salt in sweat","back":"Sodium chloride."},{"front":"Burn degrees","back":"1st: epidermis; 2nd: epidermis + dermis with blisters; 3rd: both destroyed."},{"front":"Warts","back":"Caused by human papillomavirus."},{"front":"Psoriasis","back":"Red patches with thick, dry, silvery scales."},{"front":"Vitiligo","back":"Irregular patches lacking pigment."},{"front":"Macule","back":"Flat, small discoloration even with the skin."},{"front":"Vitamin D and skin","back":"Sunlight helps skin make the precursor; liver and kidneys finish it."}],"quiz":[{"q":"The skin receives approximately ____________________ of all the blood circulating through the body.","o":["one-fifth","one-third","one-fourth","one-half"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the skin receives approximately one-third of all the blood circulating through the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Cells that are responsible for producing skin colour are called ______________.","o":["keratinocytes","melanocytes","fibroblasts","Meissner’s corpuscles"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says melanocytes are responsible for producing skin color. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The visible portion of the hair is called the _____________________________.","o":["cuticle","medulla","shaft","root"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the shaft is the visible portion of the hair. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The second layer of the skin is the____________________________ .","o":["epidermis","hypodermis","keratin layer","dermis"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the epidermis sits on top of the second layer of the skin, the dermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The subcutaneous tissue that contains a lot of fat is the _________________________ .","o":["peridermis","dermis","hypodermis","epidermis"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the subcutaneous tissue, usually containing fat, is sometimes called the hypodermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The most common and most numerous type of sweat glands is the _________________________ gland.","o":["holocrine","sebaceous","eccrine","apocrine"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the most common and most numerous sweat glands are eccrine sweat glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which structure is a bundle of smooth muscle fibers that are attached to the hair follicle?","o":["cuticle","root","medulla","arrector pili"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the arrector pili is a bundle of smooth muscle fibers attached to the hair follicle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which condition is caused by human papillomavirus?","o":["cold sores","shingles","impetigo","warts"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says warts are caused by human papillomavirus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The primary salt in sweat is _______________________________.","o":["potassium chloride","sodium chloride","sodium bromide","calcium chloride"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the chief salt in sweat is sodium chloride. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which disease results in irregular patches of skin that lack pigmentation?","o":["vitiligo","shingles","alopecia","impetigo"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says vitiligo results in irregular patches of skin completely lacking pigment. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The stratum ___________________ is commonly called the clear layer.","o":["lucidum","corneum","spinosum","granulosum"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says the stratum lucidum is commonly called the clear layer. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Each individual _______________________ is composed of the cuticle, the cortex, and the medulla.","o":["hair","arrector pili","skin","nail"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says each individual hair is composed of the cuticle, the cortex and the medulla. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The skin layer that functions as a physical barrier to light and heat waves is the stratum ____________________.","o":["germinativum","spinosum","corneum","lucidum"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says the stratum corneum is a physical barrier to light and heat waves, microorganisms and most chemicals. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The nail grows from the nail ______________.","o":["root","bed","body","lunula"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 describes the nail root as the part of the nail attached to the nail bed, from which the nail grows. The sentence could be read as pointing to the bed, but standard anatomy sources place nail growth in the matrix under the root, so \"root\" is the best answer. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A burn that involves complete destruction of both the epidermis and the dermis is a ___________- degree burn.","o":["fourth","first","second","third"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says in third-degree (full-thickness) burns the epidermis and dermis are completely destroyed. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A flat, small discoloration of the skin that is even with the skin surface is known as a _________________.","o":["papule","wheal","macule","pustule"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 defines a macule as a flat, small discoloration of the skin that is even with the skin surface. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The oily substance responsible for lubricating the surface of the skin is called __________________.","o":["sebum","sweat","milk","cerumen"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says sebum is the oily substance responsible for lubricating the surface of the skin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The condition caused by lack of oxygen in the blood that gives the skin a bluish coloration is called __________________.","o":["alopecia","shingles","cyanosis","blushing"],"a":2,"e":"Checked answer, not from an official key. Chapter 6 says cyanosis is the bluish discoloration of skin caused by lack of oxygen in the blood. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"The stratum __________________________ is the outermost layer of the skin.","o":["germinativum","corneum","spinosum","granulosum"],"a":1,"e":"Checked answer, not from an official key. Chapter 6 says the stratum corneum forms the outermost layer of the epidermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Which skin layer consists of spiny-shaped cells that are polyhedron in structure?","o":["stratum germinativum","stratum granulosum","stratum lucidum","stratum spinosum"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says the stratum spinosum has several layers of spiny-shaped cells that are polyhedral in structure. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"A thickened area of the skin that results from excess friction is known as a __________________________.","o":["papilla","nail body","Langerhans cell","callus"],"a":3,"e":"Checked answer, not from an official key. Chapter 6 says excessive abrasion or friction produces a thickened area called a callus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"First-degree burns only damage the epidermis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 says first-degree burns involve just the epidermis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Psoriasis is a common chronic skin disorder that is characterized by red patches covered by thick, dry, and silvery scales.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 6 describes psoriasis as a common chronic skin disorder with red patches covered with thick, dry, silvery scales. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Melanocytes produce the pigment keratin.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Melanocytes produce the pigment melanin. Keratin is a protein made as cells keratinize. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."},{"q":"Sweat glands produce sebum.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Sebum is made by sebaceous glands. Sweat glands make sweat. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 6."}],"caseStudy":{"title":"A hot, humid shift","scenario":"During several hours of work in warm humid conditions, a person’s skin becomes flushed and wet. Sweat drips from the surface, but cooling feels limited. A small friction callus is also visible on the palm.","prompts":["Trace the negative-feedback responses involving dermal vessels and eccrine glands.","Explain why high humidity limits cooling even when sweat production is high.","Identify the epidermal process responsible for the callus and explain its protective tradeoff.","List contextual factors needed before offering individualized fluid or electrolyte guidance."],"takeaway":"Skin observations become meaningful when layer anatomy, gland routes, environmental physics, and whole-body context are combined—without turning a visible sign into a diagnosis."},"perStepChapter":true},{"n":7,"title":"The Skeletal System","kicker":"Lesson 7 of your course, built from Chapter 7 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–90 minutes","steps":[{"id":"ap7-1","chapter":"What the skeleton does","title":"What the skeleton does","teach":["The skeletal system includes all the bones of the body plus their cartilage, tendons and ligaments. Bones are living tissue; their hardness comes from mineral salts like calcium phosphate in the matrix. The adult skeleton typically has 206 named bones.","It has five functions: support, protection of vital organs, movement (bones act as levers for muscles), making blood cells (hematopoiesis, mainly in red marrow), and storage of minerals (calcium and phosphorus) and fat.","Ligaments attach bone to bone. Tendons attach muscle to bone. Cartilage gives a smooth surface at joints and is the environment in which fetal bone develops."],"visual":{"kind":"hub","title":"Five functions of the skeleton","items":[{"label":"Support","detail":"Holds up muscles, vessels, nerves, fat and skin."},{"label":"Protection","detail":"Brain, spinal cord, heart and lungs."},{"label":"Movement","detail":"Bones are levers pulled by muscles."},{"label":"Blood cell formation","detail":"Hematopoiesis in red bone marrow."},{"label":"Storage","detail":"Calcium, phosphorus and fat."}]},"act":{"type":"choice","prompt":"Making blood cells in red bone marrow is called:","options":[{"label":"Hematopoiesis","correct":true,"feedback":"Right."},{"label":"Ossification","correct":false,"feedback":"Ossification is the formation of bone."},{"label":"Osteomalacia","correct":false,"feedback":"That’s softening of the bones in adults."}]}},{"id":"ap7-2","chapter":"Bone cells and growth","title":"Bone cells and growth","teach":["Osteoblasts are bone-forming cells that develop from osteoprogenitor cells under the periosteum (the fibrovascular membrane covering bone) and in the endosteum (lining the medullary cavity). When an osteoblast is surrounded by matrix it becomes an osteocyte, a mature bone cell.","Osteoclasts, which come from immune cells, reabsorb (remove) bone during remodeling, such as after a break or when braces straighten a bow-legged child’s legs.","Strain builds bone: the more stress on a bone, the more bone is deposited. That’s why the heel bone is so large, why bones in a cast weaken, and why exercise strengthens them.","Bones grow in length at the epiphyseal plate until about 15 in girls and 16 in boys; maturation continues to about 21."],"act":{"type":"sort","prompt":"Which bone cell?","categories":["Osteoblast","Osteocyte","Osteoclast"],"items":[{"label":"Forms new bone","category":0,"feedback":"Osteoblasts build bone."},{"label":"Mature bone cell in a lacuna","category":1,"feedback":"Osteocyte."},{"label":"Reabsorbs bone during remodeling","category":2,"feedback":"Osteoclast."},{"label":"Comes from immune system cells","category":2,"feedback":"Osteoclasts do."}]}},{"id":"ap7-3","chapter":"Ossification","title":"Ossification","teach":["Ossification is the formation of bone by osteoblasts. The fetal skeleton is mostly cartilage at three months; bone forms over the remaining months. Cartilage doesn’t turn into bone; it’s the environment where bone develops.","Intramembranous ossification replaces connective tissue membranes with bone. Only the cranial bones form this way. The unfinished membranes are the fontanelles, or soft spots, on a baby’s skull.","Endochondral ossification forms all the other bones, using cartilage as the environment (endo = inside, chondro = cartilage).","Calcium balance is controlled by hormones: calcitonin (thyroid) stores calcium in bone; parathormone (parathyroids) releases it into the blood."],"act":{"type":"sort","prompt":"Which type of ossification?","categories":["Intramembranous","Endochondral"],"items":[{"label":"Cranial bones","category":0,"feedback":"Only the skull forms this way."},{"label":"Femur","category":1,"feedback":"Long bones form in cartilage."},{"label":"Leaves fontanelles in a newborn","category":0,"feedback":"The soft spots."},{"label":"Cartilage is the environment for bone","category":1,"feedback":"Endo-chondral."}]}},{"id":"ap7-4","chapter":"Compact bone and the osteon","title":"Compact bone and the osteon","teach":["Compact bone is dense and strong. Its unit is the haversian system, or osteon, named after Clopton Havers.","At its center is the haversian (central) canal carrying blood vessels. Around it are concentric rings of bone, each called a lamella. Between the lamellae are tiny cavities, lacunae, each holding an osteocyte. Tiny canals called canaliculi connect the lacunae to each other and to the central canal. Volkmann’s (perforating) canals run crosswise and also carry vessels.","Tissue fluid flows through all these canals, bringing oxygen and nutrients to the osteocytes and carrying away waste."],"visual":{"kind":"hub","title":"Parts of an osteon","items":[{"label":"Central (haversian) canal","detail":"Runs lengthwise; blood vessels."},{"label":"Lamella","detail":"One concentric ring of bone."},{"label":"Lacuna","detail":"Small cavity holding an osteocyte."},{"label":"Canaliculi","detail":"Tiny canals linking lacunae."},{"label":"Perforating (Volkmann’s) canal","detail":"Runs crosswise; blood vessels."}]},"act":{"type":"sort","prompt":"Match each osteon part to its description.","categories":["Lamella","Lacuna","Canaliculi","Central canal"],"items":[{"label":"A concentric ring of bone","category":0,"feedback":"Lamella."},{"label":"Cavity holding an osteocyte","category":1,"feedback":"Lacuna."},{"label":"Tiny canals connecting the cavities","category":2,"feedback":"Canaliculi."},{"label":"Center of the osteon, with blood vessels","category":3,"feedback":"Haversian (central) canal."}]}},{"id":"ap7-5","chapter":"Spongy bone and marrow","title":"Spongy bone and marrow","teach":["Cancellous (spongy) bone is at the ends of long bones and the center of other bones. It’s a meshwork of bony plates called trabeculae, strong but light, with marrow in the spaces.","Red bone marrow makes red and white blood cells and platelets. In adults it’s in the ribs, vertebrae, sternum and pelvis.","Yellow bone marrow is mostly fat and fills the medullary cavity in the shafts of long bones."],"act":{"type":"choice","prompt":"What fills the medullary cavity of a long bone in an adult?","options":[{"label":"Yellow bone marrow (mostly fat)","correct":true,"feedback":"Right."},{"label":"Red bone marrow","correct":false,"feedback":"In adults, red marrow is mainly in the ribs, vertebrae, sternum and pelvis."},{"label":"Cartilage","correct":false,"feedback":"Cartilage covers joint surfaces."}]}},{"id":"ap7-6","chapter":"Bone shapes and the long bone","title":"Bone shapes and the long bone","teach":["Long bones are longer than they are wide (femur, humerus, and also metacarpals and phalanges). Short bones lack a long axis (carpals, tarsals). Flat bones are thin, usually curved, and found where muscles need wide attachment or soft organs need protection (sternum, ribs, scapula, skull bones). Irregular bones have odd shapes (vertebrae, ear ossicles). Sesamoid bones are small, round and inside tendons; the patella is the largest.","A long bone has a diaphysis (shaft, mostly compact bone), a metaphysis at each flared end, and an epiphysis at each end, separated by the epiphyseal (growth) line. The interior of the shaft is the medullary cavity. The periosteum covers the outside."],"act":{"type":"sort","prompt":"Classify each bone by shape.","categories":["Long","Short","Flat","Irregular","Sesamoid"],"items":[{"label":"Femur","category":0,"feedback":"Long."},{"label":"Carpals","category":1,"feedback":"Short."},{"label":"Sternum","category":2,"feedback":"Flat."},{"label":"Vertebra","category":3,"feedback":"Irregular."},{"label":"Patella","category":4,"feedback":"The largest sesamoid bone."},{"label":"Scapula","category":2,"feedback":"Flat."}]}},{"id":"ap7-7","chapter":"Bone markings","title":"Bone markings","teach":["Processes stick out: a spine is sharp and slender; a condyle is a rounded knuckle at a joint; a tubercle is a small round bump; a trochanter is a very large projection (femur); a crest is a narrow ridge (iliac crest); a head is an enlarged end, joined to the rest by a neck.","Fossae are depressions or openings: a suture is a narrow junction between skull bones; a foramen is a hole for vessels and nerves; a meatus is a tube-like canal; a sinus is a cavity in a bone; a sulcus is a groove."],"act":{"type":"sort","prompt":"Process (projection) or fossa (depression/opening)?","categories":["Process","Fossa"],"items":[{"label":"Condyle","category":0,"feedback":"A rounded projection."},{"label":"Foramen","category":1,"feedback":"An opening."},{"label":"Trochanter","category":0,"feedback":"A very large projection."},{"label":"Sinus","category":1,"feedback":"A cavity."},{"label":"Crest","category":0,"feedback":"A ridge."},{"label":"Meatus","category":1,"feedback":"A canal."}]}},{"id":"ap7-8","chapter":"Fractures and bone disorders","title":"Fractures and bone disorders","teach":["A fracture is a break in a bone or its cartilage. Open (compound) fractures break through the skin; closed (simple) ones don’t. A greenstick fracture is incomplete; a comminuted fracture shatters into pieces.","Rickets (children) and osteomalacia (adults) are caused by a lack of calcium, phosphorus or vitamin D/sunlight; bones stay soft.","Osteoporosis is loss of bone mass with more fractures, linked to falling estrogen. Paget’s disease is a common nonmetabolic bone disease with irregular thickening and softening of bones. Acromegaly is caused by an overactive anterior pituitary making too much growth hormone, widening the bones of the hands, face, jaws and feet. Spina bifida is a defect in the vertebral arch."],"act":{"type":"sort","prompt":"Match the disorder to its cause or sign.","categories":["Rickets","Osteoporosis","Paget’s disease","Acromegaly"],"items":[{"label":"Children lacking vitamin D and calcium","category":0,"feedback":"Rickets."},{"label":"Loss of bone mass after menopause","category":1,"feedback":"Osteoporosis."},{"label":"Irregular thickening and softening of bone","category":2,"feedback":"Paget’s disease."},{"label":"Too much growth hormone in adults","category":3,"feedback":"Acromegaly."}]}},{"id":"ap7-9","chapter":"The skeleton: axial and appendicular","title":"The skeleton: axial and appendicular","teach":["The axial skeleton is the skull (28 bones, cranial and facial), the hyoid, the vertebrae (26), the ribs (24) and the sternum.","The appendicular skeleton is the upper extremities (64 bones, including the shoulder girdles) and the lower extremities (62 bones, including the pelvic girdle)."],"act":{"type":"sort","prompt":"Axial or appendicular?","categories":["Axial","Appendicular"],"items":[{"label":"Skull","category":0,"feedback":"Axial."},{"label":"Ribs","category":0,"feedback":"Axial."},{"label":"Femur","category":1,"feedback":"Appendicular."},{"label":"Scapula","category":1,"feedback":"Part of the shoulder girdle."},{"label":"Vertebrae","category":0,"feedback":"Axial."},{"label":"Hip bones","category":1,"feedback":"Pelvic girdle."}]}},{"id":"ap7-10","chapter":"Cranial bones","title":"Cranial bones","teach":["The cranium protects the brain and sense organs. Its bones are joined by immovable sutures.","Frontal: the forehead and roof of the orbits; joins the parietals at the coronal suture. Parietals (2): the upper sides and roof; joined at the sagittal suture. Occipital: the back and base; joins the parietals at the lambdoid suture and has the foramen magnum, the large opening where the spinal cord connects to the brain. Its occipital condyles rest on the atlas.","Temporals (2): the lower sides; each encloses an ear and has the mastoid process and the styloid process. Sphenoid: looks like a butterfly and anchors all the cranial bones together. Ethmoid: supports the nasal cavities; the lightest cranial bone.","The ear ossicles are the malleus, incus and stapes. Wormian bones sit in sutures and aren’t counted."],"act":{"type":"sort","prompt":"Which cranial bone?","categories":["Frontal","Occipital","Temporal","Sphenoid","Ethmoid"],"items":[{"label":"Forms the forehead","category":0,"feedback":"Frontal."},{"label":"Has the foramen magnum","category":1,"feedback":"Occipital."},{"label":"Encloses the ear; has the mastoid process","category":2,"feedback":"Temporal."},{"label":"Butterfly-shaped anchor for the cranial bones","category":3,"feedback":"Sphenoid."},{"label":"Lightest cranial bone; supports the nasal cavities","category":4,"feedback":"Ethmoid."}]}},{"id":"ap7-11","chapter":"Facial bones and the hyoid","title":"Facial bones and the hyoid","teach":["Facial bones are joined by sutures, except the mandible, which moves.","Nasal bones (2) form the bridge of the nose. Palatine bones (2) form the back of the hard palate. Maxillae (2) form the upper jaw and hold the upper teeth; if they don’t fuse, the result is a cleft palate. Zygomatic (malar) bones (2) form the cheeks. Lacrimal bones (2) hold the tear sac. Nasal conchae (turbinates) warm and filter air. The vomer forms the lower nasal septum.","The mandible is the strongest and longest bone of the face and forms the lower jaw.","The hyoid bone supports the tongue and doesn’t articulate with any other bone; it hangs from the styloid processes by ligaments."],"act":{"type":"choice","prompt":"Which is the strongest and longest bone of the face?","options":[{"label":"Mandible","correct":true,"feedback":"Right. It forms the lower jaw."},{"label":"Maxilla","correct":false,"feedback":"The maxillae form the upper jaw."},{"label":"Zygomatic","correct":false,"feedback":"The zygomatic bones are the cheekbones."}]}},{"id":"ap7-12","chapter":"The vertebral column","title":"The vertebral column","teach":["The spine has 26 vertebrae separated by intervertebral disks of fibrocartilage: 7 cervical, 12 thoracic, 5 lumbar, plus the sacrum (5 fused) and the coccyx (4 fused).","A typical vertebra has a body, a neural arch around the vertebral foramen (for the spinal cord), a spinous process and two transverse processes, and articular processes.","The atlas (C1) holds up the head; the axis (C2) is the pivot it rotates on. Thoracic vertebrae have long downward spines and facets for ribs. Lumbar vertebrae are the largest and strongest.","Abnormal curves: kyphosis (hunchback, upper thoracic), lordosis (swayback, lumbar) and scoliosis (sideways curve, usually thoracic)."],"mnemonic":{"cue":"Breakfast at 7, lunch at 12, dinner at 5","explanation":"7 cervical, 12 thoracic, 5 lumbar vertebrae."},"act":{"type":"sort","prompt":"Match the spinal curvature to the region.","categories":["Kyphosis","Lordosis","Scoliosis"],"items":[{"label":"Exaggerated upper thoracic curve (hunchback)","category":0,"feedback":"Kyphosis."},{"label":"Exaggerated lumbar curve (swayback)","category":1,"feedback":"Lordosis."},{"label":"Sideways curve","category":2,"feedback":"Scoliosis."}]}},{"id":"ap7-13","chapter":"The thoracic cage","title":"The thoracic cage","teach":["The rib cage (sternum, costal cartilages, ribs and thoracic vertebrae) protects the heart and lungs.","The sternum, or breastbone, is shaped like a sword: the manubrium (handle), the gladiolus or body (blade) and the xiphoid process (tip).","There are 12 pairs of ribs. The upper seven pairs attach directly to the sternum: true ribs. The lower five pairs are false ribs. Pairs 8 to 10 attach indirectly through the 7th rib’s cartilage, and pairs 11 and 12 don’t attach in front at all: floating ribs."],"act":{"type":"sort","prompt":"What kind of rib?","categories":["True ribs","False ribs (attach indirectly)","Floating ribs"],"items":[{"label":"Pairs 1–7","category":0,"feedback":"Attach directly to the sternum."},{"label":"Pairs 8–10","category":1,"feedback":"Attach through the 7th rib’s cartilage."},{"label":"Pairs 11–12","category":2,"feedback":"No front attachment."}]}},{"id":"ap7-14","chapter":"Upper extremity","title":"Upper extremity","teach":["The shoulder (pectoral) girdle is the clavicle (collarbone) and scapula (shoulder blade). The scapula’s glenoid fossa receives the head of the humerus.","The humerus is the largest and longest bone of the upper arm. The ulna is the longer, medial forearm bone; its olecranon process is the elbow (\"funny bone\"). The radius is the shorter, lateral forearm bone.","The wrist has 8 carpals in two rows (pisiform, triquetral, lunate, scaphoid; hamate, capitate, trapezoid, trapezium). The palm has 5 metacarpals. Each finger has 3 phalanges; the thumb has 2."],"act":{"type":"sort","prompt":"Where is each bone?","categories":["Arm","Forearm","Wrist","Hand"],"items":[{"label":"Humerus","category":0,"feedback":"Upper arm."},{"label":"Ulna","category":1,"feedback":"Medial forearm."},{"label":"Radius","category":1,"feedback":"Lateral forearm."},{"label":"Carpals","category":2,"feedback":"Wrist bones."},{"label":"Metacarpals","category":3,"feedback":"Palm."}]}},{"id":"ap7-15","chapter":"Pelvic girdle and lower extremity","title":"Pelvic girdle and lower extremity","teach":["The pelvic girdle is the two hip (coxal) bones, which meet at the front at the pubic symphysis and at the back with the sacrum. Each hip bone is three fused parts: the ilium (largest, with the iliac crest), the ischium (strongest; you sit on its tuberosity) and the pubis. The obturator foramen is the largest foramen in the body. The acetabulum is the socket for the femur.","The femur is the largest and heaviest bone. The patella (kneecap) is the largest sesamoid bone. The tibia (shinbone) is the larger lower-leg bone; the fibula is the slender lateral one.","The ankle has 7 tarsals; the calcaneus (heel) is the largest. The foot has 5 metatarsals and 14 phalanges.","The foot has two longitudinal arches and one transverse arch. The medial longitudinal arch is the highest. Flat foot is pes planus."],"act":{"type":"sort","prompt":"Match the bone to its description.","categories":["Femur","Patella","Tibia","Calcaneus"],"items":[{"label":"Largest and heaviest bone","category":0,"feedback":"Femur."},{"label":"Largest sesamoid bone","category":1,"feedback":"Patella."},{"label":"Shinbone","category":2,"feedback":"Tibia."},{"label":"Heel bone; largest tarsal","category":3,"feedback":"Calcaneus."}]}},{"id":"ap7-16","chapter":"Bones and aging","title":"Bones and aging","teach":["With age, less protein matrix forms and calcium is lost, so bones break more easily. Less collagen in tendons and ligaments makes the skeleton stiffer.","People \"shrink\" because the intervertebral disks thin: from about age 40, roughly half an inch every 20 years. Calcium-rich food and regular exercise like walking help."],"act":{"type":"choice","prompt":"Why do people lose height with age, according to the textbook?","options":[{"label":"The intervertebral disks thin","correct":true,"feedback":"Right."},{"label":"The femur gets shorter","correct":false,"feedback":"It’s the disks in the spine."},{"label":"The skull shrinks","correct":false,"feedback":"It’s the disks."}]}}],"flashcards":[{"front":"Skeletal system","back":"All bones plus their cartilage, tendons and ligaments."},{"front":"Number of bones","back":"206 named bones."},{"front":"Hematopoiesis","back":"Making blood cells, chiefly in red bone marrow."},{"front":"Ligament / tendon","back":"Bone to bone / muscle to bone."},{"front":"Periosteum","back":"Fibrovascular membrane covering bone."},{"front":"Osteoblast / osteocyte / osteoclast","back":"Builds bone / mature bone cell / reabsorbs bone."},{"front":"Ossification","back":"The formation of bone."},{"front":"Intramembranous vs endochondral","back":"Cranial bones only / all other bones, in cartilage."},{"front":"Calcitonin / parathormone","back":"Stores calcium in bone / releases it to the blood."},{"front":"Osteon parts","back":"Central canal, lamellae, lacunae (osteocytes), canaliculi, perforating canals."},{"front":"Lamella","back":"A concentric ring of bone around the central canal."},{"front":"Medullary cavity","back":"Interior of a long bone’s shaft, with yellow marrow."},{"front":"Diaphysis / epiphysis","back":"Shaft / end of a long bone."},{"front":"Flat bones","back":"Thin; for muscle attachment or protection (sternum, ribs, scapula, skull)."},{"front":"Fracture","back":"A break in a bone or its cartilage."},{"front":"Rickets","back":"Soft bones in children from lack of calcium, phosphorus or vitamin D."},{"front":"Paget’s disease","back":"Nonmetabolic disease with irregular thickening and softening of bone."},{"front":"Acromegaly","back":"Too much growth hormone from the anterior pituitary in adults."},{"front":"Foramen magnum","back":"Large opening in the occipital bone for the spinal cord."},{"front":"Sphenoid","back":"Butterfly-shaped bone anchoring the cranial bones."},{"front":"Mandible","back":"Strongest and longest facial bone; lower jaw."},{"front":"Vertebrae","back":"7 cervical, 12 thoracic, 5 lumbar, sacrum, coccyx (26 total)."},{"front":"Lordosis / kyphosis / scoliosis","back":"Lumbar swayback / thoracic hunchback / sideways curve."},{"front":"True / false / floating ribs","back":"Pairs 1–7 / 8–12 / 11–12."},{"front":"Sternum parts","back":"Manubrium, gladiolus (body), xiphoid process."},{"front":"Humerus","back":"Largest and longest bone of the upper arm."},{"front":"Carpals / tarsals","back":"Wrist bones / ankle bones."},{"front":"Pelvic girdle","back":"The two hip bones (ilium, ischium, pubis fused)."},{"front":"Patella","back":"Kneecap; largest sesamoid bone."},{"front":"Highest arch of the foot","back":"Medial longitudinal arch."}],"quiz":[{"q":"The breaking of a bone or the associated cartilage is called a(n) __________________________.","o":["ricket","osteomalacia","epiphysis","fracture"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the breaking of bone or associated cartilage is known as a fracture. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ system includes all the bones of the body and their associated cartilage, tendons, and ligaments.","o":["integumentary","urinary","skeletal","muscular"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the skeletal system includes all the bones of the body and their associated cartilage, tendons and ligaments. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _______________ bone is the strongest and longest bone of the face and forms the lower jaw.","o":["maxillary","sphenoid","mandible","zygomatic"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the mandible is the strongest and longest bone of the face. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Overactivity of the anterior pituitary gland results in excessive secretions of growth hormone and which chronic condition?","o":["Acromegaly","Spina bifida","Cleft palate","Osteomalacia"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says acromegaly is a chronic condition caused by overactivity of the anterior pituitary, resulting in excessive growth hormone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Abnormal curvature of the lumbar portion of the spine is called _________________.","o":["lordosis","scoliosis","kyphosis","rickets"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says lordosis, or swayback, is an abnormal accentuated lumbar curvature. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which disease occurs in children and is caused by deficiencies in calcium and vitamin D?","o":["Fracture","Rickets","Osteoporosis","Diaphysis"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says rickets occurs in children and is caused by deficiencies in calcium, phosphorus or vitamin D. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The term for the formation of bone is called _________________________.","o":["calcification","ossification","fontanellation","chondrofication"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 defines ossification as the formation of bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The ____________________ bone looks like a butterfly and acts as an anchor binding all of the cranial bones together.","o":["frontal","sphenoid","occipital","temporal"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the sphenoid looks like a butterfly from below and acts as an anchor binding all the cranial bones together. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ is the largest and longest bone of the upper arm.","o":["ulna","humerus","tibia","radius"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the humerus is the largest and longest bone of the upper arm. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The highest arch of the foot is the _____________________ arch.","o":["longitudinal","transverse","medial longitudinal","medial"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the medial longitudinal arch is the highest arch of the foot. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The central canal of an osteon is surrounded by concentric rings of bone, each layer of which is called a(n) ______________________________.","o":["canaliculus","lamella","lacuna","perforating canal"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says the central canals are surrounded by concentric rings of bone, each called a lamella. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which bones are thin and typically found where there is a need for extensive muscle attachment or protection for soft or vital parts of the body?","o":["Long","Flat","Short","Irregular"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says flat bones are thin bones found where there is a need for extensive muscle attachment or protection for soft or vital parts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The _____________________ girdle is made up of the two hip bones.","o":["pectoral","pubic","iliac","pelvic"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the pelvic girdle is made up of the two hip (coxal) bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The fibrovascular membrane that covers bone is called the _________________________.","o":["periosteum","perichondrium","endosteum","osseus"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 calls the fibrovascular membrane that covers a bone the periosteum. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The occipital bone has a large opening called the _____________________ through which the spinal cord connects to the brain.","o":["mental foramen","occipital condyle","foramen magnum","temporal condyle"],"a":2,"e":"Checked answer, not from an official key. Chapter 7 says the occipital bone has a large opening called the foramen magnum, through which the spinal cord connects with the brain. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The upper seven pairs of ribs articulate directly with the sternum and are called _____________ ribs.","o":["true","free","floating","false"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the upper seven pairs of ribs articulate directly with the sternum and are called true ribs. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Which common non-metabolic disease presents with irregular thickening and softening of the bones?","o":["Gigantism","Paget’s disease","Osteoporosis","Rickets"],"a":1,"e":"Checked answer, not from an official key. Chapter 7 says Paget’s disease is a common nonmetabolic bone disease with irregular thickening and softening of the bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The type of bone cell responsible for the reabsorption of bone is called an ____________________.","o":["osteocyte","osteoblast","osteogenic cell","osteoclast"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says osteoclasts are responsible for the reabsorption of bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The breastbone is called the _____________________.","o":["scapula","clavicle","rib","sternum"],"a":3,"e":"Checked answer, not from an official key. Chapter 7 says the sternum is also known as the breastbone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The ______________ (kneecap) is the largest sesamoid bone in the human body.","o":["patella","scapula","fibula","tibia"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the patella, or kneecap, is the largest of the sesamoid bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The interior of the shaft of long bone contains the ______________________________.","o":["medullary cavity","cortical cavity","medullary sinus","cortical sinus"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says the interior of the shaft of a long bone is the medullary cavity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The tiny cavities in the osteon called lacunae contain _____________________.","o":["osteocytes","osteoblasts","osteoclasts","chondroblasts"],"a":0,"e":"Checked answer, not from an official key. Chapter 7 says each lacuna contains an osteocyte, or bone cell. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"Tendons are tough connective tissue structures that attach bones to bones.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Tendons attach muscle to bone. Ligaments attach bone to bone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"The bones of the wrist are called tarsals.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The wrist bones are carpals. Tarsals are the ankle bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."},{"q":"There are 14 thoracic vertebrae.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. There are 12 thoracic vertebrae. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 7."}],"caseStudy":{"title":"From a fall to a systems explanation","scenario":"An older adult reports a recent fall and asks whether drinking more milk alone will “rebuild” every weak bone.","prompts":["Name the skeletal functions relevant to the fall.","Explain remodeling using osteoblasts and osteoclasts.","Identify the limits of a one-food explanation.","State which concerns require clinical assessment rather than nutrition education alone."],"takeaway":"Use anatomy to explain the system, support adequate nutrition without promises, and keep fracture and bone-density assessment within clinical care."},"perStepChapter":true},{"n":8,"title":"The Articular System","kicker":"Lesson 8 of your course, built from Chapter 8 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"60–80 minutes","steps":[{"id":"ap8-1","chapter":"What a joint is","title":"What a joint is","teach":["An articulation, or joint, is any place where two or more bones meet, whatever the amount of movement. Skull sutures are joints as much as the knee is.","Joints are classified by how much they move (function) and by what holds them together (structure) into three groups: synarthroses (no movement), amphiarthroses (slight movement) and diarthroses (free movement)."],"visual":{"kind":"flow","title":"Three joint groups","items":[{"label":"Synarthroses","detail":"No movement: suture, syndesmosis, gomphosis."},{"label":"Amphiarthroses","detail":"Slight movement: symphysis, synchondrosis."},{"label":"Diarthroses (synovial)","detail":"Free movement: six types, like the hip and knee."}]},"mnemonic":{"cue":"SYN = sealed, AMPHI = a little, DI = do anything","explanation":"Synarthroses don’t move, amphiarthroses move a little, diarthroses move freely."},"act":{"type":"sort","prompt":"How much does each group move?","categories":["No movement","Slight movement","Free movement"],"items":[{"label":"Synarthroses","category":0,"feedback":"Immovable."},{"label":"Amphiarthroses","category":1,"feedback":"Slightly movable."},{"label":"Diarthroses","category":2,"feedback":"Freely movable."}]}},{"id":"ap8-2","chapter":"Synarthroses: immovable joints","title":"Synarthroses: immovable joints","teach":["A suture joins bones with a thin layer of fibrous tissue, as in the skull. The tissue is left over from intramembranous ossification.","A syndesmosis connects bones with ligaments between them, like the radius and ulna, or the tibia and fibula. (Some authors call these amphiarthroses.)","A gomphosis is a cone-shaped process held in a socket by ligaments: a tooth in its alveolus, held by the periodontal ligament."],"act":{"type":"sort","prompt":"Which synarthrosis?","categories":["Suture","Syndesmosis","Gomphosis"],"items":[{"label":"Joints of the skull","category":0,"feedback":"Suture."},{"label":"Radius and ulna joined by ligament","category":1,"feedback":"Syndesmosis."},{"label":"Tooth in its socket","category":2,"feedback":"Gomphosis."}]}},{"id":"ap8-3","chapter":"Amphiarthroses: slightly movable joints","title":"Amphiarthroses: slightly movable joints","teach":["A symphysis joins bones with a disk of fibrocartilage. The pubic symphysis gives a little during delivery to widen the birth canal.","A synchondrosis joins two bony surfaces with hyaline cartilage, later replaced by bone. Examples: the growth plate between the epiphysis and diaphysis of a long bone, and the rib-to-sternum cartilage. (Some authors call it a synarthrosis.)"],"act":{"type":"sort","prompt":"Symphysis or synchondrosis?","categories":["Symphysis (fibrocartilage)","Synchondrosis (hyaline cartilage)"],"items":[{"label":"Pubic symphysis","category":0,"feedback":"Disk of fibrocartilage."},{"label":"Growth plate between epiphysis and diaphysis","category":1,"feedback":"Hyaline cartilage."},{"label":"Ribs joined to the sternum by cartilage","category":1,"feedback":"Synchondrosis."}]}},{"id":"ap8-4","chapter":"Diarthroses: synovial joints","title":"Diarthroses: synovial joints","teach":["Diarthroses (synovial joints) move freely. They always have a cavity enclosed by a capsule. Ligaments reinforce the capsule, articular cartilage covers the bone ends, and a synovial membrane lines the inside and makes synovial fluid. Most joints of the arms and legs are diarthroses.","Synovial fluid creates a smooth gliding surface for opposing bones and nourishes the articular cartilage, which has little blood supply.","Looser capsules allow more movement. The shoulder has the widest range; the hip is more restricted because its capsule is thicker and the femur is held in the acetabulum by strong ligaments. Muscles and tendons around the capsule add stability."],"act":{"type":"choice","prompt":"What provides a smooth gliding surface for opposing bones in a synovial joint?","options":[{"label":"Synovial fluid","correct":true,"feedback":"Right. It also nourishes the cartilage."},{"label":"Sebum","correct":false,"feedback":"Sebum lubricates the skin."},{"label":"Desmosomes","correct":false,"feedback":"Desmosomes hold skin cells together."}]}},{"id":"ap8-5","chapter":"Movements: bending, straightening and side to side","title":"Movements: bending, straightening and side to side","teach":["Flexion decreases the angle between bones (bending). Extension increases it (straightening). Hyperextension goes beyond anatomic position.","Abduction moves a bone away from the midline. Adduction moves it toward the midline.","Rotation turns a bone around its own axis, like shaking your head. Circumduction moves a limb so its end draws a circle and its sides draw a cone."],"mnemonic":{"cue":"ABduction ABducts it away; ADDuction ADDs it back","explanation":"Abduction moves away from the midline; adduction brings it back to the body."},"act":{"type":"sort","prompt":"Name the movement.","categories":["Flexion","Extension","Abduction","Adduction"],"items":[{"label":"Bending the elbow","category":0,"feedback":"Decreases the angle."},{"label":"Straightening the knee","category":1,"feedback":"Increases the angle."},{"label":"Raising your arm out to the side","category":2,"feedback":"Away from the midline."},{"label":"Bringing your arm back to your side","category":3,"feedback":"Toward the midline."}]}},{"id":"ap8-6","chapter":"Movements of the hand, foot and jaw","title":"Movements of the hand, foot and jaw","teach":["Supination turns the palm up (forearm bones parallel). Pronation turns the palm down (bones crossed). These are forearm and hand movements.","Eversion turns the sole of the foot outward; inversion turns it inward. Dorsiflexion raises the foot up at the ankle; plantar flexion pushes it down.","Protraction moves a part forward and retraction moves it back, like the jaw. Elevation raises a part and depression lowers it, like shrugging the shoulders. Opposition brings the thumb tip to the fingertips; it’s unique to primates. Reposition returns the digits."],"mnemonic":{"cue":"Supination = holding a bowl of SOUP","explanation":"Palm up is supination; palm down is pronation."},"act":{"type":"sort","prompt":"Which part of the body does each movement belong to?","categories":["Forearm and hand","Foot and ankle","Jaw or shoulder"],"items":[{"label":"Supination and pronation","category":0,"feedback":"Forearm and hand."},{"label":"Eversion and inversion","category":1,"feedback":"Foot."},{"label":"Dorsiflexion","category":1,"feedback":"Raising the foot at the ankle."},{"label":"Protraction and retraction","category":2,"feedback":"For example, the jaw."},{"label":"Opposition","category":0,"feedback":"The thumb."},{"label":"Elevation and depression","category":2,"feedback":"For example, the shoulders."}]}},{"id":"ap8-7","chapter":"Six types of synovial joints","title":"Six types of synovial joints","teach":["Ball-and-socket (multiaxial): a ball fits into a socket, giving the widest range of motion in all planes. Shoulder and hip; the shoulder moves more.","Hinge (uniaxial): flexion and extension in one plane. Elbow, knee, and the middle and distal finger and toe joints.","Pivot (uniaxial): rotation in one plane, like the atlas turning on the axis.","Condyloid or ellipsoidal (biaxial): an oval condyle in an elliptical cavity, moving in two planes. The wrist joint between the radius and carpals.","Saddle (biaxial): found only in the thumb, between the trapezium and the first metacarpal. It allows opposition.","Gliding (multiaxial): flat surfaces that only glide, like the joints between vertebral articular processes."],"act":{"type":"sort","prompt":"Match the joint to its type.","categories":["Ball-and-socket","Hinge","Pivot","Saddle"],"items":[{"label":"Shoulder","category":0,"feedback":"Ball-and-socket."},{"label":"Elbow","category":1,"feedback":"Hinge."},{"label":"Atlas on axis","category":2,"feedback":"Pivot."},{"label":"Base of the thumb","category":3,"feedback":"Saddle, only in the thumb."},{"label":"Knee","category":1,"feedback":"Hinge."},{"label":"Hip","category":0,"feedback":"Ball-and-socket."}]}},{"id":"ap8-8","chapter":"Uniaxial, biaxial, multiaxial","title":"Uniaxial, biaxial, multiaxial","teach":["Joints are also named by how many planes they move in. Uniaxial: one plane (hinge, pivot). Biaxial: two planes at right angles (condyloid, saddle). Multiaxial: many planes (ball-and-socket; the textbook also calls gliding joints multiaxial)."],"act":{"type":"sort","prompt":"How many axes?","categories":["Uniaxial","Biaxial","Multiaxial"],"items":[{"label":"Hinge","category":0,"feedback":"One plane."},{"label":"Pivot","category":0,"feedback":"Rotation in one plane."},{"label":"Condyloid","category":1,"feedback":"Two planes."},{"label":"Saddle","category":1,"feedback":"Two planes."},{"label":"Ball-and-socket","category":2,"feedback":"All planes."}]}},{"id":"ap8-9","chapter":"Bursae","title":"Bursae","teach":["Bursae are closed sacs lined with synovial membrane, found wherever friction could happen between tendons, ligaments and bones.","Subcutaneous bursae are under the skin, over a bony process (like between the kneecap and the skin). Subfascial bursae are between muscles. Subtendinous bursae are where a tendon passes over another tendon or a bony projection, as in the shoulder."],"act":{"type":"sort","prompt":"Which type of bursa?","categories":["Subcutaneous","Subfascial","Subtendinous"],"items":[{"label":"Between the kneecap and the skin","category":0,"feedback":"Under the skin."},{"label":"Between two muscles","category":1,"feedback":"Between fasciae."},{"label":"Where a tendon passes over bone in the shoulder","category":2,"feedback":"Subtendinous."}]}},{"id":"ap8-10","chapter":"Joint disorders","title":"Joint disorders","teach":["Arthritis is inflammation of the whole joint; there are over 100 kinds. Rheumatoid arthritis is a connective tissue disorder with severe inflammation of small joints, possibly autoimmune. Osteoarthritis (degenerative joint disease) comes with age and affects weight-bearing joints. Gout is a build-up of uric acid crystals, often at the base of the big toe.","Bursitis is inflammation of a bursa. Tennis elbow (lateral epicondylitis) comes from overuse. Carpal tunnel syndrome is a repetitive-motion injury of the wrist, common with keyboard use.","A sprain tears ligaments. A dislocation is a bone temporarily displaced from its joint. A slipped (herniated) disk presses on the spinal cord; if therapy fails, a laminectomy removes the protruding disk."],"act":{"type":"sort","prompt":"Match the condition.","categories":["Gout","Rheumatoid arthritis","Carpal tunnel syndrome","Dislocation"],"items":[{"label":"Uric acid crystals at the base of the big toe","category":0,"feedback":"Gout."},{"label":"Severe inflammation of small joints","category":1,"feedback":"Rheumatoid arthritis."},{"label":"Repetitive wrist movements","category":2,"feedback":"Carpal tunnel syndrome."},{"label":"Bone temporarily displaced from a joint","category":3,"feedback":"Dislocation."}]}},{"id":"ap8-11","chapter":"Joints and aging","title":"Joints and aging","teach":["With age, collagen and elastin in joints stiffen, cartilage wears faster than it’s replaced, and synovial fluid production drops, so range of motion decreases.","Moderate, regular exercise helps keep joints flexible."],"act":{"type":"choice","prompt":"Which change does the textbook link to stiffer joints with age?","options":[{"label":"Less synovial fluid and less flexible tendons and ligaments","correct":true,"feedback":"Right."},{"label":"More cartilage on the bone ends","correct":false,"feedback":"Cartilage wears down with age."},{"label":"More bursae","correct":false,"feedback":"That isn’t in the textbook."}]}}],"flashcards":[{"front":"Articulation","back":"A joint: where two or more bones meet."},{"front":"Synarthroses","back":"Immovable joints: suture, syndesmosis, gomphosis."},{"front":"Amphiarthroses","back":"Slightly movable joints: symphysis, synchondrosis."},{"front":"Diarthroses","back":"Freely movable synovial joints; most limb joints."},{"front":"Suture","back":"Bones joined by fibrous tissue (skull)."},{"front":"Gomphosis","back":"Tooth in its socket."},{"front":"Symphysis","back":"Bones joined by fibrocartilage (pubic symphysis)."},{"front":"Synchondrosis","back":"Bones joined by hyaline cartilage (growth plate)."},{"front":"Synovial fluid","back":"Smooth gliding surface; nourishes articular cartilage."},{"front":"Flexion / extension","back":"Decrease / increase the angle between bones."},{"front":"Abduction / adduction","back":"Away from / toward the midline."},{"front":"Circumduction","back":"Limb end draws a circle; sides draw a cone."},{"front":"Supination / pronation","back":"Palm up / palm down."},{"front":"Eversion / inversion","back":"Sole of the foot outward / inward."},{"front":"Dorsiflexion / plantar flexion","back":"Foot up / foot down at the ankle."},{"front":"Opposition","back":"Thumb tip to fingertips."},{"front":"Ball-and-socket","back":"Multiaxial; shoulder and hip."},{"front":"Hinge joint","back":"Uniaxial; elbow, knee, fingers."},{"front":"Pivot joint","back":"Rotation; atlas and axis."},{"front":"Saddle joint","back":"Biaxial; only in the thumb."},{"front":"Subcutaneous bursae","back":"Under the skin over bony processes."},{"front":"Arthritis","back":"Inflammation of the whole joint."},{"front":"Gout","back":"Uric acid crystals, often at the base of the big toe."},{"front":"Laminectomy","back":"Surgical removal of a protruding disk."},{"front":"Dislocation","back":"A bone temporarily displaced from its joint."}],"quiz":[{"q":"Which joints do not allow movement?","o":["Diarthrosis","Synarthroses","Amphiarthoses","Fracture"],"a":1,"e":"Checked answer, not from an official key. Chapter 8 says synarthroses are joints between bones that do not allow movement. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"The act of bending or decreasing the angle between bones is called _____________________ .","o":["extension","distension","flexion","hyperextension"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 defines flexion as bending, or decreasing the angle between bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"An inflammation of the whole joint is called ___________________ .","o":["bursitis","tendonitis","fibrositis","arthritis"],"a":3,"e":"Checked answer, not from an official key. Chapter 8 says arthritis is an inflammation of the whole joint. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"A bone that is moved away from the midline has undergone _____________________ .","o":["abduction","protraction","adduction","pronation"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says abduction is moving a bone or limb away from the midline of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"The femur is connected to the acetabulum by a series of strong ________________________________ .","o":["ligaments","epithelium","sutures","synarthroses"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says the femur is connected to the acetabulum by a series of strong ligaments. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"A smooth gliding surface for opposing bones is provided by: ___________________________.","o":["desmosomes","synovial fluid","sebum","sweat"],"a":1,"e":"Checked answer, not from an official key. Chapter 8 says synovial fluid creates a smooth gliding surface for opposing bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Most joints of the upper and lower limbs are ______________________________ .","o":["amphiarthroses","sutures","diarthroses","synarthroses"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 says most joints of the upper and lower limbs are diarthroses. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"The elbow joint is an example of a _____________________ joint.","o":["hinge","condyloid","ball-and-socket","saddle"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 gives the elbow and knee as examples of hinge joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"A __________________________ is the surgical removal of a protruding disk.","o":["dislocation","rehabilitation","therapy","laminectomy"],"a":3,"e":"Checked answer, not from an official key. Chapter 8 says a laminectomy is the surgical removal of the protruding disk. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which movement involves raising the foot upward at the ankle joint?","o":["abduction","elevation","dorsiflexion","depression"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 says dorsiflexion is raising the foot up at the ankle joint. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"An example of a _____________________ is the joint between the epiphyses and the diaphysis of a long bone.","o":["gomphosis","symphysis","syndesmosis","synchondrosis"],"a":3,"e":"Checked answer, not from an official key. Chapter 8 gives the joint between the epiphyses and diaphysis of a long bone as an example of a synchondrosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Subcutaneous bursae are found under the _____________________.","o":["ligament","skin","bone","joint"],"a":1,"e":"Checked answer, not from an official key. Chapter 8 says subcutaneous bursae are found under the skin wherever it lies over a bony process. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Eversion and inversion refer to movements of the _____________________ .","o":["hand","wrist","knee","foot"],"a":3,"e":"Checked answer, not from an official key. Chapter 8 says eversion and inversion refer to movements of the foot. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which amphiarthrotic joints are characterized by two bony surfaces connected by hyaline cartilage?","o":["synchondroses","symphyses","gomphoses","syndesmoses"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says synchondroses are joints in which two bony surfaces are connected by hyaline cartilage. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"A temporarily displaced bone from a joint is called a _____________________.","o":["fracture","strain","dislocation","sprain"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 says a dislocation is a temporarily displaced bone from a joint. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which type of joint is found only in the thumb?","o":["saddle","hinge","condyloid","pivot"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says the saddle joint is found only in the thumb. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which disease occurs when an accumulation of uric acid crystals accumulates in the joint at the base of the large toe and in other joints of the feet and legs?","o":["Gout","Osteoarthritis","Rheumatoid arthritis","Bursitis"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says gout is an accumulation of uric acid crystals in the joint at the base of the large toe and other joints of the feet and legs. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"A ball-and-socket is an example of a(n) _____________________ joint.","o":["uniaxial","biaxial","multiaxial","hinge"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 says a ball-and-socket joint is an example of a multiaxial joint. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"The shoulder and hip are examples of _____________________ joints.","o":["hinge","condyloid","ball-and-socket","saddle"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 gives the hip and shoulder as the two ball-and-socket joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which type of arthritis is a connective tissue disorder resulting in severe inflammation of small joints?","o":["Fibroid","Rheumatoid","Osteoarthritis","Gout"],"a":1,"e":"Checked answer, not from an official key. Chapter 8 says rheumatoid arthritis is a connective tissue disorder causing severe inflammation of small joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"The joints of the skull are examples of _____________________ .","o":["syndesmoses","amphiarthroses","sutures","symphyses"],"a":2,"e":"Checked answer, not from an official key. Chapter 8 says the suture joints of the skull are examples of sutures. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Which injury is caused by repetitive movements that affect the wrist?","o":["Tennis elbow","Carpal tunnel syndrome","Dorsiflexion","Overextension"],"a":1,"e":"Checked answer, not from an official key. Chapter 8 says carpal tunnel syndrome, affecting the wrist, develops from long periods of repetitive keyboard use. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Pronation is a term used to describe movement of the jaw.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Pronation is a movement of the forearm and hand (palm down). The jaw protracts and retracts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"Extension increases the angle of bones.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 says extension is the act of increasing the angle between bones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."},{"q":"An example of an amphiarthrosis is a symphysis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 8 lists the symphysis as one of the two examples of amphiarthroses. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 8."}],"caseStudy":{"title":"Name the motion, then the structure","scenario":"A client with a clinician-confirmed wrist condition says repetitive chopping is difficult and asks what “kind of joint problem” it is.","prompts":["Describe the task using movement terms.","List the synovial structures that reduce friction or add stability.","Explain why symptoms alone cannot distinguish tendon, ligament, bursa or nerve involvement.","Suggest an appropriate scope-safe next step for meal-planning support."],"takeaway":"Use joint language to understand function and adapt the task; leave diagnosis and rehabilitation to the appropriate clinician."},"perStepChapter":true},{"n":9,"title":"The Muscular System","kicker":"Lesson 9 of your course, built from Chapter 9 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"75–95 minutes","steps":[{"id":"ap9-1","chapter":"Three types of muscle, revisited","title":"Three types of muscle, revisited","teach":["Muscles make up about 40% to 50% of body weight. Skeletal muscle is voluntary, striated and multinucleated. Smooth muscle is involuntary, has one nucleus and no striations, and lines hollow organs. Cardiac muscle is involuntary, striated and has one nucleus; it’s only in the heart.","Smooth and cardiac muscle are both controlled by the autonomic nervous system. So cardiac is the only striated muscle that’s under autonomic control."],"act":{"type":"choice","prompt":"Which striated muscle is controlled by the autonomic nervous system?","options":[{"label":"Cardiac","correct":true,"feedback":"Right. Skeletal muscle is striated too, but it’s voluntary."},{"label":"Skeletal","correct":false,"feedback":"Skeletal muscle is voluntary, controlled by the central nervous system."},{"label":"Smooth","correct":false,"feedback":"Smooth muscle is autonomic but not striated."}]}},{"id":"ap9-2","chapter":"Inside a skeletal muscle","title":"Inside a skeletal muscle","teach":["Skeletal muscle cells are long and slender, so they’re called muscle fibers. Each has many nuclei and an electrically polarized membrane, the sarcolemma.","Three layers of connective tissue hold a muscle together. The endomysium surrounds each fiber. Fibers are grouped into bundles called fascicles (fasciculi), each wrapped in perimysium. The epimysium, coarse irregular connective tissue, surrounds the whole muscle. Fascia covers the outside.","Each fiber is made of thousands of myofibrils, which are made of thick myosin and thin actin filaments."],"visual":{"kind":"flow","title":"From whole muscle to filament","items":[{"label":"Muscle (epimysium)","detail":"The whole muscle."},{"label":"Fascicle (perimysium)","detail":"A bundle of fibers."},{"label":"Muscle fiber (endomysium)","detail":"One cell."},{"label":"Myofibril","detail":"Thousands per fiber."},{"label":"Actin and myosin filaments","detail":"Thin and thick proteins."}]},"mnemonic":{"cue":"Epi = upon, Peri = around, Endo = within","explanation":"Epimysium wraps the whole muscle, perimysium wraps each fascicle, endomysium wraps each fiber."},"act":{"type":"sort","prompt":"Which connective tissue layer surrounds each part?","categories":["Epimysium","Perimysium","Endomysium"],"items":[{"label":"The whole muscle","category":0,"feedback":"Epimysium."},{"label":"A fascicle (bundle)","category":1,"feedback":"Perimysium."},{"label":"A single muscle fiber","category":2,"feedback":"Endomysium."}]}},{"id":"ap9-3","chapter":"Bands, lines and the sarcomere","title":"Bands, lines and the sarcomere","teach":["The stripes come from overlapping proteins. Dark A bands are thick myosin filaments. Light I bands are thin actin filaments.","The Z line runs through the middle of each I band. The H zone is the slightly lighter middle of the A band. The sarcomere, between two Z lines, is where contraction happens.","The sarcotubular system has two parts: T tubules, continuous with the sarcolemma, carry the impulse deep into the fiber, and the sarcoplasmic reticulum, wrapped around each myofibril, stores calcium."],"mnemonic":{"cue":"dArk = A band; lIght = I band","explanation":"The second letter of each word gives the band’s name."},"act":{"type":"sort","prompt":"Actin or myosin?","categories":["Actin","Myosin"],"items":[{"label":"Thin filaments","category":0,"feedback":"Actin."},{"label":"Thick filaments","category":1,"feedback":"Myosin."},{"label":"Light I bands","category":0,"feedback":"Actin."},{"label":"Dark A bands","category":1,"feedback":"Myosin."},{"label":"Heads that form cross-bridges","category":1,"feedback":"Myosin heads hold ATP."}]}},{"id":"ap9-4","chapter":"Motor units and muscle properties","title":"Motor units and muscle properties","teach":["A motor unit is one motor neuron and all the muscle fibers it supplies; they contract together. Fine movements (eye muscles) have about 10 fibers per unit; gross movements have 200 or more. The average is about 150.","Muscle cells have four properties: excitability (respond to a stimulus), conductivity (pass the response along), contractility and elasticity (return to shape)."],"act":{"type":"choice","prompt":"Muscles for fine movements, like the eye muscles, have:","options":[{"label":"Few muscle fibers per motor unit","correct":true,"feedback":"Right, about 10."},{"label":"Many fibers per motor unit","correct":false,"feedback":"That’s for gross movements."},{"label":"No motor units","correct":false,"feedback":"All skeletal muscles have motor units."}]}},{"id":"ap9-5","chapter":"Resting potential and the nerve signal","title":"Resting potential and the nerve signal","teach":["At rest, there’s more potassium inside the muscle cell and more sodium outside. Both are positive ions. The inside is negative and the outside positive: the resting potential.","When a nerve impulse reaches the neuromuscular junction, the axon terminals release acetylcholine. Sodium rushes into the cell, the inside becomes positive, and the muscle cell fires its own action potential: the signal to contract.","The action potential travels down the T tubules and makes the sarcoplasmic reticulum release calcium ions around the myofibrils."],"act":{"type":"order","prompt":"Put the steps in order.","items":[{"label":"Nerve impulse reaches the neuromuscular junction","detail":"Start"},{"label":"Acetylcholine is released","detail":"Neurotransmitter"},{"label":"Sodium rushes into the muscle cell","detail":"Action potential"},{"label":"Signal travels down the T tubules","detail":"Deep into the fiber"},{"label":"Sarcoplasmic reticulum releases calcium","detail":"Triggers contraction"}]}},{"id":"ap9-6","chapter":"The sliding filament contraction","title":"The sliding filament contraction","teach":["At rest, troponin and tropomyosin keep actin and myosin apart. Calcium binds to troponin and removes that block, activating myosin.","Myosin heads, carrying ATP, link to actin and form cross-bridges (actomyosin). Breaking ATP into ADP and phosphate releases energy that pulls the actin filaments in among the myosin. The Z lines move closer together; the A bands stay the same width.","The sodium-potassium pump restores the resting potential, calcium returns to the sarcoplasmic reticulum, and the muscle relaxes. The whole cycle takes about 1/40 of a second."],"act":{"type":"choice","prompt":"What does calcium do in contraction?","options":[{"label":"Binds to troponin, removing the block so myosin can link with actin","correct":true,"feedback":"Right."},{"label":"Carries the nerve impulse across the junction","correct":false,"feedback":"That’s acetylcholine."},{"label":"Supplies the energy for contraction","correct":false,"feedback":"ATP supplies the energy."}]}},{"id":"ap9-7","chapter":"Energy for contraction","title":"Energy for contraction","teach":["Muscles turn chemical energy (ATP) into mechanical energy. They get ATP four ways.","Aerobic respiration of glucose (38 ATP, per the textbook). Anaerobic breakdown when oxygen runs short: pyruvic acid becomes lactic acid, which builds up, with only 2 ATP. Phosphocreatine, found only in muscle, gives a fast supply: phosphocreatine + ADP ↔ creatine + ATP. And free fatty acids from the blood.","Heat is a by-product of every contraction."],"act":{"type":"sort","prompt":"Match each energy source to its description.","categories":["Aerobic glucose","Anaerobic glucose","Phosphocreatine","Fatty acids"],"items":[{"label":"Makes the most ATP; needs oxygen","category":0,"feedback":"Aerobic respiration."},{"label":"Produces lactic acid","category":1,"feedback":"Without oxygen."},{"label":"Found only in muscle; rapid ATP","category":2,"feedback":"Phosphocreatine."},{"label":"Taken up from the blood and broken down to CO₂, water and ATP","category":3,"feedback":"Free fatty acids."}]}},{"id":"ap9-8","chapter":"Twitch, all-or-none and tone","title":"Twitch, all-or-none and tone","teach":["A muscle twitch has a latent period (before contraction begins), a contraction period and a relaxation period.","The all-or-none law: a stimulus strong enough to fire a single muscle cell produces its maximum contraction; it either contracts fully or not at all. Whole-muscle strength depends on stimulus strength, duration, speed, load and temperature.","Tone is a steady partial contraction, with groups of cells taking turns. It keeps posture, firmness, blood pressure and pressure on abdominal contents."],"act":{"type":"choice","prompt":"The all-or-none law says that a single muscle cell:","options":[{"label":"Either contracts fully or not at all","correct":true,"feedback":"Right."},{"label":"Contracts harder the longer it’s stimulated","correct":false,"feedback":"For one cell, it’s all or nothing."},{"label":"Never fully relaxes","correct":false,"feedback":"That describes tone in a whole muscle."}]}},{"id":"ap9-9","chapter":"Isotonic vs isometric","title":"Isotonic vs isometric","teach":["Isotonic contraction: the muscle shortens and thickens while the tension stays the same, as when lifting a weight.","Isometric contraction: the muscle stays the same length while tension increases, as when pushing against a wall."],"mnemonic":{"cue":"Iso-TONIC = same Tension; Iso-METRIC = same length (meter)","explanation":"Isotonic keeps tension constant and the muscle shortens. Isometric keeps length constant and tension rises."},"act":{"type":"sort","prompt":"Isotonic or isometric?","categories":["Isotonic","Isometric"],"items":[{"label":"Lifting a weight","category":0,"feedback":"The muscle shortens."},{"label":"Pushing against a wall","category":1,"feedback":"Length stays the same."},{"label":"Pulling locked fingers apart","category":1,"feedback":"An isometric exercise."},{"label":"Muscle shortens and thickens, same tension","category":0,"feedback":"Isotonic."}]}},{"id":"ap9-10","chapter":"Smooth and cardiac muscle contraction","title":"Smooth and cardiac muscle contraction","teach":["Smooth muscle in hollow organs has an outer longitudinal layer and an inner circular layer that push contents forward. It contracts more slowly than skeletal muscle but stretches more. Its actin and myosin aren’t neatly lined up, so there are no stripes.","Cardiac muscle cells all contract together when one is stimulated, and the fastest cell sets the pace. The heart beats about 75 times a minute. Rapid, uncontrolled contraction of individual cells is fibrillation, which stops the heart pumping properly."],"act":{"type":"choice","prompt":"In cardiac muscle, which cell sets the pace?","options":[{"label":"The one that contracts fastest","correct":true,"feedback":"Right."},{"label":"The largest one","correct":false,"feedback":"It’s the fastest."},{"label":"Each cell beats on its own schedule","correct":false,"feedback":"That would be fibrillation."}]}},{"id":"ap9-11","chapter":"Naming muscles and how they work together","title":"Naming muscles and how they work together","teach":["Muscles are named by action (flexor, adductor), shape (trapezius), origin and insertion (sternocleidomastoid), location (frontalis), number of divisions (biceps, triceps, quadriceps) or fiber direction (oblique).","The origin is the fixed, usually proximal, attachment. The insertion is the movable attachment where the effect is seen. Muscles usually attach through tendons; a wide flat tendon is an aponeurosis.","By action: flexors bend, extensors straighten, abductors move away from the midline, adductors move toward it, rotators rotate, levators raise and depressors lower.","Prime movers (agonists) do the movement; antagonists do the opposite and must relax; synergists assist."],"act":{"type":"sort","prompt":"Which kind of muscle?","categories":["Abductor","Adductor","Levator","Depressor"],"items":[{"label":"Moves a limb away from the midline","category":0,"feedback":"Abductor."},{"label":"Brings a limb toward the midline","category":1,"feedback":"Adductor."},{"label":"Raises a body part","category":2,"feedback":"Levator."},{"label":"Lowers a body part","category":3,"feedback":"Depressor."}]}},{"id":"ap9-12","chapter":"Muscles of the head","title":"Muscles of the head","teach":["Facial expression: the frontalis raises the eyebrows and wrinkles the forehead; the occipitalis draws the scalp back; the zygomaticus pulls the mouth up when smiling and laughing; the orbicularis oris closes the lips; the buccinator compresses the cheek.","Chewing: the masseter and temporalis close the jaw, helped by the pterygoids.","Eye: the superior rectus raises the eye, the inferior rectus lowers it, the medial and lateral recti roll it in and out, and the obliques rotate it. These muscles insert on the eyeball, not on bone.","Head: the sternocleidomastoid flexes the neck (both sides) or turns the head (one side)."],"act":{"type":"sort","prompt":"What does each muscle do?","categories":["Raises eyebrows","Closes the jaw","Raises the eye","Turns the head"],"items":[{"label":"Frontalis","category":0,"feedback":"Also wrinkles the forehead."},{"label":"Masseter","category":1,"feedback":"Main chewing muscle."},{"label":"Superior rectus","category":2,"feedback":"Rolls the eye upward."},{"label":"Sternocleidomastoid","category":3,"feedback":"One side turns the head."}]}},{"id":"ap9-13","chapter":"Muscles of the shoulder, arm and hand","title":"Muscles of the shoulder, arm and hand","teach":["The trapezius, rhomboids, levator scapulae, pectoralis minor and serratus anterior move the scapula.","The pectoralis major flexes and adducts the arm. The latissimus dorsi (\"swimmer’s muscle\") extends, adducts and rotates it. The deltoid abducts the arm and is an injection site. The rotator cuff includes the supraspinatus, infraspinatus and teres minor.","The biceps brachii, brachialis and brachioradialis flex the elbow; the triceps brachii and anconeus extend it. Flexor carpi muscles flex the wrist and extensor carpi muscles extend it. The supinator supinates; the pronator teres and quadratus pronate. Pollicis means thumb: the opponens pollicis opposes it."],"act":{"type":"sort","prompt":"Flexes or extends the elbow?","categories":["Flexes the elbow","Extends the elbow"],"items":[{"label":"Biceps brachii","category":0,"feedback":"Flexor."},{"label":"Brachialis","category":0,"feedback":"Flexor."},{"label":"Triceps brachii","category":1,"feedback":"Extensor."},{"label":"Anconeus","category":1,"feedback":"Extensor."}]}},{"id":"ap9-14","chapter":"Muscles of the trunk and breathing","title":"Muscles of the trunk and breathing","teach":["The abdominal wall has three side layers, outer to inner: external oblique, internal oblique and transversus abdominis. Down the front is the rectus abdominis, the muscle sit-ups build (the \"washboard\").","The diaphragm is the main breathing muscle. The external intercostals raise the ribs when breathing in; the internal intercostals lower them when breathing out."],"act":{"type":"choice","prompt":"Which muscle do sit-ups develop?","options":[{"label":"Rectus abdominis","correct":true,"feedback":"Right."},{"label":"Transversus abdominis","correct":false,"feedback":"That’s the deepest side layer."},{"label":"External oblique","correct":false,"feedback":"That’s the outer side layer."}]}},{"id":"ap9-15","chapter":"Muscles of the hip, leg and foot","title":"Muscles of the hip, leg and foot","teach":["The psoas and iliacus flex the thigh. The gluteus maximus forms most of the buttocks and extends the thigh; the gluteus medius is an injection site.","The hamstrings (biceps femoris, semitendinosus, semimembranosus) flex the knee. The quadriceps femoris (rectus femoris and three vasti) extends it. The sartorius is the longest muscle in the body.","The gastrocnemius (calf), soleus and others plantar flex the foot; the tibialis anterior dorsiflexes it. The flexor digitorum longus flexes the toes. Hallucis means the great toe."],"act":{"type":"sort","prompt":"What does each muscle do?","categories":["Flexes the knee","Extends the knee","Plantar flexes the foot","Flexes the toes"],"items":[{"label":"Hamstrings","category":0,"feedback":"Back of the thigh."},{"label":"Quadriceps femoris","category":1,"feedback":"Front of the thigh."},{"label":"Gastrocnemius","category":2,"feedback":"The calf muscle."},{"label":"Flexor digitorum longus","category":3,"feedback":"Flexes the toes."}]}},{"id":"ap9-16","chapter":"Muscle disorders and aging","title":"Muscle disorders and aging","teach":["Atrophy is a decrease in muscle bulk from lack of exercise, as in a cast. Hypertrophy is the opposite: muscle growth from exercise like weightlifting.","Tendinitis is inflammation of a tendon. Fibromyalgia is a form of rheumatism that doesn’t affect the joints: long-term muscle and tendon pain, stiffness and fatigue. Others in the chapter include muscular dystrophy, myasthenia gravis, ALS, tetanus and plantar fasciitis.","From the late 20s, muscle fibers are gradually lost; by the late 70s about half of muscle mass is gone. Walking and resistance exercise slow this."],"act":{"type":"sort","prompt":"Match the term.","categories":["Atrophy","Hypertrophy","Tendinitis","Fibromyalgia"],"items":[{"label":"Loss of muscle bulk from lack of exercise","category":0,"feedback":"Atrophy."},{"label":"Muscle growth from weightlifting","category":1,"feedback":"Hypertrophy."},{"label":"Inflammation of a tendon","category":2,"feedback":"Tendinitis."},{"label":"Rheumatism that doesn’t affect the joints","category":3,"feedback":"Fibromyalgia."}]}}],"flashcards":[{"front":"Muscle fiber","back":"A skeletal muscle cell (long relative to its width)."},{"front":"Sarcolemma","back":"The muscle fiber’s polarized cell membrane."},{"front":"Endomysium / perimysium / epimysium","back":"Around each fiber / each fascicle / the whole muscle."},{"front":"Fascicle","back":"A bundle of muscle fibers."},{"front":"A band / I band","back":"Dark, thick myosin / light, thin actin."},{"front":"Sarcomere","back":"Section between two Z lines; where contraction happens."},{"front":"T tubules","back":"Carry the action potential deep into the fiber."},{"front":"Sarcoplasmic reticulum","back":"Stores and releases calcium."},{"front":"Motor unit","back":"One motor neuron and all the fibers it supplies."},{"front":"Resting potential","back":"More K⁺ inside, more Na⁺ outside; inside negative."},{"front":"Acetylcholine","back":"Neurotransmitter released at the neuromuscular junction."},{"front":"Troponin and tropomyosin","back":"Block actin and myosin until calcium arrives."},{"front":"Phosphocreatine","back":"Found only in muscle; rapid source of ATP."},{"front":"Lactic acid","back":"Builds up when pyruvic acid can’t be used without oxygen."},{"front":"All-or-none law","back":"A single muscle cell contracts fully or not at all."},{"front":"Tone","back":"Steady partial contraction of a muscle."},{"front":"Isotonic / isometric","back":"Shortens, same tension / same length, more tension."},{"front":"Origin / insertion","back":"Fixed attachment / movable attachment."},{"front":"Prime mover / antagonist / synergist","back":"Does the movement / opposes it / assists it."},{"front":"Levator / depressor","back":"Raises / lowers a part."},{"front":"Frontalis","back":"Raises the eyebrows and wrinkles the forehead."},{"front":"Superior rectus","back":"Raises the eye."},{"front":"Rectus abdominis","back":"Front abdominal muscle built by sit-ups."},{"front":"Hamstrings / quadriceps","back":"Flex / extend the knee."},{"front":"Atrophy / hypertrophy","back":"Loss of muscle bulk / increase in muscle size."},{"front":"Fibromyalgia","back":"Rheumatism that doesn’t affect the joints."}],"quiz":[{"q":"Muscles that move a limb away from the midline are called ________________________.","o":["extensors","abductors","flexors","adductors"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says that when a limb is moved away from the midline, an abductor is functioning. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The flexor digitorum longus flex the _________________________.","o":["wrist","elbow","toes","fingers"],"a":2,"e":"Checked answer, not from an official key. Table 9-10 in Chapter 9 says the flexor digitorum longus flexes the toes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"What is the molecule that is found only in muscle tissue and provides a rapid source of high-energy ATP for muscle contraction?","o":["acid","creatine","phosphocreatine","fatty acids"],"a":2,"e":"Checked answer, not from an official key. Chapter 9 says phosphocreatine is found only in muscle tissue and provides a rapid source of high-energy ATP for contraction. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Each individual bundle of muscle cells is called a ____________________________.","o":["fascicle","muscle fiber","myofibril","microfilament"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says each individual bundle of muscle cells is a fascicle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"If oxygen is not available to a muscle cell, pyruvic acid is changed to __________________ and builds up in the muscle cell.","o":["fatty acid","phosphocreatine","lactic acid","glucose"],"a":2,"e":"Checked answer, not from an official key. Chapter 9 says that without oxygen, pyruvic acid changes to lactic acid and builds up in the muscle cell. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The muscle we develop when we do sit-ups is the __________________________________.","o":["transversus abdominis","external oblique","rectus abdominis","internal oblique"],"a":2,"e":"Checked answer, not from an official key. Chapter 9 says the rectus abdominis is the muscle we develop when we do sit-ups. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Muscle cells have positively charged _______________________ ions in greater concentration outside the muscle cell than inside the cell.","o":["sodium","potassium","chloride","calcium"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says there is a greater concentration of sodium ions outside the muscle cell than inside. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Muscles that raise a part of the body are called ________________________.","o":["levators","flexors","rotators","depressors"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says levators raise a part of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Inflammation of a tendon is called _________________________.","o":["tendonitis","ligament","hypertrophy","bursitis"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says tendinitis (also spelled tendonitis) is an inflammation of a tendon. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Which movement involves raising the foot upward at the ankle joint?","o":["abduction","elevation","dorsiflexion","depression"],"a":2,"e":"Checked answer, not from an official key. Chapter 9 says muscles of dorsiflexion turn the foot upward at the ankle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The coarse irregular connective tissue that surrounds the whole muscle is called the ______________.","o":["perimysium","endomysium","fasciculi","epimysium"],"a":3,"e":"Checked answer, not from an official key. Chapter 9 says the coarse irregular connective tissue that surrounds the whole muscle is the epimysium. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The _____________________ muscle raises your eyebrows and wrinkles the skin of your forehead.","o":["occipitalis","frontalis","zygomaticus","buccinators"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says the frontalis raises your eyebrows and wrinkles the skin of your forehead. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The light bands are made of the thin filaments of the protein _____________________.","o":["myosin","actin","tropomyosin","troponin"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says the light bands are made of the thin filaments of the protein actin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"As the nerve impulse of an axon reaches the neuromuscular junction, it triggers the release of a neurotransmitter called _________________________ .","o":["acetylcholine","dopamine","epinephrine","norepinephrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says the nerve impulse triggers the axon terminals to release the neurotransmitter acetylcholine. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Because skeletal muscles are much longer than their width, they are often called muscle ________________.","o":["ligaments","fibers","filaments","striations"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says skeletal muscle cells are often called muscle fibers because they are much longer than they are wide. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"A form of rheumatism that does not affect the joints is called _____________________ .","o":["tendinitis","tetanus","myasthenia gravis","fibromyalgia"],"a":3,"e":"Checked answer, not from an official key. Chapter 9 says fibromyalgia is a form of rheumatism that does not affect the joints. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"A decrease in muscle bulk due to a lack of exercise is called _____________________.","o":["dystrophy","atrophy","hypertrophy","anatrophy"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says atrophy is a decrease in muscle bulk due to a lack of exercise. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Which type of striated muscle is controlled by the autonomic nervous system?","o":["cardiac","smooth","skeletal","voluntary"],"a":0,"e":"Checked answer, not from an official key. Cardiac muscle is striated and controlled by the autonomic nervous system. Skeletal muscle is striated but voluntary, and smooth muscle is autonomic but not striated. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The __________________ rectus muscle raises the eye.","o":["inferior","superior","medial","lateral"],"a":1,"e":"Checked answer, not from an official key. Chapter 9 says the superior rectus raises the eye. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The action potential traveling down the T tubule causes the sarcoplasmic reticulum to release _________________ ions into the fluids surrounding the myofibrils.","o":["sodium","potassium","chloride","calcium"],"a":3,"e":"Checked answer, not from an official key. Chapter 9 says the action potential causes the sarcoplasmic reticulum to release stored calcium ions into the fluids surrounding the myofibrils. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"Skeletal muscle is involuntary.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Skeletal muscle is voluntary. Smooth and cardiac muscle are involuntary. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The movable attachment, where the effects of muscle contraction are seen, is called the origin.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The movable attachment is the insertion. The origin is the more fixed attachment. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"When lifting a weight, muscles become shorter and thicker but the tone or tension remains the same and is referred to as isometric contraction.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. That describes isotonic contraction. In isometric contraction the muscle stays the same length while tension increases. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"The dark bands of skeletal muscle are made of thick filaments (myosin).","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says the dark bands are made of the thick filaments of the protein myosin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."},{"q":"In performing any given movement, the muscles performing the actual movement are called the prime movers or agonists.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 9 says the muscles performing the actual movement are called the prime movers or agonists. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 9."}],"caseStudy":{"title":"Fuel is only one part of force","scenario":"A recreational athlete says fatigue during repeated lifts must mean one specific nutrient is missing.","prompts":["Trace the signal from motor neuron to calcium release.","Name the ATP systems that overlap during repeated work.","Distinguish concentric, eccentric and isometric phases.","Explain why fatigue cannot be diagnosed from the workout description alone."],"takeaway":"Connect neural activation, cross-bridge cycling, energy systems and task demands before considering nutrition within scope."},"perStepChapter":true},{"n":10,"title":"The Nervous System: Introduction, Spinal Cord, and Spinal Nerves","kicker":"Lesson 10 of your course, built from Chapter 10 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"75–95 minutes","steps":[{"id":"ap10-1","chapter":"The nervous system’s job","title":"The nervous system’s job","teach":["The nervous system is the body’s control center and communication network. It directs the organs, interprets what happens around us and decides how to respond, often by making muscles contract.","It shares the job of homeostasis with the endocrine system, controlling the pituitary gland through the hypothalamus."],"act":{"type":"choice","prompt":"Which system is the body’s control center and communication network?","options":[{"label":"Nervous","correct":true,"feedback":"Right."},{"label":"Endocrine","correct":false,"feedback":"The endocrine system works with it, using hormones."},{"label":"Cardiovascular","correct":false,"feedback":"That system transports blood."}]}},{"id":"ap10-2","chapter":"Divisions of the nervous system","title":"Divisions of the nervous system","teach":["The central nervous system (CNS) is the brain and spinal cord, the control center.","The peripheral nervous system (PNS) is all the nerves connecting the CNS to receptors, muscles and glands. Its afferent (sensory) side carries information to the CNS; its efferent (motor) side carries commands out.","The efferent side splits into the somatic nervous system (to skeletal muscle) and the autonomic nervous system (ANS, involuntary, to smooth muscle, cardiac muscle and glands).","The ANS has two divisions. The sympathetic division stimulates and speeds up activity (energy use) and uses norepinephrine. The parasympathetic division stimulates \"vegetative\" activities like digestion, urination and defecation, slows other activities down, and uses acetylcholine at its nerve endings."],"visual":{"kind":"flow","title":"How the nervous system divides","items":[{"label":"CNS","detail":"Brain and spinal cord."},{"label":"PNS: afferent","detail":"Sensory neurons, toward the CNS."},{"label":"PNS: efferent → somatic","detail":"Motor neurons to skeletal muscle."},{"label":"PNS: efferent → autonomic","detail":"To smooth and cardiac muscle and glands."},{"label":"Sympathetic / parasympathetic","detail":"Speeds up (norepinephrine) / rest and digest (acetylcholine)."}]},"mnemonic":{"cue":"Afferent Arrives, Efferent Exits","explanation":"Afferent (sensory) signals arrive at the CNS; efferent (motor) signals exit to muscles and glands."},"act":{"type":"sort","prompt":"Sympathetic or parasympathetic?","categories":["Sympathetic","Parasympathetic"],"items":[{"label":"Speeds up activity and uses energy","category":0,"feedback":"Sympathetic."},{"label":"Stimulates digestion and urination","category":1,"feedback":"Parasympathetic."},{"label":"Uses norepinephrine","category":0,"feedback":"Sympathetic."},{"label":"Uses acetylcholine at its nerve endings","category":1,"feedback":"Parasympathetic."}]}},{"id":"ap10-3","chapter":"Neurons and neuroglia","title":"Neurons and neuroglia","teach":["Neurons are nerve cells that transmit impulses as electrochemical changes. A nerve is a bundle of nerve fibers. Neuroglia (\"nerve glue\") support and protect neurons and don’t conduct impulses. Over 60% of brain cells are neuroglia.","Astrocytes are star-shaped cells that form a supporting network in the brain and spinal cord, link neurons to blood vessels and help form the blood-brain barrier. Oligodendroglia support neurons and make the myelin sheath in the CNS. Microglia engulf microbes and debris. Ependymal cells line the brain’s ventricles and make or move cerebrospinal fluid. Schwann cells make the myelin sheath in the PNS."],"act":{"type":"sort","prompt":"Which neuroglia cell?","categories":["Astrocytes","Oligodendroglia","Microglia","Ependymal","Schwann"],"items":[{"label":"Star-shaped supporting network","category":0,"feedback":"Astrocytes."},{"label":"Myelin in the CNS","category":1,"feedback":"Oligodendroglia."},{"label":"Engulf microbes and debris","category":2,"feedback":"Microglia."},{"label":"Line the ventricles; cerebrospinal fluid","category":3,"feedback":"Ependymal cells."},{"label":"Myelin in the PNS","category":4,"feedback":"Schwann cells."}]}},{"id":"ap10-4","chapter":"Parts of a neuron","title":"Parts of a neuron","teach":["The cell body holds the nucleus, organelles and Nissl bodies (rough ER where proteins are made). Dendrites are short and branched; they’re the receiving areas.","Each neuron has one axon, starting at the axon hillock and ending in axon terminals. Large peripheral axons are wrapped in a fatty myelin sheath made by Schwann cells; the outer part of the Schwann cell is the neurilemma. Gaps in the sheath are the nodes of Ranvier."],"act":{"type":"sort","prompt":"Match each part to its role.","categories":["Dendrites","Axon","Myelin sheath","Nodes of Ranvier"],"items":[{"label":"Receive incoming signals","category":0,"feedback":"Dendrites."},{"label":"Single long fiber carrying the impulse away","category":1,"feedback":"Axon."},{"label":"Fatty insulation","category":2,"feedback":"Myelin sheath."},{"label":"Gaps where the impulse jumps","category":3,"feedback":"Nodes of Ranvier."}]}},{"id":"ap10-5","chapter":"Neurons by structure","title":"Neurons by structure","teach":["Multipolar neurons have several dendrites and one axon. Most neurons in the brain and spinal cord are this type, including motor and association neurons.","Bipolar neurons have one dendrite and one axon. They’re found only in the retina, the inner ear and the olfactory area of the nose.","Unipolar neurons have one process that splits into an axon-like branch and a dendrite-like branch. Most sensory neurons are unipolar."],"act":{"type":"sort","prompt":"Which structural type?","categories":["Multipolar","Bipolar","Unipolar"],"items":[{"label":"Several dendrites and one axon","category":0,"feedback":"Multipolar."},{"label":"Found in the retina and inner ear","category":1,"feedback":"Bipolar."},{"label":"Most sensory neurons","category":2,"feedback":"Unipolar."},{"label":"Most brain and spinal cord neurons","category":0,"feedback":"Multipolar."}]}},{"id":"ap10-6","chapter":"Neurons by function","title":"Neurons by function","teach":["Receptors pick up stimuli and turn them into nerve impulses.","The first nerve cell receiving the impulse from a receptor is the sensory, or afferent, neuron (unipolar). The impulse may pass through internuncial, or association, neurons in the brain or spinal cord (multipolar). The final cell, which brings about the response, is the motor, or efferent, neuron (multipolar). The response is usually muscular, but it can be glandular."],"act":{"type":"order","prompt":"Put the neurons in the order an impulse travels.","items":[{"label":"Sensory (afferent) neuron","detail":"From the receptor"},{"label":"Association (internuncial) neuron","detail":"In the brain or spinal cord"},{"label":"Motor (efferent) neuron","detail":"Brings about the response"}]}},{"id":"ap10-7","chapter":"The nerve impulse","title":"The nerve impulse","teach":["At rest, sodium is concentrated outside and potassium inside; the inside is negative. This is the resting (membrane) potential, kept by the sodium-potassium pump.","When an impulse starts, sodium rushes in and the inside turns positive: depolarization, the action potential. Potassium then moves out and the pump restores the charges: repolarization. The impulse is a self-propagating wave of depolarization and repolarization that moves in one direction down the fiber.","Unmyelinated fibers conduct along their whole length, slowly (about 0.5 m/s). In myelinated fibers the impulse jumps from node to node, much faster (about 120 m/s).","All-or-none law: if a nerve fiber carries an impulse at all, it carries a full-strength one."],"act":{"type":"sort","prompt":"Depolarization or repolarization?","categories":["Depolarization","Repolarization"],"items":[{"label":"Sodium rushes in","category":0,"feedback":"Inside becomes positive."},{"label":"Inside becomes positive","category":0,"feedback":"The action potential."},{"label":"Potassium moves out and the pump restores charges","category":1,"feedback":"Repolarization."},{"label":"Inside becomes negative again","category":1,"feedback":"Back to resting potential."}]}},{"id":"ap10-8","chapter":"Synapses and neurotransmitters","title":"Synapses and neurotransmitters","teach":["A synapse is where axon terminals come close to, but don’t touch, another neuron’s dendrites (or a muscle or gland). The gap is the synaptic cleft, and the impulse crosses it in one direction only.","The impulse makes the presynaptic neuron release a neurotransmitter, a chemical that carries the signal across. Most synapses use acetylcholine, which the enzyme acetylcholinesterase then breaks down. Others include norepinephrine, epinephrine (adrenaline), serotonin, dopamine and endorphins."],"act":{"type":"choice","prompt":"Which neurotransmitter do most synapses in the body use?","options":[{"label":"Acetylcholine","correct":true,"feedback":"Right."},{"label":"Dopamine","correct":false,"feedback":"Dopamine is one of many, but not the most common."},{"label":"Epinephrine","correct":false,"feedback":"The ANS also uses epinephrine, but most synapses use acetylcholine."}]}},{"id":"ap10-9","chapter":"Reflexes","title":"Reflexes","teach":["A reflex is an involuntary reaction to a stimulus, faster than a thought-out response, like pulling your finger off a thorn.","A reflex arc has five parts: a sensory receptor, a sensory (afferent) neuron, association neurons in the spinal cord, a motor (efferent) neuron, and an effector organ such as a muscle. The knee-jerk (patellar) reflex is the classic example.","Reflexes also keep homeostasis: heart rate, breathing, digestion, coughing, sneezing, swallowing and vomiting."],"act":{"type":"order","prompt":"Put the parts of a reflex arc in order.","items":[{"label":"Sensory receptor","detail":"Detects the stimulus"},{"label":"Sensory neuron","detail":"Carries it to the cord"},{"label":"Association neuron","detail":"In the spinal cord"},{"label":"Motor neuron","detail":"Carries the response out"},{"label":"Effector","detail":"Muscle or gland responds"}]}},{"id":"ap10-10","chapter":"White matter, gray matter, nerves and tracts","title":"White matter, gray matter, nerves and tracts","teach":["White matter is myelinated axons (myelin looks white). Gray matter is nerve cell bodies and dendrites, plus unmyelinated axons; the gray surface of the brain is the cortex.","Outside the CNS: a nerve is a bundle of fibers; ganglia are clusters of nerve cell bodies (gray matter). Inside the CNS: a tract is a bundle of fibers (white matter); a nucleus is a mass of cell bodies (gray matter). Horns are the gray matter areas of the spinal cord.","Ascending tracts carry sensation up; descending tracts carry motor signals down."],"act":{"type":"sort","prompt":"Inside or outside the CNS?","categories":["Outside the CNS","Inside the CNS"],"items":[{"label":"Nerve (bundle of fibers)","category":0,"feedback":"Outside."},{"label":"Ganglion (cell bodies)","category":0,"feedback":"Outside."},{"label":"Tract (bundle of fibers)","category":1,"feedback":"Inside."},{"label":"Nucleus (cell bodies)","category":1,"feedback":"Inside."}]}},{"id":"ap10-11","chapter":"The spinal cord and meninges","title":"The spinal cord and meninges","teach":["The spinal cord is a continuation of the medulla oblongata, about 16 to 18 inches long, with 31 segments, each giving off a pair of spinal nerves. It ends around the second lumbar vertebra.","Three meninges protect it: the tough outer dura mater, the middle arachnoid mater (spider layer) and the delicate inner pia mater, which clings to the cord.","The subdural space (between dura and arachnoid) holds serous fluid. The subarachnoid space (between arachnoid and pia) holds cerebrospinal fluid. The epidural space separates the meninges from the vertebrae and holds fat and loose connective tissue.","A spinal tap draws cerebrospinal fluid from the subarachnoid space below the end of the cord."],"mnemonic":{"cue":"DAP: Dura, Arachnoid, Pia (outside in)","explanation":"The tough mother is outside, the delicate mother hugs the cord."},"act":{"type":"sort","prompt":"Match each space to what it holds or where it is.","categories":["Epidural space","Subdural space","Subarachnoid space"],"items":[{"label":"Between the meninges and the vertebrae","category":0,"feedback":"Epidural."},{"label":"Between dura and arachnoid; serous fluid","category":1,"feedback":"Subdural."},{"label":"Between arachnoid and pia; cerebrospinal fluid","category":2,"feedback":"Subarachnoid."}]}},{"id":"ap10-12","chapter":"Spinal cord roots and spinal nerves","title":"Spinal cord roots and spinal nerves","teach":["The spinal cord carries sensory impulses up to the brain and motor impulses down, and integrates reflexes.","Each spinal nerve attaches by two roots. The dorsal (posterior) root is sensory only and connects to the dorsal gray horn. The ventral (anterior) root is motor only and connects to the ventral gray horn.","Because each spinal nerve joins both roots, all spinal nerves are mixed nerves (sensory and motor). There are 31 pairs: 8 cervical, 12 thoracic, 5 lumbar, 5 sacral and 1 coccygeal."],"act":{"type":"number","prompt":"How many pairs of spinal nerves are there?","answer":31,"tolerance":0,"unit":"pairs","explanation":"8 cervical + 12 thoracic + 5 lumbar + 5 sacral + 1 coccygeal = 31."}},{"id":"ap10-13","chapter":"Drugs that affect the CNS","title":"Drugs that affect the CNS","teach":["Depressants (\"downers\") include Valium and opiates like codeine and heroin; they sedate and can cause dependence.","Stimulants include cocaine and amphetamines. Hallucinogens like LSD distort the senses.","Anabolic steroids act like male sex hormones and enlarge muscle cells, but in large doses suppress hormones from the hypothalamus and pituitary, which can shrink the testes and cause liver and heart problems."],"act":{"type":"sort","prompt":"Which group does each drug belong to?","categories":["Depressant","Stimulant","Hallucinogen","Anabolic steroid"],"items":[{"label":"Valium","category":0,"feedback":"Depressant."},{"label":"Amphetamines","category":1,"feedback":"Stimulant."},{"label":"LSD","category":2,"feedback":"Hallucinogen."},{"label":"Acts like male sex hormones","category":3,"feedback":"Anabolic steroid."}]}}],"flashcards":[{"front":"CNS","back":"Brain and spinal cord."},{"front":"PNS","back":"All nerves connecting the CNS to receptors, muscles and glands."},{"front":"Afferent / efferent","back":"Sensory, toward the CNS / motor, away from the CNS."},{"front":"Somatic nervous system","back":"Signals to skeletal muscle."},{"front":"Autonomic nervous system","back":"Involuntary; smooth muscle, cardiac muscle and glands."},{"front":"Sympathetic division","back":"Speeds up activity; norepinephrine."},{"front":"Parasympathetic division","back":"Digestion, urination, defecation; acetylcholine."},{"front":"Neuroglia","back":"Supporting cells; over 60% of brain cells."},{"front":"Astrocytes","back":"Star-shaped support network; blood-brain barrier."},{"front":"Schwann cells","back":"Make myelin in the PNS."},{"front":"Oligodendroglia","back":"Make myelin in the CNS."},{"front":"Nodes of Ranvier","back":"Gaps in the myelin sheath."},{"front":"Multipolar / bipolar / unipolar","back":"Many dendrites, one axon / one of each / one split process (most sensory neurons)."},{"front":"Resting potential","back":"Inside negative; Na⁺ outside, K⁺ inside."},{"front":"Depolarization / repolarization","back":"Na⁺ rushes in / K⁺ out and pump restores."},{"front":"Myelinated vs unmyelinated","back":"Jumps node to node, fast / whole length, slow."},{"front":"Synapse","back":"Gap between axon terminals and the next cell."},{"front":"Neurotransmitter","back":"Chemical that carries the signal across the synapse."},{"front":"Reflex arc","back":"Receptor, sensory neuron, association neuron, motor neuron, effector."},{"front":"White / gray matter","back":"Myelinated axons / cell bodies and dendrites."},{"front":"Ganglia","back":"Nerve cell bodies outside the CNS."},{"front":"Tract","back":"Bundle of fibers inside the CNS."},{"front":"Meninges","back":"Dura mater, arachnoid mater, pia mater."},{"front":"Epidural space","back":"Separates the meninges from the vertebrae."},{"front":"Dorsal / ventral root","back":"Sensory / motor."},{"front":"Spinal nerves","back":"31 pairs; all mixed."}],"quiz":[{"q":"The parasympathetic division of the autonomic nervous system uses the neurotransmitter _____________________ at nerve endings.","o":["dopamine","epinephrine","norepinephrine","acetylcholine"],"a":3,"e":"Checked answer, not from an official key. Chapter 10 says the parasympathetic division uses acetylcholine as a neurotransmitter at nerve endings. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The final nerve cell that receives the impulse and brings about the reaction to the original stimulus is called the motor or _____________________ neuron.","o":["afferent","inter","bipolar","efferent"],"a":3,"e":"Checked answer, not from an official key. Chapter 10 says the final nerve cell, which brings about the reaction, is the motor or efferent neuron. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The spinal cord is a continuation of the _____________________ .","o":["medulla oblongata","thalamus","hypothalamus","pons"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says the spinal cord begins as a continuation of the medulla oblongata of the brainstem. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The ____________________________ act like the male sex hormones.","o":["stimulants","depressants","anabolic steroids","hallucinogens"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says anabolic steroids act like the male sex hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Nerve cells known as _______________________ transmit nerve impulses in the form of electrochemical changes.","o":["neurons","microglia","oligodendrocytes","astrocytes"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says neurons transmit nerve impulses in the form of electrochemical changes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The chemicals that transmit signals across the synapse are called _________________________.","o":["sarcolemmas","neurotransmitters","synapses","receptors"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says transmission across synapses is brought about by chemicals called neurotransmitters. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Valium is an example of a(n) _______________________________.","o":["depressant","stimulant","hallucinogen","anabolic steroid"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 gives Valium as an example of a depressant. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Nerve cell bodies found outside the central nervous system are called ____________________.","o":["tracts","nerves","neurons","ganglia"],"a":3,"e":"Checked answer, not from an official key. Chapter 10 says nerve cell bodies found outside the CNS are grouped together to form ganglia. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Most sensory neurons are _______________________ neurons.","o":["multipolar","interneurons","unipolar","bipolar"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says most sensory neurons are unipolar neurons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"A bundle of fibres inside the central nervous system is called a ________________________.","o":["ganglion","tract","nucleus","soma"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says a tract is a bundle of fibers inside the CNS. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"All the spinal nerves are __________________________ nerves.","o":["sensory","motor","mixed","efferent"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says all the spinal nerves are mixed nerves because they contain both motor and sensory fibers. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Star-shaped cells that form a supporting network in the brain and spinal cord are called ________________________.","o":["oligodendrocytes","astrocytes","microglia","ependymal cells"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says astrocytes are star-shaped cells that form a supporting network in the brain and spinal cord. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The __________________ system is the body’s control centre and communication network.","o":["muscular","digestive","nervous","cardiovascular"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says the nervous system is the body’s control center and communication network. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Areas of the nervous system known as ___________________________ consist of nerve cells bodies and dendrites.","o":["white matter","ganglia","tracts","gray matter"],"a":3,"e":"Checked answer, not from an official key. Chapter 10 says gray matter consists of nerve cell bodies and dendrites. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The ____________________________ division of the autonomic nervous system stimulates and speeds up certain bodily activities.","o":["parasympathetic","sympathetic","somatic","central"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says the sympathetic division stimulates or speeds up activity. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Myelin sheaths surrounding nerve fibers in the peripheral nervous system are produced by ____________________________.","o":["Schwann cells","microglia","satellite cells","astrocytes"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says Schwann cells form myelin sheaths around nerve fibers in the PNS. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Neurons that convey information from the brain and spinal cord to muscles and glands are called ____________________________ neurons.","o":["efferent","afferent","interneurons","cranial"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says efferent (motor) neurons convey information from the brain and spinal cord to muscles and glands. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Neurons that have several dendrites and one axon are called __________________________ neurons.","o":["bipolar","unipolar","multipolar","uniaxial"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says multipolar neurons have several dendrites and one axon. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Most synapses in our bodies use the _____________________ neurotransmitter.","o":["acetylcholine","dopamine","epinephrine","norepinephrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says most of the synapses in our bodies use acetylcholine as the neurotransmitter. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The space that separates the meninges from the vertebrae is called the ____________________ space.","o":["subarachnoid","subdura","epidural","submater"],"a":2,"e":"Checked answer, not from an official key. Chapter 10 says the meninges are separated from the vertebrae by the epidural space. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"Over 60% of all brain cells are neurons.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says over 60% of all brain cells are neuroglia, not neurons. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"An unmyelinated nerve fibre conducts an impulse over its entire length with a slower rate of conduction than that of a myelinated fibre.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says an unmyelinated fiber conducts over its entire length, more slowly than a myelinated fiber. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The action potential moves in both directions down a nerve fibre.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 10 says the action potential moves in one direction down the nerve fiber. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The parasympathetic division of the autonomic nervous system stimulates the body’s vegetative activities such as digestion, urination, and defecation.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 10 says the parasympathetic division stimulates vegetative activities such as digestion, urination and defecation. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."},{"q":"The first nerve cell receiving an impulse directly from a receptor is called a motor or efferent neuron.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The first nerve cell receiving an impulse from a receptor is the sensory, or afferent, neuron. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 10."}],"caseStudy":{"title":"A hot surface and a fast response","scenario":"A person touches a hot tray, withdraws the hand, then notices pain and a racing heart.","prompts":["Trace the withdrawal reflex from receptor to effector.","Separate the spinal reflex from conscious perception.","Name the autonomic division that supports the challenge response.","Explain why this sequence does not identify the cause of persistent symptoms."],"takeaway":"Map sensory, integrative, motor and autonomic events as connected layers, while leaving diagnosis to clinical assessment."},"perStepChapter":true},{"n":11,"title":"The Brain, Cranial Nerves, Autonomic Nervous System, and Special Senses","kicker":"Lesson 11 of your course, built from Chapter 11 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"90–110 minutes","steps":[{"id":"ap11-1","chapter":"The four parts of the brain","title":"The four parts of the brain","teach":["The brain weighs about 3 pounds and has four main parts: the brainstem (medulla oblongata, pons varolii and midbrain), the diencephalon (thalamus and hypothalamus), the cerebrum and the cerebellum.","In short: the brainstem controls breathing, heart rate and reactions to sights and sounds; the diencephalon handles much of homeostasis; the cerebrum handles intellect and emotions; the cerebellum handles posture and balance."],"visual":{"kind":"hub","title":"Main parts of the brain","items":[{"label":"Brainstem","detail":"Medulla, pons, midbrain: breathing, heartbeat, reflexes."},{"label":"Diencephalon","detail":"Thalamus (relay) and hypothalamus (homeostasis)."},{"label":"Cerebrum","detail":"Intellect, emotions, voluntary movement, senses."},{"label":"Cerebellum","detail":"Coordination, posture, balance."}]},"act":{"type":"sort","prompt":"Which part of the brain?","categories":["Brainstem","Diencephalon","Cerebrum","Cerebellum"],"items":[{"label":"Medulla oblongata","category":0,"feedback":"Part of the brainstem."},{"label":"Thalamus","category":1,"feedback":"Diencephalon."},{"label":"Intellectual processes and emotions","category":2,"feedback":"Cerebrum."},{"label":"Coordinates complex muscle movements","category":3,"feedback":"Cerebellum."}]}},{"id":"ap11-2","chapter":"Protecting the brain: meninges, ventricles and CSF","title":"Protecting the brain: meninges, ventricles and CSF","teach":["The cranial bones and the cranial meninges (dura, arachnoid and pia mater, the same as around the spinal cord) protect the brain. The arachnoid is the middle layer.","Cerebrospinal fluid (CSF) circulates through the subarachnoid space and the four ventricles. It acts as a shock absorber for the central nervous system and carries nutrients.","There are two lateral ventricles (one in each hemisphere), a third ventricle in the diencephalon, and a fourth between the cerebellum and lower brainstem. They connect through the interventricular foramen and the cerebral aqueduct."],"act":{"type":"choice","prompt":"What acts as a shock absorber for the central nervous system?","options":[{"label":"Cerebrospinal fluid","correct":true,"feedback":"Right. It also carries nutrients."},{"label":"Interstitial fluid","correct":false,"feedback":"That’s fluid between cells in general."},{"label":"Synovial fluid","correct":false,"feedback":"That lubricates joints."}]}},{"id":"ap11-3","chapter":"The brainstem","title":"The brainstem","teach":["The medulla oblongata contains all the ascending and descending tracts between the spinal cord and the brain. Some motor tracts cross here (decussation of pyramids), which is why one side of the brain controls the opposite side of the body.","It holds the reticular formation, which maintains consciousness and arousal, and three vital centers: vasomotor (blood vessel diameter), cardiac (heartbeat) and medullary rhythmicity (breathing rhythm).","The pons (\"bridge\") connects the spinal cord, brain parts and cerebellum, and helps control breathing. The midbrain carries impulses from the cortex down and has reflex centers that turn the eyes and head toward sights and sounds."],"act":{"type":"sort","prompt":"Medulla, pons or midbrain?","categories":["Medulla oblongata","Pons","Midbrain"],"items":[{"label":"Cardiac and vasomotor centers","category":0,"feedback":"Medulla."},{"label":"A \"bridge\" connecting brain parts","category":1,"feedback":"Pons means bridge."},{"label":"Turns the eyes toward a visual stimulus","category":2,"feedback":"Midbrain tectum."},{"label":"Where motor tracts cross","category":0,"feedback":"Decussation of pyramids."}]}},{"id":"ap11-4","chapter":"The diencephalon","title":"The diencephalon","teach":["The thalamus is the main relay station for sensory impulses heading to the cerebral cortex, and helps us consciously recognize pain and temperature.","The hypothalamus is small but controls much of homeostasis: it controls the autonomic nervous system, links the nervous and endocrine systems by controlling the pituitary, and regulates body temperature, thirst, hunger, sleep and waking, and rage and aggression.","Also in the diencephalon: the optic chiasma, where optic nerves cross; the infundibulum, which attaches the hypothalamus to the pituitary; the mamillary bodies; and the pineal gland, a pinecone-shaped gland that secretes melatonin."],"act":{"type":"sort","prompt":"Match each structure to its role.","categories":["Thalamus","Hypothalamus","Infundibulum","Pineal gland"],"items":[{"label":"Relays sensory impulses to the cortex","category":0,"feedback":"Thalamus."},{"label":"Controls body temperature and thirst","category":1,"feedback":"Hypothalamus."},{"label":"Attaches the hypothalamus to the pituitary","category":2,"feedback":"Infundibulum."},{"label":"Secretes melatonin","category":3,"feedback":"Pineal gland."}]}},{"id":"ap11-5","chapter":"The cerebrum","title":"The cerebrum","teach":["The cerebrum is the bulk of the brain. Its gray surface is the cerebral cortex, with white matter beneath.","The longitudinal fissure divides it into right and left cerebral hemispheres, joined by the corpus callosum. The surface folds are gyri, and the grooves between them are sulci; the folds increase the cortex’s surface area.","The cortex has motor areas (movement), sensory areas (interpreting sensations) and association areas (emotion and intellect)."],"mnemonic":{"cue":"Gyri = Go up (ridges); Sulci = Sink (grooves)","explanation":"Gyri are the raised folds; sulci are the grooves between them."},"act":{"type":"sort","prompt":"Match the term.","categories":["Longitudinal fissure","Corpus callosum","Gyri","Sulci"],"items":[{"label":"Separates the right and left hemispheres","category":0,"feedback":"Longitudinal fissure."},{"label":"Connects the two hemispheres","category":1,"feedback":"Corpus callosum."},{"label":"The folds on the surface","category":2,"feedback":"Gyri."},{"label":"The grooves between folds","category":3,"feedback":"Sulci."}]}},{"id":"ap11-6","chapter":"Lobes of the cerebrum","title":"Lobes of the cerebrum","teach":["Frontal lobe: voluntary movement, mood, aggression, smell and motivation. Parietal lobe (behind the central sulcus): touch, pain, balance, taste and temperature. Temporal lobe (below the lateral fissure): hearing, smell, memory, abstract thought and judgment. Occipital lobe (at the back): receiving and interpreting vision. The insula is a fifth lobe deep in the lateral sulcus."],"act":{"type":"sort","prompt":"Which lobe?","categories":["Frontal","Parietal","Temporal","Occipital"],"items":[{"label":"Voluntary movement and motivation","category":0,"feedback":"Frontal."},{"label":"Touch, pain and temperature","category":1,"feedback":"Parietal."},{"label":"Hearing and memory","category":2,"feedback":"Temporal."},{"label":"Vision","category":3,"feedback":"Occipital."}]}},{"id":"ap11-7","chapter":"The cerebellum","title":"The cerebellum","teach":["The cerebellum is the second largest part of the brain, below the occipital lobes and behind the brainstem. Its two hemispheres are joined by the vermis.","It’s a reflex center that coordinates complex skeletal muscle movements, maintains posture and keeps the body balanced. Damage can cause tremors, loss of balance and low muscle tone. Intellect and emotions are the cerebrum’s job, not the cerebellum’s."],"act":{"type":"choice","prompt":"What does the cerebellum do?","options":[{"label":"Coordinates complex movements, posture and balance","correct":true,"feedback":"Right."},{"label":"Controls intellect and emotions","correct":false,"feedback":"That’s the cerebrum."},{"label":"Controls thirst and temperature","correct":false,"feedback":"That’s the hypothalamus."}]}},{"id":"ap11-8","chapter":"The autonomic nervous system","title":"The autonomic nervous system","teach":["The autonomic nervous system works automatically. It regulates internal organs by controlling glands, smooth muscle and cardiac muscle. (The somatic system controls skeletal muscle.)","The sympathetic division prepares the body for stressful situations (\"fight or flight\"): raises heart rate and blood pressure, opens the airways, triggers sweating and glucose release, and slows digestion. Its fibers come from the thoracic and lumbar spinal cord; it uses acetylcholine before the ganglia and norepinephrine after.","The parasympathetic division operates under normal, nonstressful conditions (\"rest and repose\"): it stimulates digestion, urination and defecation, slows the heart and breathing, lowers blood pressure and constricts the pupil. Its fibers come from the brainstem and sacral cord, and it uses acetylcholine throughout."],"act":{"type":"sort","prompt":"Sympathetic or parasympathetic?","categories":["Sympathetic","Parasympathetic"],"items":[{"label":"Prepares for stressful situations","category":0,"feedback":"Fight or flight."},{"label":"Operates under normal, nonstressful conditions","category":1,"feedback":"Rest and repose."},{"label":"Speeds up the heart","category":0,"feedback":"Sympathetic."},{"label":"Constricts the pupil","category":1,"feedback":"Parasympathetic."},{"label":"Inhibits digestion","category":0,"feedback":"Sympathetic."}]}},{"id":"ap11-9","chapter":"The 12 cranial nerves","title":"The 12 cranial nerves","teach":["There are 12 pairs, numbered I to XII from front to back. Some are sensory, some motor, some mixed.","I Olfactory (smell, sensory). II Optic (vision, sensory). III Oculomotor (eye and eyelid movement, pupil; motor). IV Trochlear (eye movement; smallest). V Trigeminal (largest; mixed; face sensation and chewing; three branches). VI Abducens (eye movement, abduction; motor).","VII Facial (facial expression, taste, tears and saliva; mixed). VIII Vestibulocochlear (balance and hearing; sensory). IX Glossopharyngeal (swallowing, taste, saliva; mixed). X Vagus (pharynx, larynx and the organs of the thorax and abdomen; mixed). XI Accessory (head and shoulder movement; motor). XII Hypoglossal (tongue movements, speech and swallowing; motor)."],"mnemonic":{"cue":"Oh Oh Oh To Touch And Feel Very Good Velvet. Ah, Heaven!","explanation":"Olfactory, Optic, Oculomotor, Trochlear, Trigeminal, Abducens, Facial, Vestibulocochlear, Glossopharyngeal, Vagus, Accessory, Hypoglossal."},"act":{"type":"sort","prompt":"Which cranial nerve?","categories":["Trigeminal (V)","Abducens (VI)","Vestibulocochlear (VIII)","Hypoglossal (XII)"],"items":[{"label":"Largest cranial nerve","category":0,"feedback":"Trigeminal."},{"label":"Moves the eyeball outward","category":1,"feedback":"Abducens."},{"label":"Hearing and balance","category":2,"feedback":"Vestibulocochlear."},{"label":"Tongue movements","category":3,"feedback":"Hypoglossal."}]}},{"id":"ap11-10","chapter":"Smell and taste","title":"Smell and taste","teach":["Smell (olfaction): odor molecules dissolve in the mucus of the superior nasal conchae and bind to receptors on bipolar olfactory neurons. Signals pass through the olfactory bulbs to the olfactory cortex in the temporal and frontal lobes. The receptors adapt quickly to an odor.","Taste: taste buds sit on papillae of the tongue (and the palate and pharynx). Taste hairs poking out of the taste pore are the receptors. Food must dissolve in saliva first. The five tastes are sweet, sour, salty, bitter and umami. Signals travel on cranial nerves VII, IX and X to the taste cortex in the parietal lobe. Smell strongly affects taste."],"act":{"type":"choice","prompt":"What must happen before a chemical can be tasted?","options":[{"label":"It must dissolve in saliva","correct":true,"feedback":"Right."},{"label":"It must reach the stomach","correct":false,"feedback":"Taste happens in the mouth."},{"label":"It must be smelled first","correct":false,"feedback":"Smell influences taste, but dissolving in saliva is required."}]}},{"id":"ap11-11","chapter":"The eye: layers and parts","title":"The eye: layers and parts","teach":["Tears from the lacrimal gland lubricate the eye and fight bacteria (lysozyme).","The eye wall has three layers. The outer sclera is the tough white of the eye; its transparent front part is the cornea, which lets light in. The conjunctiva lines the eyelids and front of the sclera. The middle choroid is full of blood vessels and dark pigment that absorbs stray light. The innermost retina contains the light-sensitive rods and cones.","The ciliary body holds the lens. The iris, the colored muscle around the pupil, regulates how much light enters. Aqueous humor fills the front compartment; vitreous humor fills the back."],"act":{"type":"sort","prompt":"Which part of the eye?","categories":["Sclera","Cornea","Choroid","Retina","Iris"],"items":[{"label":"Tough white outer layer","category":0,"feedback":"Sclera."},{"label":"Transparent front of the outer layer","category":1,"feedback":"Cornea."},{"label":"Blood vessels and dark pigment","category":2,"feedback":"Choroid."},{"label":"Innermost layer with rods and cones","category":3,"feedback":"Retina."},{"label":"Controls pupil size","category":4,"feedback":"Iris."}]}},{"id":"ap11-12","chapter":"Rods, cones and the path to the brain","title":"Rods, cones and the path to the brain","teach":["Rods are more numerous, very sensitive to light, work in dim light and don’t give color vision. Cones give color vision and need lots of light; there are red, green and blue cones.","Rods contain rhodopsin, which needs vitamin A; a vitamin A deficiency can cause night blindness.","Rods and cones synapse with bipolar cells, which synapse with ganglion cells whose axons form the optic nerve. The fovea centralis in the macula lutea gives the sharpest vision. Nerve fibers leave at the optic disk, the \"blind spot,\" because it has no receptors. Vision is interpreted in the occipital lobe."],"act":{"type":"sort","prompt":"Rods or cones?","categories":["Rods","Cones"],"items":[{"label":"Work in dim light","category":0,"feedback":"Rods."},{"label":"Produce color vision","category":1,"feedback":"Cones."},{"label":"Need lots of light","category":1,"feedback":"Cones."},{"label":"Contain rhodopsin","category":0,"feedback":"Rods."},{"label":"More numerous","category":0,"feedback":"Rods outnumber cones."}]}},{"id":"ap11-13","chapter":"The ear: hearing and balance","title":"The ear: hearing and balance","teach":["External ear: the auricle (elastic cartilage) funnels sound into the external auditory meatus, which directs it to the tympanic membrane (eardrum), making it vibrate. Ceruminous glands make earwax.","Middle ear: the ossicles (malleus, incus, stapes) pass and amplify the vibrations to the oval window. The eustachian (auditory) tube connects to the pharynx and equalizes air pressure.","Inner ear: the cochlea handles hearing. The vestibule (static equilibrium, head position) and semicircular canals (kinetic equilibrium, rotation) handle balance."],"act":{"type":"order","prompt":"Put the path of sound in order.","items":[{"label":"Auricle","detail":"Collects sound"},{"label":"External auditory meatus","detail":"Ear canal"},{"label":"Tympanic membrane","detail":"Vibrates"},{"label":"Malleus, incus, stapes","detail":"Amplify vibrations"},{"label":"Oval window to the cochlea","detail":"Inner ear"}]}},{"id":"ap11-14","chapter":"Brain disorders","title":"Brain disorders","teach":["Encephalitis is inflammation of brain tissue, usually caused by a virus spread by mosquitoes. Meningitis is inflammation of the meninges.","Multiple sclerosis (MS) is caused by progressive demyelination of nerve cells in the brain and spinal cord; it’s considered autoimmune. Alzheimer’s disease causes severe mental deterioration and usually affects older people. Parkinson’s disease and epilepsy are also covered in the chapter.","A cerebrovascular accident (CVA), or stroke, can be caused by a clot or a piece of clot blocking a vessel, or by a ruptured vessel. An aneurysm is a ballooning (dilation) of a blood vessel wall that can rupture."],"act":{"type":"sort","prompt":"Match the disorder.","categories":["Encephalitis","Multiple sclerosis","Stroke","Aneurysm"],"items":[{"label":"Inflammation of brain tissue","category":0,"feedback":"Encephalitis."},{"label":"Progressive loss of myelin","category":1,"feedback":"MS."},{"label":"Can be caused by a blood clot","category":2,"feedback":"Cerebrovascular accident."},{"label":"Ballooning of a vessel wall","category":3,"feedback":"Aneurysm."}]}},{"id":"ap11-15","chapter":"The nervous system and aging","title":"The nervous system and aging","teach":["After maturity, the brain loses neurons in the outer cerebrum; by the mid-70s it has lost about 7% of its weight. Fewer synapses and neurotransmitters slow information processing and reactions.","Narrower arteries to the brain mean less oxygen and a higher risk of stroke. Staying mentally active, with reading and puzzles, helps keep the brain healthy."],"act":{"type":"choice","prompt":"About how much brain weight is lost by the mid-70s, according to the textbook?","options":[{"label":"About 7%","correct":true,"feedback":"Right."},{"label":"About 30%","correct":false,"feedback":"The textbook says about 7%."},{"label":"None","correct":false,"feedback":"The brain does shrink with age."}]}}],"flashcards":[{"front":"Four parts of the brain","back":"Brainstem, diencephalon, cerebrum, cerebellum."},{"front":"Brainstem","back":"Medulla oblongata, pons and midbrain."},{"front":"Cerebrospinal fluid","back":"Shock absorber for the CNS; circulates nutrients."},{"front":"Medulla oblongata","back":"All tracts between cord and brain; cardiac, vasomotor and breathing centers."},{"front":"Reticular formation","back":"Maintains consciousness and arousal."},{"front":"Thalamus","back":"Main sensory relay station to the cortex."},{"front":"Hypothalamus","back":"Homeostasis: temperature, thirst, hunger, sleep; controls the pituitary."},{"front":"Infundibulum","back":"Attaches the hypothalamus to the pituitary."},{"front":"Pineal gland","back":"Pinecone-shaped; secretes melatonin."},{"front":"Longitudinal fissure","back":"Divides the cerebrum into right and left hemispheres."},{"front":"Gyri / sulci","back":"Folds / grooves on the cerebrum."},{"front":"Corpus callosum","back":"Connects the two cerebral hemispheres."},{"front":"Occipital lobe","back":"Receives and interprets vision."},{"front":"Cerebellum","back":"Coordinates movement, posture and balance."},{"front":"Sympathetic","back":"Prepares for stress; fight or flight."},{"front":"Parasympathetic","back":"Normal, nonstressful conditions; rest and repose."},{"front":"Largest / smallest cranial nerve","back":"Trigeminal (V) / trochlear (IV)."},{"front":"Abducens (VI)","back":"Motor; moves the eyeball (abduction)."},{"front":"Hypoglossal (XII)","back":"Motor; tongue movements."},{"front":"Lacrimal gland","back":"Produces tears."},{"front":"Sclera / cornea","back":"White outer layer / its transparent front."},{"front":"Retina","back":"Innermost layer with rods and cones."},{"front":"Iris","back":"Controls how much light enters the pupil."},{"front":"Rods / cones","back":"Dim light, no color / color, need lots of light."},{"front":"Optic disk","back":"Where the optic nerve leaves; the blind spot."},{"front":"Tympanic membrane","back":"Eardrum; vibrates with sound."},{"front":"Encephalitis","back":"Inflammation of brain tissue."},{"front":"Multiple sclerosis","back":"Progressive demyelination in the brain and spinal cord."},{"front":"Aneurysm","back":"Ballooning of a blood vessel wall."}],"quiz":[{"q":"The _______________________ functions as a reflex center in coordinating complex skeletal muscular movements.","o":["cerebrum","corpus callosum","diencephalon","cerebellum"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says the cerebellum functions as a reflex center in coordinating complex skeletal muscular movements. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The ____________________ gland produces tears.","o":["trigeminal","choroid","lacrimal","orbital"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says tears are produced by the lacrimal gland. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _______________________ is the innermost layer of the eye and contains the photosensitive cells.","o":["sclera","iris","conjunctiva","retina"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says the retina is the innermost layer of the eye and contains the photosensitive cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Inflammation of brain tissue is called _________________________ .","o":["meningitis","tetanus","epilepsy","encephalitis"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says encephalitis is an inflammation of brain tissue. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The ___________________ gland is a pinecone-shaped gland that secretes melatonin.","o":["pituitary","parathyroid","thyroid","pineal"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says the pineal gland is a pinecone-shaped endocrine gland that secretes melatonin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The middle of the three spinal meninges is called the ____________________ mater.","o":["dura","arachnoid","pia","subdural"],"a":1,"e":"Checked answer, not from an official key. The meninges are the dura mater (outer), arachnoid mater (middle) and pia mater (inner). Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The ______________________ fissure separates the cerebrum into right and left halves (cerebral hemispheres).","o":["central","optic","longitudinal","transverse"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says the longitudinal fissure separates the cerebrum into right and left halves. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The ______________________ division of the autonomic nervous system prepares the body for stressful situations.","o":["sympathetic","parasympathetic","peripheral","central"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the sympathetic division prepares the body for stressful situations. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ nerve is the largest of the cranial nerves.","o":["abducens","trigeminal","trochlear","hypoglossal"],"a":1,"e":"Checked answer, not from an official key. Chapter 11 says the trigeminal nerve (V) is the largest of the cranial nerves. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The symptoms of _________________ are caused by progressive demyelination of nerve cells in the brain and spinal cord.","o":["multiple sclerosis","epilepsy","encephalitis","meningitis"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says multiple sclerosis is caused by progressive demyelination of nerve cells in the brain and spinal cord. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ attaches the hypothalamus to the pituitary gland.","o":["infundibulum","mammillary bodies","thalamus","pineal gland"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the infundibulum attaches to the pituitary gland. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ formation is the area that functions in maintaining consciousness and arousal.","o":["reticular","cerebellar","limbic","cerebral"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the reticular formation functions in maintaining consciousness and arousal. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ lobe functions in receiving and interpreting visual input.","o":["temporal","sphenoid","parietal","occipital"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says the occipital lobe functions in receiving and interpreting visual input. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The photosensitive cells that produce colour and require lots of light are the _________________.","o":["rods","cones","bipolar cells","ganglia"],"a":1,"e":"Checked answer, not from an official key. Chapter 11 says cones produce color and require lots of light. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Typically affecting the older population, _________________ results in severe mental deterioration.","o":["Alzheimer’s disease","Parkinson’s disease","meningitis","cerebral palsy"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says Alzheimer’s disease results in severe mental deterioration and usually affects older people. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ regulates the amount of light that enters through the diameter of the pupil.","o":["cornea","iris","retina","sclera"],"a":1,"e":"Checked answer, not from an official key. Chapter 11 says the iris regulates the amount of light that enters through the diameter of the pupil. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ division of the autonomic nervous system operates under normal, nonstressful conditions.","o":["sympathetic","parasympathetic","peripheral","central"],"a":1,"e":"Checked answer, not from an official key. Chapter 11 says the parasympathetic division operates under normal nonstressful conditions. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The numerous folds on the surface of the cerebral hemispheres are called _________________.","o":["sulci","fissures","gyri","callosi"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says the numerous folds on the surface of each hemisphere are called gyri. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ fluid serves as a shock absorber for the central nervous system.","o":["interstitial","intercellular","cerebrospinal","subdural"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says cerebrospinal fluid serves as a shock absorber for the central nervous system. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ nerve is a motor nerve that controls tongue movements.","o":["abducens","trigeminal","vestibulocochlear","hypoglossal"],"a":3,"e":"Checked answer, not from an official key. Chapter 11 says the hypoglossal nerve (XII) is a motor nerve that controls tongue movements. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Sound waves that enter the ear canal are directed to the _________________, causing it to vibrate.","o":["oval window","round window","tympanic membrane","eustachian tube"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says the ear canal directs sound waves to the tympanic membrane, which vibrates. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Cerebrovascular accident, more commonly called _________________, can be caused by a blood vessel clot.","o":["encephalitis","stroke","meningitis","Parkinson’s"],"a":1,"e":"Checked answer, not from an official key. Chapter 11 says a cerebrovascular accident, or stroke, can be caused by a clot in a blood vessel. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"An enlargement or dilation of a blood vessel wall is called a(n) _________________.","o":["embolism","thrombus","aneurysm","cephalalgia"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says an aneurysm is an enlargement or dilation of a blood vessel wall. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The _________________ nerve is a motor nerve that controls movement of the eyeball.","o":["abducens","trigeminal","vestibulocochlear","hypoglossal"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the abducens nerve (VI) is a motor nerve that controls movement of the eyeball. The oculomotor and trochlear nerves also move the eye, but they aren’t options here. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Nerve fibers leave the eye as the optic nerve at the _________________.","o":["fovea centralis","ciliary body","optic disk","retinal tract"],"a":2,"e":"Checked answer, not from an official key. Chapter 11 says nerve fibers leave the eye as the optic nerve at the optic disk. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The cornea is the transparent part of the outermost layer of the eye.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the cornea is the transparent part of the outermost layer that lets light into the eye. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The medulla oblongata contains all the ascending and descending tracts that connect the spinal cord and various parts of the brain.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 11 says the medulla oblongata contains all the ascending and descending tracts that connect the spinal cord and parts of the brain. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The somatic nervous system regulates the functions of internal organs by controlling glands, smooth muscles, and cardiac muscle.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. That describes the autonomic nervous system. The somatic nervous system controls skeletal muscle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"The cerebellum controls intellectual processes and emotions.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Intellectual processes and emotions are controlled by the cerebrum. The cerebellum handles coordination, posture and balance. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."},{"q":"Cones are sensitive to light and function in dim light but do not produce colour vision.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. That describes rods. Cones produce color vision and need lots of light. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 11."}],"caseStudy":{"title":"One breakfast, many neural tasks","scenario":"An older adult after a clinician-diagnosed stroke has visual-field difficulty, reduced hand control and trouble following a fast conversation.","prompts":["Name the broad brain and sensory systems involved without localizing the lesion.","Identify accommodations that could make counselling accessible.","Explain the roles of cranial nerves and somatic motor pathways in eating.","List issues that require team-based assessment, such as swallowing safety."],"takeaway":"Anatomy helps anticipate functional demands and design access; it does not replace neurologic or swallowing assessment."},"perStepChapter":true},{"n":12,"title":"The Endocrine System","kicker":"Lesson 12 of your course, built from Chapter 12 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"90–110 minutes","steps":[{"id":"ap12-1","chapter":"What the endocrine system does","title":"What the endocrine system does","teach":["The endocrine system controls the body chemically, keeping the internal environment within narrow ranges (homeostasis). It shares this job with the nervous system.","Endocrine glands are ductless: they secrete hormones straight into the bloodstream, which carries them to target organs. Exocrine glands, like sweat and salivary glands, have ducts.","Hormones control cellular respiration, growth and reproduction, water and electrolyte balance, the secretion of other hormones, behavior, reproductive cycles, and growth and development."],"act":{"type":"sort","prompt":"Endocrine or exocrine?","categories":["Endocrine (ductless)","Exocrine (ducts)"],"items":[{"label":"Thyroid gland","category":0,"feedback":"Hormones go into the blood."},{"label":"Sweat gland","category":1,"feedback":"Has a duct to the skin."},{"label":"Pituitary gland","category":0,"feedback":"Endocrine."},{"label":"Salivary gland","category":1,"feedback":"Has a duct to the mouth."}]}},{"id":"ap12-2","chapter":"Negative feedback","title":"Negative feedback","teach":["Most hormone control works by negative feedback, like a thermostat. When a hormone’s level rises high enough, it inhibits the gland that made it, so secretion stops or drops. When the level falls, the inhibition lifts and secretion starts again.","Thyroid hormones are a good example: rising thyroid hormone inhibits TSH from the pituitary and TRH from the hypothalamus."],"visual":{"kind":"cycle","title":"Negative feedback loop","items":[{"label":"Gland secretes hormone","detail":"Hormone level rises."},{"label":"Level gets high","detail":"Inhibits the gland."},{"label":"Secretion drops","detail":"Hormone level falls."},{"label":"Inhibition lifts","detail":"Gland secretes again."}]},"act":{"type":"choice","prompt":"In negative feedback, a rising blood level of a hormone:","options":[{"label":"Inhibits further secretion from its gland","correct":true,"feedback":"Right."},{"label":"Makes the gland secrete even more","correct":false,"feedback":"That would be positive feedback."},{"label":"Has no effect on the gland","correct":false,"feedback":"It inhibits the gland."}]}},{"id":"ap12-3","chapter":"Three chemical types of hormones","title":"Three chemical types of hormones","teach":["Modified amino acid hormones: epinephrine and norepinephrine (adrenal medulla), oxytocin and vasopressin (posterior pituitary).","Protein hormones: insulin (pancreatic islets), growth hormone and the gonad-stimulating hormones (anterior pituitary).","Steroid hormones are lipids: cortisol (adrenal cortex), estrogen and testosterone (gonads).","Protein and amino acid hormones bind to receptors on the cell membrane. Steroids pass through the membrane to receptors inside. Steroids can be taken by mouth (like birth control pills), but insulin is broken down in the gut, so it must be injected."],"act":{"type":"sort","prompt":"Which chemical type?","categories":["Modified amino acid","Protein","Steroid"],"items":[{"label":"Epinephrine","category":0,"feedback":"Modified amino acid."},{"label":"Insulin","category":1,"feedback":"Protein."},{"label":"Growth hormone","category":1,"feedback":"Protein."},{"label":"Cortisol","category":2,"feedback":"Steroid."},{"label":"Testosterone","category":2,"feedback":"Steroid."},{"label":"Oxytocin","category":0,"feedback":"Modified amino acid."}]}},{"id":"ap12-4","chapter":"The hypothalamus and the pituitary","title":"The hypothalamus and the pituitary","teach":["The pituitary is called the master gland because it controls many other glands, but the hypothalamus actually controls the pituitary. The infundibulum is the stalk connecting them.","The hypothalamus makes releasing hormones and release-inhibiting hormones that travel through a portal vein to the anterior pituitary. For example, TRH (thyrotropin-releasing hormone) makes the anterior pituitary release TSH.","The pituitary (hypophysis) is pea-sized and sits in a hollow of the sphenoid bone. It has an anterior lobe (adenohypophysis) and a posterior lobe (neurohypophysis)."],"act":{"type":"choice","prompt":"Which releasing hormone from the hypothalamus makes the anterior pituitary secrete TSH?","options":[{"label":"TRH","correct":true,"feedback":"Right: thyrotropin-releasing hormone."},{"label":"PTH","correct":false,"feedback":"PTH is parathyroid hormone."},{"label":"CRH","correct":false,"feedback":"CRH triggers ACTH."}]}},{"id":"ap12-5","chapter":"Anterior pituitary hormones","title":"Anterior pituitary hormones","teach":["The anterior lobe makes seven hormones.","Growth hormone (GH): cell growth, protein synthesis, bone and muscle growth. Too little in childhood causes pituitary dwarfism; too much in childhood causes gigantism; too much after childhood causes acromegaly.","TSH stimulates the thyroid. ACTH stimulates the adrenal cortex to make cortisol. MSH increases melanin, darkening the skin. FSH develops ovarian follicles, or sperm in males. LH triggers ovulation and progesterone, or testosterone in males. Prolactin (LTH) stimulates milk production after delivery."],"act":{"type":"sort","prompt":"Which anterior pituitary hormone?","categories":["GH","MSH","LH","Prolactin"],"items":[{"label":"Too much after childhood causes acromegaly","category":0,"feedback":"Growth hormone."},{"label":"Darkens the skin","category":1,"feedback":"Melanocyte-stimulating hormone."},{"label":"Stimulates ovulation","category":2,"feedback":"Luteinizing hormone."},{"label":"Stimulates milk production after childbirth","category":3,"feedback":"Prolactin."}]}},{"id":"ap12-6","chapter":"Posterior pituitary hormones","title":"Posterior pituitary hormones","teach":["The posterior lobe stores hormones made by neurons in the hypothalamus.","Antidiuretic hormone (ADH, or vasopressin) makes the kidneys reabsorb water, so less is lost in urine. A deficiency causes diabetes insipidus: 20 to 30 liters of urine a day and severe dehydration.","Oxytocin stimulates the uterus to contract during childbirth and makes the mammary glands eject milk. It’s sometimes given to induce labor."],"act":{"type":"sort","prompt":"ADH or oxytocin?","categories":["ADH (vasopressin)","Oxytocin"],"items":[{"label":"Kidneys reabsorb water","category":0,"feedback":"ADH."},{"label":"Uterine contractions in childbirth","category":1,"feedback":"Oxytocin."},{"label":"Deficiency causes diabetes insipidus","category":0,"feedback":"ADH."},{"label":"Milk ejection during breastfeeding","category":1,"feedback":"Oxytocin."}]}},{"id":"ap12-7","chapter":"The thyroid gland","title":"The thyroid gland","teach":["The thyroid has two lobes joined by the isthmus, below the larynx. Its follicles make thyroxine (T4, four iodine atoms) and triiodothyronine (T3), which regulate the metabolism of carbohydrates, fats and proteins and are needed for growth and nervous system development. It needs iodine; without enough, it enlarges into a goiter.","Hypothyroidism: in children, cretinism (stunted growth and impaired development); in adults, a slow metabolism, sluggishness and myxedema, a build-up of fluid in the tissue under the skin.","Hyperthyroidism: nervousness, fatigue and a high metabolic rate. Graves’ disease is caused by overproduction of thyroid hormone, often with a goiter and bulging eyes.","The thyroid also makes calcitonin, which lowers blood calcium."],"act":{"type":"sort","prompt":"Match the thyroid condition.","categories":["Goiter","Myxedema","Graves’ disease","Cretinism"],"items":[{"label":"Enlarged thyroid from too little iodine","category":0,"feedback":"Goiter."},{"label":"Fluid build-up under the skin in adults","category":1,"feedback":"Myxedema."},{"label":"Overproduction of thyroid hormone","category":2,"feedback":"Graves’ disease."},{"label":"Low thyroid hormone in young children","category":3,"feedback":"Cretinism."}]}},{"id":"ap12-8","chapter":"Parathyroid glands and calcium","title":"Parathyroid glands and calcium","teach":["Four raisin-sized parathyroid glands sit on the back of the thyroid. They secrete parathyroid hormone (PTH, parathormone).","When blood calcium is low, PTH makes osteoclasts break down bone matrix, releasing calcium and phosphate into the blood. It also makes the kidneys keep calcium and the intestines absorb more (with vitamin D). Calcitonin from the thyroid does the opposite.","Hyperparathyroidism softens and deforms bones and can cause kidney stones. Hypoparathyroidism lowers blood calcium, causing muscle cramps and spasms."],"act":{"type":"sort","prompt":"Raises or lowers blood calcium?","categories":["Raises blood calcium","Lowers blood calcium"],"items":[{"label":"Parathyroid hormone (PTH)","category":0,"feedback":"Releases calcium from bone."},{"label":"Calcitonin","category":1,"feedback":"Keeps calcium in bone."}]}},{"id":"ap12-9","chapter":"The adrenal glands","title":"The adrenal glands","teach":["The adrenal (suprarenal) glands sit on top of each kidney. The inner medulla and outer cortex work as two separate glands.","The adrenal medulla makes epinephrine (adrenaline) and some norepinephrine, the fight-or-flight hormones, when signaled by the sympathetic nervous system. They raise blood glucose, heart rate and blood pressure.","The adrenal cortex has three layers. The outer layer secretes mineralocorticoids, mainly aldosterone, which controls sodium and potassium. The middle layer secretes cortisol (a glucocorticoid), which raises blood glucose and reduces inflammation. The inner layer secretes androgens.","Too little cortex hormone causes Addison’s disease (bronzed skin, low sodium and glucose). Too much causes Cushing’s syndrome (high glucose, puffy moon face, obesity)."],"act":{"type":"sort","prompt":"Which part or condition?","categories":["Adrenal medulla","Outer cortex","Addison’s disease","Cushing’s syndrome"],"items":[{"label":"Fight-or-flight hormones","category":0,"feedback":"Epinephrine and norepinephrine."},{"label":"Mineralocorticoids like aldosterone","category":1,"feedback":"Outer layer of the cortex."},{"label":"Too little cortex hormone","category":2,"feedback":"Addison’s disease."},{"label":"Too much cortex hormone","category":3,"feedback":"Cushing’s syndrome."}]}},{"id":"ap12-10","chapter":"The pancreas and blood glucose","title":"The pancreas and blood glucose","teach":["The pancreas is both exocrine (digestive juice) and endocrine. Its pancreatic islets (islets of Langerhans) make two hormones.","Beta cells secrete insulin after a meal, when glucose is high. Insulin moves glucose into the liver (stored as glycogen), muscle and fat.","Alpha cells secrete glucagon when glucose is low. Glucagon makes the liver turn glycogen back into glucose.","Diabetes mellitus comes from a lack of insulin: high blood glucose, glucose in the urine, polyuria, polydipsia (excessive thirst) and polyphagia (intense hunger). If cells burn fat instead, ketones lower blood pH: acidosis."],"mnemonic":{"cue":"Beta = Builds stores (insulin); Alpha = Activates release (glucagon)","explanation":"Insulin lowers blood glucose by storing it; glucagon raises it by releasing it."},"act":{"type":"sort","prompt":"Insulin or glucagon?","categories":["Insulin","Glucagon"],"items":[{"label":"Secreted by beta cells","category":0,"feedback":"Insulin."},{"label":"Secreted by alpha cells","category":1,"feedback":"Glucagon."},{"label":"Released after a meal","category":0,"feedback":"Lowers glucose."},{"label":"Turns liver glycogen into glucose","category":1,"feedback":"Raises glucose."}]}},{"id":"ap12-11","chapter":"Gonads, thymus and pineal gland","title":"Gonads, thymus and pineal gland","teach":["The testes make testosterone, which develops male structures and secondary sex characteristics. Anabolic steroids are variants of testosterone and have serious side effects. The ovaries make estrogen and progesterone, which develop female structures and control the menstrual cycle.","The thymus, behind the sternum, secretes thymosin, which helps T lymphocytes develop. It’s largest in childhood and shrinks with age.","The pineal gland secretes melatonin, which regulates circadian rhythms (sleep–wake cycles). Darkness increases melatonin; bright light reduces it. Seasonal affective disorder occurs in people sensitive to an overproduction of melatonin in dark, cloudy winters. The pineal gland also secretes serotonin."],"act":{"type":"sort","prompt":"Which gland?","categories":["Testes","Thymus","Pineal gland"],"items":[{"label":"Testosterone","category":0,"feedback":"Testes."},{"label":"Thymosin and T cell development","category":1,"feedback":"Thymus."},{"label":"Melatonin and circadian rhythms","category":2,"feedback":"Pineal gland."}]}},{"id":"ap12-12","chapter":"Hormones and aging","title":"Hormones and aging","teach":["Growth hormone falls with age, so bone and lean muscle decrease and fat increases. Sex hormones decline in later middle age; in women this is menopause.","Less thymosin means fewer mature lymphocytes and more infections. Less melatonin changes sleep patterns, often with daytime tiredness."],"act":{"type":"choice","prompt":"With age, less growth hormone leads to:","options":[{"label":"Less bone mass and lean muscle","correct":true,"feedback":"Right. Exercise helps limit this."},{"label":"More bone growth","correct":false,"feedback":"Bone mass decreases."},{"label":"Higher melatonin","correct":false,"feedback":"Melatonin decreases with age too."}]}}],"flashcards":[{"front":"Endocrine glands","back":"Ductless; secrete hormones into the blood."},{"front":"Negative feedback","back":"Rising hormone level inhibits its own gland."},{"front":"Protein hormones","back":"Insulin, growth hormone, gonad-stimulating hormones."},{"front":"Steroid hormones","back":"Cortisol, estrogen, testosterone (lipids)."},{"front":"Modified amino acid hormones","back":"Epinephrine, norepinephrine, oxytocin, vasopressin."},{"front":"Infundibulum","back":"Stalk connecting the hypothalamus to the pituitary."},{"front":"Pituitary (hypophysis)","back":"Two lobes: anterior and posterior."},{"front":"TRH","back":"From the hypothalamus; triggers TSH release."},{"front":"Growth hormone excess","back":"Childhood: gigantism. After childhood: acromegaly."},{"front":"MSH","back":"Increases melanin, darkening the skin."},{"front":"LH","back":"Stimulates ovulation; testosterone in males."},{"front":"Prolactin","back":"Stimulates milk production after delivery."},{"front":"ADH","back":"Kidneys reabsorb water; deficiency causes diabetes insipidus."},{"front":"Oxytocin","back":"Uterine contractions in labor; milk ejection."},{"front":"Thyroid hormones","back":"T4 (thyroxine) and T3; regulate metabolism."},{"front":"Goiter","back":"Enlarged thyroid from too little iodine."},{"front":"Myxedema","back":"Fluid build-up under the skin in adult hypothyroidism."},{"front":"Graves’ disease","back":"Overproduction of thyroid hormone."},{"front":"PTH","back":"Raises blood calcium by releasing it from bone."},{"front":"Hyperparathyroidism","back":"Bones soften and deform; kidney stones."},{"front":"Epinephrine and norepinephrine","back":"Fight-or-flight hormones of the adrenal medulla."},{"front":"Mineralocorticoids","back":"From the outer adrenal cortex; mainly aldosterone."},{"front":"Cortisol","back":"Glucocorticoid; raises blood glucose; reduces inflammation."},{"front":"Addison’s / Cushing’s","back":"Too little / too much adrenal cortex hormone."},{"front":"Beta / alpha cells","back":"Insulin / glucagon."},{"front":"Polydipsia","back":"Excessive thirst."},{"front":"Acidosis","back":"A lowering of blood pH."},{"front":"Melatonin","back":"From the pineal gland; regulates circadian rhythms."},{"front":"Seasonal affective disorder","back":"Linked to overproduction of melatonin in dark winters."}],"quiz":[{"q":"Insulin and growth hormone are examples of ___________________________ hormones.","o":["steroid","modified amino acid","protein","exocrine"],"a":2,"e":"Checked answer, not from an official key. Chapter 12 lists insulin and growth hormone as protein hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"An accumulation of fluid in subcutaneous tissue is called _______________________ .","o":["goiter","myxedema","cretinism","acromegaly"],"a":1,"e":"Checked answer, not from an official key. Chapter 12 says an accumulation of fluid in subcutaneous tissues is called myxedema. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Modified amino acid hormones include _______________________ .","o":["epinephrine","testosterone","estrogen","insulin"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 lists epinephrine and norepinephrine as modified amino acid hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Overproduction of thyroid hormone results in _______________________________ .","o":["cretinism","Addison’s disease","polydipsia","Graves’ disease"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says Graves’ disease is a type of hyperthyroidism caused by overproduction of thyroid hormone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Secretion of ______ from the anterior pituitary increases pigmentation or darkening of the skin.","o":["TSH","LH","MSH","GH"],"a":2,"e":"Checked answer, not from an official key. Chapter 12 says melanocyte-stimulating hormone increases melanin production, darkening the skin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Testosterone and cortisol are examples of _______________________________ hormones.","o":["steroid","modified amino acid","protein","exocrine"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 lists cortisol and testosterone as steroid hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Excess secretion of growth hormone after childhood results in ______________________.","o":["gigantism","dwarfism","adrenogenital syndrome","acromegaly"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says excess growth hormone after childhood results in acromegaly. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Stimulation of uterine muscle contractions during childbirth is triggered by ______________________ .","o":["oxytocin","estrogen","peripheral","aldosterone"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says oxytocin stimulates contraction of the uterus in the late stages of childbirth. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"In the pancreas, insulin is secreted by cells.","o":["alpha","beta","chief","oxyphil"],"a":1,"e":"Checked answer, not from an official key. Chapter 12 says beta cells secrete insulin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The release of ___________________, stimulates the liver to convert the stored glycogen into glucose.","o":["calcitonin","insulin","cortisol","glucagon"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says glucagon stimulates the liver to convert stored glycogen into glucose. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Excessive thirst is called _____________________________.","o":["polydipsia","polynurea","polyphagia","glycosuria"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 calls excessive thirst polydipsia. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Anabolic steroids are variants of the male sex hormone _________________________.","o":["estrogen","progesterone","testosterone","prolactin"],"a":2,"e":"Checked answer, not from an official key. Chapter 12 says anabolic steroids are variants of the male sex hormone testosterone. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Following childbirth, _______________________ stimulates milk production in the mammary glands.","o":["estrogen","testosterone","progesterone","prolactin"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says prolactin stimulates milk production in the mammary glands following delivery. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The outer layer of the adrenal cortex secretes a group of hormones called _______________.","o":["cortisol","androgens","triphosphates","mineralocorticoids"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says the outer layer of the adrenal cortex secretes mineralocorticoid hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The common disorder ______________________ is caused by a deficiency in insulin production.","o":["polynuria","diabetes mellitus","diabetes insipidus","polyphagia"],"a":1,"e":"Checked answer, not from an official key. Diabetes mellitus is caused by a lack of insulin; Chapter 12 says insulin must be injected to treat it. Diabetes insipidus comes from a lack of ADH. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The hormones insulin and glucagon are produced by the ____________________________.","o":["pancreas","thyroid","pituitary","adrenals"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says the pancreatic islets produce insulin and glucagon. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Secretion of _________________________ from the anterior pituitary stimulates ovulation in the ovary.","o":["luteinizing hormone","estrogen","testosterone","aldosterone"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says luteinizing hormone stimulates ovulation in the ovary. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The ______________________ gland, also known as the hypophysis, is divided into two lobes.","o":["pineal","pituitary","adrenal","ovarian"],"a":1,"e":"Checked answer, not from an official key. Chapter 12 says the pituitary gland, also called the hypophysis, is divided into two lobes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Too much secretion of adrenal cortex hormones can lead to ________________________.","o":["Addison’s disease","Graves’ disease","gigantism","Cushing’s syndrome"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says too much secretion from the adrenal cortex can lead to Cushing’s syndrome. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The ___________________ gland stimulates the release of calcium and phosphate ions into the blood when calcium levels become too low.","o":["thyroid","pineal","parathyroid","pituitary"],"a":2,"e":"Checked answer, not from an official key. Chapter 12 says parathyroid hormone releases calcium and phosphate ions into the blood. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Inadequate amounts of iodine in the diet leads to an enlarged thyroid gland, known as a(n) __________________________.","o":["myxedema","cretin","goiter","edema"],"a":2,"e":"Checked answer, not from an official key. Chapter 12 says without enough iodine the thyroid enlarges, forming a goiter. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Circadian rhythms are regulated by __________________________.","o":["aldosterone","melatonin","cortisol","estrogen"],"a":1,"e":"Checked answer, not from an official key. Chapter 12 says studies indicate melatonin regulates circadian rhythms. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Seasonal affective disorder occurs in individuals who are sensitive to overproduction of ___________________.","o":["prolactin","melanin","aldosterone","melatonin"],"a":3,"e":"Checked answer, not from an official key. Chapter 12 says seasonal affective disorder occurs in people sensitive to an overproduction of melatonin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The release of ________ from the hypothalamus stimulates the anterior pituitary to secrete TSH.","o":["TIH","TRH","TH","PTH"],"a":1,"e":"Checked answer, not from an official key. Chapter 12 says the hypothalamus produces thyrotropin-releasing hormone (TRH), which stimulates the anterior pituitary to secrete TSH. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Hyperparathyroidism results in the softening and deformation of the _______________.","o":["bones","kidneys","intestines","adrenal glands"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says hyperparathyroidism breaks down bone matrix, so bones become soft and deformed. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Epinephrine and norepinephrine are commonly referred to as the fight-or-flight hormones.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says epinephrine and norepinephrine are commonly called the fight-or-flight hormones. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The exocrine glands are ductless glands that secrete hormone directly into the bloodstream.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Endocrine glands are ductless and secrete into the bloodstream. Exocrine glands have ducts. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"Negative feedback occurs when the increasing blood level of a hormone inhibits its continued secretion from its source endocrine gland.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 describes negative feedback exactly this way. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"The thalamus plays a major role in controlling secretions from the pituitary gland.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. It’s the hypothalamus, not the thalamus, that controls secretions from the pituitary gland. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."},{"q":"A lowering of blood pH is called acidosis.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 12 says a lowering of blood pH is called acidosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 12."}],"caseStudy":{"title":"After a meal: a coordinated endocrine story","scenario":"A learner says one high-carbohydrate meal permanently “breaks hormones” and that every tired feeling must be high cortisol.","prompts":["Trace insulin and glucagon around a meal and between meals.","Explain negative feedback using one pituitary axis.","Contrast adrenal cortex and medulla signals.","Identify why symptoms alone cannot establish an endocrine diagnosis.","Offer scope-safe nutrition education without fear-based claims."],"takeaway":"Endocrine regulation is dynamic, receptor-specific and feedback controlled; nutrition matters within a larger physiologic and clinical context."},"perStepChapter":true},{"n":13,"title":"The Blood","kicker":"Lesson 13 of your course, built from Chapter 13 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"70–90 minutes","steps":[{"id":"ap13-1","chapter":"What blood is","title":"What blood is","teach":["Blood is a specialized connective tissue with two parts: formed elements (red cells, white cells and platelets) and the fluid plasma. Plasma is about 55% of blood; formed elements about 45%.","An average woman has about 5 liters of blood and a man about 6. Blood is about 8% of body weight."],"act":{"type":"number","prompt":"About what percent of blood is plasma?","answer":55,"tolerance":2,"unit":"%","explanation":"Plasma is about 55% of blood; the formed elements are about 45%."}},{"id":"ap13-2","chapter":"What blood does","title":"What blood does","teach":["Blood carries oxygen from the lungs to the cells and carbon dioxide back; nutrients, ions and water from the gut; wastes to the kidneys and sweat glands; hormones to target organs; and enzymes.","It helps regulate pH (normally slightly basic, 7.35 to 7.45), body temperature (thanks to all the water in plasma) and cell water content. It prevents fluid loss by clotting and protects the body with white blood cells."],"act":{"type":"choice","prompt":"What is the normal pH of blood?","options":[{"label":"7.35 to 7.45","correct":true,"feedback":"Right, slightly basic."},{"label":"6.8 to 7.0","correct":false,"feedback":"That would be too acidic."},{"label":"8.0 to 8.5","correct":false,"feedback":"That would be too basic."}]}},{"id":"ap13-3","chapter":"Plasma","title":"Plasma","teach":["Plasma is 91% water. About 7% is proteins: albumin (keeps osmotic pressure and water balance), globulins (antibodies, complement and transport molecules) and fibrinogen (clotting). The other 2% is ions, nutrients, wastes, gases, enzymes and hormones.","Serum is plasma without the clotting factors: the clear yellow liquid left after a clot forms.","Dr. Charles Drew’s work on preserving plasma led to the first blood banks."],"act":{"type":"sort","prompt":"Match each plasma protein to its job.","categories":["Albumin","Globulins","Fibrinogen"],"items":[{"label":"Maintains osmotic pressure","category":0,"feedback":"Albumin."},{"label":"Antibodies","category":1,"feedback":"Globulins."},{"label":"Clotting","category":2,"feedback":"Fibrinogen."}]}},{"id":"ap13-4","chapter":"Classifying blood cells","title":"Classifying blood cells","teach":["Erythrocytes (red blood cells) make up about 95% of the volume of blood cells.","Leukocytes (white blood cells) are granular or agranular, depending on whether granules show with Wright’s stain. Granular: neutrophils (60–70% of white cells), eosinophils (2–4%), basophils (0.5–1%). Agranular: monocytes (3–8%) and lymphocytes (20–25%).","Thrombocytes (platelets) are cell fragments. There are about 700 times more red cells than white cells."],"mnemonic":{"cue":"Never Let Monkeys Eat Bananas","explanation":"White cells from most to least common: Neutrophils, Lymphocytes, Monocytes, Eosinophils, Basophils."},"act":{"type":"sort","prompt":"Granular or agranular leukocyte?","categories":["Granular","Agranular"],"items":[{"label":"Neutrophil","category":0,"feedback":"Granular."},{"label":"Eosinophil","category":0,"feedback":"Granular."},{"label":"Basophil","category":0,"feedback":"Granular."},{"label":"Monocyte","category":1,"feedback":"Agranular."},{"label":"Lymphocyte","category":1,"feedback":"Agranular."}]}},{"id":"ap13-5","chapter":"Red blood cells and hemoglobin","title":"Red blood cells and hemoglobin","teach":["Erythrocytes are biconcave disks with no nucleus, so they can’t divide. They live about 120 days.","About one-third of their volume is hemoglobin (about 280 million molecules per cell). Hemoglobin is globin (a protein) plus heme (a pigment with four iron atoms). The iron binds oxygen in the lungs; globin carries carbon dioxide back. Oxygenated blood is bright red.","A healthy man has about 5.4 million red cells per mm³ and a woman about 4.8 million."],"act":{"type":"sort","prompt":"Heme or globin?","categories":["Heme","Globin"],"items":[{"label":"Pigment with four iron atoms","category":0,"feedback":"Heme."},{"label":"Binds oxygen in the lungs","category":0,"feedback":"Through its iron."},{"label":"Protein that carries carbon dioxide","category":1,"feedback":"Globin."}]}},{"id":"ap13-6","chapter":"White blood cells","title":"White blood cells","teach":["Leukocytes have nuclei and no pigment. They fight inflammation and infection, squeeze out of blood vessels by ameboid movement, and eat invaders by phagocytosis.","Neutrophils are the most common and most active against bacteria; dead neutrophils make up pus. Monocytes are the largest; in tissues they enlarge into macrophages. Eosinophils fight allergens and, with their secretions, some worm parasites. Basophils release heparin, histamine and serotonin. Lymphocytes are the smallest and make antibodies (B and T cells)."],"act":{"type":"sort","prompt":"Which white blood cell?","categories":["Neutrophil","Monocyte","Eosinophil","Basophil","Lymphocyte"],"items":[{"label":"Most common white cell","category":0,"feedback":"60–70%."},{"label":"Becomes a macrophage in tissues","category":1,"feedback":"Monocyte."},{"label":"Attacks some worm parasites","category":2,"feedback":"Eosinophil."},{"label":"Releases heparin, histamine and serotonin","category":3,"feedback":"Basophil."},{"label":"Produces antibodies","category":4,"feedback":"Lymphocyte."}]}},{"id":"ap13-7","chapter":"Platelets","title":"Platelets","teach":["Thrombocytes (platelets) are disk-shaped cell fragments, 2 to 4 micrometers across, that live about a week. They start the chain of reactions that clots blood.","They come from large megakaryocytes in red bone marrow."],"act":{"type":"choice","prompt":"Platelets develop from:","options":[{"label":"Megakaryocytes in red bone marrow","correct":true,"feedback":"Right. Megakaryoblasts mature into platelets."},{"label":"Lymphoblasts","correct":false,"feedback":"Those become lymphocytes."},{"label":"Proerythroblasts","correct":false,"feedback":"Those become red blood cells."}]}},{"id":"ap13-8","chapter":"Making blood cells","title":"Making blood cells","teach":["Hematopoiesis, blood cell formation, happens in red bone marrow (myeloid tissue). The spleen, tonsils and lymph nodes help make lymphocytes and monocytes.","All blood cells start as stem cells (hematocytoblasts). Proerythroblasts lose their nuclei and become red cells. Myeloblasts become neutrophils, eosinophils and basophils. Lymphoblasts become lymphocytes, monoblasts become monocytes, and megakaryoblasts become platelets."],"act":{"type":"sort","prompt":"What does each cell mature into?","categories":["Red blood cell","Lymphocyte","Platelets"],"items":[{"label":"Proerythroblast","category":0,"feedback":"Loses its nucleus."},{"label":"Lymphoblast","category":1,"feedback":"Lymphocyte."},{"label":"Megakaryoblast","category":2,"feedback":"Platelets."}]}},{"id":"ap13-9","chapter":"Blood clotting","title":"Blood clotting","teach":["Small vessels can stop bleeding just by constricting. Larger ones need clotting (coagulation), which has three stages.","Stage 1: platelets clump at the rough, damaged site, and damaged tissue releases thromboplastin, which leads to prothrombin activator (calcium needed). Stage 2: prothrombin activator, with calcium ions, converts prothrombin (made by the liver) into thrombin. Stage 3: thrombin converts soluble fibrinogen into insoluble fibrin threads, which trap blood cells and platelets: the clot.","Clot retraction, or syneresis, tightens the clot. Once the vessel heals, fibrinolysis dissolves the clot. Vitamin K is needed for many clotting factors."],"visual":{"kind":"flow","title":"Three stages of clotting","items":[{"label":"Platelets clump; thromboplastin released","detail":"Leads to prothrombin activator."},{"label":"Prothrombin → thrombin","detail":"Needs calcium ions."},{"label":"Fibrinogen → fibrin","detail":"Thrombin makes the fibrin threads of the clot."}]},"act":{"type":"order","prompt":"Put the clotting steps in order.","items":[{"label":"Platelets clump at the injury","detail":"Thromboplastin is released"},{"label":"Prothrombin activator forms","detail":"Calcium needed"},{"label":"Prothrombin becomes thrombin","detail":"Stage 2"},{"label":"Fibrinogen becomes fibrin threads","detail":"The clot"},{"label":"Clot retraction (syneresis)","detail":"Clot tightens"}]}},{"id":"ap13-10","chapter":"Unwanted clots","title":"Unwanted clots","teach":["Plaque, a cholesterol-containing mass stuck to a vessel wall, roughens it and can start clotting in an unbroken vessel. That’s thrombosis, and the clot is a thrombus.","A piece of clot that breaks loose and travels is an embolus; when it lodges and blocks a vessel, that’s an embolism. Tissue killed by a blocked blood supply is an infarction.","Exercise helps prevent unwanted clots. Smoking raises fibrinogen, making clots more likely."],"act":{"type":"sort","prompt":"Match the term.","categories":["Plaque","Thrombosis","Embolus","Infarction"],"items":[{"label":"Cholesterol mass on a vessel wall","category":0,"feedback":"Plaque."},{"label":"Clotting in an unbroken vessel","category":1,"feedback":"Thrombosis."},{"label":"A travelling piece of clot","category":2,"feedback":"Embolus."},{"label":"Tissue death from a blocked supply","category":3,"feedback":"Infarction."}]}},{"id":"ap13-11","chapter":"ABO blood groups","title":"ABO blood groups","teach":["Mismatched blood causes agglutination (clumping of red cells), a transfusion reaction between antibodies in plasma and antigens on red cells.","Type A has A antigens and anti-B antibodies. Type B has B antigens and anti-A. Type AB has both antigens and neither antibody, so it’s the universal recipient. Type O has neither antigen and both antibodies, so it’s the universal donor."],"act":{"type":"sort","prompt":"Match the blood type.","categories":["Type A","Type B","Type AB","Type O"],"items":[{"label":"Has anti-B antibodies","category":0,"feedback":"Type A."},{"label":"Has anti-A antibodies","category":1,"feedback":"Type B."},{"label":"Universal recipient","category":2,"feedback":"No ABO antibodies."},{"label":"Universal donor","category":3,"feedback":"No A or B antigens."}]}},{"id":"ap13-12","chapter":"The Rh group","title":"The Rh group","teach":["The Rh group is named after the Rhesus monkey, where antigen D (the first Rh antigen identified and studied) was found. Blood with Rh antigens is Rh positive; most Americans are.","Anti-Rh antibodies don’t form on their own; an Rh-negative person makes them after exposure to Rh-positive blood.","An Rh-negative mother carrying an Rh-positive baby can become sensitized, and in a later pregnancy her antibodies can destroy the baby’s red cells: erythroblastosis fetalis (hemolytic disease of the newborn). RhoGAM prevents this."],"act":{"type":"choice","prompt":"Which antigen defines the Rh group?","options":[{"label":"Antigen D","correct":true,"feedback":"Right, first identified in Rhesus monkeys."},{"label":"Antigen A","correct":false,"feedback":"That’s the ABO group."},{"label":"Antigen O","correct":false,"feedback":"Type O has no A or B antigens."}]}},{"id":"ap13-13","chapter":"Blood disorders","title":"Blood disorders","teach":["Anemia means less oxygen-carrying capacity. Sickle-cell anemia: inherited; erythrocytes (red cells) are sickle-shaped with abnormal hemoglobin. Iron-deficiency anemia: from nutrient deficiency or blood loss. Hemolytic anemia: inherited (or caused by drugs, autoimmunity or venom); red cells break down faster than normal. Thalassemia: inherited; hemoglobin production is suppressed.","Hemophilia is an inherited clotting disorder linked to a recessive gene on the X chromosome. Leukemia is cancer with abnormal production of white cells. Thrombocytopenia is a serious drop in platelets. Erythrocytosis (polycythemia) is too many red cells.","Septicemia (blood poisoning) is infection in the blood. Malaria is caused by Plasmodium from a mosquito. Mononucleosis is caused by the Epstein-Barr virus."],"act":{"type":"sort","prompt":"Match the disorder.","categories":["Hemophilia","Thrombocytopenia","Erythrocytosis","Septicemia"],"items":[{"label":"X-linked recessive clotting disorder","category":0,"feedback":"Hemophilia."},{"label":"Serious decrease in platelets","category":1,"feedback":"Thrombocytopenia."},{"label":"Too many red blood cells","category":2,"feedback":"Erythrocytosis."},{"label":"Blood poisoning","category":3,"feedback":"Septicemia."}]}},{"id":"ap13-14","chapter":"Blood and aging, smoking and carbon monoxide","title":"Blood and aging, smoking and carbon monoxide","teach":["In the fetus, blood cells are made in the spleen, liver and yolk sac; by the third trimester, red marrow takes over for life.","Carbon monoxide (from cigarette smoke, exhaust or a faulty furnace) binds to hemoglobin’s iron, forming carboxyhemoglobin, which can’t carry oxygen. Smokers can have 5% to 15%.","With age, clotting disorders, anemias and chronic leukemias become more common."],"act":{"type":"choice","prompt":"Why is carbon monoxide dangerous?","options":[{"label":"It binds to hemoglobin’s iron so red cells can’t carry oxygen","correct":true,"feedback":"Right: carboxyhemoglobin."},{"label":"It destroys platelets","correct":false,"feedback":"It affects hemoglobin."},{"label":"It thins the plasma","correct":false,"feedback":"It blocks oxygen transport."}]}}],"flashcards":[{"front":"Plasma / formed elements","back":"About 55% / about 45% of blood."},{"front":"Normal blood pH","back":"7.35 to 7.45 (slightly basic)."},{"front":"Plasma composition","back":"91% water, 7% proteins, 2% other solutes."},{"front":"Serum","back":"Plasma without the clotting factors."},{"front":"Erythrocytes","back":"Red cells; about 95% of blood cell volume; live ~120 days."},{"front":"Hemoglobin","back":"About one-third of red cell volume; heme (4 iron atoms) + globin."},{"front":"Leukocytes","back":"White blood cells."},{"front":"Neutrophils","back":"Most common white cell (60–70%); fight bacteria."},{"front":"Monocytes","back":"Largest white cell; become macrophages in tissue."},{"front":"Eosinophils","back":"Allergies; attack some worm parasites."},{"front":"Basophils","back":"Release heparin, histamine and serotonin."},{"front":"Lymphocytes","back":"Smallest white cell; produce antibodies."},{"front":"Agranular leukocytes","back":"Monocytes and lymphocytes."},{"front":"Thrombocytes","back":"Platelets; from megakaryocytes."},{"front":"Hematopoiesis","back":"Blood cell formation in red bone marrow."},{"front":"Clotting stages","back":"Thromboplastin → prothrombin activator; prothrombin → thrombin (calcium); fibrinogen → fibrin."},{"front":"Fibrin","back":"Threads that form the clot."},{"front":"Syneresis","back":"Clot retraction."},{"front":"Plaque","back":"Cholesterol mass on a vessel wall."},{"front":"Thrombosis / thrombus","back":"Clotting in an unbroken vessel / the clot."},{"front":"Embolus","back":"A dislodged, travelling piece of clot."},{"front":"Agglutination","back":"Clumping of red cells from mismatched blood."},{"front":"Universal donor / recipient","back":"Type O / type AB."},{"front":"Rh antigen","back":"Antigen D."},{"front":"Erythroblastosis fetalis","back":"Hemolytic disease of the newborn from Rh incompatibility."},{"front":"Hemophilia","back":"X-linked recessive clotting disorder."},{"front":"Hemolytic anemia","back":"Red cells destroyed faster than normal."},{"front":"Thrombocytopenia","back":"Serious decrease in platelets."},{"front":"Erythrocytosis","back":"Too many red blood cells."},{"front":"Septicemia","back":"Blood poisoning."}],"quiz":[{"q":"The most numerous white blood cell type are the __________________, which comprise 60–70% of all white blood cells.","o":["eosinophils","basophils","lymphocytes","neutrophils"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says neutrophils make up 60% to 70% of white blood cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Heparin, histamine, and serotonin are secreted by______________________.","o":["monocytes","basophils","macrophages","eosinophils"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says basophils release heparin, histamine and serotonin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"A piece of a blood clot that dislodges and is transported by the bloodstream is called a(n) _________________.","o":["embolus","thrombus","infarction","stroke"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says a dislodged piece of clot transported by the bloodstream is called an embolus. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"White blood cells as a group are called ____________________________.","o":["erythrocytes","lymphocytes","basophils","leukocytes"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says white blood cells are leukocytes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Agglutination of RBCs is the result of a transfusion reaction caused by _____________________ blood.","o":["familial","contaminated","frozen","mismatched"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says agglutination of red cells results from a transfusion reaction caused by mismatched blood. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Hematopoiesis occurs in the __________________________.","o":["kidney","bone marrow","liver","pancreas"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says hematopoiesis occurs in red bone marrow. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Chemical secretions from __________________________ attack some worm parasites in the body.","o":["neutrophils","eosinophils","lymphocytes","monocytes"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says eosinophils’ chemical secretions attack some worm parasites. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Prothrombin activator, with the assistance of ______________ ions, converts prothrombin to thrombin.","o":["calcium","potassium","sodium","chloride"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says prothrombin activator, in the presence of calcium ions, converts prothrombin into thrombin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Red blood cells make up about _______ % of the volume of blood cells.","o":["95","50","35","75"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says erythrocytes make up about 95% of the volume of blood cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Antibodies are produced by __________________________.","o":["lymphocytes","monocytes","basophils","eosinophils"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says lymphocytes are involved in the production of antibodies. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"A cholesterol-containing mass that adheres to the smooth walls of blood vessels is called a(n) __________________________.","o":["plaque","clot","embolism","embolus"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says plaque is a cholesterol-containing mass that adheres to the smooth walls of blood vessels. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Blood poisoning is also known as __________________________.","o":["anemia","thalassemia","septicemia","leukemia"],"a":2,"e":"Checked answer, not from an official key. Chapter 13 says septicemia is also known as blood poisoning. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"An example of an agranular leukocyte is a(n) __________________________.","o":["neutrophil","eosinophil","basophil","monocyte"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 lists monocytes and lymphocytes as the agranular leukocytes. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"The Rh blood group consists of those individuals with the ___ antigen, the first identified and studied.","o":["A","B","O","D"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says antigen D was the Rh antigen first identified and studied in Rhesus monkeys. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Blood plasma without clotting factors is called __________________________.","o":["thrombin","fibrin","thromboplastin","serum"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says serum is blood plasma without the clotting factors. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"After _______________ leave the blood and enter tissues, they increase in size and are called macrophages.","o":["neutrophils","eosinophils","lymphocytes","monocytes"],"a":3,"e":"Checked answer, not from an official key. Chapter 13 says monocytes enlarge into macrophages after they leave the blood and enter tissues. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"An excessive amount of red blood cells can cause __________________________.","o":["anemia","erythrocytosis","thalassemia","thrombocytopenia"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says erythrocytosis is caused by an excessive amount of red blood cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Clot retraction is called __________________________.","o":["embolism","syneresis","thrombosis","eosinophilia"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says clot retraction is called syneresis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Clotting in an unbroken blood vessel is called __________________________.","o":["embolus","clotting","thrombosis","embolism"],"a":2,"e":"Checked answer, not from an official key. Chapter 13 says clotting in an unbroken vessel is called thrombosis. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Megakaryoblasts mature into __________________________.","o":["lymphocytes","platelets","erythrocytes","eosinophils"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says megakaryoblasts mature into blood platelets. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"An inherited form of anemia in which erythrocytes rupture or are destroyed at a faster rate than normal is known as __________________________.","o":["thalassemia","septicemia","hemolytic anemia","malaria"],"a":2,"e":"Checked answer, not from an official key. Chapter 13 says hemolytic anemia is an inherited condition in which red cells rupture or are destroyed faster than normal. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Approximately one third of the erythrocyte cell volume is composed of ________________________.","o":["globulins","albumin","hemoglobin","fibrinogen"],"a":2,"e":"Checked answer, not from an official key. Chapter 13 says hemoglobin makes up 33% of the red cell’s volume. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Smoking increases __________________________ levels in the blood, thus increasing the possibility of unwanted clotting.","o":["albumin","hemoglobin","fibrinogen","thrombin"],"a":2,"e":"Checked answer, not from an official key. Chapter 13 says smoking increases fibrinogen levels, raising the chance of unwanted clotting. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"The serious decrease in the number of thrombocytes or blood platelets is a condition known as __________________________.","o":["leukemia","thrombocytopenia","erythrocytosis","mononucleosis"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says thrombocytopenia is a serious decrease in the number of platelets. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"The genetically inherited clotting disorder __________________________ is associated with the expression of a recessive gene on the X chromosome.","o":["leukemia","hemophilia","anemia","thalassemia"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says hemophilia is an inherited clotting disorder linked to a recessive gene on the X chromosome. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Plasma accounts for about 55% of blood.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 says plasma accounts for about 55% of blood. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"The normal pH of blood is at 7.35 to 7.45.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 13 gives the normal pH of blood as 7.35 to 7.45. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Sickle-cell anemia is a hereditary disease in which leukocytes have an abnormal sickle shape due to abnormal hemoglobin.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. In sickle-cell anemia it’s the erythrocytes (red cells), not leukocytes, that are sickle-shaped. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Hemoglobin has five iron atoms that combine with oxygen gas in the lungs.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Chapter 13 says heme contains four iron atoms, not five. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."},{"q":"Thrombin forms the threads of a blood clot, which enmesh the blood cells and platelets seeping from the wound.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Fibrin, not thrombin, forms the threads of the clot. Thrombin converts fibrinogen into fibrin. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 13."}],"caseStudy":{"title":"Fatigue, a low hemoglobin result, and a tempting shortcut","scenario":"A client reports persistent fatigue and shows you a recent low hemoglobin result. They assume the answer is to buy the highest-dose iron supplement immediately. They also report heavy menstrual bleeding and have not discussed the result with their clinician.","prompts":["Which blood measurements and contextual questions would help separate anemia from its possible causes?","Why does iron's role in hemoglobin not prove iron deficiency from this information alone?","What food-intake information is useful within nutrition scope?","What follow-up is appropriate before high-dose supplementation?"],"takeaway":"Connect physiology to safe reasoning: low hemoglobin warrants cause-focused assessment. Nutrition history can support the picture, but blood loss, inflammation, absorption, inherited conditions, and other causes require appropriate clinical evaluation."},"perStepChapter":true},{"n":14,"title":"The Cardiovascular Circulatory System","kicker":"Lesson 14 of your course, built from Chapter 14 of your Fundamentals of Anatomy and Physiology textbook (Rizzo). Test practice uses checked answers, because there is no official key for this test.","duration":"80–100 minutes","steps":[{"id":"ap14-1","chapter":"The heart’s job and position","title":"The heart’s job and position","teach":["The cardiovascular system is the heart and thousands of miles of blood vessels. The heart beats about 72 times a minute for a lifetime, and valves keep blood from flowing backward.","The heart sits at an angle between the lungs in the mediastinum, with about two-thirds of it left of the midline. It’s a blunt cone about the size of a closed fist."],"act":{"type":"choice","prompt":"Where is the heart?","options":[{"label":"In the mediastinum, between the lungs, surrounded by the pericardial sac","correct":true,"feedback":"Right."},{"label":"In the pleural cavity","correct":false,"feedback":"The lungs are in the pleural cavities."},{"label":"In the peritoneum","correct":false,"feedback":"That lines the abdominal cavity."}]}},{"id":"ap14-2","chapter":"The pericardial sac","title":"The pericardial sac","teach":["The heart is enclosed in the pericardial sac (parietal pericardium), which has two layers.","The outermost layer is the fibrous pericardium: tough connective tissue that anchors the heart to the great vessels, diaphragm and sternum and stops it overstretching. The innermost layer of the sac is the thin serous pericardium.","Between the sac and the heart is the pericardial cavity, holding pericardial fluid that reduces friction. Inflammation here is pericarditis."],"act":{"type":"choice","prompt":"What is the outermost layer of the pericardial sac?","options":[{"label":"Fibrous pericardium","correct":true,"feedback":"Right. The serous pericardium is the inner layer of the sac."},{"label":"Serous pericardium","correct":false,"feedback":"That’s the inner layer of the sac."},{"label":"Myocardium","correct":false,"feedback":"That’s the heart muscle."}]}},{"id":"ap14-3","chapter":"Layers of the heart wall","title":"Layers of the heart wall","teach":["The epicardium (visceral pericardium) is the thin outer layer of the heart wall.","The myocardium is the middle layer and makes up the bulk of the heart: involuntary, striated, branched cardiac muscle that contracts.","The endocardium is the thin inner lining of endothelium. It covers the valves and the chordae tendineae."],"mnemonic":{"cue":"Epi = upon, Myo = muscle, Endo = inside","explanation":"Epicardium is on the outside, myocardium is the muscle, endocardium lines the inside."},"act":{"type":"order","prompt":"Put the heart wall layers in order, outside in.","items":[{"label":"Epicardium","detail":"Outer, serous"},{"label":"Myocardium","detail":"Cardiac muscle, the bulk"},{"label":"Endocardium","detail":"Inner lining"}]}},{"id":"ap14-4","chapter":"The four chambers","title":"The four chambers","teach":["The two upper chambers are the right and left atria, separated by the interatrial septum. Each has an ear-like auricle. The two lower chambers are the right and left ventricles, separated by the interventricular septum.","The right atrium receives blood from the whole body except the lungs: from the superior vena cava (head, neck and arms), the inferior vena cava (legs and abdomen) and the coronary sinus. The left atrium receives oxygenated blood from the lungs through four pulmonary veins.","Ventricles have thicker walls than atria, and the left ventricle’s walls are thickest because it pumps blood through the whole body."],"act":{"type":"sort","prompt":"Which chamber?","categories":["Right atrium","Right ventricle","Left atrium","Left ventricle"],"items":[{"label":"Receives blood from the venae cavae","category":0,"feedback":"Right atrium."},{"label":"Pumps blood into the pulmonary trunk","category":1,"feedback":"Right ventricle."},{"label":"Receives blood from four pulmonary veins","category":2,"feedback":"Left atrium."},{"label":"Thickest walls; pumps into the aorta","category":3,"feedback":"Left ventricle."}]}},{"id":"ap14-5","chapter":"The valves","title":"The valves","teach":["Valves keep blood from flowing back into the chamber that pumped it.","Atrioventricular valves: the tricuspid (three cusps) between the right atrium and ventricle, and the bicuspid or mitral (two cusps, the only two-cusp valve) between the left atrium and ventricle. Chordae tendineae connect their cusps to the papillary muscles.","Semilunar valves: the pulmonary semilunar valve where the pulmonary trunk leaves the right ventricle, and the aortic semilunar valve where the aorta leaves the left ventricle."],"mnemonic":{"cue":"Try before you Buy","explanation":"Blood passes the TRIcuspid (right side) before the BIcuspid (left side)."},"act":{"type":"sort","prompt":"Where is each valve?","categories":["Right side","Left side"],"items":[{"label":"Tricuspid","category":0,"feedback":"Right atrium to right ventricle."},{"label":"Pulmonary semilunar","category":0,"feedback":"Right ventricle to pulmonary trunk."},{"label":"Bicuspid (mitral)","category":1,"feedback":"Left atrium to left ventricle."},{"label":"Aortic semilunar","category":1,"feedback":"Left ventricle to aorta."}]}},{"id":"ap14-6","chapter":"Blood flow through the heart","title":"Blood flow through the heart","teach":["Deoxygenated blood enters the right atrium from the venae cavae, passes the tricuspid valve into the right ventricle, then the pulmonary semilunar valve into the pulmonary trunk and pulmonary arteries to the lungs.","In the lungs it drops carbon dioxide and picks up oxygen, returns through four pulmonary veins to the left atrium, passes the bicuspid valve into the left ventricle, then the aortic semilunar valve into the aorta and out to the body."],"act":{"type":"order","prompt":"Put the path of blood in order, starting from the body.","items":[{"label":"Venae cavae","detail":"Deoxygenated blood returns"},{"label":"Right atrium","detail":""},{"label":"Tricuspid valve","detail":""},{"label":"Right ventricle","detail":""},{"label":"Pulmonary semilunar valve and pulmonary arteries","detail":"To the lungs"},{"label":"Pulmonary veins and left atrium","detail":"Oxygenated blood returns"},{"label":"Bicuspid valve and left ventricle","detail":""},{"label":"Aortic semilunar valve and aorta","detail":"To the body"}]}},{"id":"ap14-7","chapter":"The conduction system","title":"The conduction system","teach":["The autonomic nervous system speeds up or slows down the heart, but the heart starts each beat itself through its conduction system.","The sinoatrial (SA) node in the right atrium wall is the pacemaker: it starts each cycle and sets the rate. The impulse spreads over both atria, which contract, and reaches the atrioventricular (AV) node in the lower right atrium.","From the AV node, the atrioventricular bundle (bundle of His) runs down the interventricular septum and splits into right and left branches, distributing the charge over the medial ventricle walls. Purkinje fibers carry it into the ventricle muscle, which contracts."],"act":{"type":"order","prompt":"Put the conduction system in order.","items":[{"label":"SA node (pacemaker)","detail":"Starts the beat"},{"label":"AV node","detail":"Lower right atrium"},{"label":"Bundle of His","detail":"Down the septum"},{"label":"Purkinje fibers","detail":"Into the ventricle muscle"}]}},{"id":"ap14-8","chapter":"The cardiac cycle","title":"The cardiac cycle","teach":["Systole is contraction; diastole is relaxation. A cardiac cycle is the systole and diastole of both atria and both ventricles.","At about 72 beats a minute, each cycle takes about 0.8 second: the atria contract for 0.1 second, the ventricles contract for 0.3 second, and all chambers rest for 0.4 second. So the heart rests for half of each cycle."],"mnemonic":{"cue":"Systole = Squeeze, Diastole = Dilate","explanation":"Systole is contraction; diastole is relaxation and filling."},"act":{"type":"number","prompt":"About how long does one cardiac cycle take?","answer":0.8,"tolerance":0.05,"unit":"seconds","explanation":"At about 72 beats per minute: 0.1 s atrial systole + 0.3 s ventricular systole + 0.4 s rest = 0.8 s."}},{"id":"ap14-9","chapter":"Circulation routes","title":"Circulation routes","teach":["Systemic circulation carries oxygenated blood from the left ventricle to all the body’s organs and back to the right atrium. Two subdivisions: the coronary circulation supplies the myocardium of the heart, and the hepatic portal circulation runs from the digestive tract to the liver.","Pulmonary circulation runs from the right ventricle to the lungs and back to the left atrium.","Cerebral circulation supplies the brain through the carotid and vertebral arteries, which form the Circle of Willis. Fetal circulation exists only between the fetus and mother."],"act":{"type":"sort","prompt":"Which circulation?","categories":["Coronary","Pulmonary","Cerebral","Hepatic portal"],"items":[{"label":"Supplies the heart muscle","category":0,"feedback":"Coronary."},{"label":"Right ventricle to the lungs and back","category":1,"feedback":"Pulmonary."},{"label":"Supplies the brain","category":2,"feedback":"Cerebral."},{"label":"Digestive tract to the liver","category":3,"feedback":"Hepatic portal."}]}},{"id":"ap14-10","chapter":"Blood vessels","title":"Blood vessels","teach":["Arteries and veins have three layers: the tunica intima (one layer of endothelium), the tunica media (smooth muscle) and the tunica adventitia (fibrous connective tissue). The hollow core is the lumen.","Arteries are thick, elastic and contractile. Where branches join, it’s an anastomosis. Arterioles are small arteries that deliver blood to capillaries.","Capillaries are microscopic vessels one cell thick (simple squamous endothelium) where nutrients, oxygen, wastes and carbon dioxide are exchanged. Venules connect capillaries to veins. Veins have thinner walls and valves that keep blood flowing toward the heart."],"act":{"type":"order","prompt":"Put the vessels in the order blood flows through them.","items":[{"label":"Artery","detail":""},{"label":"Arteriole","detail":""},{"label":"Capillary","detail":"Exchange happens here"},{"label":"Venule","detail":""},{"label":"Vein","detail":"Back to the heart"}]}},{"id":"ap14-11","chapter":"Major arteries","title":"Major arteries","teach":["The aorta is the largest artery: ascending aorta, aortic arch, thoracic aorta, then abdominal aorta. The coronary arteries branch first and supply the heart.","The arch gives off the brachiocephalic, left common carotid and left subclavian arteries. In the thorax, 10 pairs of intercostal arteries supply the chest muscles. In the abdomen: the celiac trunk, mesenteric arteries (intestines), renal arteries (kidneys) and gonadal arteries. The common iliac arteries lead to the femoral arteries of the legs."],"act":{"type":"sort","prompt":"What does each artery supply?","categories":["Heart","Thorax muscles","Kidneys","Small intestine and colon"],"items":[{"label":"Coronary arteries","category":0,"feedback":"Heart."},{"label":"Intercostal arteries","category":1,"feedback":"Thorax muscles."},{"label":"Renal arteries","category":2,"feedback":"Kidneys."},{"label":"Superior mesenteric artery","category":3,"feedback":"Intestines."}]}},{"id":"ap14-12","chapter":"Major veins","title":"Major veins","teach":["Veins from the head and arms drain into the superior vena cava; veins from the lower body drain into the inferior vena cava.","The median cubital vein at the elbow is used to draw blood. The great saphenous veins are the longest in the body. The hepatic portal vein drains the digestive organs and goes to the liver; the hepatic veins drain the liver. The renal veins drain the kidneys."],"act":{"type":"sort","prompt":"Superior or inferior vena cava?","categories":["Superior vena cava","Inferior vena cava"],"items":[{"label":"Blood from the head, neck and arms","category":0,"feedback":"Superior."},{"label":"Blood from the legs and abdomen","category":1,"feedback":"Inferior."}]}},{"id":"ap14-13","chapter":"Heart disorders","title":"Heart disorders","teach":["Atherosclerosis is plaque building up inside arteries. In the coronary arteries it reduces blood flow and causes angina pectoris (chest pain). A myocardial infarction (heart attack) is the death of heart muscle; the damaged area is an infarct.","An arrhythmia is any deviation from a normal heartbeat rhythm (bradycardia is under 60 beats a minute, tachycardia over 100). A heart murmur is an abnormal fluttering or humming sound. Stenosis is a narrowed valve opening; an incompetent valve leaks.","Angioplasty inserts a small balloon through the aorta into a coronary artery to flatten plaque; a stent may be added. Bypass surgery uses healthy vessels to go around blockages."],"act":{"type":"sort","prompt":"Match the term.","categories":["Arrhythmia","Stenosis","Murmur","Angioplasty"],"items":[{"label":"Any deviation from normal rhythm","category":0,"feedback":"Arrhythmia."},{"label":"Narrowed valve opening","category":1,"feedback":"Stenosis."},{"label":"Fluttering or humming heart sound","category":2,"feedback":"Murmur."},{"label":"A balloon opens a coronary artery","category":3,"feedback":"Angioplasty."}]}},{"id":"ap14-14","chapter":"The heart and aging","title":"The heart and aging","teach":["Maximum heart rate drops with age; by 70, cardiac output can fall by as much as 75%. Stiffer arteries make the left ventricle work harder and enlarge.","Valves stiffen with calcium deposits, and arrhythmias become more common. Regular aerobic exercise, like daily walking, keeps the heart working well."],"act":{"type":"choice","prompt":"Why can the left ventricle enlarge with age?","options":[{"label":"Less elastic arteries raise pressure, so it works harder","correct":true,"feedback":"Right."},{"label":"It stops contracting","correct":false,"feedback":"It works harder, not less."},{"label":"The SA node moves into it","correct":false,"feedback":"The SA node stays in the right atrium."}]}}],"flashcards":[{"front":"Mediastinum","back":"Where the heart sits, between the lungs."},{"front":"Fibrous pericardium","back":"Outermost layer of the pericardial sac."},{"front":"Epicardium / myocardium / endocardium","back":"Outer layer / muscle (bulk) / inner lining."},{"front":"Superior vena cava","back":"Brings blood from the head, neck and arms."},{"front":"Inferior vena cava","back":"Brings blood from the lower body."},{"front":"Pulmonary veins","back":"Four; carry oxygenated blood to the left atrium."},{"front":"Thickest heart wall","back":"Left ventricle."},{"front":"Tricuspid valve","back":"Right atrium to right ventricle; three cusps."},{"front":"Bicuspid (mitral) valve","back":"Left atrium to left ventricle; two cusps."},{"front":"Semilunar valves","back":"Pulmonary (right ventricle exit) and aortic (left ventricle exit)."},{"front":"Chordae tendineae","back":"Cords linking valve cusps to papillary muscles."},{"front":"SA node","back":"The pacemaker, in the right atrium."},{"front":"Bundle of His","back":"Carries the impulse down the septum to the ventricles."},{"front":"Purkinje fibers","back":"Stimulate the ventricle muscle to contract."},{"front":"Systole / diastole","back":"Contraction / relaxation."},{"front":"Cardiac cycle","back":"About 0.8 second."},{"front":"Coronary circulation","back":"Supplies the heart muscle."},{"front":"Cerebral circulation","back":"Supplies the brain."},{"front":"Hepatic portal vein","back":"Drains the digestive organs to the liver."},{"front":"Tunica intima / media / adventitia","back":"Endothelium / smooth muscle / connective tissue."},{"front":"Lumen","back":"Hollow core of a blood vessel."},{"front":"Anastomosis","back":"Junction of two or more blood vessels."},{"front":"Capillaries","back":"One cell thick; where exchange happens."},{"front":"Venules","back":"Connect capillaries to veins."},{"front":"Intercostal arteries","back":"Supply the muscles of the thorax."},{"front":"Renal arteries","back":"Supply the kidneys."},{"front":"Arrhythmia","back":"Any deviation from a normal heartbeat rhythm."},{"front":"Stenosis","back":"Narrowed valve opening."},{"front":"Infarct","back":"Area of damaged heart tissue from inadequate blood flow."},{"front":"Angioplasty","back":"Balloon inserted to open a coronary artery."}],"quiz":[{"q":"The outermost layer of the pericardial sac is the ______________________________.","o":["visceral pericardium","serous pericardium","myocardium","fibrous pericardium"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 says the outermost layer of the pericardial sac is the fibrous pericardium. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The ______________________ circulation supplies the brain with oxygen and nutrients and disposes of waste.","o":["cerebral","coronary","pulmonary","renal"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the cerebral circulation supplies the brain with oxygen and nutrients and disposes of waste. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The _________________________ arteries supply muscles of the thorax.","o":["coronary","renal","gonadal","intercostal"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 says 10 pairs of intercostal arteries supply the muscles of the thorax. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Any deviation from a normal heartbeat rhythm is called ______________________________.","o":["arrhythmia","stenosis","infarction","thrombosis"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says an arrhythmia is any deviation from a normal heartbeat rhythm. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The mitral valve is also called the ________________________.","o":["bicuspid","tricuspid","aortic semilunar","pulmonary semilunar"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the valve between the left atrium and left ventricle is the bicuspid or mitral valve. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The reconstruction of a diseased coronary artery by inserting a small balloon through the aorta and into a coronary artery is a procedure known as __________________________________.","o":["atherosclerosis","stenosis","anastomosis","angioplasty"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 describes angioplasty as reconstructing a diseased coronary artery with a small balloon inserted through the aorta. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The hollow core of a blood vessel is called the ______________________.","o":["anastomosis","endocardium","lumen","tunic"],"a":2,"e":"Checked answer, not from an official key. Chapter 14 says the hollow core of a blood vessel is the lumen. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"An average cardiac cycle takes ________ seconds.","o":["2","0.8","0.2","8"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says each cardiac cycle takes about 0.8 second. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Capillaries are connected to veins by ____________________________.","o":["venules","bronchioles","arterioles","lymphatics"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says venules connect capillaries to veins. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The coronary arteries supply blood to the _____________________.","o":["heart","lungs","kidneys","liver"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the coronary arteries supply the heart. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The bundle of _________________ distributes the electrical charge over the medial surfaces of the ventricles.","o":["His","Purkinje","sinoatrium","myoatrium"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the bundle of His distributes the electrical charge over the medial surfaces of the ventricles. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The _______________ vena cava brings blood from the upper parts of the body, the head, neck, and arms to the heart..","o":["inferior","medial","lateral","superior"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 says the superior vena cava brings blood from the head, neck and arms. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The _____________________ circulation is the blood circulatory route that supplies the myocardium of the heart.","o":["cerebral","coronary","pulmonary","renal"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says the coronary circulation supplies the myocardium of the heart. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Microscopic vessels composed of simple squamous epithelial cells are called ______________________.","o":["venules","capillaries","arterioles","lumens"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says capillaries are microscopic vessels made of simple squamous epithelial cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The ___________________ portal vein drains the organs of the digestive tract and then continues to the liver.","o":["hepatic","renal","urinary","saphenous"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the hepatic portal vein drains the digestive organs and goes to the liver. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The presence of ______________________ keeps blood from backflowing in the heart.","o":["atria","ventricles","valves","septa"],"a":2,"e":"Checked answer, not from an official key. Chapter 14 says the heart’s valves prevent blood from flowing back into the pumping chamber. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"A _______________________ is an abnormal heart sound akin to a fluttering or a humming sound.","o":["stenosis","thrombosis","pectoris","murmur"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 says a heart murmur is an abnormal heart sound like a fluttering or humming. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The tunica _________________________ of arteries and veins is composed of a single layer of endothelial cells.","o":["media","adventitia","myomedia","intima"],"a":3,"e":"Checked answer, not from an official key. Chapter 14 says the tunica intima is a single layer of endothelial cells. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Oxygenated blood returns to the heart from the lungs via four pulmonary ______________________.","o":["arteries","arterioles","veins","venues"],"a":2,"e":"Checked answer, not from an official key. Chapter 14 says oxygenated blood returns to the left atrium through four pulmonary veins. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The second layer of the wall of the heart, the ____________________, makes up the bulk of the heart.","o":["epicardium","myocardium","endocardium","pericardium"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says the myocardium, the second layer, makes up the bulk of the heart. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"A narrowed opening through the valves of the heart is called a(n) _____________________.","o":["infarct","stenosis","embolus","thrombus"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says stenosis of the heart valves is a narrowed opening through the valves. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Blood flow from the lower portions of the body return to the heart via the _______________________ vena cava.","o":["anterior","medial","inferior","lateral"],"a":2,"e":"Checked answer, not from an official key. Chapter 14 says the inferior vena cava brings blood from the lower parts of the body. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The right and left renal arteries supply blood to the ____________________________.","o":["kidneys","stomach","bladder","heart"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the right and left renal arteries go to the kidneys. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Inadequate blood flow can cause an _______________________, an area of damaged cardiac tissue.","o":["intercostal","anastomoses","infarct","embolus"],"a":2,"e":"Checked answer, not from an official key. Chapter 14 says inadequate blood flow can cause an infarct, an area of damaged cardiac tissue. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The heart is situated in the _______________________________, surrounded by the pericardial sac.","o":["peritoneum","mediastinum","pleura","myocardium"],"a":1,"e":"Checked answer, not from an official key. Chapter 14 says the heart is positioned between the lungs in the mediastinum. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The pulmonary semilunar valve is found in the right ventricle.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 places the pulmonary semilunar valve at the opening where the pulmonary trunk leaves the right ventricle. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The left ventricle has walls that are thicker than the right ventricle.","o":["True","False"],"a":0,"e":"Checked answer, not from an official key. Chapter 14 says the left ventricle’s walls are thicker than the right ventricle’s. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"Systole is the term used to refer to the phase of relaxation.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. Systole is contraction. Diastole is relaxation. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The atrioventricular node is known as the pacemaker.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The sinoatrial (SA) node is the pacemaker, not the AV node. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."},{"q":"The outermost layer of the pericardial sac is the serous pericardium.","o":["True","False"],"a":1,"e":"Checked answer, not from an official key. The outermost layer of the pericardial sac is the fibrous pericardium. The serous pericardium is the inner layer. Source: Fundamentals of Anatomy and Physiology (Rizzo), Chapter 14."}],"caseStudy":{"title":"A number, a symptom, and two different priorities","scenario":"A client wants nutrition advice after a home blood-pressure reading. During the conversation they also mention new chest pressure while climbing stairs. They ask whether simply avoiding salt for a week will settle both concerns.","prompts":["Which information belongs to long-term cardiovascular risk education?","Why can one home reading not define the mechanism?","Which symptom changes the priority of the conversation?","How can you state the nutrition role without delaying appropriate assessment?"],"takeaway":"Nutrition can support long-term cardiovascular health, but new exertional chest pressure requires prompt medical assessment. Do not let risk-factor counselling become a substitute for symptom triage."},"perStepChapter":true},{"n":15,"title":"The Lymphatic Circulatory System","kicker":"Explain how lymphatic vessels return interstitial fluid and absorbed lipids to circulation.","duration":"75–95 minutes","steps":[{"id":"l15-m1","chapter":"Follow fluid back to blood","chapterSummary":"Understand one-way lymph flow, vessel design, and intestinal lipid transport.","title":"Lymph begins as interstitial fluid","highYield":"The lymphatic system returns excess tissue fluid and proteins that blood capillaries do not directly recover.","teach":["Fluid filters from blood capillaries into the interstitial space, where it supports exchange with cells. Most returns locally to blood, while a portion enters blind-ended lymphatic capillaries. Once inside the lymphatic network, the fluid is called lymph.","Lymphatic capillaries have overlapping endothelial flaps that open when tissue pressure rises. Larger vessels contain valves and ultimately return lymph to large veins near the base of the neck. If filtration, return, or drainage becomes unbalanced, fluid can accumulate in tissues, but the cause cannot be identified from swelling alone."],"keyPoints":["Interstitial fluid becomes lymph after entering lymphatic capillaries.","Lymph flow is one-way toward the venous circulation.","Valves limit backflow.","Edema reflects a fluid-balance problem, not one single diagnosis."],"visual":{"title":"Fluid recovery loop","kind":"flow","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]},"mnemonic":{"title":"Filter–Feed–Fetch–Flow back","cue":"FFFF","explanation":"Blood filters, tissue fluid feeds cells, lymphatics fetch excess, and lymph flows back to veins."},"goodToKnow":"The lymphatic circulation has no single central pump equivalent to the heart.","act":{"type":"choice","prompt":"When does interstitial fluid become lymph?","options":[{"label":"After it enters a lymphatic capillary","correct":true,"feedback":"Correct. Location within the lymphatic vessel defines lymph."},{"label":"As soon as plasma leaves the heart","correct":false,"feedback":"Fluid becomes interstitial after capillary filtration and lymph only after lymphatic entry."},{"label":"Only after passing through the spleen","correct":false,"feedback":"Lymph is present throughout lymphatic vessels before any organ encounter."}]}},{"id":"l15-m2","chapter":null,"chapterSummary":null,"title":"Movement depends on valves and body motion","highYield":"Skeletal-muscle contraction, breathing, smooth muscle, and valves move lymph through a low-pressure system.","teach":["Lymphatic vessels resemble thin-walled veins but begin as capillaries in tissues. Contraction of surrounding skeletal muscle compresses them, pressure changes during breathing draw lymph toward the thorax, and smooth muscle in larger vessel walls contributes rhythmic propulsion.","Valves segment the pathway so each compression tends to move fluid centrally. The right lymphatic duct drains part of the upper body, while the thoracic duct drains most remaining regions. Both empty into venous circulation near the junctions of internal jugular and subclavian veins."],"keyPoints":["Lymph flow is low pressure.","Muscle and respiratory pumps assist movement.","The thoracic duct drains most of the body.","Ducts return lymph to venous blood."],"visual":{"title":"What moves lymph?","kind":"map","items":[{"label":"Skeletal-muscle pump","detail":"External compression of vessels"},{"label":"Respiratory pump","detail":"Thoracic pressure changes during breathing"},{"label":"Vessel smooth muscle","detail":"Intrinsic contraction in larger vessels"},{"label":"Valves","detail":"Limit reverse flow"}]},"mnemonic":{"title":"Move–Breathe–Valve","cue":"MBV","explanation":"Movement and breathing provide pressure; valves preserve direction."},"goodToKnow":"Being still does not stop all lymph flow, but ordinary movement contributes to its efficiency.","act":{"type":"choice","prompt":"Which feature most directly prevents lymph from moving backward after a vessel is compressed?","options":[{"label":"Valves","correct":true,"feedback":"Correct. Valves create one-way segments."},{"label":"Erythrocytes","correct":false,"feedback":"Lymph normally contains few or no erythrocytes."},{"label":"Gastric acid","correct":false,"feedback":"Gastric acid has no role in lymphatic valve function."}]}},{"id":"circulation-order","title":"Put it in order: Fluid recovery loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Blood capillary","detail":"Filters fluid into tissue"},{"label":"Interstitial space","detail":"Exchange environment around cells"},{"label":"Lymphatic capillary","detail":"Collects excess fluid and proteins"},{"label":"Lymphatic ducts","detail":"Return lymph to large veins"}]}},{"id":"circulation-match","title":"Match it: What moves lymph?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["External compression of vessels","Thoracic pressure changes during breathing","Intrinsic contraction in larger vessels","Limit reverse flow"],"items":[{"label":"Valves","category":3,"feedback":"Valves: Limit reverse flow"},{"label":"Vessel smooth muscle","category":2,"feedback":"Vessel smooth muscle: Intrinsic contraction in larger vessels"},{"label":"Respiratory pump","category":1,"feedback":"Respiratory pump: Thoracic pressure changes during breathing"},{"label":"Skeletal-muscle pump","category":0,"feedback":"Skeletal-muscle pump: External compression of vessels"}]}},{"id":"l15-m3","chapter":"Map lymphatic organs","chapterSummary":"Separate filtration of lymph, filtration of blood, immune-cell maturation, and mucosal surveillance.","title":"Nodes filter lymph and organize responses","highYield":"Lymph nodes sample lymph, house immune cells, and slow flow so antigens and cells can interact.","teach":["A lymph node receives lymph through multiple afferent vessels and releases it through fewer efferent vessels at the hilum. Its capsule and internal sinuses channel flow through regions rich in macrophages, B cells, T cells, and antigen-presenting cells.","Nodes enlarge for many reasons, including immune-cell activation, increased traffic, infection, and malignancy. Tenderness, location, duration, and associated symptoms matter. A palpable node is an observation—not enough information to label the cause."],"keyPoints":["Afferent vessels enter; efferent vessels exit.","Nodes filter lymph, not blood.","Cortex and deeper regions organize immune cells.","Node enlargement has multiple possible causes."],"visual":{"title":"Through a lymph node","kind":"flow","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]},"mnemonic":{"title":"A arrives, E exits","cue":"Afferent arrives · Efferent exits","explanation":"Use the first letters to keep vessel direction straight."},"goodToKnow":"Cancer cells may travel through lymph and be found in nodes, but node enlargement is not synonymous with cancer.","act":{"type":"choice","prompt":"Which statement correctly distinguishes lymph nodes from the spleen?","options":[{"label":"Nodes filter lymph; the spleen filters blood","correct":true,"feedback":"Correct. Their fluid pathways differ."},{"label":"Nodes pump blood; the spleen produces bile","correct":false,"feedback":"Neither statement describes their primary roles."},{"label":"Nodes mature erythrocytes; the spleen filters air","correct":false,"feedback":"Erythrocytes mature in marrow and air is filtered in the respiratory tract."}]}},{"id":"l15-m4","chapter":null,"chapterSummary":null,"title":"Spleen, thymus, and tonsils occupy different checkpoints","highYield":"Spleen monitors blood, thymus supports T-cell maturation, and tonsils sample material at the pharyngeal entrance.","teach":["The spleen's white pulp supports immune surveillance of blood-borne antigens, while red pulp removes aged or damaged erythrocytes and stores some platelets. Unlike a lymph node, the spleen is connected directly to blood circulation rather than positioned in a chain of lymphatic vessels.","The thymus provides an environment for T-cell maturation and is most active earlier in life. Tonsils and other mucosa-associated lymphoid tissues sample material near respiratory and digestive entry points. Each structure contributes to defence from a different anatomical location."],"keyPoints":["Spleen filters blood and recycles erythrocyte components.","Thymus supports T-cell maturation.","Tonsils survey the pharyngeal region.","Lymphatic organs are not interchangeable."],"visual":{"title":"Organ checkpoints","kind":"comparison","items":[{"label":"Lymph node","detail":"Samples lymph from tissues"},{"label":"Spleen","detail":"Samples blood and removes old erythrocytes"},{"label":"Thymus","detail":"Supports T-cell maturation"},{"label":"Tonsils/MALT","detail":"Monitor mucosal entry sites"}]},"mnemonic":{"title":"Node–Blood–T–Throat","cue":"Node filters lymph · spleen filters blood · thymus trains T cells · tonsils watch throat","explanation":"The location hints at the job."},"goodToKnow":"The thymus becomes less prominent after puberty but does not simply vanish or make adult immunity impossible.","act":{"type":"choice","prompt":"Which organ removes many aged erythrocytes from blood?","options":[{"label":"Spleen","correct":true,"feedback":"Correct. Red pulp participates in erythrocyte removal and recycling."},{"label":"Thymus","correct":false,"feedback":"The thymus is primarily associated with T-cell maturation."},{"label":"Tonsil","correct":false,"feedback":"Tonsils are mucosal immune tissues near the pharynx."}]}},{"id":"organs-order","title":"Put it in order: Through a lymph node","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Afferent vessels","detail":"Bring lymph into the capsule"},{"label":"Sinuses","detail":"Slow and channel flow"},{"label":"Immune zones","detail":"Support B-cell, T-cell, and macrophage interactions"},{"label":"Efferent vessel","detail":"Carries filtered lymph away"}]}},{"id":"organs-match","title":"Match it: Organ checkpoints","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Samples lymph from tissues","Samples blood and removes old erythrocytes","Supports T-cell maturation","Monitor mucosal entry sites"],"items":[{"label":"Tonsils/MALT","category":3,"feedback":"Tonsils/MALT: Monitor mucosal entry sites"},{"label":"Thymus","category":2,"feedback":"Thymus: Supports T-cell maturation"},{"label":"Spleen","category":1,"feedback":"Spleen: Samples blood and removes old erythrocytes"},{"label":"Lymph node","category":0,"feedback":"Lymph node: Samples lymph from tissues"}]}},{"id":"l15-m5","chapter":"Layer innate and adaptive defence","chapterSummary":"Understand barriers, inflammation, antigen recognition, and lymphocyte specialization.","title":"Innate defence responds quickly to patterns","highYield":"Barriers, phagocytes, complement, inflammation, and fever act without needing prior exposure to one exact antigen.","teach":["Innate defence includes intact skin and mucosa, antimicrobial secretions, resident and recruited phagocytes, natural killer cells, complement proteins, and inflammatory signals. These components recognize broad features of damage or microbes and respond rapidly.","Inflammation increases local blood flow and vessel permeability while recruiting cells and proteins. This can support containment and repair, but excessive or misplaced inflammation can damage tissue. 'Inflammation' is therefore a process, not a universal diagnosis or a food morality label."],"keyPoints":["Barriers are first-line defences.","Innate recognition is pattern-based.","Inflammation recruits cells and proteins.","Fever and inflammation are regulated responses with possible costs."],"visual":{"title":"Innate defence layers","kind":"layers","items":[{"label":"Barrier","detail":"Skin, mucosa, secretions"},{"label":"Recognition","detail":"Cells detect common danger patterns"},{"label":"Response","detail":"Phagocytosis, complement, inflammation"},{"label":"Resolution","detail":"Signals limit response and support repair"}]},"mnemonic":{"title":"B-R-R-R","cue":"Barrier · Recognize · Respond · Resolve","explanation":"A healthy defence response must eventually resolve."},"goodToKnow":"A marker of inflammation can rise for many reasons and does not identify a specific food trigger by itself.","act":{"type":"choice","prompt":"Which is an innate defence?","options":[{"label":"A skin barrier and rapid phagocyte response","correct":true,"feedback":"Correct. These act broadly without requiring antigen-specific memory."},{"label":"A highly specific memory B-cell response after vaccination","correct":false,"feedback":"That is adaptive immunity."},{"label":"ABO compatibility testing","correct":false,"feedback":"That is a transfusion-safety process, not an innate defence."}]}},{"id":"l15-m6","chapter":null,"chapterSummary":null,"title":"Adaptive immunity adds specificity and memory","highYield":"B and T lymphocytes recognize specific antigens, expand selected clones, and can leave memory cells.","teach":["Adaptive responses begin when lymphocytes with matching receptors encounter antigen in the right signalling context. Clonal expansion creates many related cells. B cells can differentiate into plasma cells that secrete antibodies, while memory B cells support faster future responses.","T-cell populations perform different work: helper T cells coordinate responses, cytotoxic T cells kill selected infected or abnormal cells, and regulatory T cells help limit inappropriate activation. Antibodies act outside cells; cytotoxic T cells inspect cellular antigen presentation. Both arms cooperate with innate defence."],"keyPoints":["Adaptive recognition is antigen-specific.","B cells can produce antibody-secreting plasma cells.","T cells coordinate, kill, or regulate.","Memory changes a later response."],"visual":{"title":"Two adaptive arms","kind":"comparison","items":[{"label":"Humoral","detail":"B cells and antibodies act in extracellular spaces"},{"label":"Cell-mediated","detail":"T cells coordinate or act on selected cells"},{"label":"Memory","detail":"Long-lived cells support faster later response"},{"label":"Cooperation","detail":"Innate signals help activate and shape adaptive responses"}]},"mnemonic":{"title":"B = antibodies, T = tasks in tissues","cue":"B builds antibodies · T targets and tunes","explanation":"A study cue, not a complete catalogue of lymphocyte biology."},"goodToKnow":"Antibodies can neutralize, tag, or activate other defence mechanisms; they do not directly 'eat' microbes.","act":{"type":"choice","prompt":"Which cell directly secretes large amounts of antibody?","options":[{"label":"A plasma cell derived from a B lymphocyte","correct":true,"feedback":"Correct. Plasma cells are specialized antibody secretors."},{"label":"An erythrocyte","correct":false,"feedback":"Erythrocytes transport gases."},{"label":"A platelet","correct":false,"feedback":"Platelets function mainly in hemostasis and repair signalling."}]}},{"id":"immunity-match","title":"Match it: Innate defence layers","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Skin, mucosa, secretions","Cells detect common danger patterns","Phagocytosis, complement, inflammation","Signals limit response and support repair"],"items":[{"label":"Resolution","category":3,"feedback":"Resolution: Signals limit response and support repair"},{"label":"Response","category":2,"feedback":"Response: Phagocytosis, complement, inflammation"},{"label":"Recognition","category":1,"feedback":"Recognition: Cells detect common danger patterns"},{"label":"Barrier","category":0,"feedback":"Barrier: Skin, mucosa, secretions"}]}},{"id":"l15-m7","chapter":"Compare acquired protection","chapterSummary":"Distinguish active and passive immunity, antigen–antibody binding, and safe practice boundaries.","title":"Active and passive immunity differ in who makes the antibody","highYield":"Active immunity develops after your immune system responds; passive immunity transfers ready-made antibodies.","teach":["Active immunity follows infection or vaccination and requires the recipient's lymphocytes to respond. It takes time to develop but can create memory. Passive immunity provides antibodies made elsewhere, such as maternal antibodies transferred across the placenta or an administered antibody product.","Passive protection can act quickly but is temporary because the recipient did not create the memory response. Natural and artificial describe how exposure occurs, while active and passive describe who produced the protective antibodies. Keep these two classification axes separate."],"keyPoints":["Active immunity can form memory.","Passive immunity transfers antibody.","Passive protection is relatively immediate and temporary.","Natural/artificial and active/passive answer different questions."],"visual":{"title":"Four acquisition routes","kind":"comparison","items":[{"label":"Natural active","detail":"Immune response after infection"},{"label":"Artificial active","detail":"Immune response after vaccination"},{"label":"Natural passive","detail":"Maternal antibody transfer"},{"label":"Artificial passive","detail":"Administered antibody preparation"}]},"mnemonic":{"title":"Active acts; passive passes","cue":"Act to make · Pass ready-made","explanation":"Active means the recipient's immune system produces the response."},"goodToKnow":"Vaccination does not guarantee identical protection in every person, but it trains adaptive recognition without requiring the full disease experience.","act":{"type":"choice","prompt":"Which example is natural passive immunity?","options":[{"label":"Maternal IgG crossing the placenta","correct":true,"feedback":"Correct. Ready-made antibody is naturally transferred."},{"label":"Memory after recovering from infection","correct":false,"feedback":"That is natural active immunity."},{"label":"Antibody production after vaccination","correct":false,"feedback":"That is artificial active immunity."}]}},{"id":"l15-m8","chapter":null,"chapterSummary":null,"title":"Antigen–antibody binding is precise but not sufficient alone","highYield":"Antibodies bind particular molecular features and then recruit or block other processes.","teach":["An antigen contains molecular regions called epitopes. An antibody's binding site fits a particular epitope closely enough to bind. This specificity explains why one antibody does not recognize every pathogen and why cross-reactivity can occur when structures are similar.","Binding can neutralize a toxin or virus, mark a target for phagocytosis, clump particles, or activate complement. Outcome depends on the antibody class, location, target, and other immune components. A positive antibody result may reflect past exposure, vaccination, current response, or cross-reactivity; interpretation needs context."],"keyPoints":["Epitopes are recognized portions of antigens.","Antibody specificity is selective, not absolute.","Binding recruits additional mechanisms.","An antibody test is contextual evidence."],"visual":{"title":"What antibody binding can do","kind":"map","items":[{"label":"Neutralize","detail":"Block a target from attaching or acting"},{"label":"Opsonize","detail":"Tag a target for phagocytes"},{"label":"Agglutinate","detail":"Cross-link particles"},{"label":"Activate complement","detail":"Trigger a protein cascade"}]},"mnemonic":{"title":"NOAC","cue":"Neutralize · Opsonize · Agglutinate · Complement","explanation":"Four common consequences of antibody binding."},"goodToKnow":"Allergy is an immune response to a usually harmless substance; it is not evidence that the immune system is simply 'weak.'","act":{"type":"choice","prompt":"What is an epitope?","options":[{"label":"A specific region of an antigen recognized by an immune receptor or antibody","correct":true,"feedback":"Correct. Recognition occurs at particular molecular features."},{"label":"The fluid inside a lymphatic vessel","correct":false,"feedback":"That fluid is lymph."},{"label":"A valve in a vein","correct":false,"feedback":"A valve directs fluid flow and is unrelated to antigen recognition."}]}},{"id":"memory-match","title":"Match it: Four acquisition routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Immune response after infection","Immune response after vaccination","Maternal antibody transfer","Administered antibody preparation"],"items":[{"label":"Artificial passive","category":3,"feedback":"Artificial passive: Administered antibody preparation"},{"label":"Natural passive","category":2,"feedback":"Natural passive: Maternal antibody transfer"},{"label":"Artificial active","category":1,"feedback":"Artificial active: Immune response after vaccination"},{"label":"Natural active","category":0,"feedback":"Natural active: Immune response after infection"}]}}],"flashcards":[{"front":"Lymph","back":"Interstitial fluid after it enters lymphatic vessels."},{"front":"Thoracic duct","back":"The major lymphatic duct draining most of the body into venous circulation."},{"front":"Lacteal","back":"A lymphatic capillary in an intestinal villus that absorbs dietary lipids packaged as chylomicrons."},{"front":"Afferent lymphatic","back":"A vessel carrying lymph into a node."},{"front":"Efferent lymphatic","back":"A vessel carrying lymph away from a node."},{"front":"Spleen","back":"A lymphatic organ that filters blood and removes many aged erythrocytes."},{"front":"Thymus","back":"An organ supporting T-cell maturation, especially early in life."},{"front":"Innate immunity","back":"Rapid pattern-based defence including barriers, phagocytes, inflammation, and complement."},{"front":"Humoral immunity","back":"Adaptive defence mediated primarily by B cells and antibodies."},{"front":"Cell-mediated immunity","back":"Adaptive defence involving T-cell coordination and action on selected cells."},{"front":"Active immunity","back":"Protection generated by the recipient's own immune response, often with memory."},{"front":"Passive immunity","back":"Temporary protection from transferred ready-made antibodies."}],"quiz":[],"caseStudy":{"title":"A persistent neck lump and an 'immune-boosting' plan","scenario":"A client has noticed an enlarging neck lump for several weeks and asks which supplement will 'drain the lymph' and strengthen immunity. They have not sought medical assessment.","prompts":["What can and cannot be inferred from a palpable node?","Which duration and change details make follow-up important?","How would you explain the role of a lymph node without diagnosing the cause?","What supportive nutrition conversation can occur without delaying assessment?"],"takeaway":"Lymph nodes enlarge for multiple reasons. Explain the mechanism, avoid supplement promises, and encourage appropriate clinical assessment of a persistent or enlarging lump."}},{"n":16,"title":"Nutrition and the Digestive System","kicker":"Trace food through the alimentary canal and identify accessory-organ contributions.","duration":"90–110 minutes","steps":[{"id":"l16-m1","chapter":"Orient to the digestive tube","chapterSummary":"Build the wall layers, movement pattern, and oral phase before following individual nutrients.","title":"One continuous tube, four repeating wall layers","highYield":"Mucosa handles contact and absorption; submucosa supports; muscularis moves; serosa/adventitia anchors or reduces friction.","teach":["The alimentary canal runs from mouth to anus. Although each region is specialized, much of the tube follows a four-layer plan: mucosa, submucosa, muscularis externa, and an outer serosa or adventitia. The mucosa includes epithelium, connective tissue, and a thin muscle layer; its surface changes according to function.","The submucosa carries vessels, glands, and nerve networks. Circular and longitudinal smooth muscle in the muscularis mix and propel contents. Enteric nerve plexuses coordinate local activity while autonomic and hormonal signals modify it. Digestion is therefore mechanical, chemical, and regulatory at the same time."],"keyPoints":["Mucosa faces the lumen.","Submucosa supports vessels, glands, and nerves.","Muscularis mixes and propels.","Serosa reduces friction; adventitia anchors some regions."],"visual":{"title":"GI wall from lumen outward","kind":"layers","items":[{"label":"Mucosa","detail":"Secretion, protection, absorption"},{"label":"Submucosa","detail":"Vessels, glands, connective support, nerve plexus"},{"label":"Muscularis externa","detail":"Circular and longitudinal movement"},{"label":"Serosa/adventitia","detail":"Outer covering or attachment"}]},"mnemonic":{"title":"M-S-M-S","cue":"Mucosa · Submucosa · Muscularis · Serosa","explanation":"Move from the lumen outward; substitute adventitia where the organ is anchored."},"goodToKnow":"The enteric nervous system can coordinate local reflexes, but it still communicates with the central nervous and endocrine systems.","act":{"type":"choice","prompt":"Which layer directly contacts material in the intestinal lumen?","options":[{"label":"Mucosa","correct":true,"feedback":"Correct. Its epithelium forms the luminal surface."},{"label":"Muscularis externa","correct":false,"feedback":"The muscularis lies deeper and produces movement."},{"label":"Serosa","correct":false,"feedback":"The serosa is an outer covering."}]}},{"id":"l16-m2","chapter":null,"chapterSummary":null,"title":"The mouth begins both processing and decision-making","highYield":"Chewing, saliva, tongue movement, and swallowing prepare a manageable bolus; digestion does not begin in the stomach.","teach":["Teeth mechanically reduce food size, increasing surface area. The tongue positions food, contributes to taste, and forms a bolus. Saliva moistens and lubricates, buffers the oral environment, and contains enzymes that begin starch and some lipid processing, although most digestion occurs later.","Swallowing begins voluntarily and then becomes a coordinated reflex moving the bolus through pharynx and esophagus. Peristaltic waves propel it toward the stomach while sphincters help direct flow. Chewing time or saliva alone cannot determine nutrient absorption, but oral function can strongly affect what a person can comfortably eat."],"keyPoints":["Mastication increases surface area.","Saliva lubricates and begins chemical digestion.","The tongue forms and positions the bolus.","Swallowing changes from voluntary to reflex control."],"visual":{"title":"Oral-to-esophageal sequence","kind":"sequence","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]},"mnemonic":{"title":"CMFSP","cue":"Chew · Moisten · Form · Swallow · Propel","explanation":"A five-step oral and esophageal route."},"goodToKnow":"Salivary amylase starts starch digestion but is not responsible for completing carbohydrate digestion.","act":{"type":"choice","prompt":"What is the main immediate benefit of chewing for digestion?","options":[{"label":"It reduces particle size and increases surface area","correct":true,"feedback":"Correct. This improves contact with fluids and enzymes."},{"label":"It absorbs all nutrients through the teeth","correct":false,"feedback":"Teeth mechanically process food; they do not absorb nutrients."},{"label":"It converts protein directly into glucose","correct":false,"feedback":"Protein digestion requires enzymatic steps in the stomach and small intestine."}]}},{"id":"organization-order","title":"Put it in order: Oral-to-esophageal sequence","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Chew","detail":"Mechanical breakdown"},{"label":"Moisten","detail":"Saliva lubricates and buffers"},{"label":"Form bolus","detail":"Tongue organizes material"},{"label":"Swallow","detail":"Pharyngeal reflex protects airway and directs bolus"},{"label":"Peristalsis","detail":"Esophagus propels toward stomach"}]}},{"id":"organization-match","title":"Match it: GI wall from lumen outward","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Secretion, protection, absorption","Vessels, glands, connective support, nerve plexus","Circular and longitudinal movement","Outer covering or attachment"],"items":[{"label":"Serosa/adventitia","category":3,"feedback":"Serosa/adventitia: Outer covering or attachment"},{"label":"Muscularis externa","category":2,"feedback":"Muscularis externa: Circular and longitudinal movement"},{"label":"Submucosa","category":1,"feedback":"Submucosa: Vessels, glands, connective support, nerve plexus"},{"label":"Mucosa","category":0,"feedback":"Mucosa: Secretion, protection, absorption"}]}},{"id":"l16-m3","chapter":"Coordinate stomach and accessory organs","chapterSummary":"Separate storage, acid and enzymes, pancreatic secretion, bile, and liver processing.","title":"The stomach stores, mixes, acidifies, and meters","highYield":"The stomach begins substantial protein digestion and delivers chyme gradually; it is not the main nutrient-absorption site.","teach":["The stomach's folds allow expansion while muscular layers churn food into chyme. Parietal cells secrete hydrochloric acid and intrinsic factor, chief cells release pepsinogen, and mucous cells help protect the lining. Acid denatures proteins and activates pepsin, while intrinsic factor later supports vitamin B12 absorption in the ileum.","Pyloric control meters chyme into the duodenum. Emptying rate changes with meal composition, particle size, and regulatory signals. Fat and high energy density often slow emptying, but individual symptoms are not a direct readout of one nutrient or of stomach acid level."],"keyPoints":["Acid denatures protein and activates pepsin.","Intrinsic factor is required for normal B12 absorption.","Mucus and bicarbonate protect the stomach lining.","The pylorus regulates delivery to duodenum."],"visual":{"title":"Gastric cell roles","kind":"comparison","items":[{"label":"Parietal cell","detail":"Hydrochloric acid and intrinsic factor"},{"label":"Chief cell","detail":"Pepsinogen precursor"},{"label":"Mucous cell","detail":"Protective mucus and local buffering"},{"label":"Muscle layers","detail":"Mix chyme and support emptying"}]},"mnemonic":{"title":"A-I-P-M","cue":"Acid · Intrinsic factor · Pepsin · Mucus","explanation":"Four gastric products/functions to keep distinct."},"goodToKnow":"Very little macronutrient absorption occurs in the stomach; most absorption occurs in the small intestine.","act":{"type":"choice","prompt":"Which stomach product is essential for efficient vitamin B12 absorption later in the ileum?","options":[{"label":"Intrinsic factor","correct":true,"feedback":"Correct. B12 binds intrinsic factor before receptor-mediated absorption."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and aids lipid handling."},{"label":"Insulin","correct":false,"feedback":"Insulin is an endocrine pancreatic hormone, not a gastric product."}]}},{"id":"l16-m4","chapter":null,"chapterSummary":null,"title":"Pancreas, liver, and gallbladder deliver complementary support","highYield":"Pancreas supplies bicarbonate and enzymes; liver makes bile and processes portal blood; gallbladder stores and concentrates bile.","teach":["The exocrine pancreas delivers bicarbonate to neutralize acidic chyme and enzymes that digest carbohydrate, protein, fat, and nucleic acids. Its endocrine islets release hormones such as insulin and glucagon into blood. Exocrine and endocrine functions share an organ but use different ducts and destinations.","The liver produces bile, processes portal nutrients, stores selected fuels and vitamins, synthesizes many plasma proteins, and modifies wastes and chemicals. The gallbladder stores and concentrates bile, then releases it when signalled. Bile emulsifies fat into smaller droplets; it is not a digestive enzyme and does not chemically split triglycerides."],"keyPoints":["Pancreatic bicarbonate raises duodenal pH.","Pancreatic enzymes act on all major nutrient classes.","Liver produces bile; gallbladder stores it.","Bile emulsifies rather than hydrolyzes fat."],"visual":{"title":"Accessory-organ teamwork","kind":"map","items":[{"label":"Pancreas","detail":"Bicarbonate plus digestive enzymes"},{"label":"Liver","detail":"Bile production and portal processing"},{"label":"Gallbladder","detail":"Bile storage and concentration"},{"label":"Duodenum","detail":"Receives chyme, bile, and pancreatic secretion"}]},"mnemonic":{"title":"PBLG","cue":"Pancreas breaks · Bile bundles · Liver generates · Gallbladder holds","explanation":"A compact cue; remember enzymes break bonds while bile disperses fat."},"goodToKnow":"A person can live without a gallbladder because the liver still produces bile, though delivery becomes less concentrated and less meal-timed.","act":{"type":"choice","prompt":"Which statement about bile is accurate?","options":[{"label":"It emulsifies fat, increasing surface area for lipase","correct":true,"feedback":"Correct. Bile disperses fat droplets but does not hydrolyze triglycerides itself."},{"label":"It is a protease secreted by the stomach","correct":false,"feedback":"Bile is not an enzyme and is produced by the liver."},{"label":"It transports oxygen in red blood cells","correct":false,"feedback":"Hemoglobin performs that role."}]}},{"id":"upper-organs-match","title":"Match it: Gastric cell roles","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hydrochloric acid and intrinsic factor","Pepsinogen precursor","Protective mucus and local buffering","Mix chyme and support emptying"],"items":[{"label":"Muscle layers","category":3,"feedback":"Muscle layers: Mix chyme and support emptying"},{"label":"Mucous cell","category":2,"feedback":"Mucous cell: Protective mucus and local buffering"},{"label":"Chief cell","category":1,"feedback":"Chief cell: Pepsinogen precursor"},{"label":"Parietal cell","category":0,"feedback":"Parietal cell: Hydrochloric acid and intrinsic factor"}]}},{"id":"l16-m5","chapter":"Digest and absorb","chapterSummary":"Use small-intestinal surface area and colon function to explain nutrient and fluid handling.","title":"The small intestine completes digestion and captures nutrients","highYield":"Folds, villi, and microvilli create a large absorptive surface supplied by blood capillaries and lacteals.","teach":["The duodenum receives chyme, bile, and pancreatic secretion; the jejunum is a major site of absorption; and the ileum completes absorption of selected substances, including the intrinsic-factor–B12 complex and recycled bile salts. Segmentation mixes contents while peristalsis advances them.","Circular folds, villi, and microvilli multiply surface area. Monosaccharides, amino acids, and many water-soluble products enter blood capillaries and travel through the hepatic portal vein. Long-chain lipids are rebuilt into triglycerides, packaged into chylomicrons, and enter lacteals before reaching blood."],"keyPoints":["Duodenum coordinates neutralization and digestion.","Villi and microvilli expand surface area.","Water-soluble nutrients generally enter portal blood.","Chylomicrons generally enter lymphatic lacteals."],"visual":{"title":"Two absorption routes","kind":"comparison","items":[{"label":"Blood capillary route","detail":"Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","detail":"Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","detail":"B12–intrinsic factor complex and bile-salt recovery"}]},"mnemonic":{"title":"Sugar and amino acids sail portal; fat floats lymph","cue":"Portal for soluble · lymph for chylomicrons","explanation":"A useful general pattern with exceptions for some shorter fatty acids."},"goodToKnow":"Absorption is selective and transporter-dependent; eating a nutrient does not guarantee identical absorption in every context.","act":{"type":"choice","prompt":"Where do most long-chain dietary lipids go immediately after absorption?","options":[{"label":"Into chylomicrons that enter intestinal lacteals","correct":true,"feedback":"Correct. They travel through lymph before venous blood."},{"label":"Directly into the aorta as free triglycerides","correct":false,"feedback":"They are packaged in enterocytes and enter lymph first."},{"label":"Into the urinary bladder","correct":false,"feedback":"The urinary tract is not an absorption route for dietary lipid."}]}},{"id":"l16-m6","chapter":null,"chapterSummary":null,"title":"The large intestine recovers fluid and forms stool","highYield":"The colon reabsorbs water and electrolytes, houses microbes, compacts contents, and coordinates elimination.","teach":["Material entering the large intestine contains water, electrolytes, undigested components, microbes, shed cells, and secretions. The colon absorbs much of the remaining water and electrolytes, secretes mucus, and moves contents through haustral mixing and mass movements toward the rectum.","Colonic microbes ferment selected carbohydrates and produce metabolites, including short-chain fatty acids, while also contributing to some vitamin production. Microbiome composition varies widely; one stool pattern cannot define a 'healthy microbiome,' and broad claims about cleansing or toxins are not supported by colon anatomy."],"keyPoints":["Colon recovers water and electrolytes.","Mucus supports passage.","Microbes ferment selected substrates.","Rectal filling participates in the defecation reflex."],"visual":{"title":"Colon functions","kind":"map","items":[{"label":"Recover","detail":"Water and electrolytes"},{"label":"Ferment","detail":"Microbial use of selected carbohydrates"},{"label":"Compact","detail":"Formation of fecal material"},{"label":"Propel","detail":"Movement toward rectum and elimination"}]},"mnemonic":{"title":"RFCP","cue":"Recover · Ferment · Compact · Propel","explanation":"Four colon functions without calling it a waste-storage tube only."},"goodToKnow":"Stool frequency varies; a change from a person's usual pattern plus symptoms is often more informative than one universal number.","act":{"type":"choice","prompt":"Which is a major function of the large intestine?","options":[{"label":"Recovery of water and electrolytes","correct":true,"feedback":"Correct. The colon helps conserve fluid while forming stool."},{"label":"Production of pancreatic enzymes","correct":false,"feedback":"Those enzymes come from the pancreas."},{"label":"Most amino-acid absorption","correct":false,"feedback":"Most nutrient absorption occurs in the small intestine."}]}},{"id":"intestinal-match","title":"Match it: Two absorption routes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein","Chylomicrons containing long-chain dietary lipid → lymph → venous blood","B12–intrinsic factor complex and bile-salt recovery"],"items":[{"label":"Blood capillary route","category":0,"feedback":"Blood capillary route: Monosaccharides, amino acids, many minerals and water-soluble vitamins → portal vein"},{"label":"Lacteal route","category":1,"feedback":"Lacteal route: Chylomicrons containing long-chain dietary lipid → lymph → venous blood"},{"label":"Ileal specialities","category":2,"feedback":"Ileal specialities: B12–intrinsic factor complex and bile-salt recovery"}]}},{"id":"l16-m7","chapter":"Connect foods to pathways","chapterSummary":"Follow macronutrient digestion and use a scoped, evidence-aware nutrition lens.","title":"Each macronutrient needs a different breakdown strategy","highYield":"Carbohydrate becomes absorbable monosaccharides, protein becomes amino acids and small peptides, and triglyceride becomes lipid products before repackaging.","teach":["Starch digestion begins with amylase and is completed by pancreatic and brush-border enzymes to monosaccharides. Protein is denatured in the stomach and hydrolyzed by gastric, pancreatic, and brush-border proteases into amino acids and small peptides. These products use specific transport systems to enter enterocytes and then portal blood.","Fat requires emulsification by bile and hydrolysis mainly by pancreatic lipase. Lipid products form micelles that approach the enterocyte membrane, then are absorbed, reassembled, and packaged into chylomicrons. The pathway explains why bile and pancreatic function matter without implying that dietary fat is inherently difficult or harmful."],"keyPoints":["Starch → monosaccharides.","Protein → amino acids and small peptides.","Triglycerides → fatty acids/monoglycerides → reassembly.","Transporters and packaging complete absorption."],"visual":{"title":"Macronutrient pathways","kind":"comparison","items":[{"label":"Carbohydrate","detail":"Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","detail":"Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","detail":"Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]},"mnemonic":{"title":"C-P-F: Cut, Process, Ferry","cue":"Cut bonds · Process at brush border · Ferry through blood or lymph","explanation":"Use the same logic while keeping each nutrient's products and route distinct."},"goodToKnow":"Fibre is not digested into glucose by human enzymes; fermentable fibre can be metabolized by colonic microbes.","act":{"type":"choice","prompt":"Which pairing is correct?","options":[{"label":"Bile emulsifies lipid; pancreatic lipase hydrolyzes triglyceride","correct":true,"feedback":"Correct. Physical dispersion and chemical digestion are different jobs."},{"label":"Pepsin digests starch into glucose","correct":false,"feedback":"Pepsin is a protease."},{"label":"Amylase converts protein into amino acids","correct":false,"feedback":"Amylase acts on starch."}]}},{"id":"l16-m8","chapter":null,"chapterSummary":null,"title":"Assessment separates intake, digestion, absorption, and use","highYield":"A nutrient problem can arise before eating, during digestion, at absorption, in transport, or during cellular use.","teach":["Nutritional status is not determined by intake alone. Food access and appetite affect intake; oral and GI function affect digestion; mucosal surface and transporters affect absorption; liver and circulation affect distribution; and cells must use or store what arrives. Losses and altered needs add further branches.","This pathway keeps counselling focused. Ask what the person eats, what happens after eating, how long the pattern has persisted, what medical evaluation exists, and which practical barriers matter. Avoid diagnosing malabsorption or prescribing restrictive diets from symptoms alone."],"keyPoints":["Availability precedes intake.","Digestion and absorption are distinct.","Transport and cellular use follow absorption.","Losses and needs change status."],"visual":{"title":"Nutrition status pathway","kind":"flow","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]},"mnemonic":{"title":"A-C-D-A-U","cue":"Available · Consumed · Digested · Absorbed · Used","explanation":"Locate the possible bottleneck before choosing an intervention."},"goodToKnow":"A normal-looking diet does not rule out impaired absorption, and GI symptoms do not prove malabsorption.","act":{"type":"choice","prompt":"A client eats adequate B12 but has impaired intrinsic-factor production. Which stage is most directly affected?","options":[{"label":"Absorption","correct":true,"feedback":"Correct. Intake may be adequate while ileal B12 uptake is impaired."},{"label":"Food availability","correct":false,"feedback":"The nutrient is available and consumed in this example."},{"label":"Chewing","correct":false,"feedback":"The mechanism described is not oral processing."}]}},{"id":"nutrient-integration-order","title":"Put it in order: Nutrition status pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Available","detail":"Food access and feasibility"},{"label":"Consumed","detail":"Appetite, chewing, swallowing"},{"label":"Digested","detail":"Mechanical and enzymatic breakdown"},{"label":"Absorbed","detail":"Movement across gut epithelium"},{"label":"Used/stored","detail":"Transport, metabolism, and reserves"}]}},{"id":"nutrient-integration-match","title":"Match it: Macronutrient pathways","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Amylases and brush-border enzymes → monosaccharides → portal blood","Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood","Bile + lipase → micelles → enterocyte → chylomicron → lymph"],"items":[{"label":"Carbohydrate","category":0,"feedback":"Carbohydrate: Amylases and brush-border enzymes → monosaccharides → portal blood"},{"label":"Protein","category":1,"feedback":"Protein: Pepsin and pancreatic/brush-border proteases → amino acids/peptides → portal blood"},{"label":"Fat","category":2,"feedback":"Fat: Bile + lipase → micelles → enterocyte → chylomicron → lymph"}]}}],"flashcards":[{"front":"Mucosa","back":"The innermost GI layer responsible for protection, secretion, and absorption."},{"front":"Peristalsis","back":"Coordinated wave-like contraction that propels contents along the digestive tract."},{"front":"Intrinsic factor","back":"A gastric protein required for efficient vitamin B12 absorption in the ileum."},{"front":"Pepsin","back":"A gastric protease activated in acidic conditions that begins protein digestion."},{"front":"Bile","back":"A liver secretion that emulsifies lipid and supports micelle formation; it is not an enzyme."},{"front":"Pancreatic bicarbonate","back":"An alkaline secretion that helps neutralize acidic chyme in the duodenum."},{"front":"Villus","back":"A projection of small-intestinal mucosa containing blood capillaries and a lacteal."},{"front":"Chylomicron","back":"A lipoprotein particle carrying absorbed long-chain dietary lipid from enterocyte into lymph."},{"front":"Hepatic portal vein","back":"Vessel delivering blood from digestive organs to the liver before systemic return."},{"front":"Segmentation","back":"Local intestinal mixing contractions that expose contents to enzymes and absorptive surfaces."},{"front":"Colon","back":"Large-intestinal region that recovers water/electrolytes, houses microbes, and compacts stool."},{"front":"Bioavailability","back":"The fraction of an ingested substance that becomes available for absorption and use, shaped by food and host factors."}],"quiz":[],"caseStudy":{"title":"A restrictive diet built from symptoms alone","scenario":"A client reports bloating, intermittent diarrhea, fatigue, and an unplanned weight change. They have removed gluten, dairy, legumes, fruit, and several vegetables after online advice, but symptoms continue. No diagnostic evaluation has occurred.","prompts":["Which stages of the nutrition-status pathway could contribute?","Which red flags or duration details should be clarified?","How might broad restriction create additional nutrition risk?","What can be documented and supported while medical assessment proceeds?"],"takeaway":"GI symptoms rarely identify one mechanism by themselves. Protect intake, document the pattern, avoid escalating unsupported restrictions, and coordinate appropriate assessment."}},{"n":17,"title":"The Respiratory System","kicker":"Trace air through conducting and respiratory zones.","duration":"75–95 minutes","steps":[{"id":"l17-m1","chapter":"Follow the conducting zone","chapterSummary":"Learn how the upper and lower airways condition air while protecting a delicate exchange surface.","title":"The upper airway warms, humidifies, filters, and senses","highYield":"The nose and pharynx prepare inspired air before it reaches the gas-exchange surface.","teach":["Air entering the nasal cavity encounters hairs, mucus, a vascular mucosa, and turbinates that create turbulence. These features trap particles and increase contact for warming and humidification. Olfactory receptors occupy a specialized superior region rather than the entire nasal lining.","The pharynx is shared by respiratory and digestive pathways. The nasopharynx carries air, while lower regions also conduct swallowed material. This shared architecture explains why coordination of swallowing, laryngeal closure, and breathing is essential for airway protection."],"keyPoints":["Nasal turbinates increase contact area.","Mucus traps particles.","Rich blood supply warms air.","The pharynx is a shared passage."],"visual":{"title":"Upper-airway tasks","kind":"map","items":[{"label":"Filter","detail":"Hair, mucus, and cilia trap material"},{"label":"Warm","detail":"Vascular mucosa transfers heat"},{"label":"Humidify","detail":"Moist surfaces add water"},{"label":"Sense","detail":"Olfactory epithelium detects odorants"}]},"mnemonic":{"title":"FWHS","cue":"Filter · Warm · Humidify · Sense","explanation":"Four functions before air reaches the larynx."},"goodToKnow":"Breathing through the mouth can bypass some nasal conditioning, but mouth breathing alone does not identify why nasal airflow is limited.","act":{"type":"choice","prompt":"What is a main function of the nasal turbinates?","options":[{"label":"Create airflow turbulence and increase mucosal contact","correct":true,"feedback":"Correct. This supports warming, humidifying, and filtering."},{"label":"Exchange oxygen directly with systemic blood","correct":false,"feedback":"Gas exchange occurs mainly in alveoli."},{"label":"Produce surfactant","correct":false,"feedback":"Alveolar type II cells produce pulmonary surfactant."}]}},{"id":"l17-m2","chapter":null,"chapterSummary":null,"title":"Larynx, trachea, and bronchi keep a route open","highYield":"Cartilage maintains airway patency while branching, smooth muscle, mucus, and cilia shape airflow and clearance.","teach":["The larynx protects the lower airway and houses the vocal folds. During swallowing, coordinated elevation and closure help direct material away from the trachea. The trachea is reinforced by C-shaped cartilage rings; its open posterior portion allows the esophagus room to expand.","The trachea branches into main bronchi, then smaller bronchi and bronchioles. Cartilage becomes less prominent with branching, while smooth muscle becomes important in controlling bronchiolar diameter. Ciliated epithelium and mucus form a clearance system that moves trapped material toward the pharynx."],"keyPoints":["Larynx supports voice and airway protection.","Tracheal cartilage limits collapse.","Bronchi branch into bronchioles.","Cilia move mucus toward the pharynx."],"visual":{"title":"Branching airway","kind":"flow","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]},"mnemonic":{"title":"L-T-B-B","cue":"Larynx · Trachea · Bronchi · Bronchioles","explanation":"Follow the branches before reaching respiratory bronchioles and alveoli."},"goodToKnow":"The right main bronchus is generally wider and more vertical, which helps explain why aspirated material often enters the right side.","act":{"type":"choice","prompt":"Why are tracheal cartilage rings C-shaped rather than complete circles?","options":[{"label":"They support the airway while allowing the esophagus behind it to expand","correct":true,"feedback":"Correct. The open posterior wall provides flexibility beside the esophagus."},{"label":"They allow blood to enter the airway","correct":false,"feedback":"Blood should remain within vessels."},{"label":"They create alveolar surfactant","correct":false,"feedback":"Surfactant is produced in alveoli, not tracheal cartilage."}]}},{"id":"airway-order","title":"Put it in order: Branching airway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Larynx","detail":"Protective gateway and voice"},{"label":"Trachea","detail":"Cartilage-supported conduit"},{"label":"Main bronchi","detail":"Enter right and left lungs"},{"label":"Bronchioles","detail":"Smooth-muscle control of small-airway radius"},{"label":"Terminal bronchioles","detail":"End of conducting zone"}]}},{"id":"airway-match","title":"Match it: Upper-airway tasks","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Hair, mucus, and cilia trap material","Vascular mucosa transfers heat","Moist surfaces add water","Olfactory epithelium detects odorants"],"items":[{"label":"Sense","category":3,"feedback":"Sense: Olfactory epithelium detects odorants"},{"label":"Humidify","category":2,"feedback":"Humidify: Moist surfaces add water"},{"label":"Warm","category":1,"feedback":"Warm: Vascular mucosa transfers heat"},{"label":"Filter","category":0,"feedback":"Filter: Hair, mucus, and cilia trap material"}]}},{"id":"l17-m3","chapter":"Reach the alveolar interface","chapterSummary":"Connect lung architecture, pleura, alveoli, and diffusion.","title":"Lungs pair branching trees with pleural mechanics","highYield":"The visceral and parietal pleura create a low-friction, pressure-coupled interface between lung and thoracic wall.","teach":["Each lung contains lobes supplied by branching bronchi, vessels, and nerves. The visceral pleura adheres to the lung surface, while parietal pleura lines the thoracic cavity. A thin fluid layer reduces friction and helps couple lung movement to changes in the chest wall.","The pleural space normally has pressure below atmospheric pressure, helping keep lungs expanded against the thoracic wall. Loss of this pressure relationship can allow lung recoil and impaired expansion. Pleural mechanics are different from airflow through bronchi and from diffusion at alveoli."],"keyPoints":["Visceral pleura covers lung.","Parietal pleura lines thorax.","Pleural fluid reduces friction.","Pressure coupling helps lungs follow chest expansion."],"visual":{"title":"Pleural relationship","kind":"layers","items":[{"label":"Thoracic wall","detail":"Moves during breathing"},{"label":"Parietal pleura","detail":"Lines the cavity"},{"label":"Pleural fluid space","detail":"Low-friction pressure coupling"},{"label":"Visceral pleura","detail":"Covers lung surface"},{"label":"Lung","detail":"Elastic tissue containing airways and alveoli"}]},"mnemonic":{"title":"Parietal = perimeter","cue":"P lines the perimeter; visceral visits the organ","explanation":"A spatial cue for the two pleural layers."},"goodToKnow":"Pleural fluid is a thin lubricating layer, not a large normal reservoir around the lungs.","act":{"type":"choice","prompt":"Which pleural layer is directly attached to the lung surface?","options":[{"label":"Visceral pleura","correct":true,"feedback":"Correct. The visceral layer follows the lung surface."},{"label":"Parietal pleura","correct":false,"feedback":"The parietal layer lines the thoracic cavity."},{"label":"Pericardium","correct":false,"feedback":"The pericardium surrounds the heart."}]}},{"id":"l17-m4","chapter":null,"chapterSummary":null,"title":"Alveoli trade distance for area","highYield":"A very thin alveolar–capillary membrane and enormous surface area support rapid diffusion.","teach":["Respiratory bronchioles lead to alveolar ducts and sacs. Alveoli are lined mainly by thin type I cells, while type II cells produce surfactant. Closely applied capillary endothelium and shared thin barriers minimize diffusion distance between air and blood.","Oxygen diffuses down its partial-pressure gradient into blood, and carbon dioxide diffuses in the opposite direction. Surfactant reduces surface tension and helps prevent small alveoli from collapsing. Efficient exchange also requires ventilation, perfusion, adequate surface area, and a thin intact membrane."],"keyPoints":["Type I cells form much of the exchange surface.","Type II cells produce surfactant.","Diffusion follows partial-pressure gradients.","Ventilation and perfusion must be reasonably matched."],"visual":{"title":"Alveolar exchange unit","kind":"layers","items":[{"label":"Alveolar air","detail":"Source of inspired oxygen"},{"label":"Type I epithelium","detail":"Thin gas-exchange surface"},{"label":"Fused basement region","detail":"Minimal diffusion distance"},{"label":"Capillary endothelium","detail":"Thin vessel wall"},{"label":"Erythrocyte","detail":"Hemoglobin binds oxygen"}]},"mnemonic":{"title":"A-T-M","cue":"Area · Thinness · Match","explanation":"Exchange needs large area, a thin membrane, and ventilation–perfusion matching."},"goodToKnow":"More ventilation does not help an alveolus that has no blood flow, and more blood flow does not help an alveolus that receives no fresh air.","act":{"type":"choice","prompt":"What is surfactant's main mechanical contribution?","options":[{"label":"It lowers alveolar surface tension","correct":true,"feedback":"Correct. This supports alveolar stability and reduces work of inflation."},{"label":"It carries oxygen through plasma","correct":false,"feedback":"Hemoglobin performs most oxygen transport."},{"label":"It contracts the diaphragm","correct":false,"feedback":"The phrenic nerves activate the diaphragm."}]}},{"id":"exchange-match","title":"Match it: Pleural relationship","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Moves during breathing","Lines the cavity","Low-friction pressure coupling","Covers lung surface","Elastic tissue containing airways and alveoli"],"items":[{"label":"Parietal pleura","category":1,"feedback":"Parietal pleura: Lines the cavity"},{"label":"Lung","category":4,"feedback":"Lung: Elastic tissue containing airways and alveoli"},{"label":"Pleural fluid space","category":2,"feedback":"Pleural fluid space: Low-friction pressure coupling"},{"label":"Thoracic wall","category":0,"feedback":"Thoracic wall: Moves during breathing"},{"label":"Visceral pleura","category":3,"feedback":"Visceral pleura: Covers lung surface"}]}},{"id":"l17-m5","chapter":"Move air and gases","chapterSummary":"Separate ventilation mechanics from exchange and transport.","title":"Inspiration follows expansion and falling pressure","highYield":"Diaphragm contraction expands thoracic volume, lowers alveolar pressure, and draws air inward.","teach":["During quiet inspiration, the diaphragm contracts and descends while external intercostal activity expands the rib cage. Greater thoracic volume lowers pressure within the lungs below atmospheric pressure, so air flows inward. Air moves because of a pressure gradient, not because lungs actively pull individual oxygen molecules.","Quiet expiration is largely passive as inspiratory muscles relax and elastic tissues recoil, raising alveolar pressure above atmospheric pressure. Forced breathing recruits additional muscles. Airway resistance, tissue elasticity, and surface tension all influence the work required."],"keyPoints":["Volume and pressure change inversely.","Diaphragm is the principal quiet-inspiration muscle.","Quiet expiration uses elastic recoil.","Air flows down a pressure gradient."],"visual":{"title":"One quiet breath","kind":"comparison","items":[{"label":"Inspiration","detail":"Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","detail":"Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","detail":"Narrower airways require a larger pressure difference"}]},"mnemonic":{"title":"Expand–Drop–Enter","cue":"EDE","explanation":"Thorax expands, pressure drops, air enters."},"goodToKnow":"Deep breathing changes ventilation, but oxygen delivery also depends on alveolar exchange, blood flow, hemoglobin, and tissue demand.","act":{"type":"choice","prompt":"What immediately draws air into the lungs during quiet inspiration?","options":[{"label":"Alveolar pressure falls below atmospheric pressure","correct":true,"feedback":"Correct. Air moves down the resulting pressure gradient."},{"label":"Carbon dioxide stops being produced","correct":false,"feedback":"Metabolism continues; pressure change drives airflow."},{"label":"The pleural membranes open to outside air","correct":false,"feedback":"The pleural space normally remains closed."}]}},{"id":"l17-m6","chapter":null,"chapterSummary":null,"title":"Ventilation, respiration, and transport are separate steps","highYield":"Airflow, lung exchange, blood transport, and tissue exchange are linked but not interchangeable.","teach":["Ventilation is movement of air into and out of lungs. External respiration is gas exchange between alveoli and pulmonary capillary blood. Blood then transports gases, mostly with oxygen bound to hemoglobin and carbon dioxide carried mainly as bicarbonate.","Internal respiration is exchange between systemic capillary blood and tissues. Cells use oxygen in aerobic metabolism and produce carbon dioxide. A problem at any step can limit overall delivery, so a normal breathing rate alone does not prove normal tissue oxygenation."],"keyPoints":["Ventilation moves air.","External respiration exchanges gases at lungs.","Blood transports gases.","Internal respiration exchanges gases with tissues."],"visual":{"title":"Oxygen pathway","kind":"flow","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]},"mnemonic":{"title":"VETDU","cue":"Ventilate · Exchange · Transport · Deliver · Use","explanation":"Locate the step before explaining low oxygen delivery."},"goodToKnow":"Most carbon dioxide is transported as bicarbonate after reactions within erythrocytes, not simply dissolved as gas.","act":{"type":"choice","prompt":"What is external respiration?","options":[{"label":"Gas exchange between alveoli and pulmonary capillary blood","correct":true,"feedback":"Correct. It occurs across the respiratory membrane."},{"label":"Air moving through the nose","correct":false,"feedback":"That is ventilation through the conducting zone."},{"label":"Cellular ATP production","correct":false,"feedback":"That is cellular metabolism using delivered oxygen."}]}},{"id":"ventilation-order","title":"Put it in order: Oxygen pathway","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ventilate","detail":"Atmosphere ↔ alveoli"},{"label":"Exchange","detail":"Alveoli ↔ pulmonary blood"},{"label":"Transport","detail":"Pulmonary blood → systemic circulation"},{"label":"Deliver","detail":"Systemic blood ↔ tissues"},{"label":"Use","detail":"Mitochondrial metabolism"}]}},{"id":"ventilation-match","title":"Match it: One quiet breath","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Thorax expands → alveolar pressure falls → air enters","Elastic recoil reduces volume → alveolar pressure rises → air leaves","Narrower airways require a larger pressure difference"],"items":[{"label":"Inspiration","category":0,"feedback":"Inspiration: Thorax expands → alveolar pressure falls → air enters"},{"label":"Expiration","category":1,"feedback":"Expiration: Elastic recoil reduces volume → alveolar pressure rises → air leaves"},{"label":"Resistance","category":2,"feedback":"Resistance: Narrower airways require a larger pressure difference"}]}},{"id":"l17-m7","chapter":"Measure and integrate","chapterSummary":"Use lung volumes as functional measurements and connect respiratory control to homeostasis.","title":"Volumes combine into capacities","highYield":"A volume is one measurable compartment; a capacity is the sum of two or more lung volumes.","teach":["Tidal volume is air moved during a quiet breath. Inspiratory and expiratory reserve volumes describe additional air that can be moved beyond a quiet breath. Residual volume remains after maximal expiration and cannot be measured by simple spirometry.","Vital capacity combines inspiratory reserve, tidal volume, and expiratory reserve. Total lung capacity also includes residual volume. Values vary with body size, age, sex-related anatomy, posture, effort, conditioning, and disease, so a measured result must be compared with appropriate reference values and test quality."],"keyPoints":["Tidal volume is a quiet breath.","Reserve volumes extend beyond tidal breathing.","Residual volume remains after maximal exhalation.","Capacities combine volumes."],"visual":{"title":"Stacked lung volumes","kind":"layers","items":[{"label":"Inspiratory reserve","detail":"Additional volume inhaled above tidal inspiration"},{"label":"Tidal volume","detail":"Quiet breath"},{"label":"Expiratory reserve","detail":"Additional volume exhaled below tidal expiration"},{"label":"Residual volume","detail":"Air remaining after maximal exhalation"}]},"mnemonic":{"title":"VC = IRV + TV + ERV","cue":"Vital uses the three movable volumes","explanation":"Residual volume is not part of vital capacity."},"goodToKnow":"Simple spirometry cannot directly measure residual volume, so it also cannot directly measure capacities that include it.","act":{"type":"choice","prompt":"Which volume remains after the strongest possible exhalation?","options":[{"label":"Residual volume","correct":true,"feedback":"Correct. It helps keep alveoli from emptying completely."},{"label":"Tidal volume","correct":false,"feedback":"Tidal volume is a quiet breath."},{"label":"Inspiratory reserve volume","correct":false,"feedback":"That is additional inhaled volume above a normal inspiration."}]}},{"id":"l17-m8","chapter":null,"chapterSummary":null,"title":"Respiratory control responds strongly to carbon dioxide","highYield":"Brainstem networks adjust ventilation using chemical and mechanical feedback; rising carbon dioxide is a major normal drive.","teach":["Respiratory rhythm is generated by interacting brainstem networks and modified by sensory input. Central chemoreceptors respond indirectly to carbon-dioxide–related changes in cerebrospinal-fluid pH, while peripheral chemoreceptors respond to arterial oxygen, carbon dioxide, and pH.","Exercise increases ventilation through feed-forward motor signals and feedback from working tissues. The respiratory, cardiovascular, renal, and nervous systems cooperate to regulate gases and acid–base conditions. Nutrition supports energy metabolism and respiratory muscle function, but does not replace evaluation of persistent cough or breathlessness."],"keyPoints":["Brainstem networks generate rhythm.","Carbon dioxide/pH strongly influence normal ventilation.","Peripheral chemoreceptors also sense low arterial oxygen.","Respiratory and renal systems coordinate acid–base balance."],"visual":{"title":"Control loop","kind":"flow","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]},"mnemonic":{"title":"Sense–Set–Send","cue":"Sensors report · brainstem sets · motor nerves send","explanation":"A short respiratory-control loop."},"goodToKnow":"In chronic respiratory disease, ventilatory control can be altered; simplified statements that oxygen 'turns off breathing' are unsafe.","act":{"type":"choice","prompt":"Which chemical change is a major normal stimulus for increased ventilation?","options":[{"label":"Rising carbon dioxide and associated fall in pH","correct":true,"feedback":"Correct. CO₂-related pH change strongly influences respiratory drive."},{"label":"A small rise in dietary fibre","correct":false,"feedback":"Fibre intake does not directly set the brainstem respiratory rhythm."},{"label":"Lower skin melanin","correct":false,"feedback":"Melanin does not regulate ventilation."}]}},{"id":"capacity-order","title":"Put it in order: Control loop","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Change","detail":"CO₂, O₂, pH, movement, emotion"},{"label":"Sensors","detail":"Central/peripheral chemoreceptors and mechanoreceptors"},{"label":"Brainstem","detail":"Integrates and adjusts rhythm"},{"label":"Muscles","detail":"Diaphragm and chest wall change ventilation"},{"label":"Feedback","detail":"Blood gases and pH shift toward need"}]}},{"id":"capacity-match","title":"Match it: Stacked lung volumes","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Additional volume inhaled above tidal inspiration","Quiet breath","Additional volume exhaled below tidal expiration","Air remaining after maximal exhalation"],"items":[{"label":"Residual volume","category":3,"feedback":"Residual volume: Air remaining after maximal exhalation"},{"label":"Expiratory reserve","category":2,"feedback":"Expiratory reserve: Additional volume exhaled below tidal expiration"},{"label":"Tidal volume","category":1,"feedback":"Tidal volume: Quiet breath"},{"label":"Inspiratory reserve","category":0,"feedback":"Inspiratory reserve: Additional volume inhaled above tidal inspiration"}]}}],"flashcards":[{"front":"Conducting zone","back":"Airways that move, warm, humidify, and filter air without direct gas exchange."},{"front":"Mucociliary escalator","back":"Cilia moving mucus and trapped material toward the pharynx."},{"front":"Visceral pleura","back":"Serous membrane covering the lung surface."},{"front":"Type I alveolar cell","back":"Thin epithelial cell forming most of the gas-exchange surface."},{"front":"Type II alveolar cell","back":"Cell that produces pulmonary surfactant."},{"front":"Surfactant","back":"Material that lowers alveolar surface tension and improves stability."},{"front":"Ventilation","back":"Movement of air into and out of lungs."},{"front":"External respiration","back":"Gas exchange between alveoli and pulmonary capillary blood."},{"front":"Internal respiration","back":"Gas exchange between systemic capillary blood and tissues."},{"front":"Tidal volume","back":"Air moved during a quiet breath."},{"front":"Residual volume","back":"Air remaining after maximal exhalation."},{"front":"Vital capacity","back":"Inspiratory reserve + tidal volume + expiratory reserve."}],"quiz":[],"caseStudy":{"title":"Breathlessness after 'just being out of shape'","scenario":"A client reports increasing shortness of breath during ordinary activity, a persistent cough, and new difficulty finishing meals because breathing feels hard. They ask for an energy supplement and assume deconditioning is the only cause.","prompts":["Which steps in VETDU could limit oxygen delivery?","Which symptoms and progression details change the urgency?","What nutrition risks can develop when breathing interferes with meals?","How can nutrition support occur without diagnosing or delaying respiratory assessment?"],"takeaway":"Breathlessness can arise at multiple respiratory, cardiovascular, hematologic, and metabolic steps. Progressive symptoms need clinical assessment; nutrition support can address intake barriers alongside, not instead of, that care."}},{"n":18,"title":"The Urinary System","kicker":"Identify the organs of the urinary system and explain how the kidneys maintain internal balance.","duration":"90–110 minutes","steps":[{"id":"l18-m1","chapter":"Orient to the kidneys","chapterSummary":"Start with the system's homeostatic jobs, then locate the external and internal structures that support them.","title":"The kidneys edit blood, not merely remove waste","highYield":"Kidneys continually adjust what stays in blood and what leaves in urine, supporting volume, composition, pH, endocrine signalling, and waste removal.","teach":["The urinary system includes two kidneys, two ureters, the urinary bladder, and the urethra. The kidneys receive a large blood supply and produce urine; the ureters transport it, the bladder stores it, and the urethra carries it outside. This sequence is simple, but urine formation is selective rather than a passive draining process.","By filtering plasma and then reclaiming or adding selected substances, kidneys regulate water, sodium, potassium, acid–base balance, and many dissolved wastes. They also release renin and erythropoietin and participate in vitamin D activation. The lungs, skin, liver, and intestines also remove particular wastes, yet they cannot replace the full range of kidney functions."],"keyPoints":["Kidneys form urine from filtered blood plasma.","Ureters transport; bladder stores; urethra eliminates.","Kidneys regulate fluid, electrolytes, and acid–base balance.","Renin, erythropoietin, and vitamin D activation are additional renal roles."],"visual":{"title":"Four organs, four main jobs","kind":"flow","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]},"mnemonic":{"title":"K-U-B-U","cue":"Kidneys edit · Ureters move · Bladder holds · Urethra exits","explanation":"Use the route to separate urine formation from transport and storage."},"goodToKnow":"Urine colour and volume change with hydration, diet, medicines, temperature, and other factors; neither alone diagnoses kidney function.","act":{"type":"choice","prompt":"Which urinary organ makes urine by selectively processing filtered blood?","options":[{"label":"Kidneys","correct":true,"feedback":"Correct. Nephrons within the kidneys form urine."},{"label":"Ureters","correct":false,"feedback":"Ureters transport urine but do not form it."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine until voiding."}]}},{"id":"l18-m2","chapter":null,"chapterSummary":null,"title":"Kidney regions create a collecting funnel","highYield":"Cortex and medulla contain nephron structures; pyramids drain through papillae and calyces into the renal pelvis.","teach":["The kidneys lie behind the peritoneal lining on the posterior abdominal wall, with the right usually slightly lower because of the liver. At the medial hilum, the renal artery, renal vein, nerves, lymphatics, and ureter enter or leave. A fibrous renal capsule, cushioning adipose tissue, and renal fascia protect and anchor each kidney.","Internally, the cortex forms the outer region and extends between medullary pyramids as renal columns. Each pyramid ends at a papilla, where collecting ducts empty into a minor calyx. Minor calyces join into major calyces, which feed the renal pelvis and then the ureter. This is the urine route after nephron processing is complete."],"keyPoints":["Kidneys are retroperitoneal.","The hilum is the gateway for vessels, nerves, lymphatics, and ureter.","Cortex surrounds medullary pyramids and extends as columns.","Papilla → minor calyx → major calyx → renal pelvis → ureter."],"visual":{"title":"From kidney tissue to ureter","kind":"sequence","items":[{"label":"Cortex/medulla","detail":"Nephrons and collecting ducts process filtrate"},{"label":"Papilla","detail":"Tip of a medullary pyramid"},{"label":"Minor calyx","detail":"Receives urine from one papillary region"},{"label":"Major calyx","detail":"Collects from minor calyces"},{"label":"Renal pelvis","detail":"Funnel leading to the ureter"}]},"mnemonic":{"title":"Please Make More Renal Urine","cue":"Papilla · Minor calyx · Major calyx · Renal pelvis · Ureter","explanation":"A route cue for urine after it leaves collecting ducts."},"goodToKnow":"The adrenal glands sit near the kidneys but are endocrine organs with distinct functions; their position does not make them part of the urinary tract.","act":{"type":"choice","prompt":"What structure receives urine immediately after a renal papilla?","options":[{"label":"Minor calyx","correct":true,"feedback":"Correct. Papillary ducts drain into a minor calyx."},{"label":"Renal artery","correct":false,"feedback":"The renal artery supplies blood, not urine."},{"label":"Urinary bladder","correct":false,"feedback":"Urine reaches the bladder only after the renal pelvis and ureter."}]}},{"id":"homeostasis-anatomy-order","title":"Put it in order: Four organs, four main jobs","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Kidneys","detail":"Filter and selectively adjust blood; form urine"},{"label":"Ureters","detail":"Move urine by smooth-muscle peristalsis"},{"label":"Bladder","detail":"Stores urine until voiding"},{"label":"Urethra","detail":"Carries urine to the exterior"}]}},{"id":"l18-m3","chapter":"Build the nephron map","chapterSummary":"Connect the renal corpuscle, tubule, collecting system, and two capillary beds before studying transport.","title":"A nephron begins with a filter and continues as a tubule","highYield":"The renal corpuscle filters; the renal tubule modifies; the collecting duct makes final water and solute adjustments.","teach":["A nephron's renal corpuscle consists of a capillary tuft called the glomerulus surrounded by the glomerular capsule. Blood enters through an afferent arteriole and leaves through an efferent arteriole. The filtration barrier separates blood cells and most large proteins from water and smaller dissolved substances that enter capsular space.","Filtrate then passes through the proximal convoluted tubule, descending and ascending limbs of the nephron loop, and distal convoluted tubule. The distal tubule empties into a collecting duct shared by several nephrons. Segment-specific permeability and transport let the kidney recover useful substances, remove additional wastes, and vary the final urine concentration."],"keyPoints":["Renal corpuscle = glomerulus plus glomerular capsule.","Afferent enters; efferent exits.","Tubule route: proximal → loop → distal.","Collecting ducts receive fluid from multiple nephrons."],"visual":{"title":"Nephron route","kind":"flow","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]},"mnemonic":{"title":"Filter, Proximal, Loop, Distal, Collect","cue":"F-P-L-D-C","explanation":"Follow filtrate through the nephron without confusing it with blood flow."},"goodToKnow":"The filtrate is not yet urine. Its composition changes substantially as it passes through the tubule and collecting duct.","act":{"type":"choice","prompt":"Which vessel carries blood away from the glomerulus?","options":[{"label":"Efferent arteriole","correct":true,"feedback":"Correct. Think E for exit."},{"label":"Afferent arteriole","correct":false,"feedback":"Afferent blood arrives at the glomerulus."},{"label":"Ureter","correct":false,"feedback":"The ureter carries urine, not blood."}]}},{"id":"l18-m4","chapter":null,"chapterSummary":null,"title":"One arteriole links two capillary networks","highYield":"Glomerular capillaries support filtration; peritubular capillaries and vasa recta support exchange with the tubule.","teach":["Renal blood travels from the renal artery through progressively smaller branches to afferent arterioles and glomerular capillaries. Instead of draining directly into a vein, the glomerulus drains through the efferent arteriole. That vessel then forms peritubular capillaries around cortical tubules and, for deeper nephrons, long vasa recta alongside the nephron loop.","This two-capillary arrangement serves two different tasks. Relatively high pressure in the glomerulus favours filtration, while vessels around the tubule receive reabsorbed water and solutes and deliver substances for secretion. Their proximity also helps preserve the medullary gradient needed to conserve water."],"keyPoints":["Renal artery branches ultimately supply afferent arterioles.","Glomerulus lies between afferent and efferent arterioles.","Peritubular capillaries exchange with cortical tubules.","Vasa recta support deep loops and medullary gradients."],"visual":{"title":"Blood–filtrate partnership","kind":"parallel","items":[{"label":"Blood path","detail":"Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","detail":"Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","detail":"Reabsorption moves toward blood; secretion moves toward tubule"}]},"mnemonic":{"title":"A-G-E-P","cue":"Afferent · Glomerulus · Efferent · Peritubular","explanation":"The core renal microcirculation sequence."},"goodToKnow":"Juxtamedullary nephrons have long loops extending deep into the medulla and are especially important for producing concentrated urine.","act":{"type":"choice","prompt":"Why is the efferent arteriole unusual in this circulation?","options":[{"label":"It leaves one capillary bed and then forms another","correct":true,"feedback":"Correct. It links glomerular filtration to peritubular exchange."},{"label":"It carries urine into the bladder","correct":false,"feedback":"Arterioles carry blood."},{"label":"It is the only vessel containing red blood cells","correct":false,"feedback":"Red blood cells normally remain throughout the blood vessels."}]}},{"id":"nephron-map-order","title":"Put it in order: Nephron route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Glomerulus","detail":"Capillary pressure creates filtrate"},{"label":"Glomerular capsule","detail":"Receives filtered water and small solutes"},{"label":"Proximal tubule","detail":"Bulk reclamation and some secretion"},{"label":"Nephron loop","detail":"Builds medullary gradients"},{"label":"Distal tubule/collecting duct","detail":"Regulated fine-tuning"}]}},{"id":"nephron-map-match","title":"Match it: Blood–filtrate partnership","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins","Capsule → proximal tubule → loop → distal tubule → collecting duct","Reabsorption moves toward blood; secretion moves toward tubule"],"items":[{"label":"Blood path","category":0,"feedback":"Blood path: Afferent arteriole → glomerulus → efferent arteriole → peritubular capillaries/vasa recta → veins"},{"label":"Filtrate path","category":1,"feedback":"Filtrate path: Capsule → proximal tubule → loop → distal tubule → collecting duct"},{"label":"Cross-talk","category":2,"feedback":"Cross-talk: Reabsorption moves toward blood; secretion moves toward tubule"}]}},{"id":"l18-m5","chapter":"Transform filtrate into urine","chapterSummary":"Use three directional processes and regulated water handling to explain how kidneys preserve balance.","title":"Filtration, reabsorption, and secretion have different directions","highYield":"Filtration enters the nephron, reabsorption returns to blood, and secretion adds from blood to tubular fluid.","teach":["Glomerular filtration uses blood pressure to move water and small solutes across the filtration barrier into capsular space. Cells and most large plasma proteins normally remain in the circulation. The resulting filtrate contains many useful substances as well as wastes, so filtration alone cannot produce an appropriate final urine.","Tubular reabsorption moves selected substances from tubular fluid through the epithelium and back to blood; most filtered water and solutes are reclaimed. Tubular secretion moves substances from peritubular blood into tubular fluid. Together, the three processes can be summarized as excretion equals filtration minus reabsorption plus secretion."],"keyPoints":["Filtration: blood → capsular space.","Reabsorption: tubule → blood.","Secretion: blood → tubule.","Excretion = filtered − reabsorbed + secreted."],"visual":{"title":"Three renal directions","kind":"equation","items":[{"label":"Filter","detail":"Glomerular blood → capsule"},{"label":"Reabsorb","detail":"Tubular fluid → peritubular blood"},{"label":"Secrete","detail":"Peritubular blood → tubular fluid"},{"label":"Excrete","detail":"What remains and leaves as urine"}]},"mnemonic":{"title":"F in, R return, S supplement","cue":"Filter in · Reabsorb returns · Secrete supplements","explanation":"Anchor each process to the direction relative to the nephron."},"goodToKnow":"A substance can be filtered and then partly reabsorbed, filtered and secreted, or handled differently along multiple nephron segments.","act":{"type":"choice","prompt":"Glucose moves from tubular fluid back into peritubular blood. What process is this?","options":[{"label":"Tubular reabsorption","correct":true,"feedback":"Correct. The substance returns from the tubule to blood."},{"label":"Glomerular filtration","correct":false,"feedback":"Filtration is the initial movement from glomerular blood to capsular space."},{"label":"Tubular secretion","correct":false,"feedback":"Secretion moves from blood into tubular fluid."}]}},{"id":"l18-m6","chapter":null,"chapterSummary":null,"title":"Hormones help match water and sodium output to need","highYield":"ADH primarily changes collecting-duct water permeability; aldosterone promotes sodium reabsorption and potassium secretion in distal segments.","teach":["The proximal tubule performs bulk reabsorption, while the nephron loop establishes a concentration gradient in the medulla. The descending limb is relatively water-permeable; the ascending limb moves salts but is much less permeable to water. This countercurrent organization allows later segments to vary how much water is recovered.","Antidiuretic hormone increases water permeability in the late distal tubule and collecting duct, conserving water when appropriate. Aldosterone supports sodium reabsorption and potassium secretion in distal segments; water may follow retained sodium. Renin-angiotensin-aldosterone signalling, natriuretic peptides, sympathetic input, thirst, and circulation all contribute to fluid and pressure regulation."],"keyPoints":["The nephron loop helps create a medullary gradient.","ADH promotes regulated water reabsorption.","Aldosterone supports sodium retention and potassium secretion.","Renal, endocrine, cardiovascular, and nervous systems coordinate fluid balance."],"visual":{"title":"Segment and signal","kind":"map","items":[{"label":"Proximal tubule","detail":"Bulk recovery of water and many solutes"},{"label":"Nephron loop","detail":"Builds medullary osmotic gradient"},{"label":"ADH","detail":"Raises late-nephron water permeability"},{"label":"Aldosterone","detail":"Promotes distal sodium reabsorption and potassium secretion"}]},"mnemonic":{"title":"ADH adds water doors","cue":"More ADH → more aquaporin-mediated water recovery","explanation":"A functional cue; ADH does not add water to the body, it changes renal retention."},"goodToKnow":"Thirst and urine concentration respond to many signals. A universal water target ignores body size, climate, activity, food moisture, pregnancy, lactation, and medical conditions.","act":{"type":"choice","prompt":"Which hormone most directly increases collecting-duct water permeability?","options":[{"label":"Antidiuretic hormone","correct":true,"feedback":"Correct. ADH promotes insertion of water channels in responsive cells."},{"label":"Erythropoietin","correct":false,"feedback":"Erythropoietin stimulates red-cell production."},{"label":"Insulin","correct":false,"feedback":"Insulin regulates fuel metabolism, not collecting-duct water permeability."}]}},{"id":"urine-formation-match","title":"Match it: Three renal directions","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Glomerular blood → capsule","Tubular fluid → peritubular blood","Peritubular blood → tubular fluid","What remains and leaves as urine"],"items":[{"label":"Excrete","category":3,"feedback":"Excrete: What remains and leaves as urine"},{"label":"Secrete","category":2,"feedback":"Secrete: Peritubular blood → tubular fluid"},{"label":"Reabsorb","category":1,"feedback":"Reabsorb: Tubular fluid → peritubular blood"},{"label":"Filter","category":0,"feedback":"Filter: Glomerular blood → capsule"}]}},{"id":"l18-m7","chapter":"Integrate regulation and elimination","chapterSummary":"Connect acid–base and endocrine roles to urine composition, transport, storage, and safe nutrition practice.","title":"Kidneys share regulation with lungs, blood, bone, and marrow","highYield":"Renal handling of hydrogen and bicarbonate supports pH; renin, erythropoietin, and vitamin D activation link kidneys to other systems.","teach":["Kidneys contribute to acid–base balance by secreting hydrogen ions, reclaiming filtered bicarbonate, and generating new bicarbonate. Their response is slower than respiratory changes but provides sustained control. This partnership explains why ventilation and renal function must be considered together when thinking about blood pH.","Renin participates in a cascade that supports blood-pressure and sodium regulation. Erythropoietin signals red bone marrow to increase red-cell production when renal oxygen sensing indicates need. The kidneys also complete a major activation step for vitamin D, linking renal function to calcium and phosphate balance and therefore to bone physiology."],"keyPoints":["Hydrogen secretion and bicarbonate handling support pH.","Renin participates in pressure and sodium regulation.","Erythropoietin links kidney oxygen sensing to marrow.","Vitamin D activation links kidneys to mineral and bone balance."],"visual":{"title":"Renal system links","kind":"network","items":[{"label":"Lungs","detail":"Rapid carbon-dioxide contribution to acid–base balance"},{"label":"Circulation","detail":"Renin-related pressure and perfusion regulation"},{"label":"Bone marrow","detail":"Erythropoietin supports erythrocyte production"},{"label":"Intestine/bone","detail":"Activated vitamin D supports calcium and phosphate handling"}]},"mnemonic":{"title":"R-E-D-A","cue":"Renin · Erythropoietin · vitamin D Activation · Acid–base","explanation":"Four kidney jobs beyond making urine."},"goodToKnow":"Renal disease can affect hemoglobin, minerals, and acid–base status; these are systemic effects, not separate coincidences.","act":{"type":"choice","prompt":"Which renal product stimulates red bone marrow to make more erythrocytes?","options":[{"label":"Erythropoietin","correct":true,"feedback":"Correct. It is produced largely by specialized cells in the kidney."},{"label":"Bile","correct":false,"feedback":"Bile is produced by the liver and supports lipid digestion."},{"label":"Surfactant","correct":false,"feedback":"Pulmonary surfactant is produced in the lungs."}]}},{"id":"l18-m8","chapter":null,"chapterSummary":null,"title":"Urine is propelled, stored, and released by coordinated muscle","highYield":"Ureteral peristalsis moves urine; bladder stretch initiates a spinal reflex; voluntary control acts mainly through the external urethral sphincter.","teach":["Urine moves from each renal pelvis through a ureter, propelled mainly by smooth-muscle peristalsis rather than gravity alone. Transitional epithelium lets the ureters and bladder stretch. The bladder's detrusor muscle expands during filling, while its trigone is defined by the two ureter openings and the urethral outlet.","As bladder stretch rises, sensory signals reach the spinal cord and higher centres. The micturition reflex contracts the detrusor and relaxes the involuntary internal sphincter, while learned control of the skeletal external sphincter helps delay or permit voiding. The urethra is shorter in typical female anatomy and longer in typical male anatomy, where it also serves the reproductive tract at different times."],"keyPoints":["Ureteral peristalsis moves urine to the bladder.","Transitional epithelium accommodates stretching.","Detrusor contraction supports voiding.","Internal sphincter is involuntary; external sphincter has voluntary control."],"visual":{"title":"Urine exit route","kind":"sequence","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]},"mnemonic":{"title":"Pelvis–Pipe–Pouch–Passage","cue":"Renal pelvis · ureter · bladder · urethra","explanation":"A plain-language route from kidney to exterior."},"goodToKnow":"Frequent urination can reflect fluid timing, caffeine, medicines, pregnancy, sleep patterns, infection, metabolic changes, and more; frequency alone does not identify the cause.","act":{"type":"choice","prompt":"Which muscle forms the main contractile wall of the bladder?","options":[{"label":"Detrusor muscle","correct":true,"feedback":"Correct. Its smooth-muscle layers contract during voiding."},{"label":"Diaphragm","correct":false,"feedback":"The diaphragm is the main inspiratory muscle."},{"label":"Myocardium","correct":false,"feedback":"Myocardium is cardiac muscle."}]}},{"id":"integration-elimination-order","title":"Put it in order: Urine exit route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Renal pelvis","detail":"Collects urine from calyces"},{"label":"Ureter","detail":"Peristaltic transport"},{"label":"Bladder","detail":"Storage and stretch sensing"},{"label":"Sphincters","detail":"Coordinate continence and voiding"},{"label":"Urethra","detail":"Final path to the exterior"}]}},{"id":"integration-elimination-match","title":"Match it: Renal system links","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Rapid carbon-dioxide contribution to acid–base balance","Renin-related pressure and perfusion regulation","Erythropoietin supports erythrocyte production","Activated vitamin D supports calcium and phosphate handling"],"items":[{"label":"Intestine/bone","category":3,"feedback":"Intestine/bone: Activated vitamin D supports calcium and phosphate handling"},{"label":"Bone marrow","category":2,"feedback":"Bone marrow: Erythropoietin supports erythrocyte production"},{"label":"Circulation","category":1,"feedback":"Circulation: Renin-related pressure and perfusion regulation"},{"label":"Lungs","category":0,"feedback":"Lungs: Rapid carbon-dioxide contribution to acid–base balance"}]}}],"flashcards":[{"front":"Urinary system organs","back":"Two kidneys, two ureters, urinary bladder, and urethra."},{"front":"Hilum","back":"Medial kidney gateway where vessels, nerves, lymphatics, and ureter enter or leave."},{"front":"Renal cortex","back":"Outer kidney region containing renal corpuscles and portions of tubules."},{"front":"Renal medulla","back":"Inner region organized into pyramids containing loops and collecting ducts."},{"front":"Renal corpuscle","back":"Glomerulus plus glomerular capsule; site where filtrate first forms."},{"front":"Afferent arteriole","back":"Vessel carrying blood into the glomerulus."},{"front":"Tubular reabsorption","back":"Movement of substances from tubular fluid back to blood."},{"front":"Tubular secretion","back":"Movement of substances from peritubular blood into tubular fluid."},{"front":"ADH","back":"Hormone that increases regulated water permeability in the late nephron."},{"front":"Erythropoietin","back":"Renal hormone that stimulates erythrocyte production in red bone marrow."},{"front":"Detrusor muscle","back":"Smooth muscle in the bladder wall that contracts during voiding."},{"front":"Micturition","back":"Coordinated process of emptying the urinary bladder."}],"quiz":[],"caseStudy":{"title":"A hydration shortcut that ignores the whole picture","scenario":"A client has started forcing several extra litres of water daily after seeing a fixed online target. They now wake repeatedly to urinate and feel light-headed at times. They also mention a recent change in medication and assume that completely clear urine always proves ideal hydration.","prompts":["Which kidney and bladder processes explain the change in urine volume and frequency?","What information about body size, activity, climate, diet, medicines, health conditions, thirst, and symptoms is missing?","Why is urine colour an imperfect standalone hydration measure?","Which symptoms or medication concerns should be referred rather than managed through a generic fluid prescription?"],"takeaway":"Fluid needs are contextual, and the kidneys continuously adjust water output. Support practical observation and clinical coordination instead of treating one intake number or urine colour as a universal target."}},{"n":19,"title":"The Reproductive System","kicker":"Map the major male and female reproductive organs and explain how structure supports each organ's role.","duration":"75–95 minutes","steps":[{"id":"l19-m1","chapter":"Male reproductive organization","chapterSummary":"Follow sperm production from the testis through maturation, transport, and seminal-fluid formation.","title":"The testes have paired exocrine and endocrine jobs","highYield":"Seminiferous tubules make sperm, while interstitial cells between the tubules make testosterone.","teach":["Each testis is wrapped by a fibrous capsule that sends partitions inward, forming lobules. Inside those lobules, tightly coiled seminiferous tubules provide the site of sperm formation. The scrotum holds the testes outside the pelvic cavity, where muscular adjustments help maintain a temperature suited to sperm production.","Two cell populations clarify the testis's dual role. Developing germ cells and their supporting Sertoli cells occupy the tubules, while interstitial Leydig cells lie in the tissue between tubules and secrete testosterone. The organ therefore sends sperm through ducts and hormones into blood."],"keyPoints":["Tunica albuginea and internal septa organize the testis into lobules.","Spermatogenesis occurs in seminiferous tubules.","Sertoli cells support developing sperm cells.","Leydig cells secrete testosterone into the circulation."],"visual":{"title":"Inside a testis","kind":"layers","items":[{"label":"Capsule","detail":"Tunica albuginea forms a durable outer coat."},{"label":"Lobules","detail":"Septa divide the organ into compartments."},{"label":"Tubules","detail":"Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Between tubules","detail":"Leydig cells produce testosterone."}]},"mnemonic":{"title":"S inside, L between","cue":"Sertoli supports sperm in Seminiferous tubules; Leydig lies between Loops.","explanation":"The repeated initials anchor the location and role of the two important support cells."},"goodToKnow":"The testes are both exocrine and endocrine: sperm travel through ducts, whereas testosterone enters the bloodstream.","act":{"type":"choice","prompt":"Which pairing correctly identifies a testicular cell and its main role?","options":[{"label":"Leydig cell — testosterone secretion","correct":true,"feedback":"Correct. Leydig cells are interstitial endocrine cells."},{"label":"Sertoli cell — carrying urine to the bladder","correct":false,"feedback":"Sertoli cells support developing sperm within seminiferous tubules."},{"label":"Spermatogonium — producing seminal-vesicle fluid","correct":false,"feedback":"A spermatogonium is an early germ cell, not an accessory gland."}]}},{"id":"l19-m2","chapter":null,"chapterSummary":null,"title":"Spermatogenesis reduces chromosome number, then reshapes the cell","highYield":"Mitosis preserves the germ-cell line; meiosis produces haploid spermatids; maturation creates a streamlined sperm cell.","teach":["Spermatogonia near the outer wall of a seminiferous tubule divide by mitosis. Some remain as a renewing cell population, while others become primary spermatocytes. A primary spermatocyte completes meiosis I to form two secondary spermatocytes, and meiosis II produces four haploid spermatids.","Spermatids are not yet fully shaped sperm. During maturation, the nucleus becomes compact, an enzyme-containing acrosome forms over the head, mitochondria concentrate in the midpiece, and a flagellum develops for movement. This is a change in form and function after the chromosome-reduction divisions."],"keyPoints":["Mitosis replenishes spermatogonia and supplies cells for development.","Meiosis I and II reduce a diploid primary spermatocyte to haploid spermatids.","One primary spermatocyte can yield four spermatids.","Head, midpiece, and tail are specialized for genetic delivery, energy, and movement."],"visual":{"title":"From germ cell to sperm","kind":"flow","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]},"mnemonic":{"title":"Grow, halve, halve, shape","cue":"Mitosis grows the line; meiosis halves twice; maturation shapes.","explanation":"This separates cell-number maintenance, chromosome reduction, and structural specialization."},"goodToKnow":"A mature sperm cell's midpiece is rich in mitochondria, but the cell's purpose is transport of paternal genetic material rather than general nutrient storage.","act":{"type":"choice","prompt":"What is produced directly by meiosis II during spermatogenesis?","options":[{"label":"Haploid spermatids","correct":true,"feedback":"Correct. Secondary spermatocytes complete meiosis II to form spermatids."},{"label":"Diploid spermatogonia","correct":false,"feedback":"Spermatogonia are maintained through mitosis."},{"label":"Seminal fluid","correct":false,"feedback":"Accessory glands contribute most seminal fluid."}]}},{"id":"l19-mod1-order","title":"Put it in order: From germ cell to sperm","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Spermatogonium","detail":"Diploid stem-line cell; divides by mitosis."},{"label":"Primary spermatocyte","detail":"Enters the first meiotic division."},{"label":"Secondary spermatocytes","detail":"Haploid products of meiosis I."},{"label":"Spermatids","detail":"Four products after meiosis II."},{"label":"Spermatozoa","detail":"Mature form with head, midpiece, and tail."}]}},{"id":"l19-mod1-match","title":"Match it: Inside a testis","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Tunica albuginea forms a durable outer coat.","Septa divide the organ into compartments.","Seminiferous tubules contain developing sperm and Sertoli cells.","Leydig cells produce testosterone."],"items":[{"label":"Between tubules","category":3,"feedback":"Between tubules: Leydig cells produce testosterone."},{"label":"Tubules","category":2,"feedback":"Tubules: Seminiferous tubules contain developing sperm and Sertoli cells."},{"label":"Lobules","category":1,"feedback":"Lobules: Septa divide the organ into compartments."},{"label":"Capsule","category":0,"feedback":"Capsule: Tunica albuginea forms a durable outer coat."}]}},{"id":"l19-m3","chapter":"Male transport and seminal fluid","chapterSummary":"Trace sperm through the ducts and identify how accessory glands assemble the transport medium.","title":"Sperm follow a continuous transport route","highYield":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra.","teach":["Newly formed sperm leave the convoluted seminiferous tubules, pass into straight tubules, cross the rete testis, and exit through efferent ductules. They then enter the epididymis, whose long coiled duct supports further maturation and storage while sperm gain motility.","During ejaculation, smooth-muscle contractions propel sperm into the ductus deferens, through an ejaculatory duct, and then into the urethra. The male urethra has prostatic, membranous, and spongy regions. Route questions become much easier when each segment is linked to its landmark."],"keyPoints":["The epididymis is a maturation and storage site, not the production site.","The ductus deferens carries sperm from the epididymis toward the pelvic cavity.","Ejaculatory ducts empty into the prostatic urethra.","The urethra provides the final passage to the exterior."],"visual":{"title":"Sperm route map","kind":"route","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]},"mnemonic":{"title":"Sperm Take Roads, Exit, Drive, Enter, Use","cue":"Seminiferous → straight → rete → efferent → ductus epididymis → ductus deferens → ejaculatory → urethra.","explanation":"The phrase cues the major route in order; add details only after the sequence is secure."},"goodToKnow":"After a vasectomy, sperm production and testosterone secretion can continue; the procedure interrupts the ductus deferens rather than removing the testes.","act":{"type":"choice","prompt":"Where do sperm normally mature and develop motility after leaving the testis?","options":[{"label":"Epididymis","correct":true,"feedback":"Correct. The coiled epididymal duct supports maturation and storage."},{"label":"Seminal vesicle","correct":false,"feedback":"The seminal vesicle adds fluid but is not a sperm-maturation site."},{"label":"Urinary bladder","correct":false,"feedback":"The bladder stores urine, not sperm."}]}},{"id":"l19-m4","chapter":null,"chapterSummary":null,"title":"Accessory glands build the transport medium","highYield":"Semen combines sperm with secretions from seminal vesicles, prostate, and bulbourethral glands.","teach":["Sperm make up only part of semen. Seminal vesicles contribute much of the fluid and include fructose that can support sperm movement. The prostate adds fluid around the first portion of the urethra, and bulbourethral glands add a mucus-like secretion that lubricates the urethral passage.","Together, these secretions provide a liquid transport medium and help buffer conditions encountered during passage. This is a useful structure–function example: glands placed along the route add components before the mixture leaves through the urethra."],"keyPoints":["Semen is sperm plus accessory-gland secretions.","Seminal-vesicle fluid contributes energy substrate and volume.","Prostatic fluid joins the ejaculatory-duct contents in the prostatic urethra.","Bulbourethral secretion lubricates the urethra before ejaculation."],"visual":{"title":"What enters semen?","kind":"contributions","items":[{"label":"Testes/epididymides","detail":"Sperm cells."},{"label":"Seminal vesicles","detail":"Large fluid contribution with fructose."},{"label":"Prostate","detail":"Additional glandular fluid around the urethral route."},{"label":"Bulbourethral glands","detail":"Lubricating mucus-like secretion."}]},"mnemonic":{"title":"Cells plus three secretions","cue":"Sperm + seminal vesicle + prostate + bulbourethral.","explanation":"Think of semen as a mixture assembled along a route, not a product made in one organ."},"goodToKnow":"Fructose in seminal fluid is a local energy substrate for sperm movement; it does not mean that eating more sugar predictably improves fertility.","act":{"type":"choice","prompt":"Which statement best describes semen?","options":[{"label":"A mixture of sperm and several accessory-gland secretions","correct":true,"feedback":"Correct. Multiple structures contribute to the final fluid."},{"label":"A hormone made only by Leydig cells","correct":false,"feedback":"Leydig cells make testosterone, not semen."},{"label":"Fluid stored in the urinary bladder","correct":false,"feedback":"The urinary bladder stores urine."}]}},{"id":"l19-mod2-order","title":"Put it in order: Sperm route map","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Produce","detail":"Seminiferous tubules."},{"label":"Collect","detail":"Straight tubules, rete testis, efferent ductules."},{"label":"Mature","detail":"Epididymis."},{"label":"Transport","detail":"Ductus deferens and ejaculatory duct."},{"label":"Exit","detail":"Prostatic → membranous → spongy urethra."}]}},{"id":"l19-mod2-match","title":"Match it: What enters semen?","teach":[],"act":{"type":"sort","variant":"match","prompt":"Drag each term onto what it describes.","categories":["Sperm cells.","Large fluid contribution with fructose.","Additional glandular fluid around the urethral route.","Lubricating mucus-like secretion."],"items":[{"label":"Bulbourethral glands","category":3,"feedback":"Bulbourethral glands: Lubricating mucus-like secretion."},{"label":"Prostate","category":2,"feedback":"Prostate: Additional glandular fluid around the urethral route."},{"label":"Seminal vesicles","category":1,"feedback":"Seminal vesicles: Large fluid contribution with fructose."},{"label":"Testes/epididymides","category":0,"feedback":"Testes/epididymides: Sperm cells."}]}},{"id":"l19-m5","chapter":"Female reproductive organization and cycles","chapterSummary":"Connect ovarian events, oocyte development, uterine anatomy, and endometrial change across a cycle.","title":"Oogenesis produces one large functional cell","highYield":"Unequal meiotic divisions preserve cytoplasm in one oocyte while small polar bodies receive little cytoplasm.","teach":["Oogonia form primary oocytes before birth, and those primary oocytes remain arrested until later reproductive cycles. When a selected oocyte resumes meiosis, the first division produces a large secondary oocyte and a small polar body rather than two equal cells.","The secondary oocyte is released at ovulation. In the usual sequence, meiosis II completes only if fertilization occurs, producing an ovum and another polar body. The unequal allocation retains organelles and cytoplasm in the cell that could support the first divisions after fertilization."],"keyPoints":["Primary oocytes form before birth and later resume development.","Meiosis I yields a secondary oocyte plus a polar body.","The secondary oocyte is the cell released at ovulation.","Meiosis II usually completes in association with fertilization."],"visual":{"title":"Unequal meiotic divisions","kind":"flow","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]},"mnemonic":{"title":"One keeps the kitchen","cue":"One oocyte keeps most cytoplasm; polar bodies carry chromosomes with little cytoplasm.","explanation":"The image explains why the divisions are genetically ordered but physically unequal."},"goodToKnow":"Oogenesis and spermatogenesis both use meiosis, but they differ in timing, equality of cell division, and the number of functional gametes produced.","act":{"type":"choice","prompt":"Why is a secondary oocyte much larger than its polar body?","options":[{"label":"Meiosis divides chromosomes but allocates most cytoplasm to the oocyte","correct":true,"feedback":"Correct. The divisions are unequal in cytoplasmic volume."},{"label":"The polar body contains twice as many chromosomes","correct":false,"feedback":"Both products are haploid after meiosis I; size reflects cytoplasmic allocation."},{"label":"The oocyte has already implanted","correct":false,"feedback":"Implantation occurs after fertilization and early cell divisions."}]}},{"id":"l19-m6","chapter":null,"chapterSummary":null,"title":"The ovarian and uterine cycles are synchronized","highYield":"Follicle growth and ovulation in the ovary align with menstrual, proliferative, and secretory changes in the endometrium.","teach":["During the follicular portion of the ovarian cycle, follicles develop and one usually becomes dominant. Rising estrogen is associated with repair and growth of the uterine endometrium. Ovulation releases the secondary oocyte, which is guided toward a uterine tube by the fimbriae and ciliary movement.","After ovulation, the emptied follicle becomes the corpus luteum and secretes progesterone as well as estrogen. These hormones support a secretory endometrium prepared for possible implantation. If implantation does not occur, the corpus luteum regresses, hormone support falls, and another menstrual phase begins."],"keyPoints":["Menstrual phase sheds the functional endometrial lining.","Proliferative phase rebuilds the lining as a follicle matures.","Ovulation separates the preovulatory and postovulatory portions of the cycle.","Secretory phase is supported by corpus-luteum hormones.","Cycle length and timing vary among individuals and across life stages."],"visual":{"title":"Two cycles, one timeline","kind":"timeline","items":[{"label":"Menstrual / early follicular","detail":"Endometrium sheds while follicles begin developing."},{"label":"Proliferative / follicular","detail":"Estrogen rises and the lining rebuilds."},{"label":"Ovulation","detail":"Secondary oocyte leaves the mature follicle."},{"label":"Secretory / luteal","detail":"Corpus luteum hormones support a receptive lining."},{"label":"No implantation","detail":"Corpus luteum regresses and the cycle resets."}]},"mnemonic":{"title":"Shed, spread, secrete","cue":"Menstrual sheds · proliferative spreads new lining · secretory enriches it.","explanation":"This anchors the three uterine phases without assuming an identical day count for everyone."},"goodToKnow":"The textbook's day numbers are a teaching model; real cycles vary. Phase relationships are more reliable than memorizing one universal calendar.","act":{"type":"choice","prompt":"Which ovarian structure chiefly supports the postovulatory secretory phase?","options":[{"label":"Corpus luteum","correct":true,"feedback":"Correct. It secretes progesterone and estrogen after ovulation."},{"label":"Fimbria","correct":false,"feedback":"Fimbriae help guide the oocyte toward the uterine tube."},{"label":"Polar body","correct":false,"feedback":"A polar body is a small meiotic product, not a hormone-secreting ovarian structure."}]}},{"id":"l19-mod3-order","title":"Put it in order: Unequal meiotic divisions","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Oogonium","detail":"Diploid precursor in fetal development."},{"label":"Primary oocyte","detail":"Begins meiosis and remains arrested."},{"label":"Secondary oocyte + polar body","detail":"Unequal products of meiosis I."},{"label":"Ovum + polar bodies","detail":"Completion of meiosis II if fertilization occurs."}]}},{"id":"l19-m7","chapter":"Fertilization, development, birth, and lactation","chapterSummary":"Follow the biological sequence from gamete union through implantation, placental exchange, labor, and milk delivery.","title":"Fertilization starts a sequence of transport and implantation","highYield":"Fertilization usually occurs in a uterine tube; the dividing conceptus reaches the uterus and implants in the endometrium.","teach":["The uterine tubes receive the ovulated secondary oocyte through the infundibulum and fimbriae. Cilia and smooth-muscle contractions move it toward the uterus. When fertilization occurs, sperm and oocyte genetic material combine to restore the diploid chromosome number in the zygote.","The zygote undergoes repeated mitotic divisions while traveling toward the uterine cavity, developing into a blastocyst. Its outer cells participate in implantation and formation of chorionic villi, while the inner cell mass gives rise to the embryo. Ectoderm, mesoderm, and endoderm then provide the foundational tissue layers."],"keyPoints":["Fertilization most often occurs in the uterine tube, not the uterus.","A zygote divides by mitosis while moving toward the uterine cavity.","Implantation occurs in the endometrium.","The inner cell mass forms the embryo; trophoblast-related tissues support implantation and placenta formation.","Three germ layers give rise to the body's tissues and organs."],"visual":{"title":"Early development route","kind":"route","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]},"mnemonic":{"title":"Tube, travel, touch down","cue":"Fertilize in the tube · divide while traveling · implant in the uterus.","explanation":"The phrase distinguishes the usual sites of fertilization, early transport, and implantation."},"goodToKnow":"Placental and maternal blood normally remain in separate circulations; exchange occurs across a thin interface rather than by directly mixing the two blood supplies.","act":{"type":"choice","prompt":"Which sequence is anatomically correct?","options":[{"label":"Fertilization in uterine tube → mitotic divisions → implantation in endometrium","correct":true,"feedback":"Correct. The early conceptus divides while moving to the uterus."},{"label":"Implantation in ovary → fertilization in cervix → cleavage in vagina","correct":false,"feedback":"Those locations reverse the normal pathway."},{"label":"Fertilization in bladder → implantation in ureter","correct":false,"feedback":"Those are urinary, not reproductive, structures."}]}},{"id":"l19-m8","chapter":null,"chapterSummary":null,"title":"Placenta, labor, and mammary glands support the transition to birth","highYield":"The placenta supports exchange during pregnancy; labor progresses through dilation, expulsion, and placental stages; mammary lobules produce milk.","teach":["Chorionic villi and uterine tissue contribute to the placenta, which supports exchange of oxygen, nutrients, and wastes between maternal and fetal circulations. The amnion surrounds the developing embryo or fetus with fluid, and the umbilical cord links fetal circulation to the placenta. These are coordinated support structures, not interchangeable names for one organ.","Labor is commonly organized into cervical dilation, expulsion of the baby, and delivery of the placenta. After birth, milk is produced by secretory alveoli grouped within mammary lobules. Milk moves through branching ducts toward widened regions and then through lactiferous ducts that open at the nipple."],"keyPoints":["The placenta is an exchange and endocrine interface during pregnancy.","The amnion encloses the developing fetus in fluid.","The umbilical cord connects fetal vessels to the placenta.","Labor progresses through dilation, expulsion, and placental stages.","Mammary alveoli make milk; ducts carry it toward the nipple."],"visual":{"title":"Support before and after birth","kind":"paired-flow","items":[{"label":"Pregnancy","detail":"Placenta exchanges; amnion cushions; cord connects."},{"label":"Dilation","detail":"Cervix opens as uterine contractions progress."},{"label":"Expulsion","detail":"Baby passes through the birth canal."},{"label":"Placental stage","detail":"Placenta separates and is delivered."},{"label":"Lactation","detail":"Alveoli produce milk and ducts convey it outward."}]},"mnemonic":{"title":"Open, out, after","cue":"Dilation opens · expulsion moves baby out · placental stage delivers afterbirth.","explanation":"A three-word cue for the major stages of labor."},"goodToKnow":"The mammary glands are organized into lobes, lobules, secretory alveoli, and ducts. Breast size mostly reflects adipose tissue and does not by itself indicate milk-making capacity.","act":{"type":"choice","prompt":"Where is milk produced within a lactating mammary gland?","options":[{"label":"Secretory alveoli in lobules","correct":true,"feedback":"Correct. Alveolar cells produce milk, which then enters the duct system."},{"label":"Placental villi","correct":false,"feedback":"Placental villi support exchange during pregnancy, not milk production."},{"label":"Uterine endometrium","correct":false,"feedback":"The endometrium lines the uterus and supports implantation."}]}},{"id":"l19-mod4-order","title":"Put it in order: Early development route","teach":[],"act":{"type":"order","prompt":"Drag the steps into the right order, top to bottom.","items":[{"label":"Ovulation","detail":"Secondary oocyte enters the vicinity of a uterine tube."},{"label":"Fertilization","detail":"Gametes unite in the tube and form a zygote."},{"label":"Cleavage","detail":"Mitotic divisions occur during transport."},{"label":"Blastocyst","detail":"Outer support cells and an inner cell mass become distinct."},{"label":"Implantation","detail":"The conceptus embeds in uterine endometrium."}]}}],"flashcards":[{"front":"Seminiferous tubule","back":"Coiled testicular tubule where spermatogenesis occurs."},{"front":"Sertoli cell","back":"Support cell within seminiferous tubules that nourishes and regulates developing sperm."},{"front":"Leydig cell","back":"Interstitial testicular cell that secretes testosterone."},{"front":"Epididymis","back":"Coiled duct where sperm mature, gain motility, and are stored."},{"front":"Sperm route","back":"Seminiferous tubules → straight tubules → rete testis → efferent ductules → epididymis → ductus deferens → ejaculatory duct → urethra."},{"front":"Semen","back":"Sperm combined with secretions from the seminal vesicles, prostate, and bulbourethral glands."},{"front":"Oogenesis","back":"Formation and maturation of the female gamete through unequal meiotic divisions."},{"front":"Ovulation","back":"Release of a secondary oocyte from a mature ovarian follicle."},{"front":"Corpus luteum","back":"Postovulatory ovarian structure that secretes progesterone and estrogen."},{"front":"Endometrium","back":"Inner uterine layer that changes across the cycle and receives an implanting conceptus."},{"front":"Blastocyst","back":"Early hollow-stage conceptus with an outer trophoblast and inner cell mass."},{"front":"Placenta","back":"Temporary maternal–fetal interface for exchange and hormone production during pregnancy."},{"front":"Three labor stages","back":"Dilation, expulsion, and placental stages."},{"front":"Mammary alveoli","back":"Secretory structures in lobules that produce milk."}],"quiz":[],"caseStudy":{"title":"A cycle change is not a one-nutrient diagnosis","scenario":"A physically active client reports that menstrual cycles have become less regular while training volume increased and meals became more restrictive. They ask for one supplement to restore fertility immediately and want reassurance that no medical assessment is needed.","prompts":["Which ovarian and uterine events must coordinate for a typical cycle?","What intake, training, stress, medication, reproductive, and health-history questions are relevant without assuming a cause?","Why would one supplement be unable to guarantee ovulation, implantation, or fertility?","Which scope and referral language would support the client without diagnosing them?"],"takeaway":"Cycle changes can reflect many interacting reproductive, endocrine, energy-availability, medication, stress, and health factors. A nutrition professional can assess intake patterns and support adequacy while recommending timely clinical evaluation rather than assigning a cause or promising a fertility outcome."}}]};
